def filter_closed(itemsets):
    closed = []
    for i, (iset, sup) in enumerate(itemsets):
        is_closed = True
        for j, (other, osup) in enumerate(itemsets):
            if i != j and set(iset) < set(other) and sup == osup:
                is_closed = False
                break
        if is_closed:
            closed.append((iset, sup))
    return closed

