# 1️⃣ Khởi tạo Spark
from pyspark.sql import SparkSession

spark = SparkSession.builder.appName("GlassIdentification").getOrCreate()

# 2️⃣ Đọc dữ liệu
df = spark.read.csv("D:/glass.data", header=False, inferSchema=True)

# 3️⃣ Đặt tên cột (chuẩn theo UCI)
columns = ["Id", "RI","Na","Mg","Al","Si","K","Ca","Ba","Fe","Type"]
df = df.toDF(*columns)


# 5️⃣ Kiểm tra dữ liệu
df.show(5)
df.groupBy("Type").count().show()
