# ==========================
# 4. Chuẩn bị dữ liệu
# ==========================
feature_cols = ["RI","Na","Mg","Al","Si","K","Ca","Ba","Fe"]
assembler = VectorAssembler(inputCols=feature_cols, outputCol="features_vec")
scaler = StandardScaler(inputCol="features_vec", outputCol="features")

# ==========================
# 5. Các mô hình
# ==========================
rf = RandomForestClassifier(labelCol="Type", featuresCol="features", numTrees=100, maxDepth=5)
dt = DecisionTreeClassifier(labelCol="Type", featuresCol="features", maxDepth=5)
lr = LogisticRegression(labelCol="Type", featuresCol="features", maxIter=50)

pipeline_rf = Pipeline(stages=[assembler, scaler, rf])
pipeline_dt = Pipeline(stages=[assembler, scaler, dt])
pipeline_lr = Pipeline(stages=[assembler, scaler, lr])

# ==========================
# 6. Chia dữ liệu
# ==========================
train_df, test_df = df.randomSplit([0.8, 0.2], seed=42)
evaluator = MulticlassClassificationEvaluator(labelCol="Type", predictionCol="prediction", metricName="accuracy")

# ==========================
# 7. Huấn luyện và đánh giá
# ==========================
models = {
    "RỪNG CÂY NGẪU NHIÊN (RANDOM FOREST)": pipeline_rf,
    "CÂY QUYẾT ĐỊNH (DECISION TREE)": pipeline_dt,
    "HỒI QUY LOGISTIC ĐA THỨC (MULTINOMINAL LOGISTIC REGRESSION)": pipeline_lr
}

results = {}
reports = {}

for name, pipe in models.items():
    print(f"\n{'='*25} {name} {'='*25}")
    
    # Huấn luyện mô hình
    model = pipe.fit(train_df)
    preds = model.transform(test_df)
    acc = evaluator.evaluate(preds)
    results[name] = acc
    print(f"✅ Độ chính xác: {acc:.4f}")

    # Lấy nhãn thật và dự đoán
    y_true = [int(row.Type) for row in preds.select("Type").collect()]
    y_pred = [int(row.prediction) for row in preds.select("prediction").collect()]

    # Ma trận nhầm lẫn
    labels = sorted(list(set(y_true)))  # [1, 2, 3, 5, 6, 7]
    cm = confusion_matrix(y_true, y_pred, labels=labels)
    disp = ConfusionMatrixDisplay(confusion_matrix=cm, display_labels=labels)
    disp.plot(cmap="Blues")
    plt.title(f"MA TRẬN NHẦM LẪN CỦA MÔ HÌNH \n{name}")
    plt.show()

    # Báo cáo chi tiết
    report = classification_report(y_true, y_pred, labels=labels, output_dict=True, zero_division=0)
    df_report = pd.DataFrame(report).transpose()
    reports[name] = df_report

    print(f"🔹 Báo cáo chi tiết cho {name}")
    print(df_report[["precision", "recall", "f1-score", "support"]])
    print("="*80)

# ==========================
# 8. So sánh tổng quan độ chính xác
# ==========================
print("\n🎯 Tổng kết độ chính xác:")
for name, acc in results.items():
    print(f"{name:25s}: {acc:.4f}")
