from pyspark.sql import SparkSession
from pyspark.ml import Pipeline
from pyspark.ml.feature import VectorAssembler, StandardScaler, StringIndexer
from pyspark.ml.classification import (
    RandomForestClassifier, DecisionTreeClassifier, LogisticRegression
)
from pyspark.ml.evaluation import MulticlassClassificationEvaluator

# --- Thư viện phân tích & trực quan hóa ---
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import (
    confusion_matrix, ConfusionMatrixDisplay, classification_report
)
from IPython.display import display, HTML
import os

# --- Đường dẫn dữ liệu ---
current_dir = os.getcwd()
file_path = os.path.join(current_dir, "glass.data")

# --- Khởi tạo SparkSession ---
spark = SparkSession.builder.appName("GlassIdentification").getOrCreate()
