def algorithm_result(title, prediction_result):
    # --- Ma trận nhầm lẫn ---
    # Cài đặt biểu đồ
    y_true = [int(row.Type) for row in prediction_result.select("Type").collect()]
    y_pred = [int(row.prediction) for row in prediction_result.select("prediction").collect()]
    labels = sorted(list(set(y_true)))
    confusion_matrix_result = confusion_matrix(y_true, y_pred, labels=labels)
    ConfusionMatrixDisplay(confusion_matrix=confusion_matrix_result, display_labels=labels).plot(cmap="Blues")

    # Thông tin biểu đồ
    plt.title("MA TRẬN NHẦM LẪN CỦA THUẬT TOÁN\n" + title, weight='bold')
    plt.xlabel("Giá trị dự đoán\n(Predicted value)", fontsize=11)
    plt.ylabel("Giá trị thực tế\n(Actual value)", fontsize=11)
    
    # --- Báo cáo hiệu suất ---
    # Báo cáo hiệu suất
    report = classification_report(y_true, y_pred, labels=labels, output_dict=True, zero_division=0)
    df_report = (
        pd.DataFrame(report)
        .transpose()[["precision", "recall", "f1-score", "support"]]
        .rename(columns={
            "precision": "Độ chính xác<br>(Precision)",
            "recall": "Độ nhạy<br>(Recall)",
            "f1-score": "Điểm F1<br>(F1-Score)",
            "support": "Số mẫu<br>(Support)"
        })
        .rename(index={
            "accuracy": "Độ chính xác tổng thể<br>(Accuracy)",
            "macro avg": "Trung bình lớp<br>(Macro average)",
            "weighted avg": "Trung bình trọng số<br>(Weighted average)"
        })
    )

    # Làm đậm tất cả nhãn (label)
    df_report.index = [f"<b>{idx}</b>" for idx in df_report.index]
    
    # Hiển thị biểu đồ
    plt.show()
    
    # Hiển thị bảng
    print(f"Báo cáo hiệu suất")
    display(HTML(
    df_report.to_html(escape=False, justify="center")
    .replace('<th>', '<th style="text-align:center; white-space:pre-line;">')
    .replace('<td>', '<td style="text-align:center;">')
    ))
    return report;
