src_root = "classificacao_binaria"
dst_root = "BreakHis"  # folder train/test chuẩn để chạy ViT

# Đường dẫn dữ liệu gốc
data_dir = "BreakHis/all_images"

# Tạo danh sách ảnh theo lớp
benign_imgs = [os.path.join(data_dir, "Benign", f) for f in os.listdir(os.path.join(data_dir, "Benign"))]
malignant_imgs = [os.path.join(data_dir, "Malignant", f) for f in os.listdir(os.path.join(data_dir, "Malignant"))]

# Chia dữ liệu theo tỷ lệ 70/15/15
def split_data(img_list, train_size=0.7, val_size=0.15):
    train, temp = train_test_split(img_list, train_size=train_size, random_state=42)
    val, test = train_test_split(temp, test_size=test_size/(1-train_size), random_state=42)
    return train, val, test

benign_train, benign_val, benign_test = split_data(benign_imgs)
malignant_train, malignant_val, malignant_test = split_data(malignant_imgs)

# Tổng hợp
train_imgs = benign_train + malignant_train
val_imgs = benign_val + malignant_val
test_imgs = benign_test + malignant_test

print(f"Train: {len(train_imgs)}, Val: {len(val_imgs)}, Test: {len(test_imgs)}")
