# Thư mục gốc và thư mục lưu ảnh augmented
src_root = "BreakHis/classificacao_multiclasse"
dst_root = "BreakHis/classificacao_multiclasse_augmented"

# Thứ tự magnification
magnification_order = ["40X", "100X", "200X", "400X"]

# Transform chỉ xoay và lật
augment = transforms.Compose([
    transforms.RandomHorizontalFlip(),
    transforms.RandomVerticalFlip(),
    transforms.RandomRotation([90, 180, 270])
])

# Tạo folder đích
for zoom in magnification_order:
    zoom_path = os.path.join(src_root, zoom)
    if not os.path.isdir(zoom_path):
        continue
    for cls in os.listdir(zoom_path):
        dst_cls_path = os.path.join(dst_root, zoom, cls)
        os.makedirs(dst_cls_path, exist_ok=True)

# --- Augmentation ---
for zoom in magnification_order:
    zoom_path = os.path.join(src_root, zoom)
    if not os.path.isdir(zoom_path):
        continue
    for cls in os.listdir(zoom_path):
        cls_path = os.path.join(zoom_path, cls)
        dst_cls_path = os.path.join(dst_root, zoom, cls)
        if not os.path.isdir(cls_path):
            continue

        imgs = [f for f in os.listdir(cls_path) if f.lower().endswith((".png",".jpg"))]
        n_imgs = len(imgs)

        # Xác định số lượng ảnh target để cân bằng
        counts = [len([f for f in os.listdir(os.path.join(zoom_path,c)) if f.lower().endswith((".png",".jpg"))])
                  for c in os.listdir(zoom_path)]
        max_count = max(counts)

        # Copy ảnh gốc
        for img_name in imgs:
            img_path = os.path.join(cls_path, img_name)
            dst_img_path = os.path.join(dst_cls_path, img_name)
            if not os.path.exists(dst_img_path):
                Image.open(img_path).save(dst_img_path)

        # Tạo các phiên bản augmented cho class ít
        n_aug = max_count - n_imgs
        for i in range(n_aug):
            img_name = random.choice(imgs)
            img = Image.open(os.path.join(cls_path, img_name))
            img_aug = augment(img)
            base_name, ext = os.path.splitext(img_name)
            dst_img_path = os.path.join(dst_cls_path, f"{base_name}_aug{i}{ext}")
            img_aug.save(dst_img_path)

print("Done! Multi-class dataset augmented and balanced (rotate & flip only).")
