# Folder gốc dataset binary (mỗi magnification có subfolder benign/malignant)
src_root = "BreakHis/classificacao_multiclasse"  # folder gốc
dst_root = "train_data_before_augment"

train_ratio = 0.7
val_ratio = 0.15  # test = 1 - train_ratio - val_ratio

for zoom in os.listdir(src_root):
    zoom_path = os.path.join(src_root, zoom)
    if not os.path.isdir(zoom_path):
        continue

    for cls in os.listdir(zoom_path):
        cls_path = os.path.join(zoom_path, cls)
        if not os.path.isdir(cls_path):
            continue

        # Tạo folder train/val/test/class
        for split in ["train", "validation", "test"]:
            os.makedirs(os.path.join(dst_root, split, zoom, cls), exist_ok=True)

        imgs = [f for f in os.listdir(cls_path) if f.lower().endswith((".png",".jpg"))]
        random.shuffle(imgs)
        n_train = int(len(imgs) * train_ratio)
        n_val = int(len(imgs) * val_ratio)

        for i, img in enumerate(imgs):
            if i < n_train:
                shutil.copy(os.path.join(cls_path, img), os.path.join(dst_root, "train", zoom, cls, img))
            elif i < n_train + n_val:
                shutil.copy(os.path.join(cls_path, img), os.path.join(dst_root, "validation", zoom, cls, img))
            else:
                shutil.copy(os.path.join(cls_path, img), os.path.join(dst_root, "test", zoom, cls, img))

print("Done splitting dataset with train/val/test!")
