src_root = "train_data_before_augment"
dst_root = "train_data_after_augment"
magnifications = ["40X", "100X", "200X", "400X"]

def rotate_flip(img):
    angle = random.choice([90, 180, 270])
    img = functional.rotate(img, angle)
    if random.random() > 0.5:
        img = functional.hflip(img)
    if random.random() > 0.5:
        img = functional.vflip(img)
    return img

max_aug_per_img = 5  # mỗi ảnh gốc augment tối đa 5 lần

for split in splits:
    print(f"Processing {split} set...")
    split_src = os.path.join(src_root, split)
    split_dst = os.path.join(dst_root, split)

    for zoom in magnifications:
        zoom_path = os.path.join(split_src, zoom)
        if not os.path.isdir(zoom_path):
            continue

        for cls in os.listdir(zoom_path):
            cls_path = os.path.join(zoom_path, cls)
            dst_cls_path = os.path.join(split_dst, zoom, cls)
            os.makedirs(dst_cls_path, exist_ok=True)

            imgs = [f for f in os.listdir(cls_path) if f.lower().endswith((".png", ".jpg"))]

            # Copy ảnh gốc
            for img_name in imgs:
                src_img_path = os.path.join(cls_path, img_name)
                dst_img_path = os.path.join(dst_cls_path, img_name)
                if not os.path.exists(dst_img_path):
                    Image.open(src_img_path).save(dst_img_path)

            # Đếm số ảnh từng class trong zoom
            counts = [len([f for f in os.listdir(os.path.join(zoom_path, c)) if f.lower().endswith((".png", ".jpg"))])
                      for c in os.listdir(zoom_path)]
            max_count = max(counts)
            n_aug = max_count - len(imgs)  # số ảnh cần augment cho class này

            if n_aug <= 0:
                continue

            # Tạo tracker để giới hạn số lần augment mỗi ảnh
            aug_tracker = {img_name: 0 for img_name in imgs}

            aug_count = 0
            while aug_count < n_aug:
                img_name = random.choice(imgs)
                if aug_tracker[img_name] >= max_aug_per_img:
                    continue
                img = Image.open(os.path.join(cls_path, img_name))
                img_aug = rotate_flip(img)
                base_name, ext = os.path.splitext(img_name)
                dst_img_path = os.path.join(dst_cls_path, f"{base_name}_aug{aug_count}{ext}")
                img_aug.save(dst_img_path)
                aug_tracker[img_name] += 1
                aug_count += 1

print("✅ Done augmenting all splits (train/validation/test)!")
