cache_path = kagglehub.dataset_download("ambarish/breakhis")

# Sao chép tập dữ liệu vào thư mục dự án
cache_data = os.path.join(cache_path, "BreaKHis_v1", "BreaKHis_v1", "histology_slides", "breast")

for cls in ["benign", "malignant"]:
    cls_src = os.path.join(cache_data, cls)
    cls_dst = os.path.join(original_data, cls)
    os.makedirs(cls_dst, exist_ok=True)

    for subtype in os.listdir(cls_src):
        subtype_src = os.path.join(cls_src, subtype)
        if not os.path.isdir(subtype_src):
            continue

        # SOB là folder thừa → lặp trực tiếp trong SOB
        sob_folder = os.path.join(subtype_src, "SOB")
        if os.path.exists(sob_folder):
            for patient_folder in os.listdir(sob_folder):
                patient_src = os.path.join(sob_folder, patient_folder)
                for mag in os.listdir(patient_src):
                    mag_src = os.path.join(patient_src, mag)
                    mag_dst = os.path.join(cls_dst, subtype, mag)
                    os.makedirs(mag_dst, exist_ok=True)
                    for img in os.listdir(mag_src):
                        shutil.copy(os.path.join(mag_src, img), mag_dst)
        else:
            # Nếu folder không có SOB, copy trực tiếp patient/folder
            for patient_folder in os.listdir(subtype_src):
                patient_src = os.path.join(subtype_src, patient_folder)
                if not os.path.isdir(patient_src):
                    continue
                for mag in os.listdir(patient_src):
                    mag_src = os.path.join(patient_src, mag)
                    mag_dst = os.path.join(cls_dst, subtype, mag)
                    os.makedirs(mag_dst, exist_ok=True)
                    for img in os.listdir(mag_src):
                        shutil.copy(os.path.join(mag_src, img), mag_dst)

# Xóa cache
shutil.rmtree(cache_path)
