classes = ["benign", "malignant"]
records = []

for cls in classes:
    cls_src = os.path.join(src_root, cls)
    cls_dst = os.path.join(dst_root, cls)
    os.makedirs(cls_dst, exist_ok=True)

    for subtype in os.listdir(cls_src):
        subtype_src = os.path.join(cls_src, subtype)
        if not os.path.isdir(subtype_src):
            continue

        # Kiểm tra folder SOB
        sob_folder = os.path.join(subtype_src, "SOB")
        if os.path.exists(sob_folder):
            patient_folders = [os.path.join(sob_folder, p) for p in os.listdir(sob_folder) if os.path.isdir(os.path.join(sob_folder, p))]
        else:
            patient_folders = [os.path.join(subtype_src, p) for p in os.listdir(subtype_src) if os.path.isdir(os.path.join(subtype_src, p))]

        for patient_folder in patient_folders:
            for mag in os.listdir(patient_folder):
                mag_src = os.path.join(patient_folder, mag)
                if not os.path.isdir(mag_src):
                    continue
                mag_dst = os.path.join(cls_dst, subtype, mag)
                os.makedirs(mag_dst, exist_ok=True)

                for img in os.listdir(mag_src):
                    src_img_path = os.path.join(mag_src, img)
                    if not os.path.isfile(src_img_path):
                        continue
                    if not img.lower().endswith((".png", ".jpg", ".jpeg")):
                        continue

                    dst_img_path = os.path.join(mag_dst, img)
                    shutil.copy(src_img_path, dst_img_path)

                    # Lấy thông tin Patient ID, magnification
                    parts = img.split("-")
                    patient_id = parts[2]
                    magnification = parts[3]

                    records.append({
                        "filepath": dst_img_path,
                        "class": cls,
                        "subclass": subtype,
                        "magnification": magnification,
                        "patient_id": patient_id
                    })


