# Tạo dataframe để lưu thông tin
data = []

src_root = "BreakHis/classificacao_multiclasse"

for zoom in sorted(os.listdir(src_root)):
    zoom_path = os.path.join(src_root, zoom)
    if not os.path.isdir(zoom_path):
        continue
    for cls in sorted(os.listdir(zoom_path)):
        cls_path = os.path.join(zoom_path, cls)
        if not os.path.isdir(cls_path):
            continue
        n_imgs = len([f for f in os.listdir(cls_path) if f.lower().endswith((".png", ".jpg"))])
        data.append({"Magnification": zoom, "Class": cls, "Count": n_imgs})

df = pd.DataFrame(data)

# Vẽ biểu đồ
