# ====== B3. Hàm đếm file ======
def list_images(folder):
    return [os.path.join(folder, f) for f in os.listdir(folder)
            if os.path.isfile(os.path.join(folder, f))]

# ====== B4. Bắt đầu xóa để cân bằng ======
for split in splits:
    print(f"\n=== PROCESSING SPLIT: {split.upper()} ===")

    split_path = os.path.join(train_data_path, split)

    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path): continue

        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if not os.path.isdir(subtype_path): continue

            for mag in magnifications:
                group_key = (main_class, subtype, mag)
                if group_key not in target_per_group:
                    continue

                target_n = target_per_group[group_key]

                # --- Tổng ảnh hiện tại ---
                all_images = []
                patient_paths = []

                for patient in os.listdir(subtype_path):
                    patient_path = os.path.join(subtype_path, patient)
                    mag_path = os.path.join(patient_path, mag)

                    if not os.path.isdir(mag_path):
                        continue

                    imgs = list_images(mag_path)
                    if imgs:
                        all_images.extend(imgs)
                        patient_paths.append((patient_path, mag_path, len(imgs)))

                current_n = len(all_images)

                if current_n <= target_n:
                    continue  # Không cần xóa

                print(f"\n➡ {main_class}/{subtype}/{mag}: {current_n} → {target_n}")

                # ===== ƯU TIÊN 3: Xóa trong TỪNG BỆNH NHÂN =====
                remove_needed = current_n - target_n

                random.shuffle(all_images)
                images_to_delete = all_images[:remove_needed]

                for img in images_to_delete:
                    os.remove(img)

                print(f"   - Deleted {len(images_to_delete)} images (in-patient)")

                # ===== Kiểm tra lại sau khi xóa =====
                # Nếu vẫn còn dư (do một số bệnh nhân không có mag đó) → xóa bệnh nhân
                remaining = 0
                for pp, mp, _ in patient_paths:
                    if os.path.isdir(mp):
                        remaining += len(list_images(mp))

                if remaining > target_n:
                    print("   ⚠ Still above target → deleting whole patients")

                    # sort patient by number of images (delete largest first)
                    sorted_patients = sorted(patient_paths, key=lambda x: x[2], reverse=True)

                    for patient_dir, mag_dir, count in sorted_patients:
                        if remaining <= target_n:
                            break
                        shutil.rmtree(patient_dir)
                        remaining -= count
                        print(f"   - Whole patient removed: {patient_dir}")

                print(f"✔ Final images: {remaining}")
