magnifications = ["40X", "100X", "200X", "400X"]
TARGET_COUNT = 16  # mức cân bằng

def count_images(path):
    return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])

def balance_subtype(subtype_path):
    # Thu thập thông tin bệnh nhân
    patient_info = defaultdict(lambda: defaultdict(int))  # patient_info[patient][mag] = count

    for patient in os.listdir(subtype_path):
        p_path = os.path.join(subtype_path, patient)
        if not os.path.isdir(p_path):
            continue

        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                patient_info[patient][mag] = count_images(mag_path)

    # Bước 1: xoá bệnh nhân nguyên cụm nếu tổng ảnh >> TARGET
    patients_sorted = sorted(patient_info.items(), key=lambda x: sum(x[1].values()), reverse=True)

    for patient, mags in patients_sorted:
        total_imgs = sum(mags.values())
        if total_imgs == 0:
            continue

        # nếu tổng ảnh subtype > TARGET * 4 (4 magnifications)
        subtype_total = sum([sum(m.values()) for m in patient_info.values()])
        if subtype_total <= TARGET_COUNT * len(magnifications):
            break

        # xoá bệnh nhân nặng nhất
        shutil.rmtree(os.path.join(subtype_path, patient))
        del patient_info[patient]

    # Bước 2: xoá ảnh dư trong từng magnification
    for patient, mags in patient_info.items():
        for mag in magnifications:
            mag_path = os.path.join(subtype_path, patient, mag)
            if not os.path.isdir(mag_path):
                continue

            files = [os.path.join(mag_path, f) for f in os.listdir(mag_path)]
            if len(files) > TARGET_COUNT:
                remove_count = len(files) - TARGET_COUNT
                files_to_remove = random.sample(files, remove_count)
                for f in files_to_remove:
                    os.remove(f)

# Chạy cân bằng cho từng split và từng subtype
for split in ["train", "validation", "test"]:
    split_path = os.path.join(train_data_path, split)
    
    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path): continue
        
        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if not os.path.isdir(subtype_path): continue

            print("Balancing:", split, main_class, subtype)
            balance_subtype(subtype_path)

print("DONE BALANCING.")
