def count_images(path):
    return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])


def get_auto_target(subtype_path):
    """
    Tìm số ảnh thấp nhất trong 4 magnifications của subtype này
    bằng cách đọc toàn bộ ảnh của tất cả bệnh nhân.
    """
    mag_counts = defaultdict(int)

    for patient in os.listdir(subtype_path):
        p_path = os.path.join(subtype_path, patient)
        if not os.path.isdir(p_path): 
            continue
        
        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                mag_counts[mag] += count_images(mag_path)

    if len(mag_counts) == 0:
        return 0

    # lấy nhóm ít nhất làm target
    return min(mag_counts.values())


def balance_subtype(subtype_path):
    # ======= 1) TÍNH TARGET_COUNT =======
    TARGET_COUNT = get_auto_target(subtype_path)

    if TARGET_COUNT == 0:
        print("⚠ Subtype trống:", subtype_path)
        return
    
    print("→ TARGET:", TARGET_COUNT)

    # ======= 2) Lấy thông tin từng bệnh nhân =======
    patient_info = defaultdict(lambda: defaultdict(int))

    for patient in os.listdir(subtype_path):
        p_path = os.path.join(subtype_path, patient)
        if not os.path.isdir(p_path):
            continue

        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                patient_info[patient][mag] = count_images(mag_path)

    # ======= 3) XÓA BỆNH NHÂN NẾU TỔNG ẢNH SUBTYPE QUÁ CAO, NHƯNG CHỈ KHI CÒN >1 BỆNH NHÂN =======
    def total_subtype_images():
        return sum(sum(m.values()) for m in patient_info.values())

    patients_sorted = sorted(
        patient_info.items(),
        key=lambda x: sum(x[1].values()),
        reverse=True
    )

    while total_subtype_images() > TARGET_COUNT * len(magnifications) and len(patient_info) > 1:
        patient, mags = patients_sorted.pop(0)
        print("  - Xóa bệnh nhân:", patient)

        shutil.rmtree(os.path.join(subtype_path, patient))
        del patient_info[patient]

    # ======= 4) XÓA ẢNH DƯ TRONG MỖI MAGNIFICATION =======
    for patient, mags in patient_info.items():
        for mag in magnifications:
            mag_path = os.path.join(subtype_path, patient, mag)
            if not os.path.isdir(mag_path):
                continue

            files = [
                os.path.join(mag_path, f)
                for f in os.listdir(mag_path)
                if os.path.isfile(os.path.join(mag_path, f))
            ]

            if len(files) > TARGET_COUNT:
                remove_count = len(files) - TARGET_COUNT
                print(f"  - Xóa {remove_count} ảnh ở {patient}/{mag}")

                files_to_remove = random.sample(files, remove_count)
                for f in files_to_remove:
                    os.remove(f)

#===========================
#      CHẠY TOÀN BỘ
#===========================
for split in ["train", "validation", "test"]:
    split_path = os.path.join(train_data_path, split)

    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path): continue

        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if not os.path.isdir(subtype_path): continue

            print(f"\n=== Balancing {split} | {main_class} | {subtype} ===")
            balance_subtype(subtype_path)

print("\nDONE BALANCING.")
