# ======== Các hàm làm giàu ==========
def rotate_flip(img):
    angle = random.choice([90, 180, 270])
    img = img.rotate(angle)
    if random.random() > 0.5:
        img = img.transpose(Image.FLIP_LEFT_RIGHT)
    if random.random() > 0.5:
        img = img.transpose(Image.FLIP_TOP_BOTTOM)
    return img

def brightness_contrast(img):
    img = ImageEnhance.Brightness(img).enhance(random.uniform(0.8, 1.2))
    img = ImageEnhance.Contrast(img).enhance(random.uniform(0.8, 1.2))
    return img

def gamma_correction(img):
    gamma = random.uniform(0.8, 1.2)
    inv_gamma = 1.0 / gamma
    table = [((i / 255.0) ** inv_gamma) * 255 for i in range(256)]
    table = np.array(table).astype(np.uint8)
    return img.point(table)

def color_jitter(img):
    return ImageEnhance.Color(img).enhance(random.uniform(0.9, 1.1))

def add_noise(img):
    arr = np.array(img)
    noise = np.random.normal(0, 5, arr.shape)
    arr = np.clip(arr + noise, 0, 255).astype(np.uint8)
    return Image.fromarray(arr)

def augment_image(img):
    img = rotate_flip(img)
    img = brightness_contrast(img)
    img = gamma_correction(img)
    img = color_jitter(img)
    img = add_noise(img)
    return img

# ======== Hàm làm giàu cho một nhóm ==========
def augment_group(group_path, target_count):
    files = [f for f in os.listdir(group_path) if os.path.isfile(os.path.join(group_path, f))]
    if not files: return
    current_count = len(files)
    needed = target_count - current_count
    if needed <= 0: return
    for _ in range(needed):
        orig_file = random.choice(files)
        img = Image.open(os.path.join(group_path, orig_file))
        img_aug = augment_image(img)
        base, ext = os.path.splitext(orig_file)
        new_name = f"{base}_aug_{random.randint(0,9999)}{ext}"
        img_aug.save(os.path.join(group_path, new_name))


# ======== Chạy toàn bộ ==========
# Tìm số ảnh ít nhất trong toàn bộ split (tất cả nhóm, tất cả mag)
def get_global_target(split_path):
    counts = []
    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path): continue
        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if not os.path.isdir(subtype_path): continue
            for patient in os.listdir(subtype_path):
                patient_path = os.path.join(subtype_path, patient)
                if not os.path.isdir(patient_path): continue
                for mag in magnifications:
                    mag_path = os.path.join(patient_path, mag)
                    if not os.path.isdir(mag_path): continue
                    n = len([f for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))])
                    counts.append(n)
    if counts:
        return min(counts) * 10
    return 0

def augment_split(split):
    split_path = os.path.join(train_data_path, split)
    target_count = get_global_target(split_path)
    if target_count == 0:
        print("⚠ Không có ảnh trong split", split)
        return
    print(f"→ Split {split}, target_count mỗi mag: {target_count}")

    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path): continue
        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if not os.path.isdir(subtype_path): continue
            for patient in os.listdir(subtype_path):
                patient_path = os.path.join(subtype_path, patient)
                if not os.path.isdir(patient_path): continue
                for mag in magnifications:
                    mag_path = os.path.join(patient_path, mag)
                    if os.path.isdir(mag_path):
                        augment_group(mag_path, target_count)
                        print(f"  - Augment {patient}/{mag} lên {target_count} ảnh")

# Chạy cho từng split
for split in ["train", "validation", "test"]:
    augment_split(split)
