def count_and_plot_images():
    """
    Đếm số lượng ảnh theo Class/Subtype/Magnification và vẽ biểu đồ.
    
    Returns:
        pd.DataFrame: DataFrame chứa thông tin số lượng ảnh
    """
    splits = ["train", "validation", "test"]
    magnifications = ["40X", "100X", "200X", "400X"]
    data_counts = {split: {} for split in splits}
    
    # --- Đếm số ảnh ---
    data_counts = {split: {} for split in splits}
    
    for split in splits:
        split_path = os.path.join(train_data_path, split)
        for main_class in os.listdir(split_path):
            class_path = os.path.join(split_path, main_class)
            if not os.path.isdir(class_path):
                continue
            for subtype in os.listdir(class_path):
                subtype_path = os.path.join(class_path, subtype)
                if not os.path.isdir(subtype_path):
                    continue

                for mag in magnifications:
                    n_images_total = 0
                    for patient in os.listdir(subtype_path):
                        patient_path = os.path.join(subtype_path, patient)
                        if not os.path.isdir(patient_path):
                            continue
                        mag_path = os.path.join(patient_path, mag)
                        if not os.path.isdir(mag_path):
                            continue
                        n_images_total += len([f for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))])

                    key = f"{main_class}/{subtype}/{mag}"
                    data_counts[split][key] = n_images_total

    # --- Tạo DataFrame ---
    all_data = []
    for split in splits:
        for cls_subtype_mag, count in data_counts[split].items():
            main_class, subtype, mag = cls_subtype_mag.split("/")
