def count_images(path):
    return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])

def get_subtype_total(subtype_path):
    """Tính tổng số ảnh của subtype (cộng tất cả bệnh nhân và magnifications)."""
    total = 0
    patient_info = {}
    for patient in os.listdir(subtype_path):
        p_path = os.path.join(subtype_path, patient)
        if not os.path.isdir(p_path):
            continue
        patient_total = 0
        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                patient_total += count_images(mag_path)
        patient_info[patient] = patient_total
        total += patient_total
    return total, patient_info

def balance_split(split_path):
    # Lấy danh sách tất cả subtype trong split
    subtype_paths = []
    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path):
            continue
        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if os.path.isdir(subtype_path):
                subtype_paths.append(subtype_path)

    # Tính tổng số ảnh của mỗi subtype
    subtype_totals = {}
    subtype_patient_info = {}
    for sp in subtype_paths:
        total, patient_info = get_subtype_total(sp)
        subtype_totals[sp] = total
        subtype_patient_info[sp] = patient_info

    # Lấy TARGET = tổng ảnh ít nhất
    TARGET = min(subtype_totals.values())
    print("→ TARGET tổng ảnh mỗi subtype:", TARGET)

    # Xóa bệnh nhân ở những subtype > TARGET
    for sp in subtype_paths:
        total = subtype_totals[sp]
        patient_info = subtype_patient_info[sp]

        if total <= TARGET:
            continue  # đã thỏa cân bằng, không xóa

        # Sắp xếp bệnh nhân theo tổng ảnh giảm dần
        patients_sorted = sorted(patient_info.items(), key=lambda x: x[1], reverse=True)

        while total > TARGET and len(patients_sorted) > 1:
            patient, patient_total = patients_sorted.pop(0)
            print(f"  - Xóa bệnh nhân {patient} ở {sp}, tổng ảnh {patient_total}")
            shutil.rmtree(os.path.join(sp, patient))
            total -= patient_total
# ---
def merge_patients_by_magnification(root_path):
    """
    Gộp ảnh từ các thư mục bệnh nhân (patient folders) theo từng độ phóng đại (40X, 100X, 200X, 400X)
    vào 4 thư mục chung trong mỗi subtype.
    """

    for subtype in os.listdir(root_path):
        subtype_path = os.path.join(root_path, subtype)
        if not os.path.isdir(subtype_path):
            continue

        print(f"🔄 Đang xử lý subtype: {subtype}...")

        # Tạo thư mục magnification chung (40X, 100X, 200X, 400X)
        for mag in magnifications:
            os.makedirs(os.path.join(subtype_path, mag), exist_ok=True)

        # Duyệt tất cả patient
        for patient in os.listdir(subtype_path):
            patient_path = os.path.join(subtype_path, patient)

            # Bỏ qua thư mục magnification
            if patient in magnifications:
                continue
            if not os.path.isdir(patient_path):
                continue

            # Copy ảnh từng magnification sang thư mục chung
            for mag in magnifications:
                mag_src = os.path.join(patient_path, mag)
                mag_dst = os.path.join(subtype_path, mag)

                if not os.path.isdir(mag_src):
                    continue

                for file in os.listdir(mag_src):
                    src_file = os.path.join(mag_src, file)
                    if os.path.isfile(src_file):

                        new_filename = f"{patient}_{file}"   # thêm prefix patient
                        dst_file = os.path.join(mag_dst, new_filename)

                        shutil.copy(src_file, dst_file)

            # Xóa thư mục patient sau khi copy xong
            shutil.rmtree(patient_path)

        print(f"✔ Hoàn tất gộp và xóa folder bệnh nhân cho subtype: {subtype}\n")
#=========================
# Chạy cân bằng cho từng split
#=========================
for split in ["train", "validation", "test"]:
    split_path = os.path.join(train_data_path, split)
    print(f"\n=== Balancing {split} ===")
    balance_split(split_path)
    merge_patients_by_magnification(split_path)
    
print("\nDONE BALANCING.")
statistic = count_and_plot_images_flat()
