# Cắt patch (Patchify)
def extract_patches(image_path, patch_size=224):
    img = cv2.imread(image_path)
    h, w, _ = img.shape
    patches = []

    for y in range(0, h, patch_size):
        for x in range(0, w, patch_size):
            patch = img[y:y+patch_size, x:x+patch_size]
            if patch.shape[0] != patch_size or patch.shape[1] != patch_size:
                continue
            patches.append(patch)
    return patches

# Dataset & DataLoader
class HistologyDataset(Dataset):
    def __init__(self, root_dir, magnification='40X', transform=None):
        self.samples = []
        self.labels = []
        self.classes = sorted(os.listdir(root_dir))
        self.transform = transform

        for idx, subtype in enumerate(self.classes):
            mag_path = os.path.join(root_dir, subtype, magnification)
            if not os.path.isdir(mag_path):
                continue
            for file in os.listdir(mag_path):
                if file.endswith('.png'):
                    self.samples.append(os.path.join(mag_path, file))
                    self.labels.append(idx)
    
    def __len__(self):
        return len(self.samples)
    
    def __getitem__(self, idx):
        img = Image.open(self.samples[idx]).convert('RGB')
        if self.transform:
            img = self.transform(img)
        label = self.labels[idx]
        return img, label

# Transformations
transform = transforms.Compose([
    transforms.Resize((224,224)),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
])

# Khởi tạo ViT
num_classes = len(os.listdir("train_data/train"))

model = timm.create_model('vit_base_patch16_224', pretrained=True, num_classes=num_classes)
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model.to(device)

# Train loop
criterion = CrossEntropyLoss()
optimizer = optim.AdamW(model.parameters(), lr=1e-4)

def train(model, dataloader, epochs=5):
    model.train()
    for epoch in range(epochs):
        total_loss = 0
        for imgs, labels in dataloader:
            imgs, labels = imgs.to(device), labels.to(device)
            optimizer.zero_grad()
            outputs = model(imgs)
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()
            total_loss += loss.item()
        print(f"Epoch {epoch+1}/{epochs}, Loss: {total_loss/len(dataloader):.4f}")
        
# Evaluation
def evaluate(model, dataloader):
    model.eval()
    preds = []
    labels_all = []
    with torch.no_grad():
        for imgs, labels in dataloader:
            imgs = imgs.to(device)
            outputs = model(imgs)
            _, predicted = torch.max(outputs, 1)
            preds.extend(predicted.cpu().numpy())
            labels_all.extend(labels.numpy())
    
    acc = accuracy_score(labels_all, preds)
    cm = confusion_matrix(labels_all, preds)
    print(f"Accuracy: {acc:.4f}")
    print("Confusion matrix:\n", cm)

# Run
train_dataset = HistologyDataset("train_data/train", magnification='40X', transform=transform)
train_loader = DataLoader(train_dataset, batch_size=16, shuffle=True)

train(model, train_loader, epochs=3)
evaluate(model, train_loader)
