# ===================== Device =====================
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Using device:", device)

magnifications = ["40X", "100X", "200X", "400X"]

# ===================== Dataset =====================
class HistologyDatasetAllMag(Dataset):
    def __init__(self, root_dir, transform=None, max_patches_per_mag=10):
        self.samples = []  # list of (subtype_path, label)
        self.labels = []
        self.transform = transform
        self.max_patches_per_mag = max_patches_per_mag  # giới hạn patch mỗi mag

        self.classes = sorted([d for d in os.listdir(root_dir) if os.path.isdir(os.path.join(root_dir, d))])
        for idx, subtype in enumerate(self.classes):
            subtype_path = os.path.join(root_dir, subtype)
            has_mag = any(os.path.isdir(os.path.join(subtype_path, mag)) for mag in magnifications)
            if has_mag:
                self.samples.append(subtype_path)
                self.labels.append(idx)
    
    def __len__(self):
        return len(self.samples)
    
    def __getitem__(self, idx):
        slide_path = self.samples[idx]
        label = self.labels[idx]
        all_patches = []

        for mag in magnifications:
            mag_path = os.path.join(slide_path, mag)
            if os.path.isdir(mag_path):
                files = [f for f in os.listdir(mag_path) if f.endswith('.png')]
                files = files[:self.max_patches_per_mag]  # giới hạn patch để tiết kiệm VRAM
                for file in files:
                    img = Image.open(os.path.join(mag_path, file)).convert('RGB')
                    if self.transform:
                        img = self.transform(img)
                    all_patches.append(img)
        
        if len(all_patches) == 0:
            img = Image.new('RGB', (224,224))
            if self.transform:
                img = self.transform(img)
            all_patches.append(img)
        
        all_patches = torch.stack(all_patches)  # [N_patches, C, H, W]
        return all_patches, label

# ===================== Transform =====================
transform = transforms.Compose([
    transforms.Resize((224,224)),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
])

# ===================== Model =====================
class PatchTransformerMIL(nn.Module):
    def __init__(self, num_classes):
        super().__init__()
        self.encoder = timm.create_model('vit_base_patch16_224', pretrained=True, num_classes=0)
        self.hidden_dim = self.encoder.num_features
        self.classifier = nn.Linear(self.hidden_dim, num_classes)
    
    def forward(self, x):
        N = x.shape[0]
        feats = []
        for i in range(N):
            feat = self.encoder(x[i].unsqueeze(0))  # [1, hidden_dim]
            feats.append(feat)
        feats = torch.cat(feats, dim=0)  # [N_patches, hidden_dim]
        pooled = feats.mean(dim=0, keepdim=True)  # mean pooling
        out = self.classifier(pooled)
        return out

# ===================== Load dataset =====================
train_dataset = HistologyDatasetAllMag("train_data/train", transform=transform, max_patches_per_mag=10)
train_loader = DataLoader(train_dataset, batch_size=1, shuffle=True)

num_classes = len([d for d in os.listdir("train_data/train") if os.path.isdir(os.path.join("train_data/train", d))])
model = PatchTransformerMIL(num_classes).to(device)

criterion = nn.CrossEntropyLoss()
optimizer = torch.optim.AdamW(model.parameters(), lr=1e-4)

# ===================== Train =====================
def train(model, dataloader, epochs=3):
    model.train()
    for epoch in range(epochs):
        total_loss = 0
        for patches, labels in dataloader:
            labels = labels.to(device)
            patches = patches.squeeze(0).to(device)
            optimizer.zero_grad()
            outputs = model(patches)
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()
            total_loss += loss.item()
        print(f"Epoch {epoch+1}/{epochs}, Loss: {total_loss/len(dataloader):.4f}")

# ===================== Evaluate =====================
def evaluate(model, dataloader):
    model.eval()
    preds = []
    labels_all = []
    with torch.no_grad():
        for patches, labels in dataloader:
            labels_all.append(labels.item())
            patches = patches.squeeze(0).to(device)
            outputs = model(patches)
            _, predicted = torch.max(outputs, 1)
            preds.append(predicted.item())
    
    acc = accuracy_score(labels_all, preds)
    cm = confusion_matrix(labels_all, preds)
    print(f"Accuracy: {acc:.4f}")
    print("Confusion matrix:\n", cm)

# ===================== Run =====================
train(model, train_loader, epochs=3)
evaluate(model, train_loader)
