DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Using device:", DEVICE)

DATA_PATH = "train_data"      # thư mục chứa train/validation/test
BATCH_SIZE = 16
EPOCHS = 5
LR = 1e-4
MAGNIFICATIONS = ["40X", "100X", "200X", "400X"]
IMG_SIZE = 224

# =====================
# ==== DATASET ========
# =====================
class HistologyDataset(Dataset):
    def __init__(self, root_dir, transform=None):
        self.samples = []
        self.labels = []
        self.transform = transform
        self.classes = sorted([d for d in os.listdir(root_dir) if os.path.isdir(os.path.join(root_dir, d))])

        for idx, subtype in enumerate(self.classes):
            subtype_path = os.path.join(root_dir, subtype)
            for mag in MAGNIFICATIONS:
                mag_path = os.path.join(subtype_path, mag)
                if not os.path.isdir(mag_path):
                    continue
                for f in os.listdir(mag_path):
                    if f.endswith(".png"):
                        self.samples.append(os.path.join(mag_path, f))
                        self.labels.append(idx)
    
    def __len__(self):
        return len(self.samples)
    
    def __getitem__(self, idx):
        img = Image.open(self.samples[idx]).convert('RGB')
        if self.transform:
            img = self.transform(img)
        label = self.labels[idx]
        return img, label

# =====================
# ==== TRANSFORMS =====
# =====================
transform = transforms.Compose([
    transforms.Resize((IMG_SIZE, IMG_SIZE)),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
])

# =====================
# ==== DATALOADERS ====
# =====================
train_dataset = HistologyDataset(os.path.join(DATA_PATH, "train"), transform=transform)
val_dataset   = HistologyDataset(os.path.join(DATA_PATH, "validation"), transform=transform)
test_dataset  = HistologyDataset(os.path.join(DATA_PATH, "test"), transform=transform)

train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, shuffle=True)
val_loader   = DataLoader(val_dataset, batch_size=BATCH_SIZE, shuffle=False)
test_loader  = DataLoader(test_dataset, batch_size=BATCH_SIZE, shuffle=False)

# =====================
# ==== MODEL ==========
# =====================
NUM_CLASSES = len(train_dataset.classes)
model = timm.create_model('vit_base_patch16_224', pretrained=True, num_classes=NUM_CLASSES)
model.to(DEVICE)

criterion = nn.CrossEntropyLoss()
optimizer = optim.AdamW(model.parameters(), lr=LR)

# =====================
# ==== TRAIN ==========
# =====================
def train(model, train_loader, val_loader=None, epochs=EPOCHS):
    for epoch in range(epochs):
        model.train()
        total_loss = 0
        for imgs, labels in train_loader:
            imgs, labels = imgs.to(DEVICE), labels.to(DEVICE)
            optimizer.zero_grad()
            outputs = model(imgs)
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()
            total_loss += loss.item()
        avg_loss = total_loss / len(train_loader)
        print(f"Epoch {epoch+1}/{epochs}, Loss: {avg_loss:.4f}")
        
        if val_loader:
            evaluate(model, val_loader, split="Validation")

# =====================
# ==== EVALUATE =======
# =====================
def evaluate(model, loader, split="Test"):
    model.eval()
    preds = []
    labels_all = []
    with torch.no_grad():
        for imgs, labels in loader:
            imgs = imgs.to(DEVICE)
            outputs = model(imgs)
            _, predicted = torch.max(outputs, 1)
            preds.extend(predicted.cpu().numpy())
            labels_all.extend(labels.numpy())
    
    acc = accuracy_score(labels_all, preds)
    cm = confusion_matrix(labels_all, preds)
    print(f"{split} Accuracy: {acc:.4f}")
    print(f"{split} Confusion Matrix:\n", cm)

# =====================
# ==== RUN ===========
# =====================
train(model, train_loader, val_loader=val_loader, epochs=EPOCHS)
print("\n=== TEST SET ===")
evaluate(model, test_loader, split="Test")
