# ========== Transforms ==========
train_transform = transforms.Compose([
    transforms.Resize((IMG_SIZE, IMG_SIZE)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(10),
    transforms.ColorJitter(brightness=0.1, contrast=0.1, saturation=0.1),
    transforms.ToTensor(),
])

eval_transform = transforms.Compose([
    transforms.Resize((IMG_SIZE, IMG_SIZE)),
    transforms.ToTensor(),
])

# ========== Helpers: train/validate/test per mag ==========
def make_dataloaders_for_mag(mag, batch_size=BATCH_SIZE):
    train_dir = os.path.join(DATA_PATH, "train")
    val_dir = os.path.join(DATA_PATH, "validation")
    test_dir = os.path.join(DATA_PATH, "test")

    train_ds = HistologyMagDataset(train_dir, mag, transform=train_transform)
    val_ds = HistologyMagDataset(val_dir, mag, transform=eval_transform)
    test_ds = HistologyMagDataset(test_dir, mag, transform=eval_transform)

    train_loader = DataLoader(train_ds, batch_size=batch_size, shuffle=True, num_workers=4, pin_memory=True)
    val_loader = DataLoader(val_ds, batch_size=batch_size, shuffle=False, num_workers=4, pin_memory=True)
    test_loader = DataLoader(test_ds, batch_size=batch_size, shuffle=False, num_workers=4, pin_memory=True)

    classes = train_ds.classes
    return train_loader, val_loader, test_loader, classes

def build_model(num_classes, model_type=MODEL_TYPE):
    model = timm.create_model(model_type, pretrained=True, num_classes=num_classes)
    model = model.to(DEVICE)
    return model

def evaluate_model(model, loader):
    model.eval()
    preds = []
    trues = []
    with torch.no_grad():
        for imgs, labels in loader:
            imgs = imgs.to(DEVICE)
            outputs = model(imgs)
            _, p = torch.max(outputs, 1)
            preds.extend(p.cpu().numpy())
            trues.extend(labels.numpy())
    acc = accuracy_score(trues, preds)
    report = classification_report(trues, preds, zero_division=0, output_dict=True)
    cm = confusion_matrix(trues, preds)
    return acc, report, cm

def train_and_evaluate_for_mag(mag):
    print(f"\n===== TRAINING for magnification {mag} =====")
    train_loader, val_loader, test_loader, classes = make_dataloaders_for_mag(mag)
    if len(train_loader.dataset) == 0:
        print(f"No training images for magnification {mag}, skipping.")
        return None

    num_classes = len(classes)
    model = build_model(num_classes)
    criterion = nn.CrossEntropyLoss()
    optimizer = optim.AdamW(model.parameters(), lr=LR)
    scaler = torch.cuda.amp.GradScaler() if USE_MIXED_PRECISION else None

    best_val_acc = 0.0
    best_epoch = -1
    patience_counter = 0
    best_path = os.path.join(OUT_DIR, f"best_{mag}.pth")

    for epoch in range(1, EPOCHS+1):
        model.train()
        running_loss = 0.0
        loop = tqdm(train_loader, desc=f"{mag} Epoch {epoch}/{EPOCHS}", leave=False)
        for imgs, labels in loop:
            imgs = imgs.to(DEVICE)
            labels = labels.to(DEVICE)
            optimizer.zero_grad()
            if USE_MIXED_PRECISION:
                with torch.cuda.amp.autocast():
                    outputs = model(imgs)
                    loss = criterion(outputs, labels)
                scaler.scale(loss).backward()
                scaler.step(optimizer)
                scaler.update()
            else:
                outputs = model(imgs)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()
            running_loss += loss.item()
            loop.set_postfix(loss=running_loss/((loop.n+1)))
        avg_loss = running_loss / len(train_loader)
        # Validate
        val_acc, val_report, val_cm = evaluate_model(model, val_loader)
        print(f"[{mag}] Epoch {epoch} loss {avg_loss:.4f} | val_acc {val_acc:.4f}")

        # Early stopping check
        if val_acc > best_val_acc + 1e-6:
            best_val_acc = val_acc
            best_epoch = epoch
            patience_counter = 0
            torch.save({
                "epoch": epoch,
                "model_state": model.state_dict(),
                "optimizer_state": optimizer.state_dict(),
                "val_acc": val_acc,
                "classes": classes
            }, best_path)
            print(f"  -> New best model saved (val_acc={val_acc:.4f})")
        else:
            patience_counter += 1
            print(f"  -> no improvement ({patience_counter}/{PATIENCE})")
            if patience_counter >= PATIENCE:
                print("  -> Early stopping triggered")
                break

    # Load best model
    if os.path.exists(best_path):
        ckpt = torch.load(best_path, map_location=DEVICE)
        model.load_state_dict(ckpt["model_state"])
    # Final evaluation on validation & test
    val_acc, val_report, val_cm = evaluate_model(model, val_loader)
    test_acc, test_report, test_cm = evaluate_model(model, test_loader)
    print(f"*** BEST {mag}: val_acc={val_acc:.4f} | test_acc={test_acc:.4f} ***")
    return {
        "mag": mag,
        "classes": classes,
        "best_val_acc": val_acc,
        "test_acc": test_acc,
        "val_cm": val_cm,
        "test_cm": test_cm,
        "val_report": val_report,
        "test_report": test_report,
        "model_path": best_path
    }

# ========== Run training for each magnification ==========
results = []
for mag in MAGNIFICATIONS:
    res = train_and_evaluate_for_mag(mag)
    if res:
        results.append(res)

# ========== Summary ==========
print("\n\n=== SUMMARY (per magnification) ===")
for r in results:
    print(f"{r['mag']}: val_acc={r['best_val_acc']:.4f} | test_acc={r['test_acc']:.4f} | saved={r['model_path']}")

# Optionally you can save summary to disk
import json
with open(os.path.join(OUT_DIR, "summary_by_mag.json"), "w") as f:
    json.dump([{
        "mag": r["mag"],
        "val_acc": r["best_val_acc"],
        "test_acc": r["test_acc"],
        "model_path": r["model_path"]
    } for r in results], f, indent=2)
