def count_and_plot_images():
    """
    Đếm số lượng ảnh theo Class/Subtype/Magnification và vẽ biểu đồ.
    
    Returns:
        pd.DataFrame: DataFrame chứa thông tin số lượng ảnh
    """
    
    data_counts = {split: {} for split in splits}
    
    # --- Đếm số ảnh ---
    data_counts = {split: {} for split in splits}
    
    for split in splits:
        split_path = os.path.join(train_data_path, split)
        for main_class in os.listdir(split_path):
            class_path = os.path.join(split_path, main_class)
            if not os.path.isdir(class_path):
                continue
            for subtype in os.listdir(class_path):
                subtype_path = os.path.join(class_path, subtype)
                if not os.path.isdir(subtype_path):
                    continue

                for mag in magnifications:
                    n_images_total = 0
                    for patient in os.listdir(subtype_path):
                        patient_path = os.path.join(subtype_path, patient)
                        if not os.path.isdir(patient_path):
                            continue
                        mag_path = os.path.join(patient_path, mag)
                        if not os.path.isdir(mag_path):
                            continue
                        n_images_total += len([f for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))])

                    key = f"{main_class}/{subtype}/{mag}"
                    data_counts[split][key] = n_images_total

    # --- Tạo DataFrame ---
    all_data = []
    for split in splits:
        for cls_subtype_mag, count in data_counts[split].items():
            main_class, subtype, mag = cls_subtype_mag.split("/")
            all_data.append({
                "Split": split,
                "Class": main_class,
                "Subtype": subtype,
                "Magnification": mag,
                "Num_Images": count
            })

    df = pd.DataFrame(all_data)

    # --- Vẽ biểu đồ ---
    for split in splits:
        df_split = df[df['Split'] == split]
        
        plt.figure(figsize=(12,6))
        sns.barplot(
            data=df_split,
            x="Subtype",
            y="Num_Images",
            hue="Magnification",
            errorbar=None,
            palette="Set2"
        )
        plt.title(f"SỐ LƯỢNG HÌNH ẢNH THEO NHÓM BỆNH ({split})")
        plt.xlabel("Loại bệnh")
        plt.ylabel("Số lượng hình ảnh")
        plt.xticks(rotation=45)
        plt.legend(title="Độ phóng đại")
        plt.tight_layout()
        plt.show()
    
        # --- Hiển thị DataFrame ---
        pd.set_option('display.max_rows', None)
        pd.set_option('display.max_columns', None)
        pd.set_option('display.max_colwidth', None)
        print("=== BẢNG DỮ LIỆU ĐẦY ĐỦ ===")
        print(df)

def count_images_per_split_flat(split_path):
    """
    Đếm tổng số ảnh cho từng nhóm Subtype/Magnification trong 1 split đã flatten.
    Trả về dict: { "subtype/mag" : count }
    """
    result = {}

    # Lấy danh sách tất cả folder subtype trực tiếp trong split_path
    for subtype in os.listdir(split_path):
        subtype_path = os.path.join(split_path, subtype)
        if not os.path.isdir(subtype_path):
            continue

        # Đếm ảnh từng magnification
        for mag in magnifications:
            mag_path = os.path.join(subtype_path, mag)
            count = 0
            if os.path.isdir(mag_path):
                count = len([
                    f for f in os.listdir(mag_path)
                    if os.path.isfile(os.path.join(mag_path, f))
                ])
            key = f"{subtype}/{mag}"
            result[key] = count

    return result


def count_and_plot_images_flat():
    """
    Đếm số lượng ảnh cho từng split sau khi flatten và vẽ biểu đồ.
    """
    data_counts = {}

    # --- Đếm các split ---
    for split in splits:
        split_path = os.path.join(train_data_path, split)
        if not os.path.exists(split_path):
            continue

        data_counts[split] = count_images_per_split_flat(split_path)

    # --- Gom DataFrame ---
    all_data = []
    for split in data_counts:
        for key, count in data_counts[split].items():
            subtype, mag = key.split("/")
            all_data.append({
                "Split": split,
                "Subtype": subtype,
                "Magnification": mag,
                "Num_Images": count
            })

    df = pd.DataFrame(all_data)

    # --- Vẽ biểu đồ ---
    for split in splits:
        df_split = df[df['Split'] == split]
        if df_split.empty:
            continue

        plt.figure(figsize=(12, 6))
        sns.barplot(
            data=df_split,
            x="Subtype",
            y="Num_Images",
            hue="Magnification",
            palette="Set2"
        )
        plt.title(f"SỐ LƯỢNG HÌNH ẢNH THEO NHÓM BỆNH ({split})")
        plt.xlabel("Subtype")
        plt.ylabel("Số lượng hình ảnh")
        plt.xticks(rotation=45)
        plt.legend(title="Độ phóng đại")
        plt.tight_layout()
        plt.show()

    print("=== BẢNG DỮ LIỆU ĐẦY ĐỦ ===")
    print(df)

    return df


