            class_path = os.path.join(split_path, main_class)
            if not os.path.isdir(class_path):
                continue
            for subtype in os.listdir(class_path):
                subtype_path = os.path.join(class_path, subtype)
                if not os.path.isdir(subtype_path):
                    continue

                for mag in magnifications:
                    n_images_total = 0
                    for patient in os.listdir(subtype_path):
                        patient_path = os.path.join(subtype_path, patient)
                        if not os.path.isdir(patient_path):
                            continue
                        mag_path = os.path.join(patient_path, mag)
                        if not os.path.isdir(mag_path):
                            continue
                        n_images_total += len([f for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))])

                    key = f"{main_class}/{subtype}/{mag}"
