def count_images(path):
    return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])

def get_subtype_total(subtype_path):
    total = 0
    patient_info = {}
    for patient in os.listdir(subtype_path):
        p_path = os.path.join(subtype_path, patient)
        if not os.path.isdir(p_path):
            continue
        patient_total = 0
        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                patient_total += count_images(mag_path)
        patient_info[patient] = patient_total
        total += patient_total
    return total, patient_info

def balance_train_and_split(train_path, val_path, test_path, val_ratio=0.5, test_ratio=0.5):
    """
    Cân bằng train và chuyển phần dư sang validation/test
    """
    for main_class in os.listdir(train_path):
        class_path = os.path.join(train_path, main_class)
        if not os.path.isdir(class_path):
            continue

        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if not os.path.isdir(subtype_path):
                continue

            total, patient_info = get_subtype_total(subtype_path)
            TARGET = min([get_subtype_total(os.path.join(class_path, s))[0] for s in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, s))])
            print(f"🔹 Subtype {subtype}, tổng ảnh {total}, TARGET={TARGET}")

            # Sắp xếp bệnh nhân theo tổng ảnh giảm dần
            patients_sorted = sorted(patient_info.items(), key=lambda x: x[1], reverse=True)

            # Di chuyển dư sang validation/test
            while total > TARGET and len(patients_sorted) > 1:
                patient, patient_total = patients_sorted.pop(0)
                total -= patient_total

                # Chọn split: validation hoặc test
                dst_split = val_path if random.random() < val_ratio else test_path
                dst_subtype_path = os.path.join(dst_split, subtype)
                os.makedirs(dst_subtype_path, exist_ok=True)

                # Di chuyển toàn bộ folder patient
                shutil.move(os.path.join(subtype_path, patient), dst_subtype_path)
                print(f"   → Chuyển bệnh nhân {patient} ({patient_total} ảnh) sang {dst_split}/{subtype}")

def merge_patients_flat(root_path):
    """
    Flatten toàn bộ patient → subtype/magnification
    """
    for subtype in os.listdir(root_path):
        subtype_path = os.path.join(root_path, subtype)
        if not os.path.isdir(subtype_path):
            continue
        for patient in os.listdir(subtype_path):
            patient_path = os.path.join(subtype_path, patient)
            if not os.path.isdir(patient_path):
                continue
            for mag in magnifications:
                mag_src = os.path.join(patient_path, mag)
                mag_dst = os.path.join(subtype_path, mag)
                os.makedirs(mag_dst, exist_ok=True)
                if os.path.isdir(mag_src):
                    for file in os.listdir(mag_src):
                        src_file = os.path.join(mag_src, file)
                        if os.path.isfile(src_file):
                            shutil.move(src_file, os.path.join(mag_dst, f"{patient}_{file}"))
            shutil.rmtree(patient_path)
        print(f"✔ Flatten xong subtype: {subtype}")

# --- Ví dụ sử dụng ---
train_path = "train_data/train"
val_path = "train_data/validation"
test_path = "train_data/test"

balance_train_and_split(train_path, val_path, test_path, val_ratio=0.5, test_ratio=0.5)

# Flatten từng split
for split in [train_path, val_path, test_path]:
    merge_patients_flat(split)

count_and_plot_images_flat()
