    # --- Gom DataFrame ---
    all_data = []
    for split in data_counts:
        for key, count in data_counts[split].items():
            subtype, mag = key.split("/")
            all_data.append({
                "Split": split,
                "Subtype": subtype,
                "Magnification": mag,
                "Num_Images": count
            })

    df = pd.DataFrame(all_data)

    # --- Vẽ biểu đồ ---
    for split in splits:
        df_split = df[df['Split'] == split]
        if df_split.empty:
            continue

        plt.figure(figsize=(12, 6))
        sns.barplot(
            data=df_split,
            x="Subtype",
            y="Num_Images",
            hue="Magnification",
            palette="Set2"
        )
