            if total - patient_total >= TARGET:
                if split == 'train':
                    # --- Chuyển patient sang validation hoặc test ---
                    class_name = os.path.basename(os.path.dirname(sp))
                    subtype_name = os.path.basename(sp)

                    # Chọn đích
