def augment_image(img):
    img = img.convert("RGB")
    applied = []

    # Rotate / Flip
    angle = random.choice([90, 180, 270])
    img = img.rotate(angle)
    applied.append(f"rot{angle}")

    if random.random() > 0.5:
        img = img.transpose(Image.FLIP_LEFT_RIGHT)
        applied.append("flipLR")
    if random.random() > 0.5:
        img = img.transpose(Image.FLIP_TOP_BOTTOM)
        applied.append("flipTB")

    # Brightness & Contrast
    img = ImageEnhance.Brightness(img).enhance(random.uniform(0.8, 1.2))
    img = ImageEnhance.Contrast(img).enhance(random.uniform(0.8, 1.2))
    applied.append("bright")

    # Gamma
    img = gamma_correction(img)
    applied.append("gamma")

    # Color jitter
    img = color_jitter(img)
    applied.append("color")

    # Noise
    img = add_noise(img)
    applied.append("noise")

    return img, applied

# Làm giàu 1 nhóm
def augment_group(group_path, target_count):
    files = [f for f in os.listdir(group_path) if os.path.isfile(os.path.join(group_path, f))]
    if not files: return
    current_count = len(files)
    needed = target_count - current_count
    if needed <= 0: return

    # Lưu kiểu augment đã dùng cho mỗi ảnh gốc
    augment_history = {f: set() for f in files}

    for _ in range(needed):
        orig_file = random.choice(files)
        img_path = os.path.join(group_path, orig_file)
        img = Image.open(img_path)

        # Thử augment mới khác kiểu cũ
        for _ in range(10):  # tối đa 10 lần thử
            img_aug, aug_types = augment_image(img)
            aug_label = "_".join(aug_types)
            if aug_label not in augment_history[orig_file]:
                augment_history[orig_file].add(aug_label)
                break
        else:
            # Nếu tất cả kiểu đã thử đều trùng, bỏ qua
            print(f"⚠ Không thể tạo kiểu mới cho {orig_file}")
            continue

