# ========== CONFIG ==========
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

DATA_PATH = "train_data"            # train/validation/test folders
MAGNIFICATIONS = ["40X","100X","200X","400X"]
IMG_SIZE = 224
BATCH_SIZE = 32                    # giảm từ 80 -> 32 (an toàn hơn với VRAM)
EPOCHS = 30
LR = 5e-5                          # nhỏ hơn 1e-4 để fine-tune ổn định
MODEL_TYPE = "convnext_tiny"
PATIENCE = 15                      # tăng patience vì val có thể dao động
USE_MIXED_PRECISION = True
NUMBER_OF_WORKER = 0               # 0 an toàn trên Windows; tăng lên 4-8 trên Linux
FREEZE_FEATURES = True             # freeze feature extractor trong vài epoch đầu
UNFREEZE_AFTER = 3                 # số epoch để unfreeze (nếu FREEZE_FEATURES=True)

OUT_DIR = "models_all_mag"
os.makedirs(OUT_DIR, exist_ok=True)

# ImageNet normalize (ConvNeXt pretrained)
IMAGENET_MEAN = [0.485, 0.456, 0.406]
IMAGENET_STD  = [0.229, 0.224, 0.225]

# ========== Dataset: gộp tất cả magnification ==========
class HistologyAllMagDataset(Dataset):
    """
    Lấy tất cả ảnh của tất cả magnification.
    structure: root/subtype/<mag>/*.png
    """
    def __init__(self, root_dir, transform=None, mags=None):
        self.samples = []
        self.labels = []
        self.transform = transform
        self.mags = mags if mags is not None else MAGNIFICATIONS

        # lấy danh sách subtype (classes)
        self.classes = sorted([
            d for d in os.listdir(root_dir)
            if os.path.isdir(os.path.join(root_dir, d))
        ])

        for idx, subtype in enumerate(self.classes):
            subtype_dir = os.path.join(root_dir, subtype)
            for mag in self.mags:
                mag_dir = os.path.join(subtype_dir, mag)
                if not os.path.isdir(mag_dir):
                    continue
                for fname in os.listdir(mag_dir):
                    if fname.lower().endswith((".png", ".jpg", ".jpeg")):
                        self.samples.append(os.path.join(mag_dir, fname))
                        self.labels.append(idx)

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, idx):
        img = Image.open(self.samples[idx]).convert("RGB")
        if self.transform:
            img = self.transform(img)
        label = self.labels[idx]
        return img, label

# ========== Transforms ==========
train_transform = transforms.Compose([
    transforms.RandomResizedCrop(IMG_SIZE, scale=(0.7, 1.0)),   # crop + scale
    transforms.RandomHorizontalFlip(),
    transforms.RandomVerticalFlip(),
    transforms.RandomRotation(20),
    transforms.RandomAffine(degrees=10, translate=(0.05,0.05), scale=(0.9,1.1), shear=5),
    transforms.ColorJitter(brightness=0.2, contrast=0.2, saturation=0.2, hue=0.02),
    transforms.GaussianBlur(kernel_size=3),
    transforms.ToTensor(),
    transforms.Normalize(mean=IMAGENET_MEAN, std=IMAGENET_STD),
    transforms.RandomErasing(p=0.2, scale=(0.02, 0.15))       # thêm randomness
])

eval_transform = transforms.Compose([
    transforms.Resize((IMG_SIZE, IMG_SIZE)),
    transforms.ToTensor(),
    transforms.Normalize(mean=IMAGENET_MEAN, std=IMAGENET_STD),
])

# ========== Helpers: dataloaders, model, evaluate ==========
def make_dataloaders(batch_size=BATCH_SIZE):
    train_dir = os.path.join(DATA_PATH, "train")
    val_dir = os.path.join(DATA_PATH, "validation")
    test_dir = os.path.join(DATA_PATH, "test")

    train_ds = HistologyAllMagDataset(train_dir, transform=train_transform)
    val_ds = HistologyAllMagDataset(val_dir, transform=eval_transform)
    test_ds = HistologyAllMagDataset(test_dir, transform=eval_transform)

    train_loader = DataLoader(train_ds, batch_size=batch_size, shuffle=True,
                              num_workers=NUMBER_OF_WORKER, pin_memory=True)
    val_loader = DataLoader(val_ds, batch_size=batch_size, shuffle=False,
                            num_workers=NUMBER_OF_WORKER, pin_memory=True)
    test_loader = DataLoader(test_ds, batch_size=batch_size, shuffle=False,
                             num_workers=NUMBER_OF_WORKER, pin_memory=True)

    classes = train_ds.classes
    print("Classes:", classes)
    print("Counts -> train:", len(train_ds), "val:", len(val_ds), "test:", len(test_ds))
    return train_loader, val_loader, test_loader, classes

def build_model(num_classes, model_type=MODEL_TYPE, pretrained=True):
    model = timm.create_model(model_type, pretrained=pretrained, num_classes=num_classes)
    model = model.to(DEVICE)
    return model

def evaluate_model(model, loader):
    model.eval()
    preds = []
    trues = []
    with torch.no_grad():
        for imgs, labels in loader:
            imgs = imgs.to(DEVICE)
            labels = labels.to(DEVICE)
            outputs = model(imgs)
            _, p = torch.max(outputs, 1)
            preds.extend(p.cpu().numpy())
            trues.extend(labels.cpu().numpy())
    acc = accuracy_score(trues, preds) if len(trues) > 0 else 0.0
    report = classification_report(trues, preds, zero_division=0, output_dict=True) if len(trues)>0 else {}
    cm = confusion_matrix(trues, preds) if len(trues)>0 else np.zeros((1,1))
    return acc, report, cm

# ========== TRAIN LOOP (gộp all mags) ==========
def train_all_mags():
    train_loader, val_loader, test_loader, classes = make_dataloaders()
    if len(train_loader.dataset) == 0:
        print("No training images found. Check DATA_PATH.")
        return

    num_classes = len(classes)
    model = build_model(num_classes)
    criterion = nn.CrossEntropyLoss()
    optimizer = optim.AdamW(model.parameters(), lr=LR, weight_decay=1e-2)
    scaler = torch.cuda.amp.GradScaler() if (USE_MIXED_PRECISION and torch.cuda.is_available()) else None

    # Optionally freeze features for a few epochs
    if FREEZE_FEATURES:
        print("Freezing feature extractor parameters (only head will train)...")
        for name, param in model.named_parameters():
            # convnext structure: model.head is classifier; features are earlier modules
            if "head" not in name and "fc" not in name and "classifier" not in name:
                param.requires_grad = False

    best_val_acc = 0.0
    patience_counter = 0
    best_path = os.path.join(OUT_DIR, "best_all_mags.pth")

    for epoch in range(1, EPOCHS+1):
        model.train()
        running_loss = 0.0
        loop = tqdm(train_loader, desc=f"Epoch {epoch}/{EPOCHS}", leave=False)
        for imgs, labels in loop:
            imgs = imgs.to(DEVICE)
            labels = labels.to(DEVICE)
            optimizer.zero_grad()

            if scaler is not None:
                with torch.amp.autocast(device_type='cuda' if torch.cuda.is_available() else 'cpu'):
                    outputs = model(imgs)
                    loss = criterion(outputs, labels)
                scaler.scale(loss).backward()
                scaler.step(optimizer)
                scaler.update()
            else:
                outputs = model(imgs)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()

            running_loss += loss.item() * imgs.size(0)
            loop.set_postfix(loss=running_loss / ((loop.n + 1) * BATCH_SIZE))

        avg_loss = running_loss / len(train_loader.dataset)
        val_acc, val_report, val_cm = evaluate_model(model, val_loader)
        print(f"Epoch {epoch} avg_loss {avg_loss:.4f} | val_acc {val_acc:.4f}")

        # Unfreeze after N epochs (if freezing enabled)
        if FREEZE_FEATURES and epoch == UNFREEZE_AFTER:
            print(f"Unfreezing all model parameters at epoch {epoch}.")
            for param in model.parameters():
                param.requires_grad = True
            # (optional) lower lr a bit
            for g in optimizer.param_groups:
                g['lr'] = LR * 0.5
            print("  -> LR reduced to", optimizer.param_groups[0]['lr'])

        # Early stopping & save best
        if val_acc > best_val_acc + 1e-6:
            best_val_acc = val_acc
            patience_counter = 0
            torch.save({
                "epoch": epoch,
                "model_state": model.state_dict(),
                "optimizer_state": optimizer.state_dict(),
                "val_acc": val_acc,
                "classes": classes
            }, best_path)
            print(f"  -> New best model saved (val_acc={val_acc:.4f})")
        else:
            patience_counter += 1
            print(f"  -> no improvement ({patience_counter}/{PATIENCE})")
            if patience_counter >= PATIENCE:
                print("  -> Early stopping triggered")
                break

    # Load best model
    if os.path.exists(best_path):
        ckpt = torch.load(best_path, map_location=DEVICE)
        model.load_state_dict(ckpt["model_state"])
        print("Loaded best checkpoint:", best_path)

    # Final evaluation on val & test
    val_acc, val_report, val_cm = evaluate_model(model, val_loader)
    test_acc, test_report, test_cm = evaluate_model(model, test_loader)
    print(f"*** BEST (final eval) val_acc={val_acc:.4f} | test_acc={test_acc:.4f} ***")

    # Save summary
    summary = {
        "val_acc": val_acc,
        "test_acc": test_acc,
        "val_report": val_report,
        "test_report": test_report
    }
    with open(os.path.join(OUT_DIR, "summary_all_mag.json"), "w") as f:
        json.dump(summary, f, indent=2)

    return best_path, summary

if __name__ == "__main__":
    best_model, summary = train_all_mags()
    print("Done. Best model:", best_model)
    print("Summary:", summary)
