def chart_table(dataFrame):
    # --- Vẽ biểu đồ ---
    for split in splits:
        df_split = dataFrame[dataFrame['Split'] == split]
        if df_split.empty:
            continue

        plt.figure(figsize=(12, 6))
        sns.barplot(
            data=df_split,
            x="Subtype",
            y="Num_Images",
            hue="Magnification",
            palette="Set2"
        )
        plt.title(f"SỐ LƯỢNG HÌNH ẢNH THEO NHÓM BỆNH ({split})")
        plt.xlabel("Subtype")
        plt.ylabel("Số lượng hình ảnh")
        plt.xticks(rotation=45)
        plt.legend(title="Độ phóng đại")
        plt.tight_layout()
        plt.show()
    
    # --- Xuất dữ liệu bảng ---    
    print(dataFrame)
