# =========================
# Hàm đếm số ảnh trong folder
# =========================
def count_images(path):
    return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])

# =========================
# Tính tổng số ảnh của một subtype (cộng tất cả patient và magnifications)
# =========================
def get_subtype_total(subtype_path):
    total = 0
    patient_info = {}
    for patient in os.listdir(subtype_path):
        p_path = os.path.join(subtype_path, patient)
        if not os.path.isdir(p_path):
            continue

        patient_total = 0
        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                patient_total += count_images(mag_path)

        patient_info[patient] = patient_total
        total += patient_total

    return total, patient_info

# =========================
# Cân bằng số ảnh cho một split (train/validation/test)
# =========================
def balance_split(split):
    split_path = os.path.join(train_data_path, split)
    
    # Lấy danh sách tất cả subtype trong split
    subtype_paths = []
    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path):
            continue
        for subtype in os.listdir(class_path):
            subtype_path = os.path.join(class_path, subtype)
            if os.path.isdir(subtype_path):
                subtype_paths.append(subtype_path)

    # Tính tổng số ảnh của mỗi subtype
    subtype_totals = {}
    subtype_patient_info = {}
    for sp in subtype_paths:
        total, patient_info = get_subtype_total(sp)
        subtype_totals[sp] = total
        subtype_patient_info[sp] = patient_info

    # Lấy TARGET = tổng ảnh ít nhất
    TARGET = min(subtype_totals.values())
    print("→ TARGET tổng ảnh mỗi subtype:", TARGET)

    # Xóa patient thừa để cân bằng
    for sp in subtype_paths:
        total = subtype_totals[sp]
        patient_info = subtype_patient_info[sp]

        if total <= TARGET:
            continue  # đã thỏa cân bằng

        # Sắp xếp patient theo tổng ảnh giảm dần
        patients_sorted = sorted(patient_info.items(), key=lambda x: x[1], reverse=True)

        changeToTest = False
        
        while total > TARGET and len(patients_sorted) > 1:
            patient, patient_total = patients_sorted.pop(0)
            if total - patient_total >= TARGET:
                if split == 'train':
                    # --- Chuyển patient sang validation hoặc test ---
                    class_name = os.path.basename(os.path.dirname(sp))
                    subtype_name = os.path.basename(sp)

                    # Chọn đích
                    r = random.random()
                    if r < VALIDATION_RATIO / (VALIDATION_RATIO + TEST_RATIO):
                        dst_root = os.path.join(train_data_path, 'validation')
                    else:
                        dst_root = os.path.join(train_data_path, 'test')

                    # Tạo folder class/subtype nếu chưa có
                    dst_subtype_path = os.path.join(dst_root, class_name, subtype_name)
                    os.makedirs(dst_subtype_path, exist_ok=True)

                    # Di chuyển patient
                    src_patient_path = os.path.join(sp, patient)
                    dst_patient_path = os.path.join(dst_subtype_path, patient)
                    shutil.move(src_patient_path, dst_patient_path)
                    print(f"  - Chuyển patient {patient} ({patient_total} ảnh) sang {dst_subtype_path}") 
                else:
                    print(f"  - Xóa patient {patient} ở {sp}, tổng ảnh {patient_total}")
                    shutil.rmtree(os.path.join(sp, patient))
                total -= patient_total

# =========================
# Flatten tất cả ảnh từ patient → thẳng folder subtype/magnification
# =========================
def merge_patients_flat(root_path):
    for class_or_subtype in os.listdir(root_path):
        path = os.path.join(root_path, class_or_subtype)
        if not os.path.isdir(path):
            continue

        # Kiểm tra nếu đây là folder class (benign/malignant)
        is_class_folder = any(os.path.isdir(os.path.join(path, x)) for x in os.listdir(path))
        if not is_class_folder:
            continue  # folder subtype đã flatten

        for subtype in os.listdir(path):
            subtype_path = os.path.join(path, subtype)
            if not os.path.isdir(subtype_path):
                continue

            print(f"🔄 Xử lý subtype: {subtype}...")

            # Tạo folder subtype mới ở root_path
            new_subtype_path = os.path.join(root_path, subtype)
            os.makedirs(new_subtype_path, exist_ok=True)

            # Tạo folder magnification trong subtype
            for mag in magnifications:
                os.makedirs(os.path.join(new_subtype_path, mag), exist_ok=True)

            # Duyệt tất cả patient
            for patient in os.listdir(subtype_path):
                patient_path = os.path.join(subtype_path, patient)
                if not os.path.isdir(patient_path):
                    continue

                # Copy tất cả ảnh từ mỗi magnification
                for mag in magnifications:
                    mag_src = os.path.join(patient_path, mag)
                    mag_dst = os.path.join(new_subtype_path, mag)
                    if not os.path.isdir(mag_src):
                        continue

                    for file in os.listdir(mag_src):
                        src_file = os.path.join(mag_src, file)
                        if os.path.isfile(src_file):
                            dst_file = os.path.join(mag_dst, f"{patient}_{file}")
                            shutil.copy(src_file, dst_file)

            # Xóa folder subtype cũ
            if os.path.exists(subtype_path):
                shutil.rmtree(subtype_path)
                print(f"✔ Đã gộp subtype: {subtype}")

        # Xóa folder class cũ
        if os.path.exists(path):
            shutil.rmtree(path)
            print(f"🗑 Đã xóa class folder: {class_or_subtype}")

# =========================
# Chạy cân bằng và flatten cho từng split
# =========================
for split in ["train", "validation", "test"]:
    split_path = os.path.join(train_data_path, split)
    print(f"\n=== Balancing {split} ===")
    balance_split(split)
    # merge_patients_flat(split_path)

print("\nDONE BALANCING.")

# Thống kê số ảnh sau khi flatten
statistic = count_and_plot_images_flat()
