def count_images_of_patient(patient_path):
    total = 0
    patient_info = {}

    for mag in magnifications:
        mag_path = os.path.join(patient_path, mag)
        if os.path.isdir(mag_path):
            n = len([
                f for f in os.listdir(mag_path)
                if os.path.isfile(os.path.join(mag_path, f))
            ])
            patient_info[mag] = n
            total += n

    return total, patient_info


def balance_split(split):
    split_path = os.path.join(train_data_path, split)

    # ================
    # 1) Lấy danh sách patient
    # ================
    patients = [
        p for p in os.listdir(split_path)
        if os.path.isdir(os.path.join(split_path, p))
    ]

    print(f"\n=== {split.upper()} có {len(patients)} patients ===")

    # ================
    # 2) Đếm tổng số ảnh mỗi patient
    # ================
    patient_totals = {}
    patient_details = {}

    for p in patients:
        p_path = os.path.join(split_path, p)
        total, info = count_images_of_patient(p_path)
        patient_totals[p] = total
        patient_details[p] = info

    # ================
    # 3) Tìm target = số bệnh nhân ít nhất trong toàn bộ split
    # ================
    TARGET = min(patient_totals.values())  # ❌ SAI: dùng ảnh
    # Bạn muốn cân bằng theo bệnh nhân → nên dùng số lượng patient

    TARGET = len(patients)  # mỗi split giữ nguyên số patient?

    # ❗ Nhưng bạn muốn điều gì?
    # - cân bằng giữa benign/malignant? (Giờ không có)
    # - hay cân bằng giữa train/val/test?

    # → Theo cấu trúc mới: chỉ cân bằng **giữa train-val-test**

    # Ta sẽ **không dùng TARGET tại đây**
    # Mà dùng target global bên ngoài.

    print("→ TARGET trong split (theo bệnh nhân):", TARGET)

    # ================ 
    # 4) Nếu split = train → chuyển bớt sang val/test
    # ================
    if split == "train":
        global TARGET_PATIENTS

        while len(patients) > TARGET_PATIENTS:
            p = patients.pop()  # pop bệnh nhân cuối cùng
            src = os.path.join(split_path, p)

            # random sang val/test
            if random.random() < 0.5:
                dst_root = os.path.join(train_data_path, "validation")
            else:
                dst_root = os.path.join(train_data_path, "test")

            dst = os.path.join(dst_root, p)
            shutil.move(src, dst)

            print(f" → MOVE patient {p} → {dst}")

    # ================
    # 5) Nếu split = val/test → xoá bớt
    # ================
    else:
        global TARGET_PATIENTS

        while len(patients) > TARGET_PATIENTS:
            p = patients.pop()
            src = os.path.join(split_path, p)
            shutil.rmtree(src)
            print(f" → DELETE patient {p} trong {split}")



