def balance_split(split):
    split_path = os.path.join(train_data_path, split)

    # Lấy danh sách tất cả class (benign/malignant)
    class_paths = [
        os.path.join(split_path, c)
        for c in os.listdir(split_path)
        if os.path.isdir(os.path.join(split_path, c))
    ]

    for class_path in class_paths:
        class_name = os.path.basename(class_path)

        # Lấy danh sách tất cả bệnh nhân
        patients = [
            p for p in os.listdir(class_path)
            if os.path.isdir(os.path.join(class_path, p))
        ]

        print(f"\n=== {split.upper()} / {class_name} có {len(patients)} patients ===")

        # Đếm tổng ảnh mỗi patient
        patient_totals = {}
        for p in patients:
            p_path = os.path.join(class_path, p)
            total = sum(
                len([f for f in os.listdir(os.path.join(p_path, mag)) if os.path.isfile(os.path.join(p_path, mag, f))])
                for mag in magnifications
                if os.path.isdir(os.path.join(p_path, mag))
            )
            patient_totals[p] = total

        # Xác định TARGET theo số lượng patient muốn giữ
        global TARGET_PATIENTS

        if split == "train":
            while len(patients) > TARGET_PATIENTS:
                p = patients.pop()
                src = os.path.join(class_path, p)
                # Random sang val/test
                if random.random() < 0.5:
                    dst_root = os.path.join(train_data_path, "validation", class_name)
                else:
                    dst_root = os.path.join(train_data_path, "test", class_name)
                os.makedirs(dst_root, exist_ok=True)
                dst = os.path.join(dst_root, p)
                shutil.move(src, dst)
                print(f" → MOVE patient {p} → {dst}")

        else:  # validation/test
            while len(patients) > TARGET_PATIENTS:
                p = patients.pop()
                src = os.path.join(class_path, p)
                shutil.rmtree(src)
                print(f" → DELETE patient {p} trong {split}/{class_name}")

