def balance_split(split):
    split_path = os.path.join(train_data_path, split)

    # Lấy danh sách tất cả class (benign/malignant)
    class_paths = [
        os.path.join(split_path, c)
        for c in os.listdir(split_path)
        if os.path.isdir(os.path.join(split_path, c))
    ]

    for class_path in class_paths:
        class_name = os.path.basename(class_path)

        # Lấy danh sách tất cả bệnh nhân
        patients = [
            p for p in os.listdir(class_path)
            if os.path.isdir(os.path.join(class_path, p))
        ]

        print(f"\n=== {split.upper()} / {class_name} có {len(patients)} patients ===")

        # Đếm tổng ảnh mỗi patient (nếu cần, dùng cho thống kê)
        patient_totals = {}
        for p in patients:
            p_path = os.path.join(class_path, p)
            total = sum(
                len([f for f in os.listdir(os.path.join(p_path, mag)) if os.path.isfile(os.path.join(p_path, mag, f))])
                for mag in magnifications
                if os.path.isdir(os.path.join(p_path, mag))
            )
            patient_totals[p] = total

        # --- Tính TARGET_PATIENTS dựa trên split "train" hoặc "validation/test" ---
        if split == "train":
            # Ví dụ: giữ tối đa 80% bệnh nhân cho train, chuyển còn lại sang val/test
            TARGET_PATIENTS = int(len(patients) * 0.8)
            while len(patients) > TARGET_PATIENTS:
                p = patients.pop()
                src = os.path.join(class_path, p)
                # Random sang val/test
                if random.random() < 0.5:
                    dst_root = os.path.join(train_data_path, "validation", class_name)
                else:
                    dst_root = os.path.join(train_data_path, "test", class_name)
                os.makedirs(dst_root, exist_ok=True)
                dst = os.path.join(dst_root, p)
                shutil.move(src, dst)
                print(f" → MOVE patient {p} → {dst}")

        else:  # validation/test
            # Giữ tất cả patient còn lại, hoặc có thể giới hạn số lượng nếu muốn
            TARGET_PATIENTS = len(patients)  # giữ nguyên
            while len(patients) > TARGET_PATIENTS:
                p = patients.pop()
                src = os.path.join(class_path, p)
                shutil.rmtree(src)
                print(f" → DELETE patient {p} trong {split}/{class_name}")
# =========================
# Flatten tất cả ảnh từ patient → thẳng folder subtype/magnification
# =========================
def merge_patients_flat(split_path):
    for class_name in os.listdir(split_path):
        class_path = os.path.join(split_path, class_name)
        if not os.path.isdir(class_path):
            continue

        print(f"🔄 Flatten {class_name}...")

        for patient in os.listdir(class_path):
            patient_path = os.path.join(class_path, patient)
            if not os.path.isdir(patient_path):
                continue

            # Copy ảnh từ từng magnification thẳng vào folder class/mag
            for mag in magnifications:
                mag_dst = os.path.join(class_path, mag)
                os.makedirs(mag_dst, exist_ok=True)

                mag_src = os.path.join(patient_path, mag)
                if not os.path.isdir(mag_src):
                    continue

                for file in os.listdir(mag_src):
                    src_file = os.path.join(mag_src, file)
                    if os.path.isfile(src_file):
                        dst_file = os.path.join(mag_dst, f"{patient}_{file}")
                        shutil.copy(src_file, dst_file)

            # Xóa folder patient cũ
            shutil.rmtree(patient_path)
        print(f"✔ Done flatten {class_name}")

