def balance_split(train_path):
    
    # Helper: chia ảnh dư sang folder
    def move_files(files, dst_path):
        os.makedirs(dst_path, exist_ok=True)
        for f in files:
            shutil.move(f, os.path.join(dst_path, os.path.basename(f)))

    splits = ["train", "validation", "test"]
    split_paths = {s: os.path.join(os.path.dirname(train_path), s) for s in splits}

    # --- Step 1: Cân bằng train và phân phối dư ---
    class_names = [c for c in os.listdir(train_path) if os.path.isdir(os.path.join(train_path, c))]

    for mag in magnifications:
        # Lấy file train
        class_files = {}
        for c in class_names:
            mag_path = os.path.join(train_path, c, mag)
            files = [os.path.join(mag_path, f) for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))]
            class_files[c] = files

        min_count = min(len(files) for files in class_files.values())
        print(f"Train / {mag}: cân bằng xuống {min_count} ảnh mỗi class")

        for c, files in class_files.items():
            random.shuffle(files)
            train_keep = files[:min_count]
            extra_files = files[min_count:]

            # Giữ train
            mag_train_path = os.path.join(train_path, c, mag)
            for f in extra_files:
                os.remove(os.path.join(mag_train_path, os.path.basename(f)))  # xóa tạm

            # Chia ảnh dư sang val/test theo tỷ lệ
            n_extra = len(extra_files)
            if n_extra > 0:
                n_val = int(n_extra * (VALIDATION_RATIO / (VALIDATION_RATIO + TEST_RATIO)))
                n_test = n_extra - n_val

                val_path = os.path.join(split_paths["validation"], c, mag)
                test_path = os.path.join(split_paths["test"], c, mag)

                move_files(extra_files[:n_val], val_path)
                move_files(extra_files[n_val:], test_path)

            print(f" → {c}/{mag}: train={len(train_keep)}, val_extra={n_val if n_extra>0 else 0}, test_extra={n_test if n_extra>0 else 0}")

    # --- Step 2: Cân bằng validation, dư chuyển sang test ---
    val_path = split_paths["validation"]
    test_path = split_paths["test"]
    class_names_val = [c for c in os.listdir(val_path) if os.path.isdir(os.path.join(val_path, c))]

    for mag in magnifications:
        class_files = {}
        for c in class_names_val:
            mag_c_path = os.path.join(val_path, c, mag)
            if os.path.isdir(mag_c_path):
                files = [os.path.join(mag_c_path, f) for f in os.listdir(mag_c_path) if os.path.isfile(os.path.join(mag_c_path, f))]
                class_files[c] = files
            else:
                class_files[c] = []

        min_count = min(len(f) for f in class_files.values())
        for c, files in class_files.items():
            if len(files) > min_count:
                extra = files[min_count:]
                move_files(extra, os.path.join(test_path, c, mag))
                print(f"Validation / {c}/{mag}: dư chuyển sang test = {len(extra)}")

    # --- Step 3: Cân bằng test ---
    class_names_test = [c for c in os.listdir(test_path) if os.path.isdir(os.path.join(test_path, c))]
    for mag in magnifications:
        class_files = {}
        for c in class_names_test:
            mag_c_path = os.path.join(test_path, c, mag)
            if os.path.isdir(mag_c_path):
                files = [f for f in os.listdir(mag_c_path) if os.path.isfile(os.path.join(mag_c_path, f))]
                class_files[c] = files
            else:
                class_files[c] = []

        min_count = min(len(f) for f in class_files.values())
        for c, files in class_files.items():
            if len(files) > min_count:
                to_remove = random.sample(files, len(files) - min_count)
                for f in to_remove:
                    os.remove(os.path.join(test_path, c, mag, f))
                print(f"Test / {c}/{mag}: xóa dư = {len(to_remove)}")

