def balance_split(base_path):
    """
    Flatten và cân bằng dataset theo bệnh nhân:
    - Train cân bằng theo số ảnh thấp nhất giữa các class/mag
    - Bệnh nhân dư train → validation/test theo tỷ lệ
    - Validation dư → test
    - Test dư → loại bỏ để cân bằng
    """
    splits = ["train", "validation", "test"]
    split_paths = {s: os.path.join(base_path, s) for s in splits}

    # --- Step 0: Đảm bảo folder split/class/mag tồn tại ---
    for split in splits:
        for class_name in os.listdir(split_paths[split]):
            for mag in magnifications:
                os.makedirs(os.path.join(split_paths[split], class_name, mag), exist_ok=True)

    # Helper: đếm tổng ảnh trong một patient
    def patient_total_images(patient_path):
        return sum(
            len(os.listdir(os.path.join(patient_path, mag)))
            if os.path.isdir(os.path.join(patient_path, mag)) else 0
            for mag in magnifications
        )

    # Helper: move patient nguyên folder sang split khác
    def move_patient(patient_path, dst_split_path, class_name):
        dst_class_path = os.path.join(dst_split_path, class_name)
        os.makedirs(dst_class_path, exist_ok=True)
        shutil.move(patient_path, dst_class_path)

    # --- Step 1: Cân bằng train theo min ảnh ---
    train_path = split_paths["train"]
    class_names = [c for c in os.listdir(train_path) if os.path.isdir(os.path.join(train_path, c))]

    patient_totals = {}
    for c in class_names:
        class_path = os.path.join(train_path, c)
        patients = [p for p in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, p))]
        patient_totals[c] = {p: patient_total_images(os.path.join(class_path, p)) for p in patients}

    # Số ảnh thấp nhất giữa các class
    min_total = min(sum(patient_totals[c].values()) for c in class_names)
    print(f"Train: cân bằng số ảnh xuống {min_total} mỗi class")

    # Loại bỏ bệnh nhân dư và phân phối sang val/test
    for c in class_names:
        patients = list(patient_totals[c].items())
        random.shuffle(patients)
        total_accum = 0
        keep_patients = []
        extra_patients = []
        for p, t in patients:
            if total_accum + t <= min_total:
                keep_patients.append(p)
                total_accum += t
            else:
                extra_patients.append(p)

        class_path = os.path.join(train_path, c)
        for p in extra_patients:
            patient_path = os.path.join(class_path, p)
            # Phân phối dư sang val/test theo tỷ lệ
            if random.random() < VALIDATION_RATIO / (VALIDATION_RATIO + TEST_RATIO):
                dst_split_path = split_paths["validation"]
            else:
                dst_split_path = split_paths["test"]
            move_patient(patient_path, dst_split_path, c)
        print(f"{c}: train giữ {len(keep_patients)} bệnh nhân, dư {len(extra_patients)} chuyển sang val/test")

    # --- Step 2: Validation dư → chuyển sang test ---
    val_path = split_paths["validation"]
    test_path = split_paths["test"]
    class_names_val = [c for c in os.listdir(val_path) if os.path.isdir(os.path.join(val_path, c))]

    for c in class_names_val:
        class_path = os.path.join(val_path, c)
        patients = [p for p in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, p))]
        totals = [patient_total_images(os.path.join(class_path, p)) for p in patients]
        if not totals:
            continue
        min_total = min(totals)
        total_accum = 0
        keep = []
        extra = []
        for p in patients:
            t = patient_total_images(os.path.join(class_path, p))
            if total_accum + t <= min_total:
                keep.append(p)
                total_accum += t
            else:
                extra.append(p)
        for p in extra:
            move_patient(os.path.join(class_path, p), test_path, c)
        print(f"Validation {c}: giữ {len(keep)}, dư chuyển sang test {len(extra)}")

    # --- Step 3: Test cân bằng ---
    class_names_test = [c for c in os.listdir(test_path) if os.path.isdir(os.path.join(test_path, c))]

    for c in class_names_test:
        class_path = os.path.join(test_path, c)
        patients = [p for p in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, p))]
        totals = [patient_total_images(os.path.join(class_path, p)) for p in patients]
        if not totals:
            continue
        min_total = min(totals)
        total_accum = 0
        keep = []
        extra = []
        for p in patients:
            t = patient_total_images(os.path.join(class_path, p))
            if total_accum + t <= min_total:
                keep.append(p)
                total_accum += t
            else:
                extra.append(p)
        for p in extra:
            shutil.rmtree(os.path.join(class_path, p))
        print(f"Test {c}: giữ {len(keep)}, xóa dư {len(extra)}")

    # --- Step 4: Flatten tất cả ảnh từ patient → class/mag ---
    for split in splits:
        split_path = split_paths[split]
        for class_name in os.listdir(split_path):
            class_path = os.path.join(split_path, class_name)
            if not os.path.isdir(class_path):
                continue

            for patient in os.listdir(class_path):
                patient_path = os.path.join(class_path, patient)
                if not os.path.isdir(patient_path):
                    continue

                for mag in magnifications:
                    mag_dst = os.path.join(class_path, mag)
                    os.makedirs(mag_dst, exist_ok=True)
                    mag_src = os.path.join(patient_path, mag)
                    if os.path.isdir(mag_src):
                        for file in os.listdir(mag_src):
                            src_file = os.path.join(mag_src, file)
                            if os.path.isfile(src_file):
                                dst_file = os.path.join(mag_dst, f"{patient}_{file}")
                                shutil.copy(src_file, dst_file)

                shutil.rmtree(patient_path)
            print(f"{split}/{class_name}: flatten done")

    print("DONE: flatten + balance dataset by patient with magnifications looped.")

