# =========================
# Đếm số ảnh trong 1 folder
# =========================
def count_images(path):
    return len([
        f for f in os.listdir(path)
        if os.path.isfile(os.path.join(path, f))
    ])


# =========================
# Tính tổng ảnh của 1 patient (cộng tất cả magnification)
# =========================
def get_patient_total(patient_path):
    total = 0
    for mag in magnifications:
        mag_path = os.path.join(patient_path, mag)
        if os.path.isdir(mag_path):
            total += count_images(mag_path)
    return total


# =========================
# Tổng ảnh của class theo magnification
# =========================
def get_class_mag_totals(class_path):
    mag_totals = {m: 0 for m in magnifications}

    for patient in os.listdir(class_path):
        patient_path = os.path.join(class_path, patient)
        if not os.path.isdir(patient_path):
            continue

        for mag in magnifications:
            mag_path = os.path.join(patient_path, mag)
            if os.path.isdir(mag_path):
                mag_totals[mag] += count_images(mag_path)

    return mag_totals


# =========================
# Cân bằng split (train/validation/test)
# =========================
def balance_split(split):
    split_path = os.path.join(train_data_path, split)

    # ===============================
    # 1) Lấy GLOBAL_TARGET cho toàn split
    # ===============================
    class_paths = [
        os.path.join(split_path, c)
        for c in os.listdir(split_path)
        if os.path.isdir(os.path.join(split_path, c))
    ]

    # tổng ảnh của từng magnification cộng từ tất cả class
    global_mag_totals = {m: 0 for m in magnifications}

    for class_path in class_paths:
        class_mag = get_class_mag_totals(class_path)
        for m in magnifications:
            global_mag_totals[m] += class_mag[m]

    GLOBAL_TARGET = min(global_mag_totals.values())

    print(f"\n=== Balancing split: {split} ===")
    print("  Tổng ảnh của toàn split theo magnification:", global_mag_totals)
    print(f"  → GLOBAL_TARGET (benign + malignant) = {GLOBAL_TARGET}\n")

    # ===============================
    # 2) Cân bằng từng class theo GLOBAL_TARGET
    # ===============================
    for class_path in class_paths:
        class_name = os.path.basename(class_path)

        # ---- Lấy mọi patient ----
        patients = [
            p for p in os.listdir(class_path)
            if os.path.isdir(os.path.join(class_path, p))
        ]

        # ---- Tính tổng ảnh từng patient ----
        patient_totals = {
            p: get_patient_total(os.path.join(class_path, p))
            for p in patients
        }

        total_class_images = sum(patient_totals.values())
        print(f"\nClass {class_name}: tổng ảnh ban đầu = {total_class_images}")

        # ---- Sort patient: nhiều ảnh → ít ảnh ----
        patients_sorted = sorted(patient_totals.items(), key=lambda x: x[1], reverse=True)

        # ---- Cắt patient để xuống GLOBAL_TARGET ----
        while total_class_images > GLOBAL_TARGET and len(patients_sorted) > 1:
            patient, pt_total = patients_sorted.pop(0)
            src_path = os.path.join(class_path, patient)

            if split == "train":
                # Move sang validation hoặc test
                r = random.random()
                dst_split = "validation" if r < VALIDATION_RATIO / (VALIDATION_RATIO + TEST_RATIO) else "test"
                dst_path = os.path.join(train_data_path, dst_split, class_name)
                os.makedirs(dst_path, exist_ok=True)
                shutil.move(src_path, os.path.join(dst_path, patient))
                print(f"  → Move {patient} ({pt_total} ảnh) sang {dst_split}/{class_name}")
            else:
                shutil.rmtree(src_path)
                print(f"  → Delete {patient} ({pt_total} ảnh)")

            total_class_images -= pt_total

        print(f"  ✓ Class {class_name}: DONE (còn {total_class_images} ảnh)")

# =========================
# Flatten tất cả ảnh từ patient → thẳng folder subtype/magnification
# =========================
def merge_patients_flat(split_path):
    for class_name in os.listdir(split_path):
        class_path = os.path.join(split_path, class_name)
        if not os.path.isdir(class_path):
            continue

        print(f"🔄 Flatten {class_name}...")

        for patient in os.listdir(class_path):
            patient_path = os.path.join(class_path, patient)
            if not os.path.isdir(patient_path):
                continue

            # Copy ảnh từ từng magnification thẳng vào folder class/mag
            for mag in magnifications:
                mag_dst = os.path.join(class_path, mag)
                os.makedirs(mag_dst, exist_ok=True)

                mag_src = os.path.join(patient_path, mag)
                if not os.path.isdir(mag_src):
                    continue

                for file in os.listdir(mag_src):
                    src_file = os.path.join(mag_src, file)
                    if os.path.isfile(src_file):
                        dst_file = os.path.join(mag_dst, f"{patient}_{file}")
                        shutil.copy(src_file, dst_file)

            # Xóa folder patient cũ
            shutil.rmtree(patient_path)
        print(f"✔ Done flatten {class_name}")

# =========================
# Chạy cân bằng và flatten cho từng split
# =========================

# 

for split in ["train", "validation", "test"]:
    split_path = os.path.join(train_data_path, split)
    print(f"\n=== Balancing {split} ===")
    balance_split(split)
    merge_patients_flat(split_path)

print("\nDONE BALANCING.")

