# =========================
# Tổng ảnh theo magnification của 1 class
# =========================
def get_class_mag_totals(class_path):
    mag_totals = {m: 0 for m in magnifications}

    for patient in os.listdir(class_path):
        p_path = os.path.join(class_path, patient)
        if not os.path.isdir(p_path):
            continue

        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                mag_totals[mag] += count_images(mag_path)

    return mag_totals


def balance_split(split):
    split_path = os.path.join(train_data_path, split)

    print(f"\n=== Balancing split: {split} ===")

    # =========================================
    # 1) Lấy path benign + malignant
    # =========================================
    benign_path = os.path.join(split_path, "benign")
    malignant_path = os.path.join(split_path, "malignant")

    # =========================================
    # 2) Lấy tổng ảnh từng magnification cho mỗi class
    # =========================================
    benign_totals = get_class_mag_totals(benign_path)
    malignant_totals = get_class_mag_totals(malignant_path)

    print("Tổng ảnh benign:", benign_totals)
    print("Tổng ảnh malignant:", malignant_totals)

    # =========================================
    # 3) Tính TARGET_m (nhỏ nhất trong từng magnification)
    # =========================================
    target_per_mag = {
        m: min(benign_totals[m], malignant_totals[m])
        for m in magnifications
    }

    print("TARGET mỗi magnification:", target_per_mag)

    # GLOBAL_TARGET = nhỏ nhất của tất cả target magnification
    GLOBAL_TARGET = min(target_per_mag.values())
    print("→ GLOBAL_TARGET =", GLOBAL_TARGET)

    # =========================================
    # 4) Cân bằng từng class theo bệnh nhân
    # =========================================
    for class_name in ["benign", "malignant"]:
        class_path = os.path.join(split_path, class_name)

        # Lấy tất cả bệnh nhân
        patients = [
            p for p in os.listdir(class_path)
            if os.path.isdir(os.path.join(class_path, p))
        ]

        # Tính tổng ảnh từng bệnh nhân
        patient_totals = {
            p: get_patient_total(os.path.join(class_path, p))
            for p in patients
        }

        total_class_images = sum(patient_totals.values())
        print(f"\nClass {class_name}: tổng ảnh = {total_class_images}")

        # Sort: bệnh nhân nhiều ảnh → ít ảnh
        patients_sorted = sorted(
            patient_totals.items(),
            key=lambda x: x[1],
            reverse=True
        )

        # Bắt đầu cắt / move
        while total_class_images > GLOBAL_TARGET and len(patients_sorted) > 1:
            patient, pt_total = patients_sorted.pop(0)
            src_path = os.path.join(class_path, patient)

            if split == "train":
                r = random.random()
                dst_split = "validation" if r < VALIDATION_RATIO / (VALIDATION_RATIO + TEST_RATIO) else "test"
                dst_path = os.path.join(train_data_path, dst_split, class_name)
                os.makedirs(dst_path, exist_ok=True)
                shutil.move(src_path, os.path.join(dst_path, patient))
                print(f"→ Move {patient} ({pt_total} ảnh) sang {dst_split}/{class_name}")
            else:
                shutil.rmtree(src_path)
                print(f"→ Xóa {patient} ({pt_total} ảnh)")

            total_class_images -= pt_total

        print(f"✓ Class {class_name}: còn {total_class_images} ảnh")

