# ========== Dựng mô hình huấn luyện ==========
def build_model(num_classes, model_type, pretrained = PRE_TRAINED):
    model = timm.create_model(model_type, pretrained = PRE_TRAINED, num_classes = num_classes)
    model = model.to(DEVICE)
    return model

# ========== Dựng mô hình đánh giá ==========
def evaluate_model(model, loader):
    model.eval()
    predictions = []
    trues = []
    with torch.no_grad():
        for images, labels in loader:
            images = images.to(DEVICE)
            labels = labels.to(DEVICE)
            outputs = model(images)
            _, p = torch.max(outputs, 1)
            predictions.extend(p.cpu().numpy())
            trues.extend(labels.cpu().numpy())
    accuracy = accuracy_score(trues, predictions) if len(trues) > 0 else 0.0
    report = classification_report(trues, predictions, zero_division=0, output_dict=True) if len(trues)>0 else {}
    confusion_matrix = confusion_matrix(trues, predictions) if len(trues) > 0 else np.zeros((1,1))
    return accuracy, report, confusion_matrix
