        for imgs, labels in loop:
            imgs = imgs.to(DEVICE)
            labels = labels.to(DEVICE)
            optimizer.zero_grad()

            if scaler is not None:
                with torch.amp.autocast(device_type='cuda' if torch.cuda.is_available() else 'cpu'):
                    outputs = model(imgs)
                    loss = criterion(outputs, labels)
                scaler.scale(loss).backward()
                scaler.step(optimizer)
                scaler.update()
            else:
                outputs = model(imgs)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()

            running_loss += loss.item() * imgs.size(0)
            loop.set_postfix(loss=running_loss / ((loop.n + 1) * batch_size))

        # ========== Thống kê vòng lặp (Epoch) ==========
        average_loss = running_loss / len(train_loader.dataset)
        validation_accuracy, validation_report, validation_confussion_matrix = evaluate_model(model, validation_loader)
        print(f"Vòng lặp (Epoch): {epoch} | Mất mát trung bình (Loss): {average_loss:.4f} | Độ chính xác (Validation): {validation_accuracy:.4f}")

        # ========== Mở khóa huấn luyện phần đầu ==========
        if FREEZE_FEATURES and epoch == number_epoch_freeze:
            print(f"Unfreezing all model parameters at epoch {epoch}.")
            for param in model.parameters():
                param.requires_grad = True
            # (optional) lower lr a bit
            for g in optimizer.param_groups:
                g['lr'] = learning_rate * 0.5
            print("  -> Tốc độ học (Learning rate) được giảm xuống: ", optimizer.param_groups[0]['lr'])

        # ========== Kết thúc sớm ==========
