def count_images_binary_flat(split_path):
    # --- Đếm số ảnh ---
    data_counts = {}

    for main_class in os.listdir(split_path):
        class_path = os.path.join(split_path, main_class)
        if not os.path.isdir(class_path):
            continue
        
        for mag in magnifications:
            count = 0
            
            mag_path = os.path.join(class_path, mag)
            if os.path.isdir(mag_path):
                count += len([
                    f for f in os.listdir(mag_path)
                    if os.path.isfile(os.path.join(mag_path, f))
                ])
            key = f"{main_class}/{mag}"
            data_counts[key] = count
    return data_counts

def count_and_plot_images_binary_flat():
    data_counts = {}

    # --- Đếm các split ---
    for split in splits:
        split_path = os.path.join(train_data_path, split)
        if not os.path.exists(split_path):
            continue

        data_counts[split] = count_images_binary_flat(split_path)

    # --- Gom DataFrame ---
    all_data = []
    for split in splits:
        if split not in data_counts:
            continue

        # loop đúng: vào dict con
        for cls_mag, count in data_counts[split].items():
            # cls_mag dạng "benign/40X"
            if "/" not in cls_mag:
                print("WARNING: Key không hợp lệ:", cls_mag)
                continue

            main_class, mag = cls_mag.split("/")
            all_data.append({
                "Split": split,
                "Class": main_class,
                "Magnification": mag,
                "Num_Images": count
            })

    df = pd.DataFrame(all_data)

    chart_table(df)
