def simple_augment(img):
    """Augment đơn giản, trả về ảnh + nhãn augment"""
    img_aug = img.convert("RGB")
    tags = []

    # Rotate
    angle = random.randint(-10, 10)
    img_aug = img_aug.rotate(angle)
    tags.append(f"rot{angle}")

    # Flip
    if random.random()>0.5:
        img_aug = img_aug.transpose(Image.FLIP_LEFT_RIGHT)
        tags.append("flipLR")
    if random.random()>0.5:
        img_aug = img_aug.transpose(Image.FLIP_TOP_BOTTOM)
        tags.append("flipTB")

    # Brightness & Contrast
    b = round(random.uniform(0.95, 1.05),2)
    c = round(random.uniform(0.95, 1.05),2)
    img_aug = ImageEnhance.Brightness(img_aug).enhance(b)
    img_aug = ImageEnhance.Contrast(img_aug).enhance(c)
    tags.append(f"bright{int(b*100)}_contrast{int(c*100)}")

    return img_aug, "_".join(tags)

