for class_name in classes:
    class_path = os.path.join(base_path, train_data_path, split, class_name)
    if not os.path.isdir(class_path):
        continue

    # Lấy 1 patient đầu tiên
    patients = [p for p in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, p))]
    if not patients:
        continue
    patient_path = os.path.join(class_path, patients[0])

    for mag in magnifications:
        mag_path = os.path.join(patient_path, mag)
        if not os.path.isdir(mag_path):
            continue
        files = [f for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))]
        if not files:
            continue

        # Chọn 1 ảnh gốc
        img = Image.open(os.path.join(mag_path, files[0]))
        row_images = [("Original", img)]

        # Tạo augment
        for _ in range(NUMBER_OF_AUG):
            img_aug, tag = simple_augment(img)
            row_images.append((tag, img_aug))
            all_augmented.append(img_aug)

        # Thêm tổng hợp cuối cùng (ghép các augment thành 1 ảnh)
        total_w = sum([im.size[0] for _, im in row_images[1:]])
        max_h = max([im.size[1] for _, im in row_images[1:]])
        combined = Image.new("RGB", (total_w, max_h))
        x_offset = 0
        for _, im in row_images[1:]:
            combined.paste(im, (x_offset, 0))
            x_offset += im.size[0]
        row_images.append(("Combined", combined))

        # Hiển thị row
        plt.figure(figsize=(3*len(row_images),4))
        for i, (tag, im) in enumerate(row_images):
            plt.subplot(1, len(row_images), i+1)
            plt.imshow(im)
            plt.title(tag, fontsize=10)
            plt.axis("off")
        plt.tight_layout()
        plt.show()
