for i, (rot, flip_lr, flip_tb, bright, contrast) in enumerate(combinations):
    img_aug = demo_img.rotate(rot)
    if flip_lr:
        img_aug = img_aug.transpose(Image.FLIP_LEFT_RIGHT)
    if flip_tb:
        img_aug = img_aug.transpose(Image.FLIP_TOP_BOTTOM)
    img_aug = ImageEnhance.Brightness(img_aug).enhance(bright)
    img_aug = ImageEnhance.Contrast(img_aug).enhance(contrast)
    
    plt.subplot(n_rows, n_cols, i+1)
