    title = f"rot{rot}"
    if flip_lr: title += "_flipLR"
    if flip_tb: title += "_flipTB"
    title += f"_b{int(bright*100)}_c{int(contrast*100)}"
    plt.title(title, fontsize=8)
    plt.axis("off")

