train_data_path = "train_data"
classes = ["benign", "malignant"]

demo_img = None
for class_name in classes:
    class_path = os.path.join(base_path, train_data_path, "test", class_name)
    if not os.path.isdir(class_path):
        continue
    patients = [p for p in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, p))]
    for patient in patients:
        patient_path = os.path.join(class_path, patient)
        mags = [m for m in os.listdir(patient_path) if os.path.isdir(os.path.join(patient_path, m))]
        for mag in mags:
            mag_path = os.path.join(patient_path, mag)
            files = [f for f in os.listdir(mag_path) if os.path.isfile(os.path.join(mag_path, f))]
            if not files:
                continue
            demo_img = Image.open(os.path.join(mag_path, random.choice(files)))
            break
        break
    break

if demo_img is None:
    print("Không tìm thấy ảnh demo!")
else:
    # --- Tạo augment riêng từng loại ---
    # 1. Rotate
    img_rotate_1 = demo_img.rotate(-ROTATE_RANGE)
    img_rotate_2 = demo_img.rotate(ROTATE_RANGE) 
    
    # 2. Flip
    img_flip_1 = flip(demo_img, True, False)
    img_flip_2 = flip(demo_img, False, True)
    img_flip_3 = flip(demo_img, True, True)
    
    # 3. Brightness
    img_bright_max = brightness_contrast(demo_img, 1 + BRIGHTNESS_RANGE, 1)
    img_bright_min = brightness_contrast(demo_img, 1 - BRIGHTNESS_RANGE, 1)
    
    # 4. Contrast
    img_contrast_max = brightness_contrast(demo_img, 1, 1 + CONTRAST_RANGE)
    img_contrast_min = brightness_contrast(demo_img, 1, 1 - CONTRAST_RANGE)
    
    # 5. Merge tất cả augment (ví dụ xếp ngang)
    image_augment = rotate(demo_img, ROTATE_RANGE)
    image_augment = rotate(image_augment, Image.FLIP_LEFT_RIGHT)
    image_augment = brightness_contrast(image_augment, 1.05, 1.05)
    

# Giả sử mỗi hình có 1 tag riêng
augments = {
    "Rotate": [(img_rotate_1, f"Xoay -{ROTATE_RANGE} độ"), (img_rotate_2, f"Xoay +{ROTATE_RANGE} độ")],
    "Flip": [(img_flip_1, "Lật ngang"), (img_flip_2, "Lật dọc"), (img_flip_3, "Lật cả hai chiều")],
    "Brightness": [(img_bright_max, f"Tăng sáng {BRIGHTNESS_RANGE} lần"), (img_bright_min, f"Giảm sáng {BRIGHTNESS_RANGE} lần")],
    "Contrast": [(img_contrast_max, "Tăng contrast"), (img_contrast_min, "Giảm contrast")],
}
from matplotlib.gridspec import GridSpec
n_cols = len(augments)
n_rows = max(len(v) for v in augments.values())

# Tạo GridSpec, đặt tỉ lệ chiều cao: hàng 1 thấp hơn các hàng còn lại
heights = [0.7] + [1]*(n_rows-1)  # hàng đầu tiên thấp hơn
fig = plt.figure(figsize=(4*n_cols, 4*n_rows))
gs = GridSpec(n_rows, n_cols, figure=fig, height_ratios=heights)

for col, (col_name, images_tags) in enumerate(augments.items()):
    # Tên cột in đậm trên cùng
    fig.text((col+0.5)/n_cols, 1.02, col_name, ha='center', va='bottom', fontsize=14, fontweight='bold')

    for row in range(n_rows):
        ax = fig.add_subplot(gs[row, col])
        ax.axis("off")
        if row < len(images_tags):
            img, tag = images_tags[row]
            ax.imshow(img)
            ax.set_title(tag, fontsize=10)
        else:
            ax.set_visible(False)

plt.tight_layout()
plt.show()
