def overlay_heatmap_on_image(img, heatmap, alpha=0.5, cmap='jet'):
    """
    img: PIL Image
    heatmap: ma trận 2D cùng tỷ lệ với img hoặc có thể resize
    alpha: độ trong suốt của heatmap
    """
    import cv2
    from matplotlib.cm import get_cmap

    # Chuyển PIL image -> numpy array
    img_np = np.array(img.convert("RGB"))

    # Resize heatmap về cùng kích thước hình
    heatmap_resized = cv2.resize(heatmap, (img_np.shape[1], img_np.shape[0]))

    # Chuyển heatmap thành màu
