def overlay_heatmap_on_image(img, heatmap, alpha=0.5, cmap_name='jet'):
    """
    img: PIL Image
    heatmap: ma trận 2D cùng tỷ lệ với img hoặc có thể resize
    alpha: độ trong suốt của heatmap
    cmap_name: tên colormap
    """
    import cv2
    import numpy as np
    import matplotlib

    # Chuyển PIL image -> numpy array
    img_np = np.array(img.convert("RGB"))

    # Resize heatmap về cùng kích thước hình
    heatmap_resized = cv2.resize(heatmap, (img_np.shape[1], img_np.shape[0]))

    # Chuyển heatmap thành màu
    cmap = matplotlib.colormaps[cmap_name]  # Cách mới thay get_cmap
    heatmap_color = cmap(heatmap_resized)[:, :, :3]  # chỉ lấy RGB
    heatmap_color = (heatmap_color * 255).astype(np.uint8)

    # Overlay với alpha
    overlay = cv2.addWeighted(img_np, 1 - alpha, heatmap_color, alpha, 0)

    return overlay

# --- Ví dụ áp dụng cho một hình ---
heatmap_example = np.random.rand(demo_img.size[1], demo_img.size[0])
img_overlay = overlay_heatmap_on_image(demo_img, heatmap_example, alpha=0.5)

plt.figure(figsize=(6,6))
plt.imshow(img_overlay)
plt.axis("off")
plt.title("Original + Heatmap Overlay")
plt.show()
