# ======== Xoay hình ==========
def rotate(img, angle):
    img = img.rotate(angle)
    return img

# ======== Lật hình ==========
def flip(img, is_flip_lr, is_flip_tb):
    if is_flip_lr:
        img = img.transpose(Image.FLIP_LEFT_RIGHT)
    if is_flip_tb:
        img = img.transpose(Image.FLIP_TOP_BOTTOM)
    return img

# ======== Độ sáng / Tương phản ==========
def brightness_contrast(img, brightness_factor, contrast_factor):
    img = ImageEnhance.Brightness(img).enhance(brightness_factor)
    img = ImageEnhance.Contrast(img).enhance(contrast_factor)
    return img

# ======== Gamma (Độ sáng / tối) ==========
def gamma_correction(img, gamma=1.0):
    img = img.convert("RGB")
    inv_gamma = 1.0 / gamma

    table = [((i / 255.0) ** inv_gamma) * 255 for i in range(256)]
    table = np.array(table).astype(np.uint8)

    lut = list(table) * 3

    return img.point(lut)

# ======== Color jitter ==========
def color_jitter(img, color_factor):
    return ImageEnhance.Color(img).enhance(color_factor)

# ======== Độ nhiễu (Noise) ==========
def add_noise(img, noise_std=1):
    arr = np.array(img)
    noise = np.random.normal(0, noise_std, arr.shape)
    arr = np.clip(arr + noise, 0, 255).astype(np.uint8)
    return Image.fromarray(arr)

# ======== Độ nhiễu (Noise) ==========
def zoom(img, zoom_factor):
    w, h = img.size
    if zoom_factor > 1:
        # Crop trung tâm
        new_w, new_h = int(w/zoom_factor), int(h/zoom_factor)
        left = (w - new_w)//2
        top = (h - new_h)//2
        right = left + new_w
        bottom = top + new_h
        img_cropped = img.crop((left, top, right, bottom))
        # Resize lại về kích thước gốc
        img_zoomed = img_cropped.resize((w,h), Image.LANCZOS)
    else:
        # Zoom out: thu nhỏ rồi chèn padding
        new_w, new_h = int(w*zoom_factor), int(h*zoom_factor)
        img_small = img.resize((new_w,new_h), Image.LANCZOS)
        # Tạo ảnh nền đen
        img_zoomed = Image.new("RGB", (w,h))
        left = (w-new_w)//2
        top = (h-new_h)//2
        img_zoomed.paste(img_small, (left, top))
    return img_zoomed
