def learning_curve(loss_history, validation_accuracy_history):
    epochs_range = range(1, len(loss_history)+1)

    plt.figure(figsize=(12,5))

    # Loss curve
    plt.subplot(1,2,1)
    plt.plot(epochs_range, loss_history, 'bo-', label='Train Loss')
    plt.title('Training Loss')
    plt.xlabel('Epoch')
    plt.ylabel('Loss')
    plt.legend()

    # Accuracy curve
    plt.subplot(1,2,2)
    plt.plot(epochs_range, validation_accuracy_history, 'ro-', label='Độ chính xác (Validation)')
    plt.title('Validation Accuracy')
    plt.xlabel('Epoch')
    plt.ylabel('Accuracy')
    plt.legend()

    plt.show()
