    plt.title('HÀM MẤT MÁT HUẤN LUYỆN\nTRAINING LOSS',fontweight="bold")
    plt.xlabel('Vòng lặp (Epoch)')
    plt.ylabel('Giá trị mất mát (Loss)')
    plt.gca().xaxis.set_major_locator(mticker.MaxNLocator(integer=True))  # Chỉ hiện số nguyên
    plt.legend()

    # Accuracy curve
    plt.subplot(1,2,2)
    plt.plot(epochs_range, validation_accuracy_history, 'ro-', label='Độ chính xác (Validation)')
    plt.title('Độ chính xác (Validation)')
    plt.xlabel('Epoch')
    plt.ylabel('Accuracy')
    plt.gca().xaxis.set_major_locator(mticker.MaxNLocator(integer=True))  # Chỉ hiện số nguyên
    plt.legend()

    plt.show()
    
