df["combined_features"] = (
    df["category"] + " " +
    df["tags"] + " " +
    df["description"]
)

# ============================================
# 3. TF-IDF VECTORIZATION
# ============================================
tfidf = TfidfVectorizer(stop_words="english")
tfidf_matrix = tfidf.fit_transform(df["combined_features"])

# ============================================
# 4. COSINE SIMILARITY
# ============================================
cosine_sim = cosine_similarity(tfidf_matrix, tfidf_matrix)

# ============================================
# 5. HÀM GỢI Ý SẢN PHẨM
# ============================================
def recommend(product_name, num_recommend=3):
    if product_name not in df["name"].values:
        return f"Không tìm thấy sản phẩm: {product_name}"

    idx = df.index[df["name"] == product_name][0]

    scores = list(enumerate(cosine_sim[idx]))
    scores = sorted(scores, key=lambda x: x[1], reverse=True)
    scores = scores[1:num_recommend + 1]  # Bỏ chính nó

    recommended_products = df.iloc[[i[0] for i in scores]][["name", "category"]]

    return recommended_products

# ============================================
# 6. TEST HỆ GỢI Ý
# ============================================
print("Gợi ý sản phẩm giống 'iPhone 15 Pro':")
print(recommend("iPhone 15 Pro"))

print("\nGợi ý sản phẩm giống 'Samsung Galaxy Tab S9':")
print(recommend("Samsung Galaxy Tab S9"))
