# vectorize using TF-IDF on content_text
tfidf = TfidfVectorizer(max_features=5000, stop_words='english')
tfidf_matrix = tfidf.fit_transform(movies_proc['content_text'])

# Compute cosine similarity matrix (content-based)
cosine_sim = linear_kernel(tfidf_matrix, tfidf_matrix)  # faster when input is TF-IDF

# Map movieId to index and back
indices = pd.Series(movies_proc.index, index=movies_proc['movieId']).drop_duplicates()

# Define Knowledge-Based rules as a list of dicts. Each rule can:
# - 'filter': remove movies matching condition (if action == 'filter')
# - 'boost': multiply similarity score by factor (if action == 'boost')
# - 'penalize': multiply similarity score by factor < 1 (if action == 'penalize')
# Conditions are evaluated against movie metadata (genres, title).
knowledge_rules = [
    # Example: if input movie is Horror and older than 1980, penalize recommending to users who prefer modern content.
    {"id": "avoid_old_horror", "condition": {"genres_contains": "horror", "title_contains_year_before": 1980}, "action": {"type": "penalize", "factor": 0.2}, "explain": "Old horror; penalized for modern audiences."},
    # Boost when same actor/director not available in small dataset; use genre boost:
    {"id": "same_genre_boost", "condition": {"genres_contains": None}, "action": {"type": "boost", "factor": 1.2}, "explain": "Boost same-genre films."},
    # Filter explicit: e.g., avoid 'classic' tag if user prefers modern content. We'll simulate using keyword 'classic' in title.
    {"id": "filter_classic_for_modern_pref", "condition": {"title_contains": "classic"}, "action": {"type": "filter"}, "explain": "Filtered classic movies for modern-pref users."}
]

# For simplicity, implement rule matching functions
def parse_year_from_title(title):
    # naive parse for year in parentheses at end, e.g., "Movie Title (1999)"
    import re
    m = re.search(r'\((\d{4})\)\s*$', str(title))
    if m:
        return int(m.group(1))
    return None

def movie_matches_condition(movie_row, condition):
    # condition can have keys: genres_contains (substring), title_contains (substring),
    # title_contains_year_before (year), title_contains_year_after, title_contains (substring)
    g = str(movie_row['genres']).lower() if pd.notna(movie_row['genres']) else ''
    title = str(movie_row['title']).lower() if pd.notna(movie_row['title']) else ''
    # genres_contains
    if 'genres_contains' in condition and condition['genres_contains'] is not None:
        if condition['genres_contains'].lower() not in g:
            return False
    # title_contains
    if 'title_contains' in condition:
        if condition['title_contains'].lower() not in title:
            return False
    # title_contains_year_before
    if 'title_contains_year_before' in condition:
        year = parse_year_from_title(movie_row['title'])
        if year is None or not (year < condition['title_contains_year_before']):
            return False
    # title_contains_year_after
    if 'title_contains_year_after' in condition:
        year = parse_year_from_title(movie_row['title'])
        if year is None or not (year > condition['title_contains_year_after']):
            return False
    return True

# The recommend function: content-based similarity + knowledge-rule adjustments + optional CF integration placeholder
def recommend(movie_id, top_k=5, apply_rules=True, verbose=False):
    if movie_id not in indices:
        raise ValueError("movie_id not found in the dataset used in this demo.")
    idx = indices[movie_id]
    sim_scores = list(enumerate(cosine_sim[idx]))
    # sim_scores: list of tuples (movie_index, score)
    # convert to numpy array for manipulation
    scores = np.array([s for _, s in sim_scores])
    # set self-similarity to 0 to avoid recommending the movie itself
    scores[idx] = 0.0
    applied_rules = []
    # Apply knowledge-based rules: iterate rules, for each candidate movie modify score
    if apply_rules:
        for r in knowledge_rules:
            for j in range(len(scores)):
                mrow = movies_proc.iloc[j]
                # special case: a rule with condition genres_contains None means apply to all (generic boost)
                condition = r.get('condition', {})
                # If rule's genres_contains is explicitly None, treat as match-all for boost rule type
                matches = False
                if condition.get('genres_contains', '<<MISSING>>') is None:
                    matches = True
                else:
                    matches = movie_matches_condition(mrow, condition)
                if matches:
                    action = r.get('action', {})
                    if action.get('type') == 'boost':
                        scores[j] = scores[j] * action.get('factor', 1.0)
                        applied_rules.append({"rule_id": r['id'], "movieId": int(mrow['movieId']), "action": "boost", "factor": action.get('factor', 1.0)})
                    elif action.get('type') == 'penalize':
                        scores[j] = scores[j] * action.get('factor', 1.0)
                        applied_rules.append({"rule_id": r['id'], "movieId": int(mrow['movieId']), "action": "penalize", "factor": action.get('factor', 1.0)})
                    elif action.get('type') == 'filter':
                        scores[j] = 0.0
                        applied_rules.append({"rule_id": r['id'], "movieId": int(mrow['movieId']), "action": "filter"})
    # After adjustments, rank by final scores
    top_indices = np.argsort(scores)[::-1][:top_k]
    recommendations = []
    for ti in top_indices:
        rec_movie = movies_proc.iloc[ti]
        recommendations.append({"movieId": int(rec_movie['movieId']), "title": rec_movie['title'], "genres": rec_movie['genres'], "score": float(scores[ti])})
    # Optionally include which rules applied per recommended movie
    rules_by_movie = {}
    for ar in applied_rules:
        rules_by_movie.setdefault(ar['movieId'], []).append(ar)
    if verbose:
        print("Applied rules (sample):", applied_rules[:10])
    return recommendations, rules_by_movie

# Demo: show processed movies
if have_display:
    display_dataframe_to_user("movies_processed", movies_proc)
else:
    print("\nProcessed movies (first rows):")
    print(movies_proc.head().to_string(index=False))

# Run a test recommendation for the first movie in the dataset
test_movie_id = int(movies_proc['movieId'].iloc[0])
recs, rules_info = recommend(test_movie_id, top_k=5, apply_rules=True, verbose=False)

print(f"\nRecommendations for movieId={test_movie_id} ({movies_proc.loc[movies_proc['movieId']==test_movie_id,'title'].values[0]}):")
for r in recs:
    print(f"- {r['movieId']}: {r['title']}  (genres: {r['genres']}) score={r['score']:.4f}")
# If any rule info is present, print summary
if rules_info:
    print("\nRules applied (grouped by movieId):")
    for mid, actions in rules_info.items():
        print(f"Movie {mid}: {actions[:3]}{'...' if len(actions)>3 else ''}")

# Save example knowledge rules to a local json file for the report
with open("knowledge_rules_example.json", "w", encoding="utf-8") as f:
    json.dump(knowledge_rules, f, ensure_ascii=False, indent=2)
print("\nKnowledge rules written to knowledge_rules_example.json in working directory.")
