# Preprocessing: combine title, genres, and tags into a text field for TF-IDF
def preprocess_movies(movies_df, tags_df=None):
    # Sao chép dataframe
    df = movies_df.copy()
    
    # Chuẩn hóa loại phim (Thành dạng string)
    df['genres'] = df['genres'].fillna('')
    df['genres_text'] = df['genres'].str.replace('|', ' ', regex=False)
    
    # Ghép tiêu đề phim và loại phim
    df['text_base'] = df['title'].fillna('') + " " + df['genres_text']
    
    # Gộp nhãn với phim
    if tags_df is not None and len(tags_df) > 0:
        agg = tags_df.groupby('movieId')['tag'].apply(lambda x: ' '.join(map(str, x))).reset_index()
        df = df.merge(agg, on='movieId', how='left')
        df['tag'] = df['tag'].fillna('')
    else:
        df['tag'] = ''
    df['content_text'] = (df['text_base'] + " " + df['tag']).str.lower()
    
    # Trả kết quả
    return df[['movieId', 'title', 'genres', 'content_text']]

movies_proc = preprocess_movies(movies, tags)

# Loại bỏ năm ra khỏi tiêu đề phim
def remove_year_from_title(title):
    # naive parse for year in parentheses at end, e.g., "Movie Title (1999)"
    movie = re.search(r'\((\d{4})\)\s*$', str(title))
    if movie:
        return int(movie.group(1))
    return None

# Vector hóa nội dung
tfidf = TfidfVectorizer(max_features=5000, stop_words='english')
tfidf_matrix = tfidf.fit_transform(movies_proc['content_text'])

# Tra cứu MovieId theo Index
indices = pd.Series(movies_proc.index, index=movies_proc['movieId']).drop_duplicates()
