# Tính độ tương đồng - Cosine Similarity (content-based)
cosine_sim = linear_kernel(tfidf_matrix, tfidf_matrix)  # faster when input is TF-IDF

# Define Knowledge-Based rules as a list of dicts. Each rule can:
# - 'filter': remove movies matching condition (if action == 'filter')
# - 'boost': multiply similarity score by factor (if action == 'boost')
# - 'penalize': multiply similarity score by factor < 1 (if action == 'penalize')
# Conditions are evaluated against movie metadata (genres, title).
knowledge_rules = [
    # Gợi ý phim mới
    {
        "id": "avoid_old_movie", 
        "condition": {"year_release_before": 1980}, 
        "action": {"type": "penalize", "factor": 0.2}, 
        "explain": "Trừ điểm - Phim quá cũ"
    },
    # Gợi ý phim cùng thể loại
    {
        "id": "same_genre_boost", 
        "condition": {"genres_contains": None}, 
        "action": {"type": "boost", "factor": 1.2}, 
        "explain": "Cộng điểm - Phim cùng thể loại"
    },
    # Không gợi ý phim bị đánh giá tiêu cực
    {
        "id": "penalize_negative_tags",
        "condition": {"tag_contains_any": ["boring", "slow", "bad"]},
        "action": {"type": "penalize", "factor": 0.5},
        "explain": "Trừ điểm - Phim bị đánh giá tiêu cực"
    }
]

def movie_matches_condition(movie_row, condition):
    print(movie_row)
    # condition can have keys: genres_contains (substring), title_contains (substring),
    # title_contains_year_before (year), title_contains_year_after, title_contains (substring)
    genres = str(movie_row['genres']).lower() if pd.notna(movie_row['genres']) else ''
    
    # genres_contains
    if 'genres_contains' in condition and condition['genres_contains'] is not None:
        if condition['genres_contains'].lower() not in genres:
            return False
    
    # tag_contains_any → kiểm tra trong content_text
    if 'tag_contains_any' in condition:
        if not any(tag.lower() in content for tag in condition['tag_contains_any']):
            return False
    
    # title_contains_year_before
    if 'year_release_before' in condition:
        year = remove_year_from_title(movie_row['title'])
        if year is None or not (year < condition['year_release_before']):
            return False
        
    # title_contains_year_after
    if 'year_release_after' in condition:
        year = remove_year_from_title(movie_row['title'])
        if year is None or not (year > condition['year_release_after']):
            return False
    return True

# The recommend function: content-based similarity + knowledge-rule adjustments + optional CF integration placeholder
def recommend(movie_id, top_k=5, apply_rules=True, verbose=False):
    if movie_id not in indices:
        raise ValueError("movie_id not found in the dataset used in this demo.")
    idx = indices[movie_id]
    sim_scores = list(enumerate(cosine_sim[idx]))
    # sim_scores: list of tuples (movie_index, score)
    # convert to numpy array for manipulation
    scores = np.array([s for _, s in sim_scores])
    # set self-similarity to 0 to avoid recommending the movie itself
    scores[idx] = 0.0
    applied_rules = []
    # Apply knowledge-based rules: iterate rules, for each candidate movie modify score
    if apply_rules:
        for r in knowledge_rules:
            for j in range(len(scores)):
                mrow = movies_proc.iloc[j]
                # special case: a rule with condition genres_contains None means apply to all (generic boost)
                condition = r.get('condition', {})
                # If rule's genres_contains is explicitly None, treat as match-all for boost rule type
                matches = False
                if condition.get('genres_contains', '<<MISSING>>') is None:
                    matches = True
                else:
                    matches = movie_matches_condition(mrow, condition)
                if matches:
                    action = r.get('action', {})
                    if action.get('type') == 'boost':
                        scores[j] = scores[j] * action.get('factor', 1.0)
                        applied_rules.append({"rule_id": r['id'], "movieId": int(mrow['movieId']), "action": "boost", "factor": action.get('factor', 1.0)})
                    elif action.get('type') == 'penalize':
                        scores[j] = scores[j] * action.get('factor', 1.0)
                        applied_rules.append({"rule_id": r['id'], "movieId": int(mrow['movieId']), "action": "penalize", "factor": action.get('factor', 1.0)})
                    elif action.get('type') == 'filter':
                        scores[j] = 0.0
                        applied_rules.append({"rule_id": r['id'], "movieId": int(mrow['movieId']), "action": "filter"})
    # After adjustments, rank by final scores
    top_indices = np.argsort(scores)[::-1][:top_k]
    recommendations = []
    for ti in top_indices:
        rec_movie = movies_proc.iloc[ti]
        recommendations.append({"movieId": int(rec_movie['movieId']), "title": rec_movie['title'], "genres": rec_movie['genres'], "score": float(scores[ti])})
    # Optionally include which rules applied per recommended movie
    rules_by_movie = {}
    for ar in applied_rules:
        rules_by_movie.setdefault(ar['movieId'], []).append(ar)
    if verbose:
        print("Applied rules (sample):", applied_rules[:10])
    return recommendations, rules_by_movie
