import pandas as pd
from sklearn.feature_extraction.text import TfidfVectorizer
import re

# Gán thông tin phim thành chuỗi (title, genres_text, tags)
def compose_movie_content(movies_df: pd.DataFrame, tags_df: pd.DataFrame, ratings_df: pd.DataFrame, links_df: pd.DataFrame) -> pd.DataFrame:
    df = movies_df.copy()
    
    df['genres'] = df['genres'].fillna('')
    df['genres_text'] = df['genres'].str.replace('|', ' ', regex=False)
    df['text_base'] = df['title'].fillna('') + " " + df['genres_text']



    # Tags
    if tags_df is not None and len(tags_df) > 0:
        agg_tags = tags_df.groupby('movieId')['tag'].apply(lambda x: ' '.join(map(str, x))).reset_index()
        df = df.merge(agg_tags, on='movieId', how='left')
        df['tag'] = df['tag'].fillna('')
    else:
        df['tag'] = ''

    df['content_text'] = (df['text_base'] + " " + df['tag']).str.lower()

    # Year
    df["year"] = df["title"].apply(year_release).astype("Int64") 
    
    # Links
    if links_df is not None and len(links_df) > 0:
        df = df.merge(
            links_df[["movieId", "imdbId", "tmdbId"]],
            on="movieId",
            how="left"
        )
        df["imdbId"] = pd.to_numeric(df["imdbId"], errors="coerce").astype("Int64")
        df["tmdbId"] = pd.to_numeric(df["tmdbId"], errors="coerce").astype("Int64")
    else:
        df['imdbId'] = None
        df['tmdbId'] = None

    # Rating
    if ratings_df is not None and len(ratings_df) > 0:
        agg_rating = (
            ratings_df
            .groupby('movieId')['rating']
            .agg(rating_mean='mean', rating_count='count')
            .reset_index()
        )
        df = df.merge(agg_rating, on='movieId', how='left')
    else:
        df['rating_mean'] = 0
        df['rating_count'] = 0

    # Weighted rating
    m = 100  # ngưỡng lượt tối thiểu
    C = df['rating_mean'].mean()
    df['weighted_rating'] = (df['rating_count'] / (df['rating_count'] + m)) * df['rating_mean'] + (m / (df['rating_count'] + m)) * C

    # Sắp xếp theo năm ra mắt và weighted rating
    df['year_release'] = df['title'].apply(year_release)

    # Sắp xếp
    df_sorted = df.sort_values(by=['year_release', 'weighted_rating'], ascending=[False, False])

    # Chọn cột cần hiển thị
    movie_list = df_sorted[
        [
            'movieId',
            'title',
            'year',
            'genres',
            'content_text',
            'imdbId',
            'tmdbId',
            'rating_mean',
            'rating_count',
            'weighted_rating'
        ]
    ]
    print(movie_list.head(5))
    return movie_list
    

    

# Loại bỏ năm ra khỏi tiêu đề phim - Tiêu đề hiện tại: Movie Title (1999)
def year_release(title) -> int | None:
    title = re.search(r'\((\d{4})\)\s*$', str(title))
    if title:
        return int(title.group(1))
    return None

def preprocess_movies(movies_df: pd.DataFrame, tags_df: pd.DataFrame, ratings_df: pd.DataFrame, links_df: pd.DataFrame):
    movies_proc = compose_movie_content(movies_df, tags_df, ratings_df, links_df)

    # Vector hóa nội dung
    tfidf = TfidfVectorizer(max_features=5000, stop_words='english')
    tfidf_matrix = tfidf.fit_transform(movies_proc['content_text'])

    # Tra cứu MovieId theo Index
    indices = pd.Series(movies_proc.index, index=movies_proc['movieId']).drop_duplicates()
    return movies_proc, tfidf_matrix, indices
