# =========================
# Hàm đếm số ảnh trong folder
# =========================
def count_images(path):
    return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])

# =========================
# Tổng ảnh theo magnification của 1 class
# =========================
def get_class_mag_totals(class_path):
    mag_totals = {m: 0 for m in magnifications}

    for patient in os.listdir(class_path):
        p_path = os.path.join(class_path, patient)
        if not os.path.isdir(p_path):
            continue

        for mag in magnifications:
            mag_path = os.path.join(p_path, mag)
            if os.path.isdir(mag_path):
                mag_totals[mag] += count_images(mag_path)

    return mag_totals

def balance_split(split):
    split_path = os.path.join(train_data_path, split)
    print(f"\n=== Cân bằng tập dữ liệu: {split} ===")

    benign_path = os.path.join(split_path, "benign")
    malignant_path = os.path.join(split_path, "malignant")

    # Tổng ảnh từng magnification
    benign_totals = get_class_mag_totals(benign_path)
    malignant_totals = get_class_mag_totals(malignant_path)
    print("Tổng ảnh benign:", benign_totals)
    print("Tổng ảnh malignant:", malignant_totals)

    # TARGET mỗi magnification = min giữa 2 class
    target_per_mag = {m: min(benign_totals[m], malignant_totals[m]) for m in magnifications}
    print("Mục tiêu mỗi độ phóng đại:", target_per_mag)

    for class_name in ["benign", "malignant"]:
        class_path = os.path.join(split_path, class_name)
        patients = [p for p in os.listdir(class_path) if os.path.isdir(os.path.join(class_path, p))]

        # Tính tổng ảnh từng bệnh nhân từng magnification
        patient_mag_totals = {}
        for p in patients:
            patient_path = os.path.join(class_path, p)
            patient_mag_totals[p] = {m: count_images(os.path.join(patient_path, m)) if os.path.isdir(os.path.join(patient_path, m)) else 0
                                     for m in magnifications}

        # Duyệt từng magnification
        for mag in magnifications:
            total_mag_images = sum(patient_mag_totals[p][mag] for p in patients)
            print(f"\nNhóm {class_name} - {mag}: Tổng ảnh: {total_mag_images}, Mục tiêu: {target_per_mag[mag]}")

            # Sort bệnh nhân nhiều → ít ảnh ở magnification hiện tại
            patients_sorted = sorted(patient_mag_totals.items(), key=lambda x: x[1][mag], reverse=True)

            while total_mag_images > target_per_mag[mag] and len(patients_sorted) > 1:
                patient, mags = patients_sorted.pop(0)
                n_to_remove = total_mag_images - target_per_mag[mag]
                patient_mag_count = mags[mag]

                src_path = os.path.join(class_path, patient, mag)
                if not os.path.isdir(src_path) or patient_mag_count == 0:
                    continue

                if patient_mag_count <= n_to_remove:
                    # Move hoặc xóa cả folder magnification
                    files = os.listdir(src_path)
                    n_to_process = len(files)
                else:
                    files = os.listdir(src_path)[:n_to_remove]
                    n_to_process = n_to_remove

                for f in files:
                    src_file = os.path.join(src_path, f)
                    if split == "train":
                        r = random.random()
                        dst_split = "validation" if r < VALIDATION_RATIO / (VALIDATION_RATIO + TEST_RATIO) else "test"
                        dst_dir = os.path.join(train_data_path, dst_split, class_name, mag)
                        os.makedirs(dst_dir, exist_ok=True)
                        shutil.move(src_file, os.path.join(dst_dir, f"{patient}_{f}"))
                    else:
                        os.remove(src_file)

                total_mag_images -= n_to_process
                patient_mag_totals[patient][mag] -= n_to_process

            print(f"✓ Nhóm {class_name} - {mag}: Còn {total_mag_images} ảnh")

# =========================
# Flatten tất cả ảnh từ patient → thẳng folder subtype/magnification
# =========================
def merge_patients_flat(split_path):
    for class_name in os.listdir(split_path):
        class_path = os.path.join(split_path, class_name)
        if not os.path.isdir(class_path):
            continue

        print(f"🔄 Di chuyển hình trong {class_name}...")

        for patient in os.listdir(class_path):
            patient_path = os.path.join(class_path, patient)
            if not os.path.isdir(patient_path):
                continue

            # Copy ảnh từ từng magnification thẳng vào folder class/mag
            for mag in magnifications:
                mag_dst = os.path.join(class_path, mag)
                os.makedirs(mag_dst, exist_ok=True)

                mag_src = os.path.join(patient_path, mag)
                if not os.path.isdir(mag_src):
                    continue

                for file in os.listdir(mag_src):
                    src_file = os.path.join(mag_src, file)
                    if os.path.isfile(src_file):
                        dst_file = os.path.join(mag_dst, f"{patient}_{file}")
                        shutil.copy(src_file, dst_file)

            # Xóa folder patient cũ
            shutil.rmtree(patient_path)
        print(f"✔ Hoàn thành di chuyển hình trong {class_name}")

def show_sample_images(data_path, split="train", class_name="benign", n_samples=12):
    """
    Hiển thị vài tấm hình mẫu sau khi flatten.
    Mặc định: lấy ảnh từ train/benign
    """

    class_path = os.path.join(data_path, split, class_name)

    all_images = []
    for mag in magnifications:
        mag_path = os.path.join(class_path, mag)
        if os.path.isdir(mag_path):
            files = os.listdir(mag_path)
            for f in files:
                all_images.append(os.path.join(mag_path, f))

    if len(all_images) == 0:
        print("⚠ Không có ảnh để hiển thị.")
        return

    # Random chọn n_samples ảnh
    samples = random.sample(all_images, min(n_samples, len(all_images)))

    cols = 4
    rows = (len(samples) // cols) + 1

    plt.figure(figsize=(16, 4 * rows))

    for idx, img_path in enumerate(samples):
        img = Image.open(img_path)

        plt.subplot(rows, cols, idx + 1)
        plt.imshow(img)
        plt.axis("off")
        plt.title(os.path.basename(img_path), fontsize=8)

    plt.tight_layout()
    plt.show()
# =========================
# Chạy cân bằng và flatten cho từng split
# =========================
for split in ["train", "validation", "test"]:
    split_path = os.path.join(train_data_path, split)
    balance_split(split)
    merge_patients_flat(split_path)

print("\nHoàn thành cân bằng dữ liệu.")

# Thống kê số ảnh sau khi flatten
count_and_plot_images_binary_flat()
