NUMBER_OF_RETRY:int = 10

# ======== Làm giàu (Tấm hình) ==========
def augment_image(img):
    img = img.convert("RGB")
    applied = []

    # Rotate / Flip
    # angle = random.choice([90, 180, 270])
    angle = random.randint(-ROTATE_RANGE, ROTATE_RANGE)
    img = rotate(img, angle)
    applied.append(f"rot{angle}")


    # Flip
    is_flip_lr = random.random() > FLIP_LEFT_RIGHT_CHANCE
    is_flip_tb = random.random() > FLIP_LEFT_RIGHT_CHANCE
    img = flip(img, is_flip_lr, is_flip_tb)
    applied += ["flipLR"] if is_flip_lr else []
    applied += ["flipTB"] if is_flip_tb else []

    # Brightness & Contrast
    brightness_factor = round(random.uniform(1 - BRIGHTNESS_RANGE, 1 + BRIGHTNESS_RANGE), ROUND_NUMBER)
    contrast_factor   = round(random.uniform(1 - CONTRAST_RANGE, 1 + CONTRAST_RANGE), ROUND_NUMBER)
    img = brightness_contrast(img, brightness_factor, contrast_factor)
    applied.append("bright{:03d}_contrast{:03d}".format(int(brightness_factor*(ROUND_NUMBER*10)), int(contrast_factor*(ROUND_NUMBER * 10))))

    # Zoom
    zoom_factor = round(random.uniform(1 - ZOOM_RANGE, 1 + ZOOM_RANGE), ROUND_NUMBER)
    img = zoom(img, zoom_factor)
    applied.append("zoom{:03d}".format(int(zoom_factor*(ROUND_NUMBER*10))))
    
    # # Gamma
    # gamma_value = round(random.uniform(0.8, 1.2), 2)
    # img = gamma_correction(img, gamma_value)
    # applied.append("gamma{:03d}".format(int(gamma_value*100)))

    # # Color jitter
    # color_factor = round(random.uniform(0.9, 1.1), 2)
    # img = color_jitter(img, color_factor)
    # applied.append("color{:03d}".format(int(color_factor*100)))

    # # Noise
    # noise_std = round(random.uniform(1, 5), 2)
    # img = add_noise(img, noise_std)
    # applied.append("noise{:03d}".format(int(noise_std*100)))

    return img, applied

# ======== Làm giàu (Nhóm hình) ==========
def augment_group(group_path, target_count):
    files = [f for f in os.listdir(group_path) if os.path.isfile(os.path.join(group_path, f))]
    if not files: 
        return
    current_count = len(files)
    needed = target_count - current_count
    if needed <= 0: 
        return

    # Lưu kiểu augment đã dùng cho mỗi ảnh gốc
    augment_history = {f: set() for f in files}
    augmented_count = 0
    
    # Làm giàu dữ liệu
    while augmented_count < needed:
        original_file = random.choice(files)
        img_path = os.path.join(group_path, original_file)
        img = Image.open(img_path)

        for _ in range(NUMBER_OF_RETRY):
            img_aug, aug_types = augment_image(img)
            aug_label = "_".join(aug_types)
            
            # Nếu hình độc nhất --> Lưu
            if aug_label not in augment_history[original_file]:
                augment_history[original_file].add(aug_label)
                base, ext = os.path.splitext(original_file)
                new_name = f"{base}_{aug_label}_{ext}"
                img_aug.save(os.path.join(group_path, new_name))
                augmented_count += 1
                break
        # -- Đã có hình làm giàu tương tự --> Bỏ qua
        else:
            # nếu trùng hết, thử lại ảnh khác
            print(f"⚠ Không thể tạo hình mới cho {original_file}")
            continue
