# ======== Xác định chuẩn làm giàu ==========
def augment_requirement(split_path):
    train_data_count = count_images_per_split_flat(split_path)
    mininum_data_count = min(train_data_count.values())
    return mininum_data_count * AUGMENT_MULTIPLIER

# ======== Làm giàu theo nhóm ==========
def augment_split(split):
    split_path = os.path.join(train_data_path, split)
    
    # Xác định số lượng hình cần làm giàu
    target_count = augment_requirement(split_path)
    
    if target_count == 0:
        print("⚠ Không có ảnh trong split", split)
        return
    print(f"→ Split {split}, Mục tiêu làm giàu cho từng độ phóng đại: {target_count}")

    # Tiến hành làm giàu cho từng độ phóng đại
    for subtype in os.listdir(split_path):
        subtype_path = os.path.join(split_path, subtype)
        if not os.path.isdir(subtype_path):
            continue

        for mag in magnifications:
            mag_path = os.path.join(subtype_path, mag)
            if os.path.isdir(mag_path):
                augment_group(mag_path, target_count)
                print(f"  - Đã làm giàu {target_count} ảnh cho {subtype}/{mag}")

# ======== Tiến hành làm giàu ==========
