def to_json_safe(x):
    if isinstance(x, np.ndarray):
        return x.tolist()
    if isinstance(x, (np.float32, np.float64)):
        return float(x)
    if isinstance(x, (np.int32, np.int64)):
        return int(x)
    return x

def train_model(model_name, model_type, image_size, learning_rate, epochs, batch_size, number_epoch_freeze, patience, imagenet_mean = None, imagenet_std = None, pretrained = PRE_TRAINED):
    train_loader, validation_loader, test_loader, classes = make_dataloaders(image_size ,batch_size, imagenet_mean, imagenet_std)
    
    # Cấu hình log
    logger = log_setup(model_name)
    logger.info("===== CẤU HÌNH HUẤN LUYỆN =====")
    logger.info(f"                          Tên model: {model_name}")
    logger.info(f"                         Loại Model: {model_type}")
    logger.info(f"                       Kích cỡ hình: {image_size}")
    logger.info(f"Số mẫu dữ liệu/lần học (Batch size): {batch_size}")
    logger.info(f" Số lượt huấn luyện tối ta (Epochs): {epochs}")
    logger.info(f"         Tốc độ học (Learning rate): {learning_rate}")
    logger.info(f"                  Số lượt đóng băng: {number_epoch_freeze}")
    logger.info(f"             Số lượt chờ (patience): {patience}")
    logger.info("========================")
    
    if len(train_loader.dataset) == 0:
        print("Không tìm thấy ảnh nào. Kiểm tra đường dẫn")
        logger.info("Không tìm thấy ảnh nào. Kiểm tra đường dẫn")
        return

    num_classes = len(classes)
    model = build_model(num_classes, model_type, pretrained = PRE_TRAINED)
    criterion = nn.CrossEntropyLoss(label_smoothing=0.05)

    device_type = "cuda" if torch.cuda.is_available() else "cpu"
    scaler = torch.amp.GradScaler(device_type) if USE_MIXED_PRECISION else None

    optimizer = optim.AdamW(model.parameters(), lr = learning_rate, weight_decay = WEIGHT_DECAY)
    # Giảm LR khi val_acc không cải thiện trong 'patience' epoch
    scheduler = ReduceLROnPlateau(optimizer, mode='max', factor=0.5, patience=1, verbose=True)
    # ========== Huấn luyện phần cuối (Vài lượt đầu) ==========
    if FREEZE_FEATURES:
        print("\nĐang khóa các lớp đầu (Feature extractor), chỉ huấn luyện các lớp cuối (Head)...\n")
        logger.info("\nĐang khóa các lớp đầu (Feature extractor), chỉ huấn luyện các lớp cuối (Head)...\n")
        for name, param in model.named_parameters():
            if "head" not in name and "fc" not in name and "classifier" not in name:
                param.requires_grad = False

    best_validation_accuracy = 0.0
    patience_counter = 0
    last_learning_rate = learning_rate
    # Đường dẫn lưu model
    os.makedirs(os.path.join(MODEL_TYPE_PATH, model_name), exist_ok=True)
    best_model_path = os.path.join(MODEL_TYPE_PATH, model_name, "best_train.pth")
    current_model_path = os.path.join(MODEL_TYPE_PATH, model_name, "last_train.pth")
    
    # Lịch sử train
    history_path = os.path.join(MODEL_TYPE_PATH, model_name, "train_history.json")
    train_history = []
    
    # ========== Vòng lặp huấn luyện ==========
    for epoch in range(1, epochs+1):
        model.train()
        running_loss = 0.0
        correct = 0
        total = 0
        loop = tqdm(train_loader, desc=f"Vòng lặp (Epoch) {epoch}/{epochs}", leave=False)
        
        # Bắt đầu ghi nhận thời gian train
        epoch_start_time = time.time()
        for imgs, labels in loop:
            imgs = imgs.to(DEVICE)
            labels = labels.to(DEVICE)
            optimizer.zero_grad()

            if scaler is not None:
                with torch.amp.autocast(device_type='cuda' if torch.cuda.is_available() else 'cpu'):
                    outputs = model(imgs)
                    loss = criterion(outputs, labels)
                scaler.scale(loss).backward()
                scaler.step(optimizer)
                scaler.update()
            else:
                outputs = model(imgs)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()

            # Thống kê dữ liệu
            running_loss += loss.item() * labels.size(0)
            total += labels.size(0)
            
            predictions = outputs.argmax(dim=1)
            correct += (predictions == labels).sum().item()
            
            # In kết quả huấn luyện
            loop.set_postfix(
                loss = running_loss / total,
                accuracy  = correct / total
            )
        epoch_time = time.time() - epoch_start_time
        
        # ========== Thống kê vòng lặp (Epoch) ==========
        train_average_loss = running_loss / total
        train_accuracy  = correct / total
        validation_loss, validation_accuracy, validation_report, validation_confussion_matrix = evaluate_model(model, validation_loader, criterion)
        epoch_time = time.time() - epoch_start_time
        
        # --- Điều chỉnh tốc độ học ---
        scheduler.step(validation_accuracy)
        current_lr = optimizer.param_groups[0]['lr']
        if last_learning_rate != current_lr:
            print("  -> Tốc độ học (Learning rate) được điều chỉnh thành: ", optimizer.param_groups[0]['lr'])
            logger.info("  -> Tốc độ học (Learning rate) được điều chỉnh thành: %f", optimizer.param_groups[0]['lr'])

        print(f"Vòng lặp (Epoch): {epoch} | Tổng thời gian: {epoch_time:.2f} giây| Mất mát trung bình (Loss): {train_average_loss:.4f} | Độ chính xác (Validation): {validation_accuracy:.4f}")
        logger.info(f"Vòng lặp (Epoch): {epoch} | Tổng thời gian: {epoch_time:.2f} giây| Mất mát trung bình (Loss): {train_average_loss:.4f} | Độ chính xác (Validation): {validation_accuracy:.4f}")
        
        # Ghi nhận lịch sử train
        epoch_record = {
            "epoch": epoch,
            "train_time": epoch_time,
            "learning_rate": optimizer.param_groups[0]["lr"],
            
            # Kết quả train
            "train_loss": train_average_loss,
            "train_accuracy": train_accuracy,
            
            "validation_loss": validation_loss,
            "validation_acc": validation_accuracy,
            "validation_report": validation_report,
            "validation_confussion_matrix": validation_confussion_matrix.tolist(),
            
            "epoch": epoch,
            "best_val_acc": best_validation_accuracy,
            "patience_counter": patience_counter,
            "is_early_stop": (
                validation_accuracy <= best_validation_accuracy + 1e-6
                and patience_counter + 1 >= patience
            )
        }
        train_history.append(epoch_record)

        with open(history_path, "w", encoding="utf-8") as f:
            json.dump(train_history, f, indent=2, ensure_ascii=False)
            
        # ========== Lưu thông số mô hình mới nhất ==========
        torch.save({
            # Thông số train
            "model_name": model_name,
            "model_type": model_type,
            "learning_rate": learning_rate,
            "batch_size": batch_size,
            "image_size": image_size,
            "train_time": epoch_time,
            
            # Thông tin model train hiện tại
            "model_state": model.state_dict(),
            "optimizer_state": optimizer.state_dict(),
            "scaler_state": scaler.state_dict() if scaler else None,
            "classes": classes,
            
            # Kết quả train
            "train_loss": train_average_loss,
            "train_accuracy": train_accuracy,
            
            "validation_loss": validation_loss,
            "validation_acc": validation_accuracy,
            "validation_report": validation_report,
            "validation_confussion_matrix": validation_confussion_matrix.tolist(),
            
            # Tổng quan quá trình trình train
            "epoch": epoch,
            "best_val_acc": best_validation_accuracy,
            "patience_counter": patience_counter,
            "is_early_stop": (
                validation_accuracy <= best_validation_accuracy + 1e-6
                and patience_counter + 1 >= patience
            )
        }, current_model_path)
                    
                    
        # ========== Mở khóa huấn luyện phần đầu ==========
        if FREEZE_FEATURES and epoch == number_epoch_freeze:
            print(f"Bỏ đóng băng tất cả tham số của mô hình tại vòng lặp {epoch}.")
            logger.info(f"Bỏ đóng băng tất cả tham số của mô hình tại vòng lặp {epoch}.")
            
            # # Unfreeze toàn bộ
            # for param in model.parameters():
            #     param.requires_grad = True
            
            for name, param in model.named_parameters():
                if "stages.3" in name:
                    param.requires_grad = True
                    
            # (optional) lower lr a bit
            for g in optimizer.param_groups:
                g['lr'] = learning_rate * 0.1
            print("  -> Tốc độ học (Learning rate) được giảm xuống: ", optimizer.param_groups[0]['lr'])
            logger.info("  -> Tốc độ học (Learning rate) được giảm xuống: %f", optimizer.param_groups[0]['lr'])
        
        # ========== Kết thúc sớm ==========
        if validation_accuracy > best_validation_accuracy + 1e-6:
            best_validation_accuracy = validation_accuracy
            patience_counter = 0    
            torch.save({
                # Thông số train
                "model_name": model_name,
                "model_type": model_type,
                "learning_rate": learning_rate,
                "batch_size": batch_size,
                "image_size": image_size,
                "train_time": epoch_time,
                
                # Thông tin model train hiện tại
                "model_state": model.state_dict(),
                "optimizer_state": optimizer.state_dict(),
                "scaler_state": scaler.state_dict() if scaler else None,
                "classes": classes,
            
                # Kết quả train
                "train_loss": train_average_loss,
                "train_accuracy": train_accuracy,
                
                "validation_loss": validation_loss,
                "validation_acc": validation_accuracy,
                "validation_report": validation_report,
                "validation_confussion_matrix": validation_confussion_matrix.tolist(),
                
                # Tổng quan quá trình trình train
                "epoch": epoch,
                "best_val_acc": best_validation_accuracy,
                "patience_counter": patience_counter,
                
                
            }, best_model_path)
            print(f"  -> Mô hình huấn luyện tốt nhất đã được ghi nhận (Với độ chính xác (Validation): {validation_accuracy:.4f})")
            logger.info(f"  -> Mô hình huấn luyện tốt nhất đã được ghi nhận (Với độ chính xác (Validation): {validation_accuracy:.4f})")
            
        # ========== Tiếp tục ==========
        else:
            patience_counter += 1
            print(f"  -> Số lần không cải thiện: ({patience_counter}/{patience})")
            logger.info(f"  -> Số lần không cải thiện: ({patience_counter}/{patience})")
            if patience_counter >= patience:
                print("  -> Kết thúc sớm quá trình huấn luyện")
                logger.info("  -> Kết thúc sớm quá trình huấn luyện")
                break
        print("\n")
    # ========== Đánh giá ==========
    summary, validation_report, validation_confusion_matrix, test_report, test_confussion_matrix = report_model(model, best_model_path, validation_loader, test_loader, classes, criterion)
    return best_model_path, summary, validation_report, validation_confusion_matrix, test_report, test_confussion_matrix
