# ========== Dựng mô hình huấn luyện ==========
def build_model(num_classes, model_type, pretrained = PRE_TRAINED):
    model = timm.create_model(model_type, pretrained = PRE_TRAINED, num_classes = num_classes)
    model = model.to(DEVICE)
    return model

# ========== Dựng mô hình đánh giá ==========
def evaluate_model(model, loader, criterion):
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0

    predictions = []
    trues = []

    with torch.no_grad():
        for images, labels in loader:
            images = images.to(DEVICE)
            labels = labels.to(DEVICE)

            outputs = model(images)
            loss = criterion(outputs, labels)

            batch_size = labels.size(0)
            running_loss += loss.item() * batch_size
            total += batch_size

            preds = outputs.argmax(dim=1)
            correct += (preds == labels).sum().item()

            predictions.extend(preds.cpu().numpy())
            trues.extend(labels.cpu().numpy())

    val_loss = running_loss / total if total > 0 else 0.0
    val_acc = correct / total if total > 0 else 0.0

    report = classification_report(trues, predictions, zero_division=0, output_dict=True) if total > 0 else {}
    cm = confusion_matrix(trues, predictions) if total > 0 else np.zeros((1,1))

    return val_loss, val_acc, report, cm
