# ========== Dựng mô hình huấn luyện ==========
def build_model(num_classes, model_type, pretrained = PRE_TRAINED):
    model = timm.create_model(model_type, pretrained = PRE_TRAINED, num_classes = num_classes)
    model = model.to(DEVICE)
    return model

# ========== Dựng mô hình đánh giá ==========
def evaluate_model(model, loader, criterion, threshold=0.5):
    model.eval()
    running_loss = 0.0
    total = 0

    predictions = []
    labels = []

    with torch.no_grad():
        for images, labels in loader:
            images = images.to(DEVICE)
            labels = labels.float().to(DEVICE)

            outputs = model(images).squeeze(1)
            loss = criterion(outputs, labels)

            probs = torch.sigmoid(outputs)
            preds = (probs >= threshold).long()

            running_loss += loss.item() * labels.size(0)
            total += labels.size(0)

            predictions.extend(preds.cpu().numpy())
            labels.extend(labels.cpu().numpy())

    validation_loss = running_loss / total
    validation_report = classification_report(
        labels,
        predictions,
        zero_division=0,
        output_dict=True
    )
    validation_confussion_matrix = confusion_matrix(labels, predictions)

    validation_accuracy = validation_report["accuracy"]
    recall_malignant = validation_report["1"]["recall"]

    return validation_loss, validation_accuracy, recall_malignant, validation_report, validation_confussion_matrix
