# ========== Dựng mô hình huấn luyện ==========
def build_model(num_classes, model_type, pretrained = PRE_TRAINED):
    model = timm.create_model(model_type, pretrained = PRE_TRAINED, num_classes = num_classes)
    model = model.to(DEVICE)
    return model

# ========== Dựng mô hình đánh giá ==========
def evaluate_model(model, loader, criterion):
    model.eval()
    running_loss = 0.0
    total = 0

    all_preds = []
    all_labels = []

    with torch.no_grad():
        for images, batch_labels in loader:
            images = images.to(DEVICE)
            batch_labels = batch_labels.float().to(DEVICE)

            outputs = model(images).squeeze(1)
            loss = criterion(outputs, batch_labels)

            running_loss += loss.item() * batch_labels.size(0)
            total += batch_labels.size(0)

            probs = torch.sigmoid(outputs)
            preds = (probs >= 0.5).long()

            all_preds.extend(preds.cpu().numpy())
            all_labels.extend(batch_labels.long().cpu().numpy())

    avg_loss = running_loss / total if total > 0 else 0.0
    acc = (np.array(all_preds) == np.array(all_labels)).mean()

    report = classification_report(
        all_labels,
        all_preds,
        zero_division=0,
        output_dict=True
    )

    cm = confusion_matrix(all_labels, all_preds)

    # recall malignant = class 1
    recall_malignant = report["1"]["recall"] if "1" in report else 0.0

    return avg_loss, acc, recall_malignant, report, cm
