cache_path = kagglehub.dataset_download("ambarish/breakhis")

# cache_path = "C:\\Users\\MIT\\.cache\\kagglehub\\datasets\\ambarish\\breakhis\\versions\\4"

# Kiểm tra tồn tại trước khi xóa
if os.path.exists(original_data_path) and os.path.isdir(original_data_path):
    shutil.rmtree(original_data_path)
    print(f"Đã xóa tệp tin: {original_data_path}")
    
# Sao chép tập dữ liệu vào thư mục dự án
cache_data = os.path.join(cache_path, "BreaKHis_v1", "BreaKHis_v1", "histology_slides", "breast")

records = []

for main_class in classes:
    main_class_path = os.path.join(cache_data, main_class)
    if not os.path.isdir(main_class_path):
        continue

    for subtype_folder in os.listdir(main_class_path):
        subtype_path = os.path.join(main_class_path, subtype_folder)
        if not os.path.isdir(subtype_path):
            continue

        if subtype_folder == "SOB":
            # Lấy các con của SOB làm subtype thực
            for real_subtype in os.listdir(subtype_path):
                real_subtype_path = os.path.join(subtype_path, real_subtype)
                if not os.path.isdir(real_subtype_path):
                    continue

                for patient in os.listdir(real_subtype_path):
                    patient_path = os.path.join(real_subtype_path, patient)
                    if not os.path.isdir(patient_path):
                        continue

                    dst_patient_path = os.path.join(original_data_path, main_class, real_subtype, patient)
                    os.makedirs(dst_patient_path, exist_ok=True)

                    for magnification in os.listdir(patient_path):
                        mag_src_path = os.path.join(patient_path, magnification)
                        if not os.path.isdir(mag_src_path):
                            continue
                        mag_dst_path = os.path.join(dst_patient_path, magnification)
                        shutil.copytree(mag_src_path, mag_dst_path)
        else:
            # Nếu không phải SOB, giữ nguyên
            for patient in os.listdir(subtype_path):
                patient_path = os.path.join(subtype_path, patient)
                if not os.path.isdir(patient_path):
                    continue

                dst_patient_path = os.path.join(original_data_path, main_class, subtype_folder, patient)
                os.makedirs(dst_patient_path, exist_ok=True)

                for magnification in os.listdir(patient_path):
                    mag_src_path = os.path.join(patient_path, magnification)
                    if not os.path.isdir(mag_src_path):
                        continue
                    mag_dst_path = os.path.join(dst_patient_path, magnification)
                    shutil.copytree(mag_src_path, mag_dst_path)
                    
