def chart_table_original(dataFrame):
    plt.figure(figsize=(12, 6))

    ax = sns.barplot(
        data=dataFrame,
        x="Class",
        y="Num_Images",
        hue="Magnification",
        palette="Set2"
    )

    plt.title("SỐ LƯỢNG HÌNH ẢNH THEO NHÓM BỆNH", fontweight="bold")
    plt.xlabel("Loại")
    plt.ylabel("Số lượng hình ảnh")

    # --- Đưa legend xuống dưới ---
