# --- Chia dữ liệu ---
for main_class in os.listdir(original_data_path):
    class_path = os.path.join(original_data_path, main_class)
    if not os.path.isdir(class_path):
        continue

    for subtype in os.listdir(class_path):
        subtype_path = os.path.join(class_path, subtype)
        if not os.path.isdir(subtype_path):
            continue

        # Lấy danh sách bệnh nhân
        patients = [p for p in os.listdir(subtype_path) if os.path.isdir(os.path.join(subtype_path, p))]
        random.shuffle(patients)
        n_total = len(patients)

        if n_total == 0:
            continue  # Không có bệnh nhân → bỏ qua

        # --- Phân bổ bệnh nhân ---
        split_dict = {"train": [], "validation": [], "test": []}

        if n_total < 3:
            # Quá ít bệnh nhân → phân bổ theo thứ tự train → val → test
            for i, patient in enumerate(patients):
                if i == 0:
                    split_dict["train"].append(patient)
                elif i == 1:
                    split_dict["validation"].append(patient)
                else:
                    split_dict["test"].append(patient)
        else:
            # >=3 bệnh nhân → chia theo tỉ lệ
            n_train = max(1, round(splits_ratio["train"] * n_total))
            n_val = max(1, round(splits_ratio["validation"] * n_total))
            n_test = n_total - n_train - n_val

            # Nếu test hoặc val = 0 → gán ít nhất 1 bệnh nhân
            if n_val == 0 and n_total >= 2:
                n_val = 1
                n_train -= 1
            if n_test == 0 and n_total >= 3:
                n_test = 1
                n_train -= 1

            # Chia bệnh nhân theo chỉ số
            split_dict["train"] = patients[:n_train]
            split_dict["validation"] = patients[n_train:n_train+n_val]
            split_dict["test"] = patients[n_train+n_val:]

        # --- Copy bệnh nhân sang split tương ứng ---
        for split_name, patient_list in split_dict.items():
            for patient in patient_list:
                src_patient_path = os.path.join(subtype_path, patient)
                #dst_patient_path = os.path.join(train_data_path, split_name, main_class, subtype, patient)
                dst_patient_path = os.path.join(train_data_path, split_name, main_class, patient)
                if not os.path.exists(dst_patient_path):
                    os.makedirs(dst_patient_path, exist_ok=True)

                # Copy toàn bộ magnification và hình
                for magnification in os.listdir(src_patient_path):
                    mag_src_path = os.path.join(src_patient_path, magnification)
                    if not os.path.isdir(mag_src_path):
                        continue
                    mag_dst_path = os.path.join(dst_patient_path, magnification)
                    shutil.copytree(mag_src_path, mag_dst_path, dirs_exist_ok=True)
