    data_counts = {}

    # --- Đếm các split ---
    for split in SPLITS:
        split_path = os.path.join(train_data_path, split)
        if not os.path.exists(split_path):
            continue

        data_counts[split] = count_images_binary_flat(split_path)

    # --- Gom DataFrame ---
    all_data = []
    for split in SPLITS:
        if split not in data_counts:
            continue

        # loop đúng: vào dict con
        for cls_mag, count in data_counts[split].items():
            # cls_mag dạng "benign/40X"
            if "/" not in cls_mag:
                print("WARNING: Key không hợp lệ:", cls_mag)
                continue

            main_class, mag = cls_mag.split("/")
            all_data.append({
                "Split": split,
                "Class": main_class,
                "Magnification": mag,
                "Num_Images": count
            })

    df = pd.DataFrame(all_data)

    chart_table(df)
    
