def original_image_statistics():
    records = []
    for label in classes:
        label_path = os.path.join(original_data_path, label)
        if not os.path.isdir(label_path):
            continue

        for subtype in os.listdir(label_path):
            subtype_path = os.path.join(label_path, subtype)
            if not os.path.isdir(subtype_path):
                continue

            for patient in os.listdir(subtype_path):
                patient_path = os.path.join(subtype_path, patient)
                if not os.path.isdir(patient_path):
                    continue

                for magnification in os.listdir(patient_path):
                    mag_path = os.path.join(patient_path, magnification)
                    if not os.path.isdir(mag_path):
                        continue

                    num_images = len([
                        f for f in os.listdir(mag_path)
                        if f.lower().endswith((".png", ".jpg", ".jpeg", ".tif", ".tiff"))
                    ])

                    records.append({
                        "Split": "all",
                        "Class": label,
                        "Subtype": subtype,
                        "Patient": patient,
                        "Magnification": magnification,
                        "Num_Images": num_images
                    })

    df = pd.DataFrame(records)

    df = (
        df.groupby(["Split", "Class", "Magnification"], as_index=False)
          .agg({"Num_Images": "sum"})
    )

    original_chart(df)

