def stain_normalization(img):
    normalizer = torchstain.normalizers.MacenkoNormalizer()
    normalizer.fit(torch.tensor(img).permute(2, 0, 1))
    t_img = transforms.ToTensor()(img).unsqueeze(0)
    
    with torch.no_grad():
        curr_norm, H, E = normalizer.normalize(probs=t_img, stiffness=1.0)
        # Chuyển ngược lại PIL
        curr_norm = curr_norm.squeeze(0).permute(1, 2, 0).numpy().astype(np.uint8)
        img = Image.fromarray(curr_norm)

# ======== Chuẩn hóa màu (Stain Normalization) ==========
to_tensor = transforms.ToTensor()
normalizer = torchstain.normalizers.MacenkoNormalizer()

def stain_normalization(img, stiffness_factor, alpha_factor):
    normalizer.fit(torch.tensor(img).permute(2, 0, 1))
    try:
        # Chuyển PIL sang Tensor để xử lý
        img_t = to_tensor(img)
        
        with torch.no_grad():
            # I: ảnh đầu vào, stiffness: độ cứng của việc tách màu
            norm_t, _, _ = normalizer.normalize(I=img_t, stiffness=stiffness_factor, alpha=alpha_factor)
            
            # Chuyển ngược lại thành mảng Numpy uint8
            norm_np = norm_t.numpy().astype(np.uint8)
            return Image.fromarray(norm_np), True
    except Exception as e:
        # Nếu lỗi (do ảnh quá trắng/trống), trả về ảnh gốc và thông báo False
        return img, False
