# ======== Chuẩn hóa màu (Stain Normalization) ==========
to_tensor = transforms.ToTensor()
normalizer = torchstain.normalizers.MacenkoNormalizer()

def stain_normalization(img, h_factor, e_factor):
    # Chuyển PIL sang Tensor
    img_t = to_tensor(img.convert("RGB"))
    
    try:
        with torch.no_grad():
            # 1. Tách ma trận màu (stain matrix) và nồng độ (concentrations)
            # Chú ý: .transform trả về (nồng độ, ma trận màu)
            concentric, stain_matrix = normalizer.transform(img_t)
            
            # 2. Trong Macenko, nồng độ được lưu theo hàng: 
            # hàng 0 thường là Hematoxylin, hàng 1 là Eosin
            concentric[0, :] *= h_factor # Nhân factor cho H
            concentric[1, :] *= e_factor # Nhân factor cho E
            
            # 3. Tái tạo lại ảnh từ nồng độ mới và ma trận màu ban đầu
            # Công thức: I = S * C (trong không gian Optical Density)
            # Thư viện torchstain hỗ trợ hàm normalize() trực tiếp sẽ tiện hơn, 
            # nhưng nếu muốn can thiệp sâu, ta dùng công thức tính ngược:
            
            # Tuy nhiên, cách ĐƠN GIẢN nhất để dùng h_factor và e_factor 
            # là truyền trực tiếp vào hàm normalize nếu phiên bản của bạn hỗ trợ:
            norm_t, _, _ = normalizer.normalize(I=img_t, stiffness=h_factor, alpha=e_factor)
            
            norm_np = norm_t.numpy().astype(np.uint8)
            return Image.fromarray(norm_np), True
    except Exception as e:
        print(f"Lỗi: {e}")
        return img, False
