# ========== Dựng mô hình huấn luyện ==========
def build_model(num_classes, model_type, pretrained = PRE_TRAINED):
    model = timm.create_model(model_type, pretrained = PRE_TRAINED, num_classes = num_classes)
    model = model.to(DEVICE)
    return model

# ========== Dựng mô hình đánh giá ==========
def evaluate_model(model, loader, criterion, threshold=0.5):
    model.eval()
    running_loss = 0.0
    total = 0

    all_predictions = [] # Đổi tên để tránh trùng
    all_labels = []      # Đổi tên để tránh trùng

    with torch.no_grad():
        for images, batch_labels in loader:
            images = images.to(DEVICE)
            batch_labels = batch_labels.float().to(DEVICE) # BCEWithLogitsLoss cần float

            outputs = model(images).squeeze(1) 
            loss = criterion(outputs, batch_labels)

            probs = torch.sigmoid(outputs)
            preds = (probs >= threshold).long()

            running_loss += loss.item() * batch_labels.size(0)
            total += batch_labels.size(0)

            all_predictions.extend(preds.cpu().numpy())
            all_labels.extend(batch_labels.cpu().numpy())

    avg_loss = running_loss / total
    
    # Chuyển về dạng int để làm report
    all_labels_int = [int(i) for i in all_labels]
    
    report = classification_report(
        all_labels_int,
        all_predictions,
        zero_division=0,
        output_dict=True
    )
    
    cm = confusion_matrix(all_labels_int, all_predictions)
    TN, FP, FN, TP = cm.ravel()
    accuracy = report["accuracy"]
    recall_0 = TN / (TN + FP + 1e-8)
    recall_1 = TP / (TP + FN + 1e-8)
    
    return avg_loss, accuracy, recall_0, recall_1, report, cm
