import matplotlib.pyplot as plt

epochs = list(range(1, 17))

# Recall từng lớp
recall_0 = [
    0.17162471395881007, 0.7482837528604119, 0.9816933638443935, 0.988558352402746,
    0.9931350114416476, 0.9931350114416476, 1.0, 0.8672768878718535,
    0.9748283752860412, 1.0, 0.9473684210526315, 0.9702517162471396,
    0.988558352402746, 0.9931350114416476, 0.9977116704805492, 0.9908466819221968
]
recall_1 = [
    0.9244851258581236, 0.8993135011441648, 0.5835240274599542, 0.8032036613272311,
    0.7757437070938215, 0.7459954233409611, 0.6544622425629291, 0.9954233409610984,
    0.9176201372997712, 0.471395881006865, 0.9862700228832952, 0.9427917620137299,
    0.8558352402745996, 0.8100686498855835, 0.7917620137299771, 0.8237986270022883
]

# Balanced score: trung bình recall hai lớp
balanced_score = [(r0 + r1)/2 for r0, r1 in zip(recall_0, recall_1)]

plt.figure(figsize=(9, 7))
plt.plot(epochs, recall_0, marker='o', linewidth=2, label="Lành tính (Benign)")
plt.plot(epochs, recall_1, marker='s', linewidth=2, label="Ác tính (Malignant)")
plt.plot(epochs, balanced_score, marker='^', linewidth=2, label="Balanced Score")

# Ghi số lên biểu đồ
for x, y in zip(epochs, recall_0):
    plt.text(x, y - 0.02, f"{y:.3f}", fontsize=9, ha="center")
for x, y in zip(epochs, recall_1):
    plt.text(x, y + 0.01, f"{y:.3f}", fontsize=9, ha="center")
for x, y in zip(epochs, balanced_score):
    plt.text(x, y + 0.02, f"{y:.3f}", fontsize=9, ha="center")

