plt.ylim(0, 1.05)
plt.xlabel("Lượt huấn luyện (Epoch)")
plt.ylabel("Tỷ lệ dương tính thật (Recall)")
plt.title("Recall từng lớp và Balanced Score theo từng Epoch", fontsize=14, fontweight="bold")

plt.legend(loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=3, frameon=False)
plt.grid(alpha=0.3)
plt.tight_layout()
plt.show()
