import matplotlib.pyplot as plt

epochs = list(range(1, 17))
train_loss = [
    0.1738,0.1739,0.1739,0.1752,0.1727,0.1719,0.1718,0.1714,
    0.1715,0.1713,0.1712,0.1710,0.1706,0.1707,0.1704,0.1699
]
val_loss = [
    0.1695,0.1616,0.1611,0.1255,0.1062,0.1230,0.1226,0.1111,
    0.0957,0.1341,0.0984,0.1100,0.0926,0.1046,0.1078,0.0965
]
learning_rate = [
    0.0001,0.0001,0.0001,1e-05,1e-05,1e-05,1e-05,1e-05,
    1e-05,1e-05,1e-05,1e-05,1e-05,1e-05,1e-05,1e-05
]

fig, ax1 = plt.subplots(figsize=(10, 6))

# Loss curves
ax1.plot(epochs, train_loss, marker="o", linewidth=2, label="Train Loss", color="blue")
ax1.plot(epochs, val_loss, marker="s", linewidth=2, label="Validation Loss", color="green")
ax1.set_xlabel("Epoch")
ax1.set_ylabel("Loss")
ax1.set_xticks(epochs)
ax1.set_title("Loss và Learning Rate theo từng Epoch", fontsize=14, fontweight="bold")
ax1.grid(alpha=0.3)
ax1.legend(loc="upper left")

# Annotate loss values
for x, y in zip(epochs, train_loss):
    ax1.text(x, y + 0.001, f"{y:.3f}", fontsize=9, ha="center")
for x, y in zip(epochs, val_loss):
    ax1.text(x, y + 0.001, f"{y:.3f}", fontsize=9, ha="center")

# Learning rate curve (twin axis)
ax2 = ax1.twinx()
ax2.plot(epochs, learning_rate, marker="^", linewidth=2, color="red", label="Learning Rate")
ax2.set_ylabel("Learning Rate")
ax2.set_yscale("log")
ax2.legend(loc="upper right")

plt.tight_layout()
plt.show()
