def to_json_safe(x):
    if isinstance(x, np.ndarray):
        return x.tolist()
    if isinstance(x, (np.float32, np.float64)):
        return float(x)
    if isinstance(x, (np.int32, np.int64)):
        return int(x)
    return x

def early_stop(balanced_score, best_balanced_score, patience_counter, patience):
    return balanced_score <= best_balanced_score and patience_counter >= patience

class FocalLoss(nn.Module):
    def __init__(self, gamma=2.0):
        super().__init__()
        self.gamma = gamma
        self.bce = nn.BCEWithLogitsLoss(reduction="none")

    def forward(self, logits, targets):
        bce = self.bce(logits, targets)
        pt = torch.exp(-bce)
        loss = (1 - pt) ** self.gamma * bce
        return loss.mean()

def train_model(model_name, model_type, image_size, learning_rate, epochs, batch_size, number_epoch_freeze, patience, imagenet_mean = None, imagenet_std = None, pretrained = PRE_TRAINED):
    train_loader, validation_loader, test_loader, classes = make_dataloaders(image_size ,batch_size, imagenet_mean, imagenet_std)
    
    # Cấu hình log
