def bar_chart(df, title):
    df = df.copy()
    
    df["Magnification"] = pd.Categorical(
        df["Magnification"],
        categories=MAGNIFICATIONS,
        ordered=True
    )

    plt.figure(figsize=(8, 6))
    ax = sns.barplot(
        data=df,
        x="Class",
        y="Num_Images",
        hue="Magnification",
        hue_order = MAGNIFICATIONS,
        palette="Set2"
    )

    plt.title(title, fontweight="bold")
    plt.xlabel("Loại mô bệnh")
    plt.ylabel("Số lượng hình ảnh")

    # --- Đổi nhãn Class ---
    ax.set_xticks(range(len(ax.get_xticklabels())))
    ax.set_xticklabels([
        "Lành tính (Benign)",
        "Ác tính (Malignant)"
    ])
        
    # --- Hiện số trên cột ---
    for container in ax.containers:
        ax.bar_label(
            container,
            fmt="%d",
            label_type="edge",
            padding=2
        )

    handles, labels = ax.get_legend_handles_labels()
    ax.legend_.remove()
    plt.legend(
        handles,
        labels,
        title="Độ phóng đại",
        loc="upper center",
        bbox_to_anchor=(0.5, -0.15),
        ncol=len(labels),
        frameon=False
    )

    plt.tight_layout()
    plt.show()

# Thống kê tập dữ liệu huấn luyện
def chart_table(dataFrame, title):
    for split in SPLITS:
        df_split = dataFrame[dataFrame["Split"] == split]
        if df_split.empty:
            continue
        bar_chart(df_split, f"{title.upper()}\nTẬP DỮ LIỆU {split.upper()}")
    print(dataFrame)

# Thống kê tập dữ liệu gốc
def original_chart(dataFrame):
    bar_chart(dataFrame, "SỐ LƯỢNG HÌNH ẢNH THEO NHÓM BỆNH")
    print(dataFrame)
