# ========== CONFIG ==========
MODEL_NAME = "conv_next"
IMAGE_SIZE = 224
BATCH_SIZE = 16
EPOCHS = 30
LEARNING_RATE = 1e-4
UNFREEZE_AFTER = 3
PATIENCE = 5
MODEL_TYPE = "convnext_tiny"

