class LEVEL(IntEnum):
    DEBUG = logging.DEBUG
    INFO = logging.INFO
    WARNING = logging.WARNING
    ERROR = logging.ERROR

    
def log_setup(model_name: str):
    # Kiểm tra tệp tin dữ liệu đã được tạo
    log_directory = os.path.join(MODEL_TYPE_PATH, model_name)
    os.makedirs(log_directory, exist_ok=True)

    # Tạo tập tin lưu lịch sử
    log_file = os.path.join(log_directory, f"train_{datetime.now().strftime('%Y%m%d_%H%M%S')}.log")
    logger = logging.getLogger(model_name)
    logger.setLevel(logging.INFO)

    # Tránh thêm handler nhiều lần
    if logger.hasHandlers():
        logger.handlers.clear()
    file_handler = logging.FileHandler(log_file, mode="w", encoding="utf-8")

    # Định dạng log
    formatter = logging.Formatter(fmt="%(asctime)s | %(levelname)s | %(message)s")

    file_handler.setFormatter(formatter) 
    logger.addHandler(file_handler)
        
    return logger

def write_console(logger, level: LEVEL, message: str):
    logger.log(level, message.replace("\n", ""))
    print(message)
