# ========== Lấy ảnh từ tập dữ liệu ==========
class HistologyAllMagDataset(Dataset):
    def __init__(self, root_dir, transform=None, mags=None):
        self.samples = []
        self.labels = []
        self.transform = transform
        self.mags = mags if mags is not None else magnifications

        # lấy danh sách subtype (classes)
        self.classes = sorted([
            d for d in os.listdir(root_dir)
            if os.path.isdir(os.path.join(root_dir, d))
        ])

        for idx, subtype in enumerate(self.classes):
            subtype_dir = os.path.join(root_dir, subtype)
            for mag in self.mags:
                mag_dir = os.path.join(subtype_dir, mag)
                if not os.path.isdir(mag_dir):
                    continue
                for fname in os.listdir(mag_dir):
                    if fname.lower().endswith((".png", ".jpg", ".jpeg")):
                        self.samples.append(os.path.join(mag_dir, fname))
                        self.labels.append(idx)

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, idx):
        img = Image.open(self.samples[idx]).convert("RGB")
        if self.transform:
            img = self.transform(img)
        label = torch.tensor(self.labels[idx], dtype=torch.long) 
        return img, label

# ========== Chia dữ liệu (Theo Split) ==========
def data_loader(split, transform_setting, batch_size):
    data_directory = os.path.join(train_data_path, split)
    shuffle = True if split == "train" else False
    dataset = HistologyAllMagDataset(data_directory, transform = transform_setting)
    return DataLoader(dataset, batch_size = batch_size, shuffle = shuffle, num_workers = NUMBER_OF_WORKER, pin_memory=True), dataset

# ========== Chia dữ liệu (Toàn bộ Split) ==========
def make_dataloaders(image_size ,batch_size, IMAGENET_MEAN = None, IMAGENET_STD = None):
    
# ========== Biến đổi hình ==========
    train_transform_list = [
        transforms.RandomResizedCrop(image_size, scale=(0.8, 1.0)),
        transforms.RandomHorizontalFlip(),
        transforms.RandomVerticalFlip(),
        transforms.RandomRotation(90),
        # transforms.RandomAffine(degrees=10, translate=(0.05,0.05), scale=(0.9,1.1), shear=5),
        transforms.ColorJitter(brightness=0.1, contrast=0.1, saturation=0.1, hue=0.02),
        # transforms.GaussianBlur(kernel_size=3),
        transforms.ToTensor(),
        # transforms.RandomErasing(p=0.2, scale=(0.02, 0.15)),
    ]

    normal_transform_list = [
        transforms.Resize((image_size, image_size)),
        transforms.ToTensor(),
    ]

    # Nếu có Imagenet normalization
    if IMAGENET_MEAN is not None and IMAGENET_STD is not None:
        norm = transforms.Normalize(mean=IMAGENET_MEAN, std=IMAGENET_STD)
        train_transform_list.append(norm)
        normal_transform_list.append(norm)

    # Cuối cùng đóng lại thành Compose
    train_transform = transforms.Compose(train_transform_list)
    normal_transform = transforms.Compose(normal_transform_list)
    
    # ========== Chia dữ liệu ==========
    train_loader,       train_dataset       = data_loader("train", train_transform, batch_size)
    validation_loader,  validation_dataset  = data_loader("validation", normal_transform, batch_size)
    test_loader,        test_dataset        = data_loader("test", normal_transform, batch_size)
    
    # ========== Thống kê ==========
    train_class = train_dataset.classes
    print("Các lớp được sử dụng:", train_class)
    print(
    f"Số lượng dữ liệu dùng để huấn luyện:\n"
    f"         Train: {len(train_dataset)}\n"
    f"    Validation: {len(validation_dataset)}\n"
    f"          Test: {len(test_dataset)}"
    )
    return train_loader, validation_loader, test_loader, train_class
