def epoch_run(model, criterion, optimizer, scaler, loop):
    running_loss = 0.0
    correct = 0
    total = 0
    
    for imgs, labels in loop:
            imgs = imgs.to(DEVICE)
            labels = labels.float().to(DEVICE)
            optimizer.zero_grad()

            if scaler is not None:
                with torch.amp.autocast(device_type = DEVICE.type):
                    outputs = model(imgs).squeeze(1)
                    loss = criterion(outputs, labels)
                scaler.scale(loss).backward()
                scaler.step(optimizer)
                scaler.update()
            else:
                outputs = model(imgs).squeeze(1)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()

            # Thống kê dữ liệu
            running_loss += loss.item() * labels.size(0)
            total += labels.size(0)
            
            probs = torch.sigmoid(outputs)
            predictions = (probs >= 0.5).long()
            correct += (predictions == labels.long()).sum().item()
            
            # In kết quả huấn luyện
            loop.set_postfix(loss = running_loss / total, accuracy  = correct / total)
    return running_loss, correct, total
            
def train_model(model_name, model_type, image_size, learning_rate, epochs, batch_size, number_epoch_freeze, max_patience, imagenet_mean = None, imagenet_std = None, pretrained = PRE_TRAINED):
    # Cấu hình log
    logger = log_setup(model_name)
    train_setting(logger, model_name, model_type, image_size, batch_size, epochs, learning_rate, number_epoch_freeze, max_patience)
    
    # Tạo dataset
    train_loader, validation_loader, test_loader, classes = make_dataloaders(image_size ,batch_size, imagenet_mean, imagenet_std)
    
    # Kiểm tra số lượng ảnh
    if len(train_loader.dataset) == 0:
        write_console(logger, LEVEL.ERROR, "Không tìm thấy ảnh nào. Kiểm tra đường dẫn")
        return
    
    # Đường dẫn lưu mô hình đánh giá
    os.makedirs(os.path.join(MODEL_TYPE_PATH, model_name), exist_ok=True)
    best_model_path = os.path.join(MODEL_TYPE_PATH, model_name, "best_train.pth")
    current_model_path = os.path.join(MODEL_TYPE_PATH, model_name, "last_train.pth")
    
    # Lịch sử train
    history_path = os.path.join(MODEL_TYPE_PATH, model_name, "train_history.json")
    train_history = []
    
    # Cấu hình mô hình
    model = timm.create_model(model_type,pretrained=PRE_TRAINED,num_classes=1).to(DEVICE)
    criterion = FocalLoss(gamma=1.5)
    scaler = torch.amp.GradScaler(DEVICE) if USE_MIXED_PRECISION else None
    optimizer = optim.AdamW(model.parameters(), lr = learning_rate, weight_decay = WEIGHT_DECAY)
    scheduler = ReduceLROnPlateau(optimizer, mode='max', factor=0.5, patience=1) # Giảm LR khi val_acc không cải thiện trong 'patience' epoch
    
    # ========== Huấn luyện phần cuối (Vài lượt đầu) ==========
    if FREEZE_FEATURES:
        write_console(logger, LEVEL.WARNING, "Đang khóa các lớp đầu (Feature extractor), chỉ huấn luyện các lớp cuối (Head)...")
        for name, param in model.named_parameters():
            if "head" not in name and "fc" not in name and "classifier" not in name:
                param.requires_grad = False

    # Các biến đánh giá mô hình
    best_balanced_score = 0.0
    patience_counter = 0
    last_learning_rate = learning_rate
    
    # ========== Vòng lặp huấn luyện ==========
    for epoch in range(1, epochs+1):
        model.train()
        loop = tqdm(train_loader, desc=f"Vòng lặp (Epoch) {epoch}/{epochs}", leave=False)
        
        # ========== Huấn luyện mô hình ==========
        epoch_start_time = time.time()
        train_loss, correct, total = epoch_run(model, criterion, optimizer, scaler, loop)
        epoch_run_time = time.time() - epoch_start_time
        
        # ========== Thống kê vòng lặp (Epoch) ==========
        train_average_loss = train_loss / total
        train_accuracy  = correct / total
        validation_loss, validation_accuracy, recall_0, recall_1, validation_report, validation_confussion_matrix = evaluate_model(model, validation_loader, criterion)
        balanced_score = min(recall_0, recall_1)
        
        is_early_stop = early_stop(balanced_score, best_balanced_score, patience_counter, max_patience)
        epoch_statistic, run_statistic, model_info = statistic(model_name, model_type, batch_size, image_size, epochs, max_patience, model.state_dict(), optimizer.state_dict(), scaler.state_dict() if scaler else None, classes, epoch, epoch_run_time, learning_rate, train_loss, train_accuracy, validation_loss, validation_accuracy, validation_report, validation_confussion_matrix, validation_balanced_score, patience_counter, best_balanced_score, is_early_stop)
        
        write_console(logger, LEVEL.INFO, f"Vòng lặp (Epoch): {epoch} | Tổng thời gian: {epoch_run_time:.2f} giây| Mất mát trung bình (Loss): {train_average_loss:.4f} | Độ chính xác (Validation): {validation_accuracy:.4f} | Điểm trung bình (Balanced score): {validation_balanced_score:.4f})")
        
        # ========== Điều chỉnh mô hình ==========
        scheduler.step(balanced_score)
        current_lr = optimizer.param_groups[0]['lr']
        if last_learning_rate != current_lr:
            last_learning_rate = current_lr
            write_console(logger, LEVEL.WARNING, "  -> Tốc độ học (Learning rate) được điều chỉnh thành: %f", optimizer.param_groups[0]['lr'])

        # ========== Ghi nhận lịch sử huấn luyện ==========
        train_history.append({**epoch_statistic, **run_statistic})
        with open(history_path, "w", encoding="utf-8") as f:
            json.dump(train_history, f, indent=2, ensure_ascii=False)
            
        # ========== Lưu mô hình mới nhất ==========
        torch.save({**model_info, **epoch_statistic, **run_statistic}, current_model_path)
                    
                    
        # ========== Mở khóa huấn luyện phần đầu ==========
        if FREEZE_FEATURES and epoch == number_epoch_freeze:
            write_console(logger, LEVEL.WARNING, f"Bỏ đóng băng toàn bộ mô hình tại epoch {epoch}")

            for param in model.parameters():
                param.requires_grad = True

            optimizer = torch.optim.AdamW(
                model.parameters(),
                lr=learning_rate*0.1,
                weight_decay=WEIGHT_DECAY
            )

        # ========== Kết thúc sớm ==========
        if recall_0 == 0 or recall_1 == 0:
            write_console(logger, LEVEL.WARNING, "  -> Mô hình sập - Tạm dừng")
            break
        
        if best_balanced_score < balanced_score:
            best_balanced_score = balanced_score
            patience_counter = 0    
            torch.save({**model_info, **epoch_statistic}, best_model_path)
            write_console(logger, LEVEL.INFO, f"  -> Mô hình huấn luyện tốt nhất đã được ghi nhận (Với điểm trung bình (Balanced score): {balanced_score:.4f})")
            
        # ========== Tiếp tục ==========
        else:
            patience_counter += 1
            write_console(logger, LEVEL.INFO, f"  -> Số lần không cải thiện: ({patience_counter}/{max_patience})")
            if patience_counter >= max_patience:
                write_console(logger, LEVEL.WARNING, "  -> Kết thúc sớm quá trình huấn luyện")
                break
        print("\n")
    # ========== Đánh giá ==========
    summary, validation_report, validation_confusion_matrix, test_report, test_confussion_matrix = report_model(model, best_model_path, validation_loader, test_loader, classes, criterion)
    return best_model_path, summary, validation_report, validation_confusion_matrix, test_report, test_confussion_matrix
