def report_model(model, best_path, validation_loader, test_loader, classes, criterion):
    
    # Tải mô hình tốt nhất
    if os.path.exists(best_path):
        ckpt = torch.load(best_path, map_location = DEVICE)
        model.load_state_dict(ckpt["model_state"])
        print("\nĐường dẫn mô hình tốt nhất:", best_path)

    # Đánh giá cuối trên validation và test
    validation_loss, validation_accuracy, validation_recall_0, validation_recall_1, validation_report, validation_confusion_matrix = evaluate_model(model, validation_loader, criterion)
    test_loss, test_accuracy, test_recall_0, validation_recall_1, test_report, test_confussion_matrix = evaluate_model(model, test_loader, criterion)
    print(f"*** Độ chính xác (Test): {test_accuracy:.4f} ***")

    # Tạo summary
    summary = {
        "val_acc": float(validation_accuracy),
        "test_acc": float(test_accuracy),
        "val_report": validation_report,
        "test_report": test_report,
        "classes": classes
    }
    return summary, validation_report, validation_confusion_matrix, test_report, test_confussion_matrix
