class LEVEL(IntEnum):
    DEBUG = logging.DEBUG
    INFO = logging.INFO
    WARNING = logging.WARNING
    ERROR = logging.ERROR

    
def log_setup(model_name: str):
    # Kiểm tra tệp tin dữ liệu đã được tạo
    log_directory = os.path.join(MODEL_TYPE_PATH, model_name)
    os.makedirs(log_directory, exist_ok=True)

    # Tạo tập tin lưu lịch sử
    log_file = os.path.join(log_directory, f"train_{datetime.now().strftime('%Y%m%d_%H%M%S')}.log")
    logger = logging.getLogger(model_name)
    logger.setLevel(logging.INFO)

    # Tránh thêm handler nhiều lần
    if logger.hasHandlers():
        logger.handlers.clear()
    file_handler = logging.FileHandler(log_file, mode="w", encoding="utf-8")

    # Định dạng log
    formatter = logging.Formatter(fmt="%(asctime)s | %(levelname)s | %(message)s")

    file_handler.setFormatter(formatter) 
    logger.addHandler(file_handler)
        
    return logger

def write_console(logger, level: LEVEL, message: str):
    logger.log(level, message.replace("\n", ""))
    print(message)
    
def train_setting(logger, model_name, model_type, image_size, batch_size, epochs, learning_rate, number_epoch_freeze, patience):
    logger.info("===== CẤU HÌNH HUẤN LUYỆN =====")
    logger.info(f"                          Tên model: {model_name}")
    logger.info(f"                         Loại Model: {model_type}")
    logger.info(f"                       Kích cỡ hình: {image_size}")
    logger.info(f"Số mẫu dữ liệu/lần học (Batch size): {batch_size}")
    logger.info(f" Số lượt huấn luyện tối ta (Epochs): {epochs}")
    logger.info(f"         Tốc độ học (Learning rate): {learning_rate}")
    logger.info(f"                  Số lượt đóng băng: {number_epoch_freeze}")
    logger.info(f"             Số lượt chờ (patience): {patience}")
    logger.info("========================")

def statistic(model_name, model_type, batch_size, image_size, total_epoch, max_patience, model_state, optimizer_state, scaler_state, classes, epoch, epoch_run_time, learning_rate, train_loss, train_accuracy, validation_loss, validation_accuracy, validation_report, validation_confussion_matrix, balanced_score, patience_counter, best_balanced_score, is_early_stop):
    epoch_statistic = {
        # Tổng quan quá trình trình huấn luyện
        "epoch": epoch,
        "train_time": epoch_run_time,
        "learning_rate": learning_rate,
        
        # Kết quả huấn luyện
        "train_loss": train_loss,
        "train_accuracy": train_accuracy,

        # Kết quả kiểm định
        "validation_loss": validation_loss,
        "validation_acc": validation_accuracy,
        "validation_report": validation_report,
        "validation_confussion_matrix": validation_confussion_matrix.tolist(),
        "balanced_score": balanced_score,
    }

    run_statistic = {
        "current_patience": patience_counter,
        "is_early_stop": bool(is_early_stop),
        "best_balanced_score": best_balanced_score
    }
    
    model_info = {
        # Mô hình
        "model_name": model_name,
        "model_type": model_type,
        
        # Cấu hình
        "batch_size": batch_size,
        "image_size": image_size,
        "total_epoch": total_epoch,
        "max_patience": max_patience,
        
        # Quá trình huấn luyện
        "model_state": model_state,
        "optimizer_state": optimizer_state,
        "scaler_state": scaler_state,
        "classes": classes,
    }
    
    return epoch_statistic, run_statistic, model_info
