import pandas as pd
from itertools import combinations

# Đọc file dữ liệu (ví dụ: ratings.csv)
# Cột: userId, movieId, rating, timestamp
df = pd.read_csv("ratings.csv")

# Tạo mapping: movieId -> tập user đã đánh giá
movie_users = (
    df.groupby("movieId")["userId"]
    .apply(set)
    .to_dict()
)

# Tìm 3 phim có ít nhất 3 người dùng cùng đánh giá
result = []
for m1, m2, m3 in combinations(movie_users.keys(), 3):
    common_users = (
        movie_users[m1]
        & movie_users[m2]
        & movie_users[m3]
    )
    if len(common_users) >= 3:
        result.append((m1, m2, m3, common_users))
        break  # chỉ lấy 1 bộ đầu tiên

# In kết quả
if result:
    m1, m2, m3, users = result[0]
    print("3 phim:", m1, m2, m3)
    print("Người dùng cùng đánh giá:", users)

    # Lấy chi tiết rating
    filtered = df[
        (df["movieId"].isin([m1, m2, m3])) &
        (df["userId"].isin(users))
    ]
    print(filtered.sort_values(["userId", "movieId"]))
else:
    print("Không tìm thấy 3 phim có ít nhất 3 người cùng đánh giá.")
