import pandas as pd
import random

df = pd.read_csv("ratings.csv")  # userId, movieId, rating, timestamp

# Mapping nhanh
user_movies = df.groupby("userId")["movieId"].apply(list).to_dict()
movie_users = df.groupby("movieId")["userId"].apply(set).to_dict()

attempts = 0
max_attempts = 10000

while attempts < max_attempts:
    attempts += 1

    # 1) Random 1 user có >= 3 phim
    u = random.choice(list(user_movies.keys()))
    movies = user_movies[u]
    if len(movies) < 3:
        continue

    # 2) Random 3 phim từ user này
    m1, m2, m3 = random.sample(movies, 3)

    # 3) Tìm user chung của 3 phim
    common_users = (
        movie_users[m1]
        & movie_users[m2]
        & movie_users[m3]
    )

    if len(common_users) >= 3:
        # Random 3 user chung
        selected_users = random.sample(list(common_users), 3)

        result = df[
            (df["movieId"].isin([m1, m2, m3])) &
            (df["userId"].isin(selected_users))
        ].sort_values(["userId", "movieId"])

        print("Số lần thử:", attempts)
        print("3 phim:", m1, m2, m3)
        print("3 người dùng:", selected_users)
        print(result)
        break
else:
    print("Không tìm được sau", max_attempts, "lần thử")
