import numpy as np

# Dữ liệu
R = np.array([
    [np.nan, 1.0, 4.0, 0.5],
    [2.5, 3.5, 5.0, np.nan],
    [5.0, np.nan, 2.0, 3.0],
    [1.0, 4.0, np.nan, 3.0]
])

num_users, num_items = R.shape
k = 2
epochs = 10
lambda_reg = 0.0  # regularization

# Khởi tạo ngẫu nhiên P, Q
np.random.seed(42)
P = np.random.rand(num_users, k)
Q = np.random.rand(num_items, k)

# ALS
for epoch in range(epochs):
    print(f"\n--- Epoch {epoch+1} ---")
    
    # Cập nhật P
    for u in range(num_users):
        idx = ~np.isnan(R[u, :])
        Q_u = Q[idx, :]
        R_u = R[u, idx]
        if Q_u.shape[0] > 0:
            # Least Squares: P_u = (Q^T Q)^-1 Q^T R_u
            A = Q_u.T @ Q_u + lambda_reg * np.eye(k)
            b = Q_u.T @ R_u
            P[u, :] = np.linalg.solve(A, b)
            print(f"P[{u}] updated: {P[u, :]}")
    
    # Cập nhật Q
    for i in range(num_items):
        idx = ~np.isnan(R[:, i])
        P_i = P[idx, :]
        R_i = R[idx, i]
        if P_i.shape[0] > 0:
            A = P_i.T @ P_i + lambda_reg * np.eye(k)
            b = P_i.T @ R_i
            Q[i, :] = np.linalg.solve(A, b)
            print(f"Q[{i}] updated: {Q[i, :]}")
    
    # Tính lỗi
    error = 0
    count = 0
    for u in range(num_users):
        for i in range(num_items):
            if not np.isnan(R[u, i]):
                pred = P[u, :] @ Q[i, :].T
                error += (R[u, i] - pred)**2
                count += 1
    rmse = np.sqrt(error / count)
    print(f"RMSE after epoch {epoch+1}: {rmse:.4f}")

# Dự đoán các giá trị missing
R_hat = P @ Q.T
print("\nPredicted R:")
print(R_hat)
