import numpy as np

# Dữ liệu
R = np.array([
    [np.nan, 1.0, 4.0, 0.5],
    [2.5, 3.5, 5.0, np.nan],
    [5.0, np.nan, 2.0, 3.0],
    [1.0, 4.0, np.nan, 3.0]
])

num_users, num_items = R.shape
k = 2
epochs = 20
alpha = 0.01
lambda_reg = 0.0  # regularization

# Khởi tạo P và Q
np.random.seed(42)
P = np.random.rand(num_users, k)
Q = np.random.rand(num_items, k)

# Ma trận mask cho các giá trị đã biết
mask = ~np.isnan(R)

for epoch in range(epochs):
    print(f"\n=== Epoch {epoch+1} ===")
    for u in range(num_users):
        for i in range(num_items):
            if mask[u, i]:
                # Dự đoán
                pred = P[u, :] @ Q[i, :].T
                # Lỗi
                e_ui = R[u, i] - pred
                # Cập nhật P và Q
                old_P = P[u, :].copy()
                old_Q = Q[i, :].copy()
                P[u, :] += alpha * (2 * e_ui * Q[i, :] - lambda_reg * P[u, :])
                Q[i, :] += alpha * (2 * e_ui * old_P - lambda_reg * Q[i, :])
                print(f"Updated P[{u}], Q[{i}]: P={P[u, :]}, Q={Q[i, :]}, error={e_ui:.4f}")
    
    # Tính loss toàn bộ
    error = 0
    count = 0
    for u in range(num_users):
        for i in range(num_items):
            if mask[u, i]:
                pred = P[u, :] @ Q[i, :].T
                error += (R[u, i] - pred)**2
                count += 1
    rmse = np.sqrt(error / count)
    print(f"RMSE after epoch {epoch+1}: {rmse:.4f}")

# Ma trận dự đoán đầy đủ
R_hat = P @ Q.T
print("\nPredicted R:")
print(R_hat)
