def recommend_content_based(user_ratings, top_n=10):
    watched = set(user_ratings.keys())
    scores = {}
    for movie_id in movies['movieId']:
        if movie_id in watched:
            continue
        sim_score = max(cosine_sim(
            movies.loc[movies['movieId']==movie_id, 'genre_vector'].values[0],
            movies.loc[movies['movieId']==w, 'genre_vector'].values[0]
        ) for w in watched)
        scores[movie_id] = sim_score
    top_movies = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]
    return dict(top_movies)

print(recommend_content_based(ratings, top_n=10))
