import math
from process.read_data import one_hot_encoder

# Hàm cosine similarity giữa 2 vector
def cosine_sim(v1, v2):
    dot = sum(a*b for a,b in zip(v1,v2))
    norm1 = math.sqrt(sum(a*a for a in v1))
    norm2 = math.sqrt(sum(b*b for b in v2))
    return dot / (norm1*norm2) if norm1 and norm2 else 0

# recommend_content_based
def recommend_content_based(movies, user_ratings, top_n=10):
    """
    movies: DataFrame có cột 'movieId', 'genre_vector'
    user_ratings: dict {movieId: rating} của user
    top_n: số lượng gợi ý
    """
    
    watched = set(user_ratings.keys())
    scores = {}
    
    # Tạo dict movieId -> vector
    movie_vectors = {row.movieId: row.genre_vector for row in movies.itertuples()}
    
    for movie_id, v1 in movie_vectors.items():
        if movie_id in watched:
            continue
        sim_score = max(cosine_sim(v1, movie_vectors[w]) for w in watched)
        scores[movie_id] = sim_score
    
    # Sắp xếp giảm dần và lấy top_n
    top_movies = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]
    
    # Trả về danh sách (title, score)
    return [(movies.loc[movies['movieId']==mid, 'title'].values[0], score) 
            for mid, score in top_movies]
