import pandas as pd
from collections import defaultdict

class SlopeOne:
    def __init__(self):
        self.dev = defaultdict(lambda: defaultdict(float))
        self.cnt = defaultdict(lambda: defaultdict(int))

    def recommend_collaborative(self, ratings: pd.DataFrame):
        """
        ratings: DataFrame với cột [userId, itemId, rating]
        """
        # Gom rating theo user
        user_ratings = defaultdict(dict)
        for _, row in ratings.iterrows():
            user_ratings[row['userId']][row['itemId']] = row['rating']

        # Tính deviation
        for items in user_ratings.values():
            for i, r_i in items.items():
                for j, r_j in items.items():
                    if i == j:
                        continue
                    self.dev[i][j] += (r_i - r_j)
                    self.cnt[i][j] += 1

        # Lấy trung bình
        for i in self.dev:
            for j in self.dev[i]:
                self.dev[i][j] /= self.cnt[i][j]

    def predict(self, user_items: dict, target_item):
        numerator = 0.0
        denominator = 0

        for j, r_j in user_items.items():
            if target_item in self.dev and j in self.dev[target_item]:
                c = self.cnt[target_item][j]
                numerator += (r_j + self.dev[target_item][j]) * c
                denominator += c

        if denominator == 0:
            return None  # không đủ dữ liệu

        return numerator / denominator
