import pandas as pd
from collections import defaultdict

class SlopeOne:
    def __init__(self):
        self.dev = defaultdict(lambda: defaultdict(float))
        self.cnt = defaultdict(lambda: defaultdict(int))

    def fit_slope_one(ratings: pd.DataFrame):
        dev = defaultdict(lambda: defaultdict(float))
        cnt = defaultdict(lambda: defaultdict(int))

        user_ratings = defaultdict(dict)
        for _, row in ratings.iterrows():
            user_ratings[row["userId"]][row["itemId"]] = row["rating"]

        for items in user_ratings.values():
            for i, r_i in items.items():
                for j, r_j in items.items():
                    if i == j:
                        continue
                    dev[i][j] += (r_i - r_j)
                    cnt[i][j] += 1

        for i in dev:
            for j in dev[i]:
                dev[i][j] /= cnt[i][j]

        return dev, cnt
    
    
    def predict(self, user_items: dict, target_item):
        numerator = 0.0
        denominator = 0

        for j, r_uj in user_items.items():
            if j in dev[target_item]:
                c = cnt[target_item][j]
                numerator += (r_uj + dev[target_item][j]) * c
                denominator += c

        return numerator / denominator
