# =========================
# 1. CHUẨN BỊ DỮ LIỆU
# =========================

# movies:
# movieId | title | genre_vector
# genre_vector = one_hot_encoder(genres)

movies = pd.read_csv("movies_with_vector.csv")

# ratings_df:
# userId | itemId | rating
ratings_df = pd.read_csv("ratings.csv")


# =========================
# 2. TRAIN SLOPE ONE (CHỈ 1 LẦN)
# =========================

so = SlopeOne()
so.fit(ratings_df)


# =========================
# 3. CHỌN USER CẦN GỢI Ý
# =========================

user_id = 1

user_ratings_df = ratings_df[ratings_df.userId == user_id]

# dict cho Content-Based
user_ratings_dict = {
    row.itemId: row.rating
    for _, row in user_ratings_df.iterrows()
}


# =========================
# 4. GỌI HÀM DỰ ĐOÁN 1 ITEM
# =========================

movie_id = 50

r_hat = predict_hybrid(
    movies=movies,
    user_ratings_dict=user_ratings_dict,
    user_ratings_df=user_ratings_df,
    slopeone_model=so,
    target_movie_id=movie_id,
    alpha=0.6
)

print("Predicted rating:", r_hat)


# =========================
# 5. GỌI HÀM RECOMMEND TOP-N
# =========================

top_movies = recommend_hybrid(
    movies=movies,
    user_ratings_dict=user_ratings_dict,
    user_ratings_df=user_ratings_df,
    slopeone_model=so,
    top_n=10,
    alpha=0.6
)

for title, score in top_movies:
    print(title, score)
