import math
from process.read_data import one_hot_encoder

# Hàm cosine similarity giữa 2 vector
def cosine_sim(v1, v2):
    dot = sum(a*b for a,b in zip(v1,v2))
    norm1 = math.sqrt(sum(a*a for a in v1))
    norm2 = math.sqrt(sum(b*b for b in v2))
    return dot / (norm1*norm2) if norm1 and norm2 else 0

def build_user_profile(movies, user_ratings):
    vectors = []
    weights = []

    for mid, rating in user_ratings.items():
        vec = movies.loc[movies['movieId'] == mid, 'genre_vector'].values[0]
        vectors.append(vec)
        weights.append(rating)

    profile = [
        sum(v[i] * w for v, w in zip(vectors, weights)) / sum(weights)
        for i in range(len(vectors[0]))
    ]
    return profile

def recommend_content_based(movies, user_ratings, top_n=10):
    watched = set(user_ratings.keys())

    # USER VECTOR U
    user_vector = build_user_profile(movies, user_ratings)

    scores = {}
    for row in movies.itertuples():
        if row.movieId in watched:
            continue
        score = cosine_sim(user_vector, row.genre_vector)
        scores[row.movieId] = score
        print(row.movieId, score)

    top = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]

    return [
        (movies.loc[movies['movieId'] == mid, 'title'].values[0], score)
        for mid, score in top
    ]
