import pandas as pd
from collections import defaultdict

class SlopeOne:
    def __init__(self):
        self.dev = defaultdict(lambda: defaultdict(float))
        self.cnt = defaultdict(lambda: defaultdict(int))

    def fit(self, ratings: pd.DataFrame):
        user_ratings = defaultdict(dict)
        for _, row in ratings.iterrows():
            user_ratings[row["userId"]][row["movieId"]] = row["rating"]

        for items in user_ratings.values():
            for i, r_i in items.items():
                for j, r_j in items.items():
                    if i == j:
                        continue
                    self.dev[i][j] += (r_i - r_j)
                    self.cnt[i][j] += 1

        for i in self.dev:
            for j in self.dev[i]:
                self.dev[i][j] /= self.cnt[i][j]

    def predict(self, user_df: pd.DataFrame, target_item):
        numerator = 0.0
        denominator = 0

        # đảm bảo target_item đã được học
        if target_item not in self.dev:
            return None

        # duyệt các item user đã đánh giá
        for _, row in user_df.iterrows():
            j = row["movieId"]
            r_uj = row["rating"]

            if j in self.dev[target_item]:
                c = self.cnt[target_item][j]
                numerator += (r_uj + self.dev[target_item][j]) * c
                denominator += c

        if denominator == 0:
            return None

        return numerator / denominator
