def predict_hybrid(
    movies,
    user_ratings_dict,
    user_ratings_df,
    slopeone_model,
    target_movie_id,
    alpha=0.5
):
    r_cb = predict_content_based(
        movies,
        user_ratings_dict,
        target_movie_id
    )

    r_so = slopeone_model.predict(
        user_ratings_df,
        target_movie_id
    )

    if r_cb is None and r_so is None:
        return None
    if r_so is None:
        return r_cb
    if r_cb is None:
        return r_so

    return alpha * r_cb + (1 - alpha) * r_so


def recommend_hybrid(
    movies,
    user_ratings_dict,
    user_ratings_df,
    slopeone_model,
    top_n=10,
    alpha=0.5
):
    watched = set(user_ratings_dict.keys())
    scores = {}

    for mid in movies["movieId"]:
        if mid in watched:
            continue

        r_hat = predict_hybrid(
            movies,
            user_ratings_dict,
            user_ratings_df,
            slopeone_model,
            mid,
            alpha
        )

        if r_hat is not None:
            scores[mid] = r_hat

    top = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]

    return [
        (movies.loc[movies["movieId"] == mid, "title"].values[0], score)
        for mid, score in top
    ]


# =========================
# USAGE
# =========================
"""
movies DataFrame:
- movieId
- title
- genre_vector (list[int/float])

ratings_df DataFrame:
- userId
- itemId
- rating
"""

