import math
import numpy as np
import pandas as pd
from collections import defaultdict

# =========================
# 1. COSINE SIMILARITY (NUMPY)
# =========================

def cosine_sim(u, v):
    denom = np.linalg.norm(u) * np.linalg.norm(v)
    if denom == 0:
        return 0.0
    return float(np.dot(u, v) / denom)


# =========================
# 2. BUILD USER PROFILE
# =========================

def build_user_profile(movie_vec, user_ratings_dict):
    vectors = []
    weights = []

    for mid, r in user_ratings_dict.items():
        if mid in movie_vec:
            vectors.append(movie_vec[mid])
            weights.append(r)

    if not vectors:
        return None

    vectors = np.vstack(vectors)
    weights = np.array(weights).reshape(-1, 1)

    profile = (vectors * weights).sum(axis=0) / weights.sum()
    return profile


# =========================
# 3. CONTENT-BASED CANDIDATES
# =========================

def get_cb_candidates(movie_vec, user_vector, watched, top_k=200):
    sims = []
    for mid, vec in movie_vec.items():
        if mid in watched:
            continue
        sims.append((mid, cosine_sim(user_vector, vec)))

    sims.sort(key=lambda x: x[1], reverse=True)
    return [mid for mid, _ in sims[:top_k]]


def cb_score_to_rating(sim):
    return sim * 5.0


# =========================
# 4. SLOPE ONE
# =========================

class SlopeOne:
    def __init__(self):
        self.dev = defaultdict(dict)
        self.cnt = defaultdict(dict)

    def fit(self, ratings: pd.DataFrame):
        user_ratings = defaultdict(dict)
        for u, i, r in zip(
            ratings.userId.values,
            ratings.movieId.values,
            ratings.rating.values
        ):
            user_ratings[u][i] = r

        for items in user_ratings.values():
            for i, r_i in items.items():
                for j, r_j in items.items():
                    if i == j:
                        continue
                    self.dev.setdefault(i, {}).setdefault(j, 0.0)
                    self.cnt.setdefault(i, {}).setdefault(j, 0)

                    self.dev[i][j] += (r_i - r_j)
                    self.cnt[i][j] += 1

        for i in self.dev:
            for j in self.dev[i]:
                self.dev[i][j] /= self.cnt[i][j]

    def predict(self, user_items, target_item):
        if target_item not in self.dev:
            return None

        num = 0.0
        den = 0

        dev_i = self.dev[target_item]
        cnt_i = self.cnt[target_item]

        for j, r_uj in user_items.items():
            if j in dev_i:
                c = cnt_i[j]
                num += (r_uj + dev_i[j]) * c
                den += c

        if den == 0:
            return None

        return num / den


# =========================
# 5. HYBRID RECOMMENDER
# =========================

def recommend_hybrid(
    movie_vec,
    movie_title,
    user_ratings_dict,
    slopeone_model,
    alpha=0.6,
    top_n=10,
    top_k_cb=200
):
    watched = set(user_ratings_dict.keys())

    user_vector = build_user_profile(movie_vec, user_ratings_dict)
    if user_vector is None:
        return []

    candidates = get_cb_candidates(
        movie_vec,
        user_vector,
        watched,
        top_k=top_k_cb
    )

    scores = {}

    for mid in candidates:
        sim = cosine_sim(user_vector, movie_vec[mid])
        r_cb = cb_score_to_rating(sim)

        r_so = slopeone_model.predict(user_ratings_dict, mid)

        r_hat = r_cb if r_so is None else alpha * r_cb + (1 - alpha) * r_so
        scores[mid] = r_hat

    top = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]

    return [(movie_title[mid], score) for mid, score in top]


# =========================
# 6. USAGE
# =========================

# movies_encoded:
# columns: movieId, title, genre_vector (list / array)

movie_vec = {
    row.movieId: np.array(row.genre_vector, dtype=np.float32)
    for row in movies_encoded.itertuples()
}

movie_title = {
    row.movieId: row.title
    for row in movies_encoded.itertuples()
}

# ratings:
# columns: userId, movieId, rating

so = SlopeOne()
so.fit(ratings)

user_id = 1
user_ratings_df = ratings[ratings.userId == user_id]

user_ratings_dict = dict(zip(
    user_ratings_df.movieId.values,
    user_ratings_df.rating.values
))

top_movies = recommend_hybrid(
    movie_vec=movie_vec,
    movie_title=movie_title,
    user_ratings_dict=user_ratings_dict,
    slopeone_model=so,
    alpha=0.6,
    top_n=10,
    top_k_cb=200
)

for title, score in top_movies:
    print(title, score)
