def recommend_hybrid(
    movies,
    user_ratings_dict,
    user_ratings_df,
    slopeone_model,
    top_n=10,
    alpha=0.6,
    top_k_cb=200
):
    watched = set(user_ratings_dict.keys())

    # 1. build user profile ONCE
    user_vector = build_user_profile(movies, user_ratings_dict)
    if user_vector is None:
        return []

    # 2. content-based candidate filtering
    candidates = get_cb_candidates(
        movies,
        user_vector,
        watched,
        top_k=top_k_cb
    )

    scores = {}

    for mid in candidates:
        # content-based
        row = movies.loc[movies.movieId == mid]
        sim = cosine_sim(user_vector, row.iloc[0].genre_vector)
        r_cb = cb_score_to_rating(sim)

        # slope one
        r_so = slopeone_model.predict(user_ratings_df, mid)

        if r_so is None:
            r_hat = r_cb
        else:
            r_hat = alpha * r_cb + (1 - alpha) * r_so

        scores[mid] = r_hat

    top = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:top_n]

    return [
        (movies.loc[movies.movieId == mid, "title"].values[0], score)
        for mid, score in top
    ]

