import os
import pickle
import pandas as pd
from collections import defaultdict


class SlopeOne:
    def __init__(self, ratings: pd.DataFrame, model_path="slope_one.pkl"):
        """
        ratings: DataFrame[userId, movieId, rating]
        model_path: nơi lưu / load model
        """
        self.ratings = ratings
        self.model_path = model_path

        self.dev = defaultdict(lambda: defaultdict(float))
        self.cnt = defaultdict(lambda: defaultdict(int))
        self.is_fitted = False

        # nếu đã có model thì load ngay
        if os.path.exists(self.model_path):
            self._load()
        else:
            self._fit()
            self._save()

    # =========================
    # TRAIN (PRIVATE)
    # =========================
    def _fit(self):
        user_ratings = defaultdict(dict)

        for _, row in self.ratings.iterrows():
            user_ratings[row["userId"]][row["movieId"]] = row["rating"]

        for items in user_ratings.values():
            for i, r_i in items.items():
                for j, r_j in items.items():
                    if i == j:
                        continue
                    self.dev[i][j] += (r_i - r_j)
                    self.cnt[i][j] += 1

        for i in self.dev:
            for j in self.dev[i]:
                self.dev[i][j] /= self.cnt[i][j]

        self.is_fitted = True

    # =========================
    # PREDICT (PUBLIC)
    # =========================
    def predict(self, user_df: pd.DataFrame, target_item):
        """
        user_df: DataFrame[movieId, rating] của 1 user
        """
        if target_item not in self.dev:
            return None

        numerator = 0.0
        denominator = 0

        for _, row in user_df.iterrows():
            j = row["movieId"]
            r_uj = row["rating"]

            if j in self.dev[target_item]:
                c = self.cnt[target_item][j]
                numerator += (r_uj + self.dev[target_item][j]) * c
                denominator += c

        if denominator == 0:
            return None

        return numerator / denominator

    # =========================
    # SAVE / LOAD (PRIVATE)
    # =========================
    def _save(self):
        with open(self.model_path, "wb") as f:
            pickle.dump(
                {
                    "dev": {i: dict(j) for i, j in self.dev.items()},
                    "cnt": {i: dict(j) for i, j in self.cnt.items()}
                },
                f
            )

    def _load(self):
        with open(self.model_path, "rb") as f:
            data = pickle.load(f)

        self.dev = defaultdict(
            lambda: defaultdict(float),
            {i: defaultdict(float, j) for i, j in data["dev"].items()}
        )
        self.cnt = defaultdict(
            lambda: defaultdict(int),
            {i: defaultdict(int, j) for i, j in data["cnt"].items()}
        )
        self.is_fitted = True
