def recommend_hybrid(
    movies: pd.DataFrame,
    ratings_df: pd.DataFrame,
    user_id: int,
    slope_one: SlopeOne,
    top_n=10
):
    # ratings của user
    user_df = ratings_df[ratings_df.userId == user_id][["movieId", "rating"]]
    user_ratings = dict(zip(user_df.movieId, user_df.rating))

    watched = set(user_ratings.keys())

    # user profile (content)
    user_vector = build_user_profile(movies, user_ratings)

    alpha = compute_alpha(user_ratings)

    results = []

    for row in movies.itertuples():
        if row.movieId in watched:
            continue

        # CONTENT SCORE
        score_cb = cosine_sim(user_vector, row.genre_vector)

        # CF SCORE
        raw_cf = slope_one.predict(user_df, row.movieId)
        score_cf = normalize_cf(raw_cf) if raw_cf is not None else None

        # HYBRID
        score = hybrid_score(score_cf, score_cb, alpha)

        results.append((row.movieId, score))

    results.sort(key=lambda x: x[1], reverse=True)
    return pd.DataFrame(results[:top_n], columns=["movieId", "score"])
