import math
from collections import defaultdict

# =========================
# 1. Dữ liệu giả lập
# =========================
ratings = {
    'U1': {'M1': 5, 'M2': 3},
    'U2': {'M1': 4, 'M2': 2, 'M3': 5},
    'U3': {'M2': 5, 'M3': 4}
}

# vector đặc trưng phim (one-hot thể loại)
item_features = {
    'M1': [1, 0, 0],
    'M2': [1, 1, 0],
    'M3': [0, 1, 1]
}

# =========================
# 2. Huấn luyện Slope One
# =========================
dev = defaultdict(lambda: defaultdict(float))
count = defaultdict(lambda: defaultdict(int))

items = list(item_features.keys())

for i in items:
    for j in items:
        if i == j: continue
        numerator = 0
        c = 0
        for user, rs in ratings.items():
            if i in rs and j in rs:
                numerator += rs[i] - rs[j]
                c += 1
        if c > 0:
            dev[i][j] = numerator / c
            count[i][j] = c

# =========================
# 3. Cosine similarity
# =========================
def cosine_sim(v1, v2):
    dot = sum(a*b for a,b in zip(v1,v2))
    norm1 = math.sqrt(sum(a*a for a in v1))
    norm2 = math.sqrt(sum(b*b for b in v2))
    return dot / (norm1*norm2) if norm1 and norm2 else 0

# =========================
# 4. Dự đoán Slope One
# =========================
def predict_slope_one(user_ratings, target_item):
    numerator = 0
    denominator = 0
    for rated_item, rating in user_ratings.items():
        if target_item in dev and rated_item in dev[target_item]:
            numerator += (dev[target_item][rated_item] + rating) * count[target_item][rated_item]
            denominator += count[target_item][rated_item]
    return numerator / denominator if denominator else 0

# =========================
# 5. Dự đoán Content-Based
# =========================
def predict_content_based(user_ratings, target_item):
    numerator = 0
    denominator = 0
    target_vec = item_features[target_item]
    for rated_item, rating in user_ratings.items():
        sim = cosine_sim(target_vec, item_features[rated_item])
        numerator += sim * rating
        denominator += sim
    return numerator / denominator if denominator else 0

# =========================
# 6. Dự đoán Hybrid
# =========================
def predict_hybrid(user_ratings, target_item, alpha=0.5):
    so = predict_slope_one(user_ratings, target_item)
    cb = predict_content_based(user_ratings, target_item)
    return alpha*so + (1-alpha)*cb

# =========================
# 7. Ví dụ dự đoán cho U1
# =========================
user = 'U1'
predictions = {}
for item in items:
    if item not in ratings[user]:
        predictions[item] = predict_hybrid(ratings[user], item, alpha=0.6)

# Sắp xếp theo rating dự đoán
predictions = dict(sorted(predictions.items(), key=lambda x: x[1], reverse=True))
print(predictions)
