recommendations = movies_to_recommend.sort_values('hybrid_score', ascending=False)

# =========================
# 8. Đánh giá Precision@N / Recall@N
# =========================
top_n = 2
recommended_ids = recommendations.head(top_n)['movieId'].tolist()

# Phim thực sự user 1 đã xem trong test set
user_test = test_ratings[test_ratings['userId']==user_id]['movieId'].tolist()

hits = len(set(recommended_ids) & set(user_test))
precision = hits / top_n
recall = hits / len(user_test) if user_test else 0

print("Recommended:", recommended_ids)
print("Actual test movies:", user_test)
print(f"Precision@{top_n}: {precision:.2f}, Recall@{top_n}: {recall:.2f}")
