    score_factor = 1.0
    for rule in rules:
        cond = rule.get("condition",{})
        act = rule.get("action",{})
        if rule['id']=="recent_flim":
            current_year = cond.get("current_year", datetime.now().year)
            factor_decay = cond.get("factor_decay",0.2)
