import pandas as pd
import numpy as np
from collections import defaultdict
from sklearn.model_selection import train_test_split
from sklearn.metrics.pairwise import cosine_similarity
train_ratings, test_ratings = train_test_split(
    ratings,
    test_size=0.2,
    random_state=42
)

def build_user_profile(user_id):
    user_data = train_ratings[train_ratings.userId == user_id]
    if user_data.empty:
        return None

    merged = user_data.merge(movies_encoded, on="movieId")
    X = merged[genres_vector].values
    w = merged["rating"].values.reshape(-1, 1)

    profile = np.sum(X * w, axis=0)
    norm = np.linalg.norm(profile)

    return profile / norm if norm != 0 else profile
def content_score(user_profile):
    item_vectors = movies_encoded[genres_vector].values
    scores = cosine_similarity([user_profile], item_vectors)[0]
    return dict(zip(movies_encoded.movieId, scores))


def train_slope_one():
    dev = defaultdict(lambda: defaultdict(float))
    cnt = defaultdict(lambda: defaultdict(int))

    for _, group in train_ratings.groupby("userId"):
        items = group[["movieId", "rating"]].values
        for i in items:
            for j in items:
                if i[0] != j[0]:
                    dev[i[0]][j[0]] += i[1] - j[1]
                    cnt[i[0]][j[0]] += 1

    for i in dev:
        for j in dev[i]:
            dev[i][j] /= cnt[i][j]

    return dev, cnt

def slope_one_predict(user_id, item_id):
    user_data = train_ratings[train_ratings.userId == user_id]
    if user_data.empty:
        return None

    num, den = 0, 0

    for _, row in user_data.iterrows():
        j = row.movieId
        if item_id in dev and j in dev[item_id]:
            num += (dev[item_id][j] + row.rating) * cnt[item_id][j]
            den += cnt[item_id][j]

    return num / den if den != 0 else None

ALPHA = 0.5
TOP_N = 10
def hybrid_recommend(user_id):
    profile = build_user_profile(user_id)
    if profile is None:
        return []

    content = content_score(profile)
    watched = set(train_ratings[train_ratings.userId == user_id].movieId)

    scores = {}

    for movie_id in movies_encoded.movieId:
        if movie_id in watched:
            continue

        cf = slope_one_predict(user_id, movie_id)
        if cf is None:
            continue

        scores[movie_id] = ALPHA * content[movie_id] + (1 - ALPHA) * cf

    return sorted(scores, key=scores.get, reverse=True)[:TOP_N]
def evaluate():
    P, R, F = [], [], []

    for user_id in test_ratings.userId.unique():
        recs = set(hybrid_recommend(user_id))

        relevant = set(
            test_ratings[
                (test_ratings.userId == user_id) &
                (test_ratings.rating >= 4)
            ].movieId
        )

        if not recs or not relevant:
            continue

        tp = len(recs & relevant)

        precision = tp / TOP_N
        recall = tp / len(relevant)
        f1 = (2 * precision * recall) / (precision + recall) if precision + recall else 0

        P.append(precision)
        R.append(recall)
        F.append(f1)

    return np.mean(P), np.mean(R), np.mean(F)

p, r, f1 = evaluate()
print(f"Precision@{TOP_N}: {p:.4f}")
print(f"Recall@{TOP_N}: {r:.4f}")
print(f"F1@{TOP_N}: {f1:.4f}")
dev, cnt = train_slope_one()
