import numpy as np
import pandas as pd
from sklearn.metrics.pairwise import cosine_similarity
from collections import defaultdict
import matplotlib.pyplot as plt
import warnings
warnings.filterwarnings('ignore')

print("="*70)
print("HYBRID RECOMMENDER SYSTEM")
print("Content-Based + Slope One (Model-based Collaborative)")
print("="*70)

# ===== DATA PREPARATION =====
# Content-Based Example từ tài liệu
movies_content = pd.DataFrame({
    'movieId': ['M1', 'M2', 'M3', 'M4', 'M5'],
    'title': ['Shanghai Triad', 'Doom Generation', 'White Balloon', 
              'Runaway Bride', 'Mortal Thoughts'],
    'genres': ['Crime|Drama', 'Crime|Drama|Comedy', 'Drama|Children',
               'Comedy|Romance', 'Mystery|Thriller']
})

user_ratings_content = pd.DataFrame({
    'userId': ['U1', 'U1'],
    'movieId': ['M1', 'M2'],
    'rating': [5.0, 4.0]
})

# Slope One Example từ tài liệu
movies_slope = pd.DataFrame({
    'movieId': ['M1', 'M2', 'M3', 'M4'],
    'title': ['Muppet Treasure Island', 
              'Chronicles of Narnia: The Lion, the Witch and the Wardrobe',
              'Paprika', 'Tron: Legacy']
})

ratings_slope = pd.DataFrame({
    'userId': ['U1', 'U1', 'U1',
               'U2', 'U2', 'U2',
               'U3', 'U3', 'U3',
               'U4', 'U4', 'U4'],
    'movieId': ['M2', 'M3', 'M4',
                'M1', 'M2', 'M3',
                'M1', 'M3', 'M4',
                'M1', 'M2', 'M4'],
    'rating': [1.0, 4.0, 0.5,
               2.5, 3.5, 5.0,
               5.0, 2.0, 3.0,
               1.0, 4.0, 3.0]
})

print("\n📊 DATASET INFO")
print(f"Content-Based: {len(movies_content)} movies, {len(user_ratings_content)} ratings")
print(f"Slope One: {len(movies_slope)} movies, {len(ratings_slope)} ratings")


# ===== 1. CONTENT-BASED FILTERING =====
class ContentBasedRecommender:
    def __init__(self, movies_df):
        self.movies = movies_df
        self.feature_matrix = None
        self.all_genres = []
        
    def fit(self):
        """Xây dựng feature matrix với one-hot encoding"""
        # Trích xuất tất cả genres
        all_genres_set = set()
        for genres in self.movies['genres']:
            all_genres_set.update(genres.split('|'))
        self.all_genres = sorted(list(all_genres_set))
        
        # One-hot encoding
        feature_vectors = []
        for genres in self.movies['genres']:
            genre_list = genres.split('|')
            vector = [1 if g in genre_list else 0 for g in self.all_genres]
            feature_vectors.append(vector)
        
        self.feature_matrix = np.array(feature_vectors)
        
        print(f"\n✓ Content-Based: {len(self.all_genres)} genres extracted")
        print(f"  Genres: {self.all_genres}")
        return self
    
    def build_user_profile(self, user_ratings_df):
        """Xây dựng user profile vector từ rated movies"""
        user_profile = np.zeros(len(self.all_genres))
        total_weight = 0
        
        for _, row in user_ratings_df.iterrows():
            movie_idx = self.movies[self.movies['movieId'] == row['movieId']].index[0]
            rating = row['rating']
            
            # Weighted average: U = (Σ w_i × V_i) / Σ w_i
            user_profile += rating * self.feature_matrix[movie_idx]
            total_weight += rating
        
        if total_weight > 0:
            user_profile = user_profile / total_weight
        
        return user_profile
    
    def predict(self, user_id, user_ratings_df):
        """Dự đoán và gợi ý phim cho user"""
        # Build user profile
        user_profile = self.build_user_profile(user_ratings_df)
        
        # Tính cosine similarity với tất cả phim
        user_profile_2d = user_profile.reshape(1, -1)
        similarities = cosine_similarity(user_profile_2d, self.feature_matrix)[0]
        
        # Lấy phim chưa xem
        rated_movies = set(user_ratings_df['movieId'])
        predictions = []
        
        for idx, movie_id in enumerate(self.movies['movieId']):
            if movie_id not in rated_movies:
                predictions.append({
                    'movieId': movie_id,
                    'title': self.movies.iloc[idx]['title'],
                    'similarity': similarities[idx]
                })
        
        # Sort by similarity
        predictions = sorted(predictions, key=lambda x: x['similarity'], reverse=True)
        return predictions, user_profile


# ===== 2. SLOPE ONE =====
class SlopeOne:
    def __init__(self):
        self.deviations = defaultdict(lambda: defaultdict(float))
        self.frequencies = defaultdict(lambda: defaultdict(int))
        
    def fit(self, ratings_df):
        """Tính deviation matrix"""
        # Group by user
        user_ratings = ratings_df.groupby('userId').apply(
            lambda x: dict(zip(x['movieId'], x['rating']))
        ).to_dict()
        
        # Calculate deviations
        for ratings in user_ratings.values():
            for item1, rating1 in ratings.items():
                for item2, rating2 in ratings.items():
                    if item1 != item2:
                        self.deviations[item1][item2] += rating1 - rating2
                        self.frequencies[item1][item2] += 1
        
        # Average deviations
        for item1 in self.deviations:
            for item2 in self.deviations[item1]:
                self.deviations[item1][item2] /= self.frequencies[item1][item2]
        
        print(f"\n✓ Slope One: Trained with {len(self.deviations)} items")
        return self
    
    def predict(self, user_id, movie_id, user_ratings_df):
        """Dự đoán rating cho một movie"""
        user_rated = dict(zip(user_ratings_df['movieId'], user_ratings_df['rating']))
        
        numerator = 0
        denominator = 0
        
        for rated_movie, rating in user_rated.items():
            if rated_movie in self.deviations and movie_id in self.deviations[rated_movie]:
                freq = self.frequencies[rated_movie][movie_id]
                dev = self.deviations[rated_movie][movie_id]
                numerator += (dev + rating) * freq
                denominator += freq
        
        if denominator == 0:
            return None
        
        return numerator / denominator
    
    def predict_all(self, user_id, user_ratings_df, all_movies):
        """Dự đoán tất cả phim chưa xem"""
        rated_movies = set(user_ratings_df['movieId'])
        predictions = []
        
        for movie_id in all_movies:
            if movie_id not in rated_movies:
                pred_rating = self.predict(user_id, movie_id, user_ratings_df)
                if pred_rating is not None:
                    predictions.append({
                        'movieId': movie_id,
                        'predicted_rating': pred_rating
                    })
        
        predictions = sorted(predictions, key=lambda x: x['predicted_rating'], reverse=True)
        return predictions


# ===== 3. HYBRID RECOMMENDER =====
class HybridRecommender:
    def __init__(self, cb_model, slope_model, alpha=0.5):
        """
        alpha: trọng số cho Content-Based (0-1)
        (1-alpha): trọng số cho Slope One
        """
        self.cb_model = cb_model
        self.slope_model = slope_model
        self.alpha = alpha
        
    def predict(self, user_id, user_ratings_cb, user_ratings_slope, movies_list):
        """Kết hợp predictions từ cả hai models"""
        # Content-Based predictions
        cb_predictions, user_profile = self.cb_model.predict(user_id, user_ratings_cb)
        
        # Slope One predictions
        slope_predictions = self.slope_model.predict_all(
            user_id, user_ratings_slope, movies_list
        )
        
        # Normalize scores
        cb_dict = {p['movieId']: p['similarity'] for p in cb_predictions}
        slope_dict = {p['movieId']: p['predicted_rating'] for p in slope_predictions}
        
        # Normalize to 0-1 range
        if cb_dict:
            max_cb = max(cb_dict.values())
            if max_cb > 0:
                cb_dict = {k: v/max_cb for k, v in cb_dict.items()}
        
        if slope_dict:
            max_slope = max(slope_dict.values())
            min_slope = min(slope_dict.values())
            if max_slope > min_slope:
                slope_dict = {k: (v-min_slope)/(max_slope-min_slope) 
                             for k, v in slope_dict.items()}
        
        # Hybrid combination: weighted average
        hybrid_scores = {}
        all_movies = set(cb_dict.keys()) | set(slope_dict.keys())
        
        for movie_id in all_movies:
            cb_score = cb_dict.get(movie_id, 0)
            slope_score = slope_dict.get(movie_id, 0)
            
            # Weighted combination
            hybrid_scores[movie_id] = self.alpha * cb_score + (1 - self.alpha) * slope_score
        
        # Sort and return
        hybrid_predictions = [
            {'movieId': movie_id, 'hybrid_score': score}
            for movie_id, score in hybrid_scores.items()
        ]
        hybrid_predictions = sorted(
            hybrid_predictions, 
            key=lambda x: x['hybrid_score'], 
            reverse=True
        )
        
        return hybrid_predictions, cb_predictions, slope_predictions, user_profile


# ===== DEMONSTRATION =====
print("\n" + "="*70)
print("TRAINING MODELS")
print("="*70)

# Train Content-Based
