# ===== HELPER FUNCTIONS =====
def cosine_similarity_manual(vec1, vec2):
    """Calculate cosine similarity between two vectors"""
    dot_product = np.dot(vec1, vec2)
    norm1 = np.linalg.norm(vec1)
    norm2 = np.linalg.norm(vec2)
    
    if norm1 == 0 or norm2 == 0:
        return 0.0
    
    return dot_product / (norm1 * norm2)


def build_tfidf_manual(documents):
    """Build TF-IDF matrix manually from documents (genres)"""
    # Step 1: Build vocabulary
    vocabulary = set()
    for doc in documents:
        if pd.notna(doc):
            terms = doc.split('|')
            vocabulary.update(terms)
    
    vocabulary = sorted(list(vocabulary))
    vocab_to_idx = {term: idx for idx, term in enumerate(vocabulary)}
    
    # Step 2: Calculate TF (Term Frequency)
    tf_matrix = np.zeros((len(documents), len(vocabulary)))
    
    for doc_idx, doc in enumerate(documents):
        if pd.notna(doc):
            terms = doc.split('|')
            for term in terms:
                term_idx = vocab_to_idx[term]
                tf_matrix[doc_idx, term_idx] += 1
    
    # Step 3: Calculate IDF (Inverse Document Frequency)
    # IDF = log(N / df) where df is document frequency
    N = len(documents)
    idf = np.zeros(len(vocabulary))
    
    for term_idx in range(len(vocabulary)):
        df = np.sum(tf_matrix[:, term_idx] > 0)  # Number of docs containing term
        if df > 0:
            idf[term_idx] = np.log(N / df)
    
    # Step 4: Calculate TF-IDF
    tfidf_matrix = tf_matrix * idf
    
    # Normalize rows to unit length
    for i in range(len(tfidf_matrix)):
        norm = np.linalg.norm(tfidf_matrix[i])
        if norm > 0:
            tfidf_matrix[i] = tfidf_matrix[i] / norm
    
    return tfidf_matrix, vocabulary


def one_hot_encoding(genres_list, all_genres):
    """One-hot encode genres"""
    encoding = np.zeros(len(all_genres))
    genre_to_idx = {g: idx for idx, g in enumerate(all_genres)}
    
    for genre in genres_list:
        if genre in genre_to_idx:
            encoding[genre_to_idx[genre]] = 1
    
    return encoding


# ===== 1. CONTENT-BASED FILTERING =====
class ContentBasedRecommender:
    def __init__(self, movies_df):
        self.movies = movies_df
        self.movie_features = None
        self.movie_id_to_idx = {}
        self.all_genres = []
        
    def fit(self, method='tfidf'):
        """Build movie feature matrix using TF-IDF or One-Hot encoding"""
        start_time = time.time()
        
        # Create movie ID to index mapping
        self.movie_id_to_idx = {mid: idx for idx, mid in enumerate(self.movies['movieId'])}
        
        if method == 'tfidf':
            # TF-IDF approach
            genres_docs = self.movies['genres'].fillna('').tolist()
            self.movie_features, self.all_genres = build_tfidf_manual(genres_docs)
            print(f"  Method: TF-IDF with {len(self.all_genres)} genres")
            
        else:  # one-hot
            # One-hot encoding approach (theo tài liệu)
            all_genres_set = set()
            for genres in self.movies['genres']:
                if pd.notna(genres):
                    all_genres_set.update(genres.split('|'))
            self.all_genres = sorted(list(all_genres_set))
            
            # Build one-hot vectors
            feature_vectors = []
            for genres in self.movies['genres']:
                if pd.notna(genres):
                    genre_list = genres.split('|')
                else:
                    genre_list = []
                vector = one_hot_encoding(genre_list, self.all_genres)
                feature_vectors.append(vector)
            
            self.movie_features = np.array(feature_vectors)
            print(f"  Method: One-Hot with {len(self.all_genres)} genres")
        
        self.train_time = time.time() - start_time
        return self
    
    def build_user_profile(self, user_ratings):
        """Build weighted user profile from rated movies (theo công thức trong tài liệu)"""
        profile = np.zeros(self.movie_features.shape[1])
        total_weight = 0
        
        for movie_id, rating in user_ratings.items():
            if movie_id in self.movie_id_to_idx:
                idx = self.movie_id_to_idx[movie_id]
                movie_vec = self.movie_features[idx]
                # U = (Σ w_i × V_i) / Σ w_i
                profile += rating * movie_vec
                total_weight += rating
        
        if total_weight > 0:
            profile = profile / total_weight
        
        return profile
    
    def predict(self, user_id, user_ratings, candidate_movies, top_n=10):
        """Predict ratings for candidate movies using cosine similarity"""
        start_time = time.time()
        
        # Build user profile
        profile = self.build_user_profile(user_ratings)
        
        # Calculate similarities
        predictions = []
        for movie_id in candidate_movies:
            if movie_id in self.movie_id_to_idx:
                idx = self.movie_id_to_idx[movie_id]
                movie_vec = self.movie_features[idx]
                # sim(A,B) = (A·B) / (||A|| × ||B||)
                similarity = cosine_similarity_manual(profile, movie_vec)
                predictions.append((movie_id, similarity))
        
        # Sort by similarity
        predictions.sort(key=lambda x: x[1], reverse=True)
        
        pred_time = time.time() - start_time
        return predictions[:top_n], pred_time


# ===== 2. SLOPE ONE =====
class SlopeOne:
    def __init__(self):
        self.deviations = defaultdict(lambda: defaultdict(float))
        self.frequencies = defaultdict(lambda: defaultdict(int))
        
    def fit(self, ratings_df):
        """Calculate deviation matrix (theo công thức trong tài liệu)"""
        start_time = time.time()
        
        # Group by user
        user_ratings = ratings_df.groupby('userId').apply(
            lambda x: dict(zip(x['movieId'], x['rating']))
        ).to_dict()
        
        # Calculate deviations
        # dev(i,j) = Σ(r_u,i - r_u,j) / |U_i,j|
        count = 0
        for ratings in user_ratings.values():
            items = list(ratings.items())
            for i, (item1, rating1) in enumerate(items):
                for item2, rating2 in items[i+1:]:
                    # Store both directions
                    self.deviations[item1][item2] += rating1 - rating2
                    self.deviations[item2][item1] += rating2 - rating1
                    self.frequencies[item1][item2] += 1
                    self.frequencies[item2][item1] += 1
            
            count += 1
            if count % 100 == 0:
                print(f"\r  Processing: {count}/{len(user_ratings)} users", end='')
        
        print(f"\r  Processing: {len(user_ratings)}/{len(user_ratings)} users - Done!")
        
        # Average deviations
        for item1 in self.deviations:
            for item2 in self.deviations[item1]:
                if self.frequencies[item1][item2] > 0:
                    self.deviations[item1][item2] /= self.frequencies[item1][item2]
        
        self.train_time = time.time() - start_time
        return self
    
    def predict_rating(self, user_ratings, movie_id):
        """Predict rating for a single movie (theo công thức trong tài liệu)"""
        numerator = 0
        denominator = 0
        
        # r̂_u,i = Σ[(dev(i,j) + r_u,j) × |U_i,j|] / Σ|U_i,j|
        for rated_movie, rating in user_ratings.items():
            if rated_movie in self.deviations and movie_id in self.deviations[rated_movie]:
                freq = self.frequencies[rated_movie][movie_id]
                dev = self.deviations[rated_movie][movie_id]
                numerator += (dev + rating) * freq
                denominator += freq
        
        if denominator == 0:
            return None
        
        return numerator / denominator
    
    def predict(self, user_id, user_ratings, candidate_movies, top_n=10):
        """Predict ratings for candidate movies"""
        start_time = time.time()
        
        predictions = []
        for movie_id in candidate_movies:
            pred_rating = self.predict_rating(user_ratings, movie_id)
            if pred_rating is not None:
                predictions.append((movie_id, pred_rating))
        
        # Sort by predicted rating
        predictions.sort(key=lambda x: x[1], reverse=True)
        
        pred_time = time.time() - start_time
        return predictions[:top_n], pred_time


# ===== 3. HYBRID RECOMMENDER =====
class HybridRecommender:
    def __init__(self, cb_model, slope_model, alpha=0.5):
        """
        Hybrid combination using weighted average
        alpha: weight for Content-Based (0-1)
        (1-alpha): weight for Slope One
        """
        self.cb_model = cb_model
        self.slope_model = slope_model
        self.alpha = alpha
        self.train_time = cb_model.train_time + slope_model.train_time
        
    def normalize_scores(self, predictions):
        """Normalize scores to [0, 1] range"""
        if not predictions:
            return {}
        
        scores = [score for _, score in predictions]
        min_score = min(scores)
        max_score = max(scores)
        
        if max_score == min_score:
            return {movie_id: 0.5 for movie_id, _ in predictions}
        
        normalized = {}
        for movie_id, score in predictions:
            normalized[movie_id] = (score - min_score) / (max_score - min_score)
        
        return normalized
    
    def predict(self, user_id, user_ratings, candidate_movies, top_n=10):
        """Hybrid prediction combining both methods"""
        start_time = time.time()
        
        # Get predictions from both models
        cb_preds, _ = self.cb_model.predict(user_id, user_ratings, candidate_movies, top_n=len(candidate_movies))
        slope_preds, _ = self.slope_model.predict(user_id, user_ratings, candidate_movies, top_n=len(candidate_movies))
        
        # Normalize scores to [0,1]
        cb_norm = self.normalize_scores(cb_preds)
        slope_norm = self.normalize_scores(slope_preds)
        
        # Combine scores: Hybrid = α × CB + (1-α) × Slope
        hybrid_scores = {}
        all_movies = set(cb_norm.keys()) | set(slope_norm.keys())
        
        for movie_id in all_movies:
            cb_score = cb_norm.get(movie_id, 0)
            slope_score = slope_norm.get(movie_id, 0)
            hybrid_scores[movie_id] = self.alpha * cb_score + (1 - self.alpha) * slope_score
        
        # Sort and return top N
        predictions = sorted(hybrid_scores.items(), key=lambda x: x[1], reverse=True)
        
        pred_time = time.time() - start_time
        return predictions[:top_n], pred_time


# ===== EVALUATION METRICS (Manual Implementation) =====
def precision_at_k(predictions, relevant_items, k=10):
    """Precision@K = |Relevant ∩ Retrieved| / K"""
    if not predictions:
        return 0.0
    top_k = [movie_id for movie_id, _ in predictions[:k]]
    relevant_in_top_k = len(set(top_k) & set(relevant_items))
    return relevant_in_top_k / k if k > 0 else 0.0


def recall_at_k(predictions, relevant_items, k=10):
    """Recall@K = |Relevant ∩ Retrieved| / |Relevant|"""
    if not relevant_items:
        return 0.0
    top_k = [movie_id for movie_id, _ in predictions[:k]]
    relevant_in_top_k = len(set(top_k) & set(relevant_items))
    return relevant_in_top_k / len(relevant_items)


def f1_score(precision, recall):
    """F1 = 2 × (Precision × Recall) / (Precision + Recall)"""
    if precision + recall == 0:
        return 0.0
    return 2 * (precision * recall) / (precision + recall)


def ndcg_at_k(predictions, relevant_items, k=10):
    """NDCG@K = DCG / IDCG"""
    if not predictions or not relevant_items:
        return 0.0
    
    # DCG = Σ (1 / log2(i+2)) for relevant items
    dcg = 0.0
    for i, (movie_id, _) in enumerate(predictions[:k]):
        if movie_id in relevant_items:
            dcg += 1.0 / np.log2(i + 2)
    
    # IDCG (Ideal DCG)
    idcg = sum(1.0 / np.log2(i + 2) for i in range(min(len(relevant_items), k)))
    
    return dcg / idcg if idcg > 0 else 0.0


def mean_reciprocal_rank(predictions, relevant_items):
    """MRR = 1 / rank of first relevant item"""
    for i, (movie_id, _) in enumerate(predictions):
        if movie_id in relevant_items:
            return 1.0 / (i + 1)
    return 0.0


def hit_rate(predictions, relevant_items, k=10):
    """Hit Rate@K = 1 if any relevant item in top-K, else 0"""
    top_k = [movie_id for movie_id, _ in predictions[:k]]
    return 1.0 if any(item in relevant_items for item in top_k) else 0.0


