K = 10  # Top-K recommendations

for idx, user_id in enumerate(sample_users):
    if (idx + 1) % 20 == 0:
        print(f"\r  Progress: {idx+1}/{len(sample_users)} users", end='')
    
    # Get user's training ratings
    user_train = train_ratings[train_ratings['userId'] == user_id]
    user_ratings = dict(zip(user_train['movieId'], user_train['rating']))
    
    # Get user's test ratings (ground truth)
    user_test = test_ratings[test_ratings['userId'] == user_id]
    relevant_items = user_test[user_test['rating'] >= 4.0]['movieId'].tolist()
    
    if len(user_ratings) == 0 or len(relevant_items) == 0:
        continue
    
    # Get candidate movies (movies user hasn't rated in training)
    all_movies = set(movies_df['movieId'])
    candidate_movies = list(all_movies - set(user_ratings.keys()))
    
    # IMPORTANT: Don't sample candidates randomly!
    # This was causing metrics to be 0 because relevant items were excluded
    # For production, use all candidates or at least ensure test items are included
    
    # Check if we have relevant items in candidates
    relevant_in_candidates = len(set(relevant_items) & set(candidate_movies))
    
    # If no relevant items in candidates, skip this user
    if relevant_in_candidates == 0:
        continue
    
    # Only limit if there are WAY too many (> 5000)
    # and ensure we keep the relevant items
    if len(candidate_movies) > 5000:
        # Keep all relevant items + random sample of others
        other_candidates = list(set(candidate_movies) - set(relevant_items))
        sampled_others = list(np.random.choice(other_candidates, min(4000, len(other_candidates)), replace=False))
        candidate_movies = list(set(relevant_items) | set(sampled_others))
    
    # Evaluate Content-Based
    cb_preds, cb_time = cb_model.predict(user_id, user_ratings, candidate_movies, top_n=K)
    if cb_preds:
        metrics['Content-Based']['precision'].append(precision_at_k(cb_preds, relevant_items, K))
        metrics['Content-Based']['recall'].append(recall_at_k(cb_preds, relevant_items, K))
        metrics['Content-Based']['f1'].append(f1_score(
            metrics['Content-Based']['precision'][-1],
            metrics['Content-Based']['recall'][-1]
        ))
        metrics['Content-Based']['ndcg'].append(ndcg_at_k(cb_preds, relevant_items, K))
        metrics['Content-Based']['mrr'].append(mean_reciprocal_rank(cb_preds, relevant_items))
        metrics['Content-Based']['hit_rate'].append(hit_rate(cb_preds, relevant_items, K))
        metrics['Content-Based']['time'].append(cb_time)
    
    # Evaluate Slope One
    slope_preds, slope_time = slope_model.predict(user_id, user_ratings, candidate_movies, top_n=K)
    if slope_preds:
        metrics['Slope One']['precision'].append(precision_at_k(slope_preds, relevant_items, K))
        metrics['Slope One']['recall'].append(recall_at_k(slope_preds, relevant_items, K))
        metrics['Slope One']['f1'].append(f1_score(
            metrics['Slope One']['precision'][-1],
            metrics['Slope One']['recall'][-1]
        ))
        metrics['Slope One']['ndcg'].append(ndcg_at_k(slope_preds, relevant_items, K))
        metrics['Slope One']['mrr'].append(mean_reciprocal_rank(slope_preds, relevant_items))
        metrics['Slope One']['hit_rate'].append(hit_rate(slope_preds, relevant_items, K))
