import numpy as np
import pandas as pd
from collections import defaultdict
import time
import warnings
warnings.filterwarnings('ignore')

# ===== 1. CONTENT-BASED FILTERING =====
class ContentBasedRecommender:
    def __init__(self, movies_df):
        self.movies = movies_df
        self.movie_features = None
        self.movie_id_to_idx = {}
        self.all_genres = []
        self.train_time = 0
        
    def fit(self, method='tfidf'):
        start_time = time.time()
        self.movie_id_to_idx = {mid: idx for idx, mid in enumerate(self.movies['movieId'])}
        
        # Lấy dữ liệu thể loại
        genres_data = self.movies['genres'].apply(lambda x: '|'.join(x) if isinstance(x, list) else str(x)).tolist()
        
        if method == 'tfidf':
            self.movie_features, self.all_genres = build_tfidf_manual(genres_data)
        else:
            all_genres_set = set()
            for g in genres_data: all_genres_set.update(g.split('|'))
            self.all_genres = sorted(list(all_genres_set))
            self.movie_features = np.array([one_hot_encoding(g.split('|'), self.all_genres) for g in genres_data])
        
        self.train_time = time.time() - start_time
        return self
    
    def predict(self, user_id, user_ratings, candidate_movies, top_n=10):
        if not user_ratings: return [], 0
        start_time = time.time()
        
        # Build user profile
        profile = np.zeros(self.movie_features.shape[1])
        total_w = 0
        for mid, r in user_ratings.items():
            if mid in self.movie_id_to_idx:
                profile += r * self.movie_features[self.movie_id_to_idx[mid]]
                total_w += r
        if total_w > 0: profile /= total_w
        
        # Sim
        preds = []
        for mid in candidate_movies:
            if mid in self.movie_id_to_idx:
                sim = cosine_similarity_manual(profile, self.movie_features[self.movie_id_to_idx[mid]])
                preds.append((mid, sim))
        
        preds.sort(key=lambda x: x[1], reverse=True)
        return preds[:top_n], time.time() - start_time

# ===== 2. SLOPE ONE (OPTIMIZED) =====
class SlopeOne:
    def __init__(self, min_support=3):
        self.deviations = defaultdict(lambda: defaultdict(float))
        self.frequencies = defaultdict(lambda: defaultdict(int))
        self.min_support = min_support
        self.train_time = 0
        
    def fit(self, ratings_df):
        start_time = time.time()
        user_ratings = ratings_df.groupby('userId').apply(lambda x: dict(zip(x['movieId'], x['rating']))).to_dict()
        
        for ratings in user_ratings.values():
            items = list(ratings.items())
            for i, (m1, r1) in enumerate(items):
                for m2, r2 in items[i+1:]:
                    self.deviations[m1][m2] += (r1 - r2)
                    self.deviations[m2][m1] += (r2 - r1)
                    self.frequencies[m1][m2] += 1
                    self.frequencies[m2][m1] += 1
        
        # Average & Filter by Min Support
        for m1 in list(self.deviations.keys()):
            for m2 in list(self.deviations[m1].keys()):
                if self.frequencies[m1][m2] >= self.min_support:
                    self.deviations[m1][m2] /= self.frequencies[m1][m2]
                else:
                    del self.deviations[m1][m2]
                    del self.frequencies[m1][m2]
                    
        self.train_time = time.time() - start_time
        return self
    
    def predict(self, user_id, user_ratings, candidate_movies, top_n=10):
        start_time = time.time()
        preds = []
        user_avg = np.mean(list(user_ratings.values())) if user_ratings else 3.0
        
        for mid in candidate_movies:
            num, den = 0, 0
            for r_mid, r_val in user_ratings.items():
                if mid in self.deviations[r_mid]:
                    freq = self.frequencies[r_mid][mid]
                    num += (self.deviations[r_mid][mid] + r_val) * freq
                    den += freq
            
            p_rating = num / den if den > 0 else user_avg
            preds.append((mid, max(0.5, min(5.0, p_rating)))) # Clip rating
            
        preds.sort(key=lambda x: x[1], reverse=True)
        return preds[:top_n], time.time() - start_time

# ===== 3. HYBRID (WITH ROBUST NORMALIZATION) =====
class HybridRecommender:
    def __init__(self, cb_model, slope_model, alpha=0.7):
        self.cb_model = cb_model
        self.slope_model = slope_model
        self.alpha = alpha
        
    def _normalize(self, preds):
        if not preds: return {}
        scores = [p[1] for p in preds]
        s_min, s_max = min(scores), max(scores)
        if s_max == s_min: return {p[0]: 0.5 for p in preds}
        return {p[0]: (p[1] - s_min) / (s_max - s_min) for p in preds}

    def predict(self, user_id, user_ratings, candidate_movies, top_n=10):
        start_time = time.time()
        cb_raw, _ = self.cb_model.predict(user_id, user_ratings, candidate_movies, top_n=len(candidate_movies))
        sl_raw, _ = self.slope_model.predict(user_id, user_ratings, candidate_movies, top_n=len(candidate_movies))
        
        cb_norm = self._normalize(cb_raw)
        sl_norm = self._normalize(sl_raw)
        
        hybrid_scores = []
        for mid in candidate_movies:
            s = self.alpha * cb_norm.get(mid, 0) + (1 - self.alpha) * sl_norm.get(mid, 0)
            hybrid_scores.append((mid, s))
            
        hybrid_scores.sort(key=lambda x: x[1], reverse=True)
        return hybrid_scores[:top_n], time.time() - start_time

# ===== CHẠY ĐÁNH GIÁ =====
# (Giả định bạn đã có movies_df, train_ratings, test_ratings)

