import numpy as np
import pandas as pd
from collections import defaultdict
import time
import warnings

warnings.filterwarnings('ignore')

# ==============================================================================
# 1. TIỀN XỬ LÝ DỮ LIỆU (Giả định bạn đã load movies_df và ratings_df)
# ==============================================================================

def prepare_data(movies_df, ratings_df):
    print("--- Đang chuẩn bị dữ liệu ---")
    # Chia Train/Test (80/20) theo thời gian hoặc ngẫu nhiên
    np.random.seed(42)
    shuffled_indices = np.random.permutation(len(ratings_df))
    train_size = int(0.8 * len(ratings_df))
    
    train_indices = shuffled_indices[:train_size]
    test_indices = shuffled_indices[train_size:]
    
    train_df = ratings_df.iloc[train_indices]
    test_df = ratings_df.iloc[test_indices]
    
    return train_df, test_df

# ==============================================================================
# 2. CÁC LỚP MÔ HÌNH (ONE-HOT & HYBRID)
# ==============================================================================

class ContentBasedOneHot:
    def __init__(self, movies_df):
        self.movies = movies_df
        self.movie_features = None
        self.movie_id_to_idx = {}
        self.all_genres = []
        
    def fit(self):
        start = time.time()
        self.movie_id_to_idx = {mid: i for i, mid in enumerate(self.movies['movieId'])}
        
        # Xử lý genres thành One-Hot
        genres_series = self.movies['genres'].apply(lambda x: x if isinstance(x, list) else str(x).split('|'))
        unique_genres = sorted(list(set([g for sublist in genres_series for g in sublist])))
        self.all_genres = unique_genres
        
        # Vector hóa One-Hot
        self.movie_features = np.zeros((len(self.movies), len(unique_genres)))
        genre_to_idx = {g: i for i, g in enumerate(unique_genres)}
        
        for i, g_list in enumerate(genres_series):
            for g in g_list:
                if g in genre_to_idx:
                    self.movie_features[i, genre_to_idx[g]] = 1
        
        # Chuẩn hóa vector
        norms = np.linalg.norm(self.movie_features, axis=1, keepdims=True)
        self.movie_features = np.divide(self.movie_features, norms, out=np.zeros_like(self.movie_features), where=norms!=0)
        
        print(f"✓ Content-Based One-Hot trained: {time.time()-start:.2f}s")
        return self

    def predict(self, user_ratings_dict, candidates):
        if not user_ratings_dict: return {}
        
        # Tạo User Profile từ phim đã xem (Weighted by rating)
        u_profile = np.zeros(self.movie_features.shape[1])
        for mid, r in user_ratings_dict.items():
            if mid in self.movie_id_to_idx:
                u_profile += self.movie_features[self.movie_id_to_idx[mid]] * (r / 5.0)
        
        # Tính tương đồng dot product (vì đã chuẩn hóa nên dot = cosine)
        candidate_indices = [self.movie_id_to_idx[m] for m in candidates if m in self.movie_id_to_idx]
        if not candidate_indices: return {}
        
        sims = np.dot(self.movie_features[candidate_indices], u_profile)
        return dict(zip([candidates[i] for i in range(len(candidate_indices))], sims))

class SlopeOneOptimized:
    def __init__(self, min_support=3):
        self.deviations = defaultdict(dict)
        self.frequencies = defaultdict(dict)
        self.min_support = min_support
        
    def fit(self, train_df):
        start = time.time()
        u_map = train_df.groupby('userId').apply(lambda x: dict(zip(x['movieId'], x['rating']))).to_dict()
        
        for ratings in u_map.values():
            items = list(ratings.items())
            for i, (m1, r1) in enumerate(items):
                for m2, r2 in items[i+1:]:
                    self.deviations[m1][m2] = self.deviations[m1].get(m2, 0) + (r1 - r2)
                    self.frequencies[m1][m2] = self.frequencies[m1].get(m2, 0) + 1
                    self.deviations[m2][m1] = self.deviations[m2].get(m1, 0) + (r2 - r1)
                    self.frequencies[m2][m1] = self.frequencies[m2].get(m1, 0) + 1
                    
        for m1 in list(self.deviations.keys()):
            for m2 in list(self.deviations[m1].keys()):
                if self.frequencies[m1][m2] >= self.min_support:
                    self.deviations[m1][m2] /= self.frequencies[m1][m2]
                else:
                    del self.deviations[m1][m2]
                    del self.frequencies[m1][m2]
        print(f"✓ Slope One trained: {time.time()-start:.2f}s")
        return self

    def predict(self, user_ratings_dict, candidates):
        preds = {}
        user_avg = np.mean(list(user_ratings_dict.values())) if user_ratings_dict else 3.0
        
        for m_cand in candidates:
            num, den = 0, 0
            for m_rated, r_val in user_ratings_dict.items():
                if m_cand in self.deviations[m_rated]:
                    freq = self.frequencies[m_rated][m_cand]
                    num += (self.deviations[m_rated][m_cand] + r_val) * freq
                    den += freq
            preds[m_cand] = max(0.5, min(5.0, num / den)) if den > 0 else user_avg
        return preds

# ==============================================================================
# 3. CHẠY VÀ ĐÁNH GIÁ TRÊN TOÀN BỘ DATASET
# ==============================================================================

def run_full_evaluation(movies_df, ratings_df, alpha=0.5, top_k=10):
    train_df, test_df = prepare_data(movies_df, ratings_df)
    
    cb = ContentBasedOneHot(movies_df).fit()
    sl = SlopeOneOptimized(min_support=3).fit(train_df)
    
    test_users = test_df['userId'].unique()
    all_precision, all_recall = [], []
    
    print(f"--- Đang đánh giá trên {len(test_users)} người dùng ---")
    
    for uid in test_users:
        # Lấy lịch sử train và test
        u_train = train_df[train_df['userId'] == uid]
        u_train_dict = dict(zip(u_train['movieId'], u_train['rating']))
        
        u_test = test_df[test_df['userId'] == uid]
        relevant_items = u_test[u_test['rating'] >= 4.0]['movieId'].tolist()
        
        if not relevant_items: continue
        
        # Tập ứng viên: tất cả phim trong test và một ít phim ngẫu nhiên để thử thách
        candidates = list(set(u_test['movieId'].tolist()) | set(np.random.choice(movies_df['movieId'], 50)))
        
        # Lấy điểm từ 2 model
        cb_scores = cb.predict(u_train_dict, candidates)
        sl_scores = sl.predict(u_train_dict, candidates)
        
        # Chuẩn hóa và Hybrid
        def norm(d):
            if not d: return {}
            vals = list(d.values())
            v_min, v_max = min(vals), max(vals)
            if v_max == v_min: return {k: 0.5 for k in d}
            return {k: (v - v_min) / (v_max - v_min) for k, v in d.items()}
        
        cb_n, sl_n = norm(cb_scores), norm(sl_scores)
        
        final_preds = []
        for m in candidates:
            score = alpha * cb_n.get(m, 0) + (1 - alpha) * sl_n.get(m, 0)
            final_preds.append((m, score))
            
        final_preds.sort(key=lambda x: x[1], reverse=True)
        top_recommendations = [x[0] for x in final_preds[:top_k]]
        
        # Tính metrics
        hits = len(set(top_recommendations) & set(relevant_items))
        all_precision.append(hits / top_k)
        all_recall.append(hits / len(relevant_items))

    print("\n" + "="*50)
    print(f"KẾT QUẢ CUỐI CÙNG TRÊN TOÀN BỘ DATASET")
    print(f"Average Precision@{top_k}: {np.mean(all_precision):.4f}")
    print(f"Average Recall@{top_k}:    {np.mean(all_recall):.4f}")
    print("="*50)

# Chạy lệnh này
# run_full_evaluation(movies_df, ratings_df)
