import numpy as np
import pandas as pd
from collections import defaultdict
import time
import warnings

warnings.filterwarnings('ignore')

# ==============================================================================
# 1. CÁC HÀM TIỀN XỬ LÝ & TRỢ GIÚP
# ==============================================================================

def load_and_clean_data():
    print("--- Đang tải dữ liệu thực tế ---")
    try:
        # Thay đổi đường dẫn file nếu cần
        movies = pd.read_csv('movies.csv')
        ratings = pd.read_csv('ratings.csv')
        
        # Chuyển genres thành list
        movies['genres'] = movies['genres'].apply(lambda x: x.split('|'))
        
        # Chia Train/Test (80/20)
        np.random.seed(42)
        shuffled = ratings.sample(frac=1, random_state=42)
        split_idx = int(0.8 * len(shuffled))
        train_df = shuffled.iloc[:split_idx]
        test_df = shuffled.iloc[split_idx:]
        
        print(f"✓ Loaded: {len(movies)} movies, {len(ratings)} ratings.")
        return movies, train_df, test_df
    except FileNotFoundError:
        print("❌ Lỗi: Không tìm thấy file csv. Hãy kiểm tra lại đường dẫn.")
        return None, None, None

def norm_scores(d):
    """Chuẩn hóa điểm số về khoảng [0, 1]"""
    if not d: return {}
    vals = list(d.values())
    v_min, v_max = min(vals), max(vals)
    if v_max == v_min: return {k: 0.5 for k in d}
    return {k: (v - v_min) / (v_max - v_min) for k, v in d.items()}

# ==============================================================================
# 2. CONTENT-BASED (ONE-HOT ENCODING)
# ==============================================================================

class ContentBasedOneHot:
    def __init__(self, movies_df):
        self.movies = movies_df
        self.movie_features = None
        self.movie_id_to_idx = {mid: i for i, mid in enumerate(movies_df['movieId'])}
        
    def fit(self):
        start = time.time()
        # Lấy danh sách genres duy nhất
        all_genres = sorted(list(set([g for sublist in self.movies['genres'] for g in sublist])))
        genre_to_idx = {g: i for i, g in enumerate(all_genres)}
        
        # Tạo ma trận One-Hot
        self.movie_features = np.zeros((len(self.movies), len(all_genres)))
        for i, g_list in enumerate(self.movies['genres']):
            for g in g_list:
                if g in genre_to_idx:
                    self.movie_features[i, genre_to_idx[g]] = 1
        
        # Chuẩn hóa vector hàng (Unit vector) để dot product = cosine similarity
        norms = np.linalg.norm(self.movie_features, axis=1, keepdims=True)
        self.movie_features = np.divide(self.movie_features, norms, out=np.zeros_like(self.movie_features), where=norms!=0)
        
        print(f"✓ CB One-Hot trained in {time.time()-start:.2f}s")
        return self

    def predict(self, user_ratings_dict, candidates):
        if not user_ratings_dict: return {}
        # User Profile = Trung bình có trọng số của các phim đã xem
        u_profile = np.zeros(self.movie_features.shape[1])
        for mid, r in user_ratings_dict.items():
            if mid in self.movie_id_to_idx:
                u_profile += self.movie_features[self.movie_id_to_idx[mid]] * (r / 5.0)
        
        candidate_indices = [self.movie_id_to_idx[m] for m in candidates if m in self.movie_id_to_idx]
        if not candidate_indices: return {}
        
        sims = np.dot(self.movie_features[candidate_indices], u_profile)
        return dict(zip([candidates[i] for i in range(len(candidate_indices))], sims))

# ==============================================================================
# 3. SLOPE ONE (COLLABORATIVE FILTERING)
# ==============================================================================

class SlopeOneModel:
    def __init__(self, min_support=3):
        self.deviations = defaultdict(dict)
        self.frequencies = defaultdict(dict)
        self.min_support = min_support
        
    def fit(self, train_df):
        start = time.time()
        u_map = train_df.groupby('userId').apply(lambda x: dict(zip(x['movieId'], x['rating']))).to_dict()
        
        for ratings in u_map.values():
            items = list(ratings.items())
            for i, (m1, r1) in enumerate(items):
                for m2, r2 in items[i+1:]:
                    self.deviations[m1][m2] = self.deviations[m1].get(m2, 0) + (r1 - r2)
                    self.frequencies[m1][m2] = self.frequencies[m1].get(m2, 0) + 1
                    self.deviations[m2][m1] = self.deviations[m2].get(m1, 0) + (r2 - r1)
                    self.frequencies[m2][m1] = self.frequencies[m2].get(m1, 0) + 1
                    
        for m1 in list(self.deviations.keys()):
            for m2 in list(self.deviations[m1].keys()):
                if self.frequencies[m1][m2] >= self.min_support:
                    self.deviations[m1][m2] /= self.frequencies[m1][m2]
                else:
                    del self.deviations[m1][m2]
                    del self.frequencies[m1][m2]
        print(f"✓ Slope One trained in {time.time()-start:.2f}s")
        return self

    def predict(self, user_ratings_dict, candidates):
        preds = {}
        user_avg = np.mean(list(user_ratings_dict.values())) if user_ratings_dict else 3.0
        for m_cand in candidates:
            num, den = 0, 0
            for m_rated, r_val in user_ratings_dict.items():
                if m_cand in self.deviations[m_rated]:
                    freq = self.frequencies[m_rated][m_cand]
                    num += (self.deviations[m_rated][m_cand] + r_val) * freq
                    den += freq
            preds[m_cand] = num / den if den > 0 else user_avg
        return preds

# ==============================================================================
# 4. CHẠY TOÀN BỘ HỆ THỐNG
# ==============================================================================

def main():
    movies_df, train_df, test_df = load_and_clean_data()
    if movies_df is None: return

    # Huấn luyện
    cb = ContentBasedOneHot(movies_df).fit()
    sl = SlopeOneModel(min_support=3).fit(train_df)

    test_users = test_df['userId'].unique()
    all_prec, all_rec = [], []
    alpha = 0.5  # Tỉ lệ 50/50 giữa CB và Slope One
    K = 10

    print(f"\n--- Đang đánh giá trên {len(test_users)} người dùng thực tế ---")
    
    start_time = time.time()
    for i, uid in enumerate(test_users):
        if i % 100 == 0 and i > 0:
            print(f"Tiến độ: Đã xử lý {i}/{len(test_users)} users...")

        # Dữ liệu của user
        u_train_dict = dict(zip(train_df[train_df['userId']==uid]['movieId'], 
                                train_df[train_df['userId']==uid]['rating']))
        u_test = test_df[test_df['userId']==uid]
        relevant_items = u_test[u_test['rating'] >= 4.0]['movieId'].tolist()
        
        if not relevant_items: continue

        # Ứng viên (tất cả phim chưa xem trong Train)
        candidates = list(set(movies_df['movieId']) - set(u_train_dict.keys()))
        
        # Dự đoán từ 2 nguồn
        cb_s = cb.predict(u_train_dict, candidates)
        sl_s = sl.predict(u_train_dict, candidates)
        
        # Hybrid
        cb_n, sl_n = norm_scores(cb_s), norm_scores(sl_s)
        
        final_scores = []
        for m in candidates:
            # Kết hợp điểm đã chuẩn hóa
            s = alpha * cb_n.get(m, 0) + (1 - alpha) * sl_n.get(m, 0)
            final_scores.append((m, s))
            
        final_scores.sort(key=lambda x: x[1], reverse=True)
        recs = [x[0] for x in final_scores[:K]]
        
        # Tính toán Metrics
        hits = len(set(recs) & set(relevant_items))
        all_prec.append(hits / K)
        all_rec.append(hits / len(relevant_items))

    print("\n" + "="*50)
    print(f"KẾT QUẢ ĐÁNH GIÁ CHI TIẾT (K={K}, Alpha={alpha})")
    print(f"Thời gian chạy: {time.time() - start_time:.2f} giây")
    print(f"Average Precision@{K}: {np.mean(all_prec):.4f}")
    print(f"Average Recall@{K}:    {np.mean(all_rec):.4f}")
    print("="*50)

if __name__ == "__main__":
    main()
