import pandas as pd
import numpy as np
import math
from collections import defaultdict

# =========================
# 1. LOAD DATA
# =========================

movies, ratings, links = clean_process_dataset(*read_dataset())

# =========================
# 2. TRAIN / TEST SPLIT
# =========================

ratings = ratings.sample(frac=1, random_state=42).reset_index(drop=True)
split = int(0.8 * len(ratings))

train = ratings.iloc[:split]
test = ratings.iloc[split:]

# =========================
# 3. CONTENT-BASED
# =========================

# One-hot encoding genres (manual)
movies["genres"] = movies["genres"].apply(lambda x: x.split("|"))
all_genres = sorted({g for gs in movies["genres"] for g in gs})

def one_hot(genres):
    return np.array([1 if g in genres else 0 for g in all_genres])

movie_vectors = {
    row.movieId: one_hot(row.genres)
    for _, row in movies.iterrows()
}

train_by_user = defaultdict(list)
for _, row in train.iterrows():
    train_by_user[row.userId].append((row.movieId, row.rating))

def build_user_profile(user_id):
    items = train_by_user.get(user_id, [])
    if not items:
        return None

    profile = np.zeros(len(all_genres))
    total = 0.0

    for m, r in items:
        profile += r * movie_vectors[m]
        total += r

    return profile / total

def cosine(a, b):
    denom = np.linalg.norm(a) * np.linalg.norm(b)
    return float(np.dot(a, b) / denom) if denom else 0.0

def content_predict(user_id, movie_id):
    profile = build_user_profile(user_id)
    if profile is None:
        return None
    return cosine(profile, movie_vectors[movie_id])

# =========================
# 4. SLOPE ONE
# =========================

dev = defaultdict(lambda: defaultdict(float))
cnt = defaultdict(lambda: defaultdict(int))

for user, items in train_by_user.items():
    for i, r_i in items:
        for j, r_j in items:
            if i != j:
                dev[i][j] += r_i - r_j
                cnt[i][j] += 1

for i in dev:
    for j in dev[i]:
        dev[i][j] /= cnt[i][j]

def slope_one_predict(user_id, movie_id):
    items = train_by_user.get(user_id, [])
    if not items:
        return None

    num, den = 0.0, 0
    for j, r_j in items:
        if j in dev[movie_id]:
            w = cnt[movie_id][j]
            num += (dev[movie_id][j] + r_j) * w
            den += w

    return num / den if den else None

# =========================
# 5. HYBRID PREDICTION
# =========================

def hybrid_predict(user_id, movie_id, alpha=0.5):
    c = content_predict(user_id, movie_id)
    cf = slope_one_predict(user_id, movie_id)

    if c is None and cf is None:
        return None
    if c is None:
        return cf
    if cf is None:
        return c

    return alpha * c + (1 - alpha) * cf

# =========================
# 6. RMSE / MAE
# =========================

y_true, y_pred = [], []

for _, row in test.iterrows():
    p = hybrid_predict(row.userId, row.movieId)
    if p is not None:
        y_true.append(row.rating)
        y_pred.append(p)

y_true = np.array(y_true)
y_pred = np.array(y_pred)

rmse = math.sqrt(np.mean((y_true - y_pred) ** 2))
mae = np.mean(np.abs(y_true - y_pred))

print("RATING PREDICTION")
print("RMSE:", round(rmse, 4))
print("MAE :", round(mae, 4))
print("Samples:", len(y_true))

# =========================
# 7. TOP-K RECOMMENDATION
# =========================

def top_k(user_id, k=10):
    seen = {m for m, _ in train_by_user.get(user_id, [])}
    scores = []

    for m in movie_vectors:
        if m in seen:
            continue
        s = hybrid_predict(user_id, m)
        if s is not None:
            scores.append((m, s))

    scores.sort(key=lambda x: x[1], reverse=True)
    return [m for m, _ in scores[:k]]

# =========================
# 8. PRECISION / RECALL / F1
# =========================

test_by_user = defaultdict(list)
for _, row in test.iterrows():
    test_by_user[row.userId].append((row.movieId, row.rating))

def precision_recall_f1(k=10, threshold=4.0):
    P, R, F = [], [], []

    for u, items in test_by_user.items():
        relevant = {m for m, r in items if r >= threshold}
        if not relevant:
            continue

        recommended = set(top_k(u, k))
        if not recommended:
            continue

        tp = len(recommended & relevant)
        precision = tp / k
        recall = tp / len(relevant)
        f1 = 0 if precision + recall == 0 else 2 * precision * recall / (precision + recall)

        P.append(precision)
        R.append(recall)
        F.append(f1)

    return np.mean(P), np.mean(R), np.mean(F)

p, r, f1 = precision_recall_f1()

print("\nRANKING METRICS @10")
print("Precision:", round(p, 4))
print("Recall   :", round(r, 4))
print("F1-score :", round(f1, 4))
