import pandas as pd
import numpy as np
from collections import defaultdict

# ======================================================
# 0. INPUT DATA (ĐÃ CÓ SẴN)
# movies: movieId | genres (list[str])
# ratings: userId | movieId | rating
# ======================================================

# ======================================================
# 1. TRAIN / TEST SPLIT
# ======================================================

ratings = ratings.sample(frac=1, random_state=42).reset_index(drop=True)
split = int(0.8 * len(ratings))

train = ratings.iloc[:split]
test  = ratings.iloc[split:]

# ======================================================
# 2. CONTENT-BASED (ONE-HOT) – USER PROFILE KHÔNG TRỌNG SỐ
# U = (1 / |I_u|) * Σ V_i
# ======================================================

all_genres = sorted({g for gs in movies["genres"] for g in gs})

def one_hot(genres):
    return np.array([1.0 if g in genres else 0.0 for g in all_genres])

movie_vectors = {
    row.movieId: one_hot(row.genres)
    for _, row in movies.iterrows()
}

train_by_user = defaultdict(list)
for _, r in train.iterrows():
    train_by_user[r.userId].append(r.movieId)

def build_user_profile(user):
    items = train_by_user[user]
    if not items:
        return None
    v = np.zeros(len(all_genres))
    for m in items:
        v += movie_vectors[m]
    return v / len(items)

def cosine(a, b):
    denom = np.linalg.norm(a) * np.linalg.norm(b)
    return 0.0 if denom == 0 else float(np.dot(a, b) / denom)

def content_score(user, movie):
    profile = build_user_profile(user)
    if profile is None:
        return None
    return cosine(profile, movie_vectors[movie])

# ======================================================
# 3. COLLABORATIVE FILTERING – SLOPE ONE
# ======================================================

train_by_user_rating = defaultdict(list)
for _, r in train.iterrows():
    train_by_user_rating[r.userId].append((r.movieId, r.rating))

dev = defaultdict(lambda: defaultdict(float))
cnt = defaultdict(lambda: defaultdict(int))

for user, items in train_by_user_rating.items():
    for i, ri in items:
        for j, rj in items:
            if i != j:
                dev[i][j] += ri - rj
                cnt[i][j] += 1

for i in dev:
    for j in dev[i]:
        dev[i][j] /= cnt[i][j]

def slope_one_score(user, movie):
    items = train_by_user_rating[user]
    num, den = 0.0, 0
    for j, rj in items:
        if j in dev[movie]:
            w = cnt[movie][j]
            num += (dev[movie][j] + rj) * w
            den += w
    return None if den == 0 else num / den

# ======================================================
# 4. HYBRID SCORE
# ======================================================

def hybrid_score(user, movie, alpha=0.5):
    c = content_score(user, movie)
    s = slope_one_score(user, movie)

    if c is None and s is None:
        return None
    if s is None:
        return c
    if c is None:
        return s / 5.0

    return alpha * c + (1 - alpha) * (s / 5.0)

# ======================================================
# 5. CLASSIFICATION EVALUATION
# ======================================================

LIKE_THRESHOLD_GT   = 4.0
LIKE_THRESHOLD_PRED = 0.55

TP = FP = FN = TN = 0

for _, row in test.iterrows():
    u, m, r = row.userId, row.movieId, row.rating

    score = hybrid_score(u, m)
    if score is None:
        continue

    y_true = r >= LIKE_THRESHOLD_GT
    y_pred = score >= LIKE_THRESHOLD_PRED

    if y_true and y_pred:
        TP += 1
    elif not y_true and y_pred:
        FP += 1
    elif y_true and not y_pred:
        FN += 1
    else:
        TN += 1

precision = TP / (TP + FP) if (TP + FP) else 0
recall    = TP / (TP + FN) if (TP + FN) else 0
f1        = 2 * precision * recall / (precision + recall) if (precision + recall) else 0

# ======================================================
# 6. OUTPUT
# ======================================================

print("=" * 60)
print("HYBRID CONTENT-BASED + SLOPE ONE (CLASSIFICATION)")
print("=" * 60)
print(f"Precision : {precision:.2f}")
print(f"Recall    : {recall:.2f}")
print(f"F1-Score  : {f1:.2f}")
print("=" * 60)

print("\nConfusion Matrix")
print(f"TP: {TP} | FP: {FP}")
print(f"FN: {FN} | TN: {TN}")
