dev = defaultdict(lambda: defaultdict(float))
cnt = defaultdict(lambda: defaultdict(int))

for user, items in train_by_user_rating.items():
    for i, ri in items:
        for j, rj in items:
            if i != j:
                dev[i][j] += ri - rj
                cnt[i][j] += 1

for i in dev:
    for j in dev[i]:
        dev[i][j] /= cnt[i][j]

def slope_one_score(user, movie, min_cnt=5):
    items = train_by_user_rating[user]
    num, den = 0.0, 0
    for j, rj in items:
        if j in dev[movie] and cnt[movie][j] >= min_cnt:
            w = cnt[movie][j]
            num += (dev[movie][j] + rj) * w
            den += w
    return None if den == 0 else num / den

# ======================================================
# 4. CHUẨN HÓA SLOPE ONE (MIN–MAX)
# ======================================================

all_slope_preds = []
for u, items in train_by_user_rating.items():
    for m, _ in items:
        s = slope_one_score(u, m)
        if s is not None:
            all_slope_preds.append(s)

s_min, s_max = min(all_slope_preds), max(all_slope_preds)

def norm_slope(s):
    return (s - s_min) / (s_max - s_min)

# ======================================================
# 5. HYBRID SCORE (ALPHA TỐI ƯU)
# ======================================================

ALPHA = 0.7   # ưu tiên content-based để tăng precision

def hybrid_score(user, movie):
    c = content_score(user, movie)
    s = slope_one_score(user, movie)

    if c is None and s is None:
        return None
    if s is None:
        return c
    if c is None:
        return norm_slope(s)

    return ALPHA * c + (1 - ALPHA) * norm_slope(s)

# ======================================================
# 6. CLASSIFICATION EVALUATION
# ======================================================

LIKE_THRESHOLD_GT   = 4.0
LIKE_THRESHOLD_PRED = 0.65   # ngưỡng cao hơn để giảm FP

TP = FP = FN = TN = 0

for _, row in test.iterrows():
    u, m, r = row.userId, row.movieId, row.rating

    score = hybrid_score(u, m)
    if score is None:
        continue

    y_true = r >= LIKE_THRESHOLD_GT
    y_pred = score >= LIKE_THRESHOLD_PRED

    if y_true and y_pred:
        TP += 1
    elif not y_true and y_pred:
        FP += 1
    elif y_true and not y_pred:
        FN += 1
    else:
        TN += 1

precision = TP / (TP + FP) if (TP + FP) else 0
recall    = TP / (TP + FN) if (TP + FN) else 0
f1        = 2 * precision * recall / (precision + recall) if (precision + recall) else 0

# ======================================================
# 7. OUTPUT
# ======================================================

print("=" * 60)
print("HYBRID CONTENT-BASED + SLOPE ONE (IMPROVED)")
print("=" * 60)
print(f"Precision : {precision:.2f}")
print(f"Recall    : {recall:.2f}")
print(f"F1-Score  : {f1:.2f}")
print("=" * 60)

print("\nConfusion Matrix")
print(f"TP: {TP} | FP: {FP}")
print(f"FN: {FN} | TN: {TN}")
