import pandas as pd
import numpy as np
from collections import defaultdict
import math

# ======================================================
# 0. INPUT DATA
# movies: movieId | genres (list[str])
# ratings: userId | movieId | rating
# ======================================================

# ======================================================
# 1. TRAIN / TEST SPLIT
# ======================================================

ratings = ratings.sample(frac=1, random_state=42).reset_index(drop=True)
split = int(0.8 * len(ratings))

train = ratings.iloc[:split]
test  = ratings.iloc[split:]

# ======================================================
# 2. CONTENT-BASED – WEIGHTED USER PROFILE
# U = (1 / Σw_i) * Σ (w_i * V_i)
# ======================================================

all_genres = sorted({g for gs in movies["genres"] for g in gs})

def one_hot(genres):
    return np.array([1.0 if g in genres else 0.0 for g in all_genres])

movie_vectors = {
    row.movieId: one_hot(row.genres)
    for _, row in movies.iterrows()
}

train_items_by_user = defaultdict(list)
for _, r in train.iterrows():
    train_items_by_user[r.userId].append((r.movieId, r.rating))

def build_user_profile(user):
    items = train_items_by_user[user]
    if not items:
        return None

    profile = np.zeros(len(all_genres))
    weight_sum = 0.0

    for m, r in items:
        w = r
        profile += w * movie_vectors[m]
        weight_sum += w

    return profile / weight_sum if weight_sum > 0 else None

def cosine(a, b):
    denom = np.linalg.norm(a) * np.linalg.norm(b)
    return 0.0 if denom == 0 else float(np.dot(a, b) / denom)

def content_score(user, movie):
    profile = build_user_profile(user)
    if profile is None:
        return None
    return cosine(profile, movie_vectors[movie])

# ======================================================
# 3. COLLABORATIVE FILTERING – SLOPE ONE
# ======================================================

train_by_user_rating = defaultdict(list)
for _, r in train.iterrows():
    train_by_user_rating[r.userId].append((r.movieId, r.rating))

dev = defaultdict(lambda: defaultdict(float))
cnt = defaultdict(lambda: defaultdict(int))

for user, items in train_by_user_rating.items():
    for i, ri in items:
        for j, rj in items:
            if i != j:
                dev[i][j] += ri - rj
                cnt[i][j] += 1

for i in dev:
    for j in dev[i]:
        dev[i][j] /= cnt[i][j]

def slope_one_score(user, movie, min_cnt=5):
    items = train_by_user_rating[user]
    num, den = 0.0, 0

    for j, rj in items:
        if j in dev[movie] and cnt[movie][j] >= min_cnt:
            w = cnt[movie][j]
            num += (dev[movie][j] + rj) * w
            den += w

    return None if den == 0 else num / den

# ======================================================
# 4. HYBRID SCORE (CLASSIFICATION ONLY)
# ======================================================

all_s = []
for u, items in train_by_user_rating.items():
    for m, _ in items:
        s = slope_one_score(u, m)
        if s is not None:
            all_s.append(s)

s_min, s_max = min(all_s), max(all_s)

def norm_slope(s):
    return (s - s_min) / (s_max - s_min)

ALPHA = 0.7

def hybrid_score(user, movie):
    c = content_score(user, movie)
    s = slope_one_score(user, movie)

    if c is None and s is None:
        return None
    if s is None:
        return c
    if c is None:
        return norm_slope(s)

    return ALPHA * c + (1 - ALPHA) * norm_slope(s)

# ======================================================
# 5. EVALUATION
# ======================================================

LIKE_THRESHOLD_GT   = 4.0
LIKE_THRESHOLD_PRED = 0.5

TP = FP = FN = TN = 0
sq_err = abs_err = 0.0
n_reg = 0

for _, row in test.iterrows():
    u, m, r = row.userId, row.movieId, row.rating

