import numpy as np

thresholds = np.arange(0.05, 1.01, 0.05)  # LIKE_THRESHOLD_PRED từ 0.05 → 1.0
alphas = np.arange(0.05, 1.01, 0.05)       # ALPHA từ 0.4 → 0.8

F1_matrix = np.zeros((len(alphas), len(thresholds)))
Precision_matrix = np.zeros_like(F1_matrix)
Recall_matrix    = np.zeros_like(F1_matrix)

for i, alpha in enumerate(alphas):
    for j, th in enumerate(thresholds):
        TP = FP = FN = TN = 0
        for _, row in test.iterrows():
            u, m, r = row.userId, row.movieId, row.rating
            score = hybrid_score(u, m, alpha=alpha)
            if score is None:
                continue

            y_true = r >= LIKE_THRESHOLD_GT
            y_pred = score >= th

            if y_true and y_pred: TP += 1
            elif not y_true and y_pred: FP += 1
            elif y_true and not y_pred: FN += 1
            else: TN += 1

        precision = TP / (TP + FP) if (TP + FP) else 0
        recall    = TP / (TP + FN) if (TP + FN) else 0
        f1        = 2 * precision * recall / (precision + recall) if (precision + recall) else 0

        Precision_matrix[i, j] = precision
        Recall_matrix[i, j]    = recall
        F1_matrix[i, j]        = f1
