import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from matplotlib.colors import LinearSegmentedColormap
# Grid từ 0 → 1 với bước 0.05 → 21 x 21
threshold_list = np.arange(0.0, 1.01, 0.05)
content_weight_list = np.arange(0.0, 1.01, 0.05)

# Tạo ma trận F1-score giả lập (ví dụ: F1 = alpha * (1-threshold))
F1_matrix = np.zeros((len(content_weight_list), len(threshold_list)))
for i, alpha in enumerate(content_weight_list):
    for j, th in enumerate(threshold_list):
        F1_matrix[i, j] = alpha * (1 - th)  # công thức demo
colors = ["red", "yellow", "green"]
cmap = LinearSegmentedColormap.from_list("red_yellow_green", colors)
# Vẽ heatmap
plt.figure(figsize=(10, 10))
sns.heatmap(F1_matrix,
            xticklabels=np.round(threshold_list,2),
            yticklabels=np.round(content_weight_list,2),
            cmap=cmap, annot=True, fmt=".2f",
            cbar_kws={'label':'F1-Score'})
plt.xlabel("LIKE_THRESHOLD_PRED")
plt.ylabel("ALPHA (Content Weight)")
plt.title("Heatmap F1-Score (Theme Đen - Xanh lá - Đỏ)")
plt.tight_layout()
plt.show()
