import torch
import torch.nn as nn
import torch.nn.functional as F
from timm.models.layers import trunc_normal_, DropPath
import math

"""
CONVNEXT BREAKHIS - CẢI TIẾN CHO ẢNH MÔ HỌC UNG THƯ VÚ
Dataset: BreakHis (Breast Cancer Histopathological Database)
"""

# ==================== CORE COMPONENTS ====================

class LayerNorm(nn.Module):
    def __init__(self, normalized_shape, eps=1e-6, data_format="channels_last"):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = eps
        self.data_format = data_format
        self.normalized_shape = (normalized_shape, )
    
    def forward(self, x):
        if self.data_format == "channels_last":
            return F.layer_norm(x, self.normalized_shape, self.weight, self.bias, self.eps)
        elif self.data_format == "channels_first":
            u = x.mean(1, keepdim=True)
            s = (x - u).pow(2).mean(1, keepdim=True)
            x = (x - u) / torch.sqrt(s + self.eps)
            x = self.weight[:, None, None] * x + self.bias[:, None, None]
            return x


class Block(nn.Module):
    """ConvNeXt Block"""
    def __init__(self, dim, drop_path=0., layer_scale_init_value=1e-6):
        super().__init__()
        self.dwconv = nn.Conv2d(dim, dim, kernel_size=7, padding=3, groups=dim)
        self.norm = LayerNorm(dim, eps=1e-6)
        self.pwconv1 = nn.Linear(dim, 4 * dim)
        self.act = nn.GELU()
        self.pwconv2 = nn.Linear(4 * dim, dim)
        self.gamma = nn.Parameter(layer_scale_init_value * torch.ones((dim)), 
                                    requires_grad=True) if layer_scale_init_value > 0 else None
        self.drop_path = DropPath(drop_path) if drop_path > 0. else nn.Identity()

    def forward(self, x):
        input = x
        x = self.dwconv(x)
        x = x.permute(0, 2, 3, 1)
        x = self.norm(x)
        x = self.pwconv1(x)
        x = self.act(x)
        x = self.pwconv2(x)
        if self.gamma is not None:
            x = self.gamma * x
        x = x.permute(0, 3, 1, 2)
        x = input + self.drop_path(x)
        return x


# ==================== CẢI TIẾN 1: TEXTURE ATTENTION MODULE ====================

class TextureAttention(nn.Module):
    """
    Texture Attention cho ảnh mô học
    Tập trung vào các patterns texture đặc trưng của tế bào ung thư
    """
    def __init__(self, channels, reduction=16):
        super().__init__()
        
        # Local texture branch
        self.local_branch = nn.Sequential(
            nn.Conv2d(channels, channels // reduction, 3, padding=1),
            nn.BatchNorm2d(channels // reduction),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 3, padding=1),
        )
        
        # Global context branch
        self.global_branch = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Conv2d(channels, channels // reduction, 1),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 1),
        )
        
        self.sigmoid = nn.Sigmoid()
        
    def forward(self, x):
        local_att = self.local_branch(x)
        global_att = self.global_branch(x)
        attention = self.sigmoid(local_att + global_att)
        return x * attention


# ==================== CẢI TIẾN 2: MULTI-SCALE TEXTURE BLOCK (FIXED) ====================

class MultiScaleTextureBlock(nn.Module):
    """
    Multi-Scale Texture Extraction Block - FIXED VERSION
    Trích xuất texture ở nhiều scales cho histopathology
    
    FIX: Sử dụng depthwise separable convolution đúng cách
    """
    def __init__(self, channels):
        super().__init__()
        
        # Đảm bảo channels chia hết cho 4
        assert channels % 4 == 0, f"channels ({channels}) must be divisible by 4"
        
        channel_per_scale = channels // 4
        
        # Different kernel sizes for different texture scales
        # Mỗi conv xử lý 1/4 channels
        self.conv_3x3 = nn.Sequential(
            nn.Conv2d(channel_per_scale, channel_per_scale, 3, padding=1, groups=channel_per_scale),
            nn.Conv2d(channel_per_scale, channel_per_scale, 1)
        )
        self.conv_5x5 = nn.Sequential(
            nn.Conv2d(channel_per_scale, channel_per_scale, 5, padding=2, groups=channel_per_scale),
            nn.Conv2d(channel_per_scale, channel_per_scale, 1)
        )
        self.conv_7x7 = nn.Sequential(
            nn.Conv2d(channel_per_scale, channel_per_scale, 7, padding=3, groups=channel_per_scale),
            nn.Conv2d(channel_per_scale, channel_per_scale, 1)
        )
        self.conv_9x9 = nn.Sequential(
            nn.Conv2d(channel_per_scale, channel_per_scale, 9, padding=4, groups=channel_per_scale),
            nn.Conv2d(channel_per_scale, channel_per_scale, 1)
        )
        
        self.fusion = nn.Sequential(
            nn.Conv2d(channels, channels, 1),
            nn.BatchNorm2d(channels),
            nn.ReLU(inplace=True)
        )
        
    def forward(self, x):
        # Chia input thành 4 phần bằng nhau
        c = x.size(1) // 4
        
        # Extract multi-scale textures từng phần
        feat_3 = self.conv_3x3(x[:, :c])
        feat_5 = self.conv_5x5(x[:, c:2*c])
        feat_7 = self.conv_7x7(x[:, 2*c:3*c])
        feat_9 = self.conv_9x9(x[:, 3*c:])
        
        # Concatenate và fuse
        multi_scale = torch.cat([feat_3, feat_5, feat_7, feat_9], dim=1)
        return self.fusion(multi_scale)


# ==================== CẢI TIẾN 3: COLOR-AWARE STEM ====================

class ColorAwareStem(nn.Module):
    """
    Color-Aware Stem cho H&E stained images
    
    H&E staining có 2 channels chính:
    - Hematoxylin (xanh): Nhân tế bào
    - Eosin (hồng): Chất tế bào
    """
    def __init__(self, in_chans=3, out_chans=96):
        super().__init__()
        
        # Separate processing cho từng color channel
        self.channel_convs = nn.ModuleList([
            nn.Conv2d(1, out_chans // 3, kernel_size=4, stride=4) 
            for _ in range(in_chans)
        ])
        
        # Fusion layer
        self.fusion = nn.Sequential(
            nn.Conv2d(out_chans, out_chans, 1),
            LayerNorm(out_chans, eps=1e-6, data_format="channels_first"),
            nn.GELU()
        )
        
    def forward(self, x):
        # Process each channel separately
        channel_features = []
        for i, conv in enumerate(self.channel_convs):
            channel_features.append(conv(x[:, i:i+1]))
        
        # Concatenate and fuse
        features = torch.cat(channel_features, dim=1)
        return self.fusion(features)


# ==================== CẢI TIẾN 4: MAGNIFICATION-AWARE HEAD ====================

class MagnificationAwareHead(nn.Module):
    """
    Classification Head nhận biết độ phóng đại
    
    BreakHis có 4 magnifications: 40X, 100X, 200X, 400X
    """
    def __init__(self, in_channels, num_classes=2, use_magnification=False, dropout=0.5):
        super().__init__()
        self.use_magnification = use_magnification
        
        # Global Average Pooling
        self.gap = nn.AdaptiveAvgPool2d(1)
        
        # Texture attention
        self.texture_att = TextureAttention(in_channels)
        
        # Magnification embedding (optional)
        if use_magnification:
            self.mag_embedding = nn.Embedding(4, 64)  # 4 magnifications
            classifier_in = in_channels + 64
        else:
            classifier_in = in_channels
        
        # Classifier
        self.classifier = nn.Sequential(
            nn.Linear(classifier_in, 1024),
            nn.BatchNorm1d(1024),
            nn.ReLU(inplace=True),
            nn.Dropout(dropout),
            
            nn.Linear(1024, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(inplace=True),
            nn.Dropout(dropout),
            
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(inplace=True),
            nn.Dropout(dropout / 2),
            
            nn.Linear(256, num_classes)
        )
        
    def forward(self, x, magnification=None):
        # Apply texture attention
        x = self.texture_att(x)
        
        # Global pooling
        features = self.gap(x).flatten(1)
        
        # Add magnification info if available
        if self.use_magnification and magnification is not None:
            mag_emb = self.mag_embedding(magnification)
            features = torch.cat([features, mag_emb], dim=1)
        
        # Classify
        return self.classifier(features)


# ==================== MAIN MODEL ====================

class ConvNeXtBreakHis(nn.Module):
    """
    ConvNeXt for BreakHis Dataset
    
    Optimizations for histopathology images:
    1. Color-aware stem for H&E staining
    2. Texture attention modules
    3. Multi-scale texture extraction
    4. Magnification-aware classification
    """
    def __init__(self, in_chans=3, num_classes=2, 
                 depths=[3, 3, 9, 3], dims=[96, 192, 384, 768], 
                 drop_path_rate=0.2, layer_scale_init_value=1e-6,
                 use_color_stem=True, use_texture_attention=True,
                 use_multiscale_texture=True, use_magnification=False):
        super().__init__()
        
        self.use_texture_attention = use_texture_attention
        self.use_multiscale_texture = use_multiscale_texture
        self.use_magnification = use_magnification

        # Stem
        self.downsample_layers = nn.ModuleList()
        if use_color_stem:
            stem = ColorAwareStem(in_chans, dims[0])
        else:
            stem = nn.Sequential(
                nn.Conv2d(in_chans, dims[0], kernel_size=4, stride=4),
                LayerNorm(dims[0], eps=1e-6, data_format="channels_first")
            )
        self.downsample_layers.append(stem)
        
        # Downsampling layers
        for i in range(3):
            downsample_layer = nn.Sequential(
                LayerNorm(dims[i], eps=1e-6, data_format="channels_first"),
                nn.Conv2d(dims[i], dims[i+1], kernel_size=2, stride=2),
            )
            self.downsample_layers.append(downsample_layer)

        # Stages
        self.stages = nn.ModuleList()
        dp_rates = [x.item() for x in torch.linspace(0, drop_path_rate, sum(depths))] 
        cur = 0
        for i in range(4):
            stage = nn.Sequential(
                *[Block(dim=dims[i], drop_path=dp_rates[cur + j], 
                       layer_scale_init_value=layer_scale_init_value) 
                  for j in range(depths[i])]
            )
            self.stages.append(stage)
            cur += depths[i]
        
        # Texture Attention sau mỗi stage
        if use_texture_attention:
            self.texture_attentions = nn.ModuleList([
                TextureAttention(dim) for dim in dims
            ])
        
        # Multi-scale Texture Blocks
        if use_multiscale_texture:
            self.texture_blocks = nn.ModuleList([
                MultiScaleTextureBlock(dim) for dim in dims
            ])
        
        # Classification Head
        self.head = MagnificationAwareHead(
            dims[-1], 
            num_classes=num_classes,
            use_magnification=use_magnification,
            dropout=0.5
        )

        self.apply(self._init_weights)

    def _init_weights(self, m):
        if isinstance(m, (nn.Conv2d, nn.Linear)):
            trunc_normal_(m.weight, std=.02)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)

    def forward(self, x, magnification=None):
        for i in range(4):
            x = self.downsample_layers[i](x)
            x = self.stages[i](x)
            
            # Apply texture attention
            if self.use_texture_attention:
                x = self.texture_attentions[i](x)
            
            # Apply multi-scale texture extraction
            if self.use_multiscale_texture:
                texture_feat = self.texture_blocks[i](x)
                x = x + texture_feat  # Residual connection
        
        # Classification
        return self.head(x, magnification)


# ==================== LOSS FUNCTIONS ====================

class LabelSmoothingCrossEntropy(nn.Module):
    """Label Smoothing cho histopathology"""
    def __init__(self, smoothing=0.1):
        super().__init__()
        self.smoothing = smoothing
        self.confidence = 1.0 - smoothing

    def forward(self, pred, target):
        logprobs = F.log_softmax(pred, dim=-1)
        nll_loss = -logprobs.gather(dim=-1, index=target.unsqueeze(1))
        nll_loss = nll_loss.squeeze(1)
        smooth_loss = -logprobs.mean(dim=-1)
        loss = self.confidence * nll_loss + self.smoothing * smooth_loss
        return loss.mean()


def mixup_data(x, y, alpha=0.2):
    """Mixup augmentation cho BreakHis"""
    if alpha > 0:
        lam = torch.distributions.Beta(alpha, alpha).sample()
    else:
        lam = 1

    batch_size = x.size()[0]
    index = torch.randperm(batch_size).to(x.device)

    mixed_x = lam * x + (1 - lam) * x[index]
    y_a, y_b = y, y[index]
    return mixed_x, y_a, y_b, lam


def mixup_criterion(criterion, pred, y_a, y_b, lam):
    """Loss cho mixup"""
    return lam * criterion(pred, y_a) + (1 - lam) * criterion(pred, y_b)


# ==================== HELPER FUNCTIONS ====================

def convnext_breakhis_tiny(num_classes=2, pretrained=False, **kwargs):
    """ConvNeXt for BreakHis - Tiny version"""
    model = ConvNeXtBreakHis(
        depths=[3, 3, 9, 3], 
        dims=[96, 192, 384, 768],
        num_classes=num_classes,
        drop_path_rate=0.2,
        **kwargs
    )
    
    if pretrained:
        try:
            import timm
            pretrained_model = timm.create_model('convnext_tiny', pretrained=True)
            pretrained_dict = pretrained_model.state_dict()
            model_dict = model.state_dict()
            
            # Load backbone (skip stem nếu dùng ColorAwareStem)
            if kwargs.get('use_color_stem', True):
                pretrained_dict = {k: v for k, v in pretrained_dict.items() 
                                 if k in model_dict and 'head' not in k 
                                 and 'downsample_layers.0' not in k}
            else:
                pretrained_dict = {k: v for k, v in pretrained_dict.items() 
                                 if k in model_dict and 'head' not in k}
            
            model_dict.update(pretrained_dict)
            model.load_state_dict(model_dict, strict=False)
            print("✓ Loaded pretrained ImageNet weights")
        except Exception as e:
            print(f"⚠ Could not load pretrained weights: {e}")
    
    return model


