import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
import timm
from typing import Optional
import numpy as np

# ============================================
# 1. ATTENTION MODULES (Thêm vào ConvNeXt)
# ============================================

class ChannelAttention(nn.Module):
    """Channel Attention từ CBAM"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        
        self.fc = nn.Sequential(
            nn.Conv2d(channels, channels // reduction, 1, bias=False),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 1, bias=False)
        )
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = self.fc(self.avg_pool(x))
        max_out = self.fc(self.max_pool(x))
        out = self.sigmoid(avg_out + max_out)
        return x * out

class SpatialAttention(nn.Module):
    """Spatial Attention từ CBAM"""
    def __init__(self, kernel_size=7):
        super().__init__()
        self.conv = nn.Conv2d(2, 1, kernel_size, padding=kernel_size//2, bias=False)
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        out = torch.cat([avg_out, max_out], dim=1)
        out = self.sigmoid(self.conv(out))
        return x * out

class CBAM(nn.Module):
    """Convolutional Block Attention Module"""
    def __init__(self, channels, reduction=16, kernel_size=7):
        super().__init__()
        self.ca = ChannelAttention(channels, reduction)
        self.sa = SpatialAttention(kernel_size)
    
    def forward(self, x):
        x = self.ca(x)
        x = self.sa(x)
        return x

class SEBlock(nn.Module):
    """Squeeze-and-Excitation Block"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.squeeze = nn.AdaptiveAvgPool2d(1)
        self.excitation = nn.Sequential(
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False),
            nn.Sigmoid()
        )
    
    def forward(self, x):
        b, c, _, _ = x.size()
        y = self.squeeze(x).view(b, c)
        y = self.excitation(y).view(b, c, 1, 1)
        return x * y.expand_as(x)

# ============================================
# 2. MODIFIED CONVNEXT BLOCK (Cải tiến)
# ============================================

class MedicalConvNeXtBlock(nn.Module):
    """
    ConvNeXt Block được cải tiến cho Medical Imaging
    Thêm: CBAM/SE attention + Stochastic Depth
    """
    def __init__(
        self, 
        dim, 
        drop_path=0., 
        layer_scale_init_value=1e-6,
        attention_type='cbam'  # 'cbam', 'se', hoặc None
    ):
        super().__init__()
        
        # Kiến trúc ConvNeXt gốc
        self.dwconv = nn.Conv2d(dim, dim, kernel_size=7, padding=3, groups=dim)  # Depthwise
        self.norm = nn.LayerNorm(dim, eps=1e-6)
        self.pwconv1 = nn.Linear(dim, 4 * dim)  # 1x1 conv, expansion 4x
        self.act = nn.GELU()
        self.pwconv2 = nn.Linear(4 * dim, dim)  # 1x1 conv, projection
        
        # Layer Scale (từ paper gốc)
        self.gamma = nn.Parameter(
            layer_scale_init_value * torch.ones((dim)), 
            requires_grad=True
        ) if layer_scale_init_value > 0 else None
        
        # Stochastic Depth
        self.drop_path = DropPath(drop_path) if drop_path > 0. else nn.Identity()
        
        # ✨ THÊM MỚI: Attention module
        if attention_type == 'cbam':
            self.attention = CBAM(dim)
        elif attention_type == 'se':
            self.attention = SEBlock(dim)
        else:
            self.attention = nn.Identity()
    
    def forward(self, x):
        input = x
        
        # Depthwise Convolution
        x = self.dwconv(x)
        
        # Permute để dùng LayerNorm
        x = x.permute(0, 2, 3, 1)  # (N, C, H, W) -> (N, H, W, C)
        x = self.norm(x)
        
        # Inverted Bottleneck
        x = self.pwconv1(x)
        x = self.act(x)
        x = self.pwconv2(x)
        
        # Layer Scale
        if self.gamma is not None:
            x = self.gamma * x
        
        # Permute trở lại
        x = x.permute(0, 3, 1, 2)  # (N, H, W, C) -> (N, C, H, W)
        
        # ✨ THÊM MỚI: Apply attention
        x = self.attention(x)
        
        # Residual Connection + Stochastic Depth
        x = input + self.drop_path(x)
        return x

class DropPath(nn.Module):
    """Stochastic Depth (Drop Path) cho regularization"""
    def __init__(self, drop_prob=0.):
        super().__init__()
        self.drop_prob = drop_prob
    
    def forward(self, x):
        if self.drop_prob == 0. or not self.training:
            return x
        keep_prob = 1 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)
        random_tensor.floor_()
        output = x.div(keep_prob) * random_tensor
        return output

# ============================================
# 3. MEDICAL CONVNEXT MODEL (Model hoàn chỉnh)
# ============================================

class MedicalConvNeXt(nn.Module):
    """
    ConvNeXt được tối ưu hóa cho Medical Image Classification
    """
    def __init__(
        self,
        num_classes=2,  # Benign vs Malignant
        depths=[3, 3, 9, 3],  # Số blocks mỗi stage
        dims=[96, 192, 384, 768],  # Channels mỗi stage
        drop_path_rate=0.4,
        attention_stages=[True, True, True, True],  # Stage nào dùng attention
        pretrained=True
    ):
        super().__init__()
        
        # Load pretrained ConvNeXt từ timm
        if pretrained:
            self.backbone = timm.create_model(
                'convnext_tiny', 
                pretrained=True,
                num_classes=0  # Không lấy classification head
            )
            # Freeze early layers nếu muốn
            # for param in list(self.backbone.parameters())[:20]:
            #     param.requires_grad = False
        else:
            raise NotImplementedError("Implement from scratch nếu cần")
        
        # ✨ THÊM MỚI: Multi-scale Feature Fusion
        self.lateral_convs = nn.ModuleList([
            nn.Conv2d(dims[i], 256, 1) for i in range(len(dims))
        ])
        
        # ✨ THÊM MỚI: Medical Classification Head
        # Thay vì chỉ 1 FC layer, dùng multi-layer với regularization
        final_dim = dims[-1]  # 768 cho tiny
        
        self.head = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            nn.Dropout(0.5),
            
            nn.Linear(final_dim, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(inplace=True),
            nn.Dropout(0.3),
            
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(inplace=True),
            nn.Dropout(0.2),
            
            nn.Linear(256, num_classes)
        )
        
        # Initialize weights
        self._init_head()
    
    def _init_head(self):
        """Initialize classification head"""
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                nn.init.trunc_normal_(m.weight, std=0.02)
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
    
    def forward(self, x):
        # Extract features từ backbone
        features = self.backbone.forward_features(x)
        
        # Classification
        out = self.head(features)
        return out

# ============================================
# 4. DATA AUGMENTATION CHO Y TẾ
# ============================================

def get_medical_transforms(image_size=224, is_training=True):
    """
    Augmentation đặc biệt cho ảnh y tế
    """
    if is_training:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandomVerticalFlip(p=0.5),
            transforms.RandomRotation(20),
            
            # ✨ Medical-specific augmentations
            transforms.ColorJitter(brightness=0.2, contrast=0.2),
            transforms.RandomAffine(
                degrees=0,
                translate=(0.1, 0.1),
                scale=(0.9, 1.1),
                shear=10
            ),
            
            # Elastic deformation có thể thêm bằng albumentations
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            ),
            
            # Random erasing để simulate artifacts
            transforms.RandomErasing(p=0.2, scale=(0.02, 0.1))
        ])
    else:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            )
        ])

# ============================================
# 5. DATASET CLASS
# ============================================

class BreastCancerDataset(Dataset):
    """
    Dataset cho ảnh ung thư vú
    Giả sử cấu trúc: data/train/benign/, data/train/malignant/
    """
    def __init__(self, image_paths, labels, transform=None):
        self.image_paths = image_paths
        self.labels = labels
        self.transform = transform
    
    def __len__(self):
        return len(self.image_paths)
    
    def __getitem__(self, idx):
        from PIL import Image
        
        # Load image
        img = Image.open(self.image_paths[idx]).convert('RGB')
        label = self.labels[idx]
        
        if self.transform:
            img = self.transform(img)
        
        return img, label

# ============================================
# 6. TRAINING FUNCTION
# ============================================

def train_one_epoch(model, dataloader, criterion, optimizer, device, epoch):
    """Train cho 1 epoch"""
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    
    for batch_idx, (images, labels) in enumerate(dataloader):
        images, labels = images.to(device), labels.to(device)
        
        # Forward
        optimizer.zero_grad()
        outputs = model(images)
        loss = criterion(outputs, labels)
        
        # Backward
        loss.backward()
        optimizer.step()
        
        # Statistics
        running_loss += loss.item()
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        if batch_idx % 10 == 0:
            print(f'Epoch: {epoch} | Batch: {batch_idx}/{len(dataloader)} | '
                  f'Loss: {loss.item():.4f} | Acc: {100.*correct/total:.2f}%')
    
    epoch_loss = running_loss / len(dataloader)
    epoch_acc = 100. * correct / total
    return epoch_loss, epoch_acc

def validate(model, dataloader, criterion, device):
    """Validation"""
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    
    all_preds = []
    all_labels = []
    
    with torch.no_grad():
        for images, labels in dataloader:
            images, labels = images.to(device), labels.to(device)
            
            outputs = model(images)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item()
            _, predicted = outputs.max(1)
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
    
    val_loss = running_loss / len(dataloader)
    val_acc = 100. * correct / total
    
    return val_loss, val_acc, all_preds, all_labels

# ============================================
# 7. MAIN TRAINING SCRIPT
# ============================================

def main():
    # ==================== CONFIG ====================
    CONFIG = {
        'num_classes': 2,
        'image_size': 224,
        'batch_size': 16,
        'num_epochs': 50,
        'learning_rate': 1e-4,
        'weight_decay': 1e-5,
        'device': 'cuda' if torch.cuda.is_available() else 'cpu',
        'num_workers': 4,
    }
    
    print(f"Using device: {CONFIG['device']}")
    
    # ==================== DATA ====================
    # TODO: Thay đổi theo dataset thực tế của bạn
    # Ví dụ cấu trúc dữ liệu:
    from pathlib import Path
    import glob
    
    data_dir = Path('data/breast_cancer')  # Thay đổi path
    
    # Lấy đường dẫn ảnh
    benign_images = glob.glob(str(data_dir / 'train/benign/*.png'))
    malignant_images = glob.glob(str(data_dir / 'train/malignant/*.png'))
    
    train_paths = benign_images + malignant_images
    train_labels = [0] * len(benign_images) + [1] * len(malignant_images)
    
    # Tương tự cho validation
    benign_val = glob.glob(str(data_dir / 'val/benign/*.png'))
    malignant_val = glob.glob(str(data_dir / 'val/malignant/*.png'))
    
    val_paths = benign_val + malignant_val
    val_labels = [0] * len(benign_val) + [1] * len(malignant_val)
    
    # Transforms
    train_transform = get_medical_transforms(CONFIG['image_size'], is_training=True)
    val_transform = get_medical_transforms(CONFIG['image_size'], is_training=False)
    
    # Datasets
    train_dataset = BreastCancerDataset(train_paths, train_labels, train_transform)
    val_dataset = BreastCancerDataset(val_paths, val_labels, val_transform)
    
    # DataLoaders
    train_loader = DataLoader(
        train_dataset,
        batch_size=CONFIG['batch_size'],
        shuffle=True,
        num_workers=CONFIG['num_workers'],
        pin_memory=True
    )
    
    val_loader = DataLoader(
        val_dataset,
        batch_size=CONFIG['batch_size'],
        shuffle=False,
        num_workers=CONFIG['num_workers'],
        pin_memory=True
    )
    
    print(f"Train samples: {len(train_dataset)}, Val samples: {len(val_dataset)}")
    
    # ==================== MODEL ====================
    model = MedicalConvNeXt(
        num_classes=CONFIG['num_classes'],
        pretrained=True
    ).to(CONFIG['device'])
    
    print(f"Model parameters: {sum(p.numel() for p in model.parameters())/1e6:.2f}M")
    
    # ==================== LOSS & OPTIMIZER ====================
    # Focal Loss cho imbalanced data (option)
    criterion = nn.CrossEntropyLoss()
    
    # AdamW optimizer
    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=CONFIG['learning_rate'],
        weight_decay=CONFIG['weight_decay']
    )
    
    # Learning rate scheduler
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
        optimizer,
        T_max=CONFIG['num_epochs'],
        eta_min=1e-6
    )
    
    # ==================== TRAINING LOOP ====================
    best_val_acc = 0.0
    
    for epoch in range(CONFIG['num_epochs']):
        print(f"\n{'='*50}")
        print(f"Epoch {epoch+1}/{CONFIG['num_epochs']}")
        print(f"{'='*50}")
        
        # Train
        train_loss, train_acc = train_one_epoch(
            model, train_loader, criterion, optimizer, CONFIG['device'], epoch+1
        )
        
        # Validate
        val_loss, val_acc, val_preds, val_labels = validate(
            model, val_loader, criterion, CONFIG['device']
        )
        
        # Learning rate update
        scheduler.step()
        
        print(f"\nEpoch {epoch+1} Summary:")
        print(f"Train Loss: {train_loss:.4f} | Train Acc: {train_acc:.2f}%")
        print(f"Val Loss: {val_loss:.4f} | Val Acc: {val_acc:.2f}%")
        print(f"LR: {optimizer.param_groups[0]['lr']:.6f}")
        
        # Save best model
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            torch.save({
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'val_acc': val_acc,
            }, 'best_model.pth')
            print(f"✅ Saved best model with Val Acc: {val_acc:.2f}%")
        
        # Compute metrics
        from sklearn.metrics import classification_report, confusion_matrix
        if epoch % 5 == 0:  # Mỗi 5 epochs
            print("\nClassification Report:")
            print(classification_report(val_labels, val_preds, 
                                       target_names=['Benign', 'Malignant']))
            print("\nConfusion Matrix:")
            print(confusion_matrix(val_labels, val_preds))
    
    print(f"\n{'='*50}")
    print(f"Training completed! Best Val Acc: {best_val_acc:.2f}%")
    print(f"{'='*50}")

if __name__ == '__main__':
    main()
