import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader
from torchvision import datasets, transforms
import torch.nn.functional as F
from timm.models.layers import trunc_normal_, DropPath
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import confusion_matrix, recall_score, classification_report
import numpy as np

# ==================== ConvNeXt Architecture ====================

class Block(nn.Module):
    """ConvNeXt Block"""
    def __init__(self, dim, drop_path=0., layer_scale_init_value=1e-6):
        super().__init__()
        self.dwconv = nn.Conv2d(dim, dim, kernel_size=7, padding=3, groups=dim)
        self.norm = LayerNorm(dim, eps=1e-6)
        self.pwconv1 = nn.Linear(dim, 4 * dim)
        self.act = nn.GELU()
        self.pwconv2 = nn.Linear(4 * dim, dim)
        self.gamma = nn.Parameter(layer_scale_init_value * torch.ones((dim)), 
                                    requires_grad=True) if layer_scale_init_value > 0 else None
        self.drop_path = DropPath(drop_path) if drop_path > 0. else nn.Identity()

    def forward(self, x):
        input = x
        x = self.dwconv(x)
        x = x.permute(0, 2, 3, 1)
        x = self.norm(x)
        x = self.pwconv1(x)
        x = self.act(x)
        x = self.pwconv2(x)
        if self.gamma is not None:
            x = self.gamma * x
        x = x.permute(0, 3, 1, 2)
        x = input + self.drop_path(x)
        return x


class LayerNorm(nn.Module):
    """LayerNorm hỗ trợ channels_last và channels_first"""
    def __init__(self, normalized_shape, eps=1e-6, data_format="channels_last"):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = eps
        self.data_format = data_format
        self.normalized_shape = (normalized_shape, )
    
    def forward(self, x):
        if self.data_format == "channels_last":
            return F.layer_norm(x, self.normalized_shape, self.weight, self.bias, self.eps)
        elif self.data_format == "channels_first":
            u = x.mean(1, keepdim=True)
            s = (x - u).pow(2).mean(1, keepdim=True)
            x = (x - u) / torch.sqrt(s + self.eps)
            x = self.weight[:, None, None] * x + self.bias[:, None, None]
            return x


class ConvNeXt(nn.Module):
    """ConvNeXt Model"""
    def __init__(self, in_chans=3, num_classes=1000, 
                 depths=[3, 3, 9, 3], dims=[96, 192, 384, 768], 
                 drop_path_rate=0., layer_scale_init_value=1e-6, 
                 head_init_scale=1.):
        super().__init__()

        self.downsample_layers = nn.ModuleList()
        stem = nn.Sequential(
            nn.Conv2d(in_chans, dims[0], kernel_size=4, stride=4),
            LayerNorm(dims[0], eps=1e-6, data_format="channels_first")
        )
        self.downsample_layers.append(stem)
        
        for i in range(3):
            downsample_layer = nn.Sequential(
                    LayerNorm(dims[i], eps=1e-6, data_format="channels_first"),
                    nn.Conv2d(dims[i], dims[i+1], kernel_size=2, stride=2),
            )
            self.downsample_layers.append(downsample_layer)

        self.stages = nn.ModuleList()
        dp_rates=[x.item() for x in torch.linspace(0, drop_path_rate, sum(depths))] 
        cur = 0
        for i in range(4):
            stage = nn.Sequential(
                *[Block(dim=dims[i], drop_path=dp_rates[cur + j], 
                layer_scale_init_value=layer_scale_init_value) for j in range(depths[i])]
            )
            self.stages.append(stage)
            cur += depths[i]

        self.norm = nn.LayerNorm(dims[-1], eps=1e-6)
        self.head = nn.Linear(dims[-1], num_classes)

        self.apply(self._init_weights)
        self.head.weight.data.mul_(head_init_scale)
        self.head.bias.data.mul_(head_init_scale)

    def _init_weights(self, m):
        if isinstance(m, (nn.Conv2d, nn.Linear)):
            trunc_normal_(m.weight, std=.02)
            nn.init.constant_(m.bias, 0)

    def forward_features(self, x):
        for i in range(4):
            x = self.downsample_layers[i](x)
            x = self.stages[i](x)
        return self.norm(x.mean([-2, -1]))

    def forward(self, x):
        x = self.forward_features(x)
        x = self.head(x)
        return x


def convnext_tiny(num_classes=1000, drop_path_rate=0.):
    """ConvNeXt-Tiny: depths=[3,3,9,3], dims=[96,192,384,768]"""
    model = ConvNeXt(depths=[3, 3, 9, 3], dims=[96, 192, 384, 768], 
                     num_classes=num_classes, drop_path_rate=drop_path_rate)
    return model


# ==================== Training Code ====================

def get_dataloaders(data_dir, batch_size=32, img_size=224):
    """
    Load data từ thư mục.
    Yêu cầu cấu trúc: data_dir/train/ và data_dir/val/
    """
    import os
    
    # Data augmentation mạnh hơn cho medical images
    train_transform = transforms.Compose([
        transforms.Resize((img_size, img_size)),
        transforms.RandomHorizontalFlip(p=0.5),
        transforms.RandomVerticalFlip(p=0.5),
        transforms.RandomRotation(degrees=20),
        transforms.ColorJitter(brightness=0.2, contrast=0.2, saturation=0.2, hue=0.1),
        transforms.RandomAffine(degrees=0, translate=(0.1, 0.1), scale=(0.9, 1.1)),
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.485, 0.456, 0.406], 
                           std=[0.229, 0.224, 0.225])
    ])
    
    val_transform = transforms.Compose([
        transforms.Resize((img_size, img_size)),
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.485, 0.456, 0.406], 
                           std=[0.229, 0.224, 0.225])
    ])
    
    # Load train và val
    train_path = os.path.join(data_dir, 'train')
    val_path = os.path.join(data_dir, 'validation')
    
    if not os.path.exists(train_path):
        raise FileNotFoundError(f"Không tìm thấy thư mục: {train_path}")
    if not os.path.exists(val_path):
        raise FileNotFoundError(f"Không tìm thấy thư mục: {val_path}")
    
    print(f"✓ Loading data from {data_dir}")
    train_dataset = datasets.ImageFolder(train_path, transform=train_transform)
    val_dataset = datasets.ImageFolder(val_path, transform=val_transform)
    
    train_loader = DataLoader(train_dataset, batch_size=batch_size, 
                            shuffle=True, num_workers=4, pin_memory=True)
    val_loader = DataLoader(val_dataset, batch_size=batch_size, 
                          shuffle=False, num_workers=4, pin_memory=True)
    
    class_names = train_dataset.classes
    num_classes = len(class_names)
    
    print(f"✓ Train samples: {len(train_dataset)}")
    print(f"✓ Val samples: {len(val_dataset)}")
    print(f"✓ Classes: {class_names}")
    
    return train_loader, val_loader, num_classes, class_names


def train_epoch(model, dataloader, criterion, optimizer, device):
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    
    for inputs, labels in dataloader:
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()
        
        running_loss += loss.item() * inputs.size(0)
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        all_preds.extend(predicted.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())
    
    epoch_loss = running_loss / total
    epoch_acc = 100. * correct / total
    
    # Tính recall (macro average) cho train
    recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    
    return epoch_loss, epoch_acc, recall


def validate(model, dataloader, criterion, device):
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    
    with torch.no_grad():
        for inputs, labels in dataloader:
            inputs, labels = inputs.to(device), labels.to(device)
            outputs = model(inputs)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item() * inputs.size(0)
            _, predicted = outputs.max(1)
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
    
    epoch_loss = running_loss / total
    epoch_acc = 100. * correct / total
    
    # Tính recall (macro average)
    recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    
    return epoch_loss, epoch_acc, recall, all_preds, all_labels


def plot_training_history(history, save_path='training_history.png'):
    """Vẽ biểu đồ Loss, Accuracy và Recall"""
    fig, axes = plt.subplots(2, 2, figsize=(15, 10))
    
    epochs = range(1, len(history['train_loss']) + 1)
    
    # Plot Loss
    axes[0, 0].plot(epochs, history['train_loss'], 'b-', label='Train Loss', linewidth=2)
    axes[0, 0].plot(epochs, history['val_loss'], 'r-', label='Val Loss', linewidth=2)
    axes[0, 0].set_xlabel('Epoch', fontsize=12)
    axes[0, 0].set_ylabel('Loss', fontsize=12)
    axes[0, 0].set_title('Training and Validation Loss', fontsize=14, fontweight='bold')
    axes[0, 0].legend(fontsize=10)
    axes[0, 0].grid(True, alpha=0.3)
    
    # Plot Accuracy
    axes[0, 1].plot(epochs, history['train_acc'], 'b-', label='Train Accuracy', linewidth=2)
    axes[0, 1].plot(epochs, history['val_acc'], 'r-', label='Val Accuracy', linewidth=2)
    axes[0, 1].set_xlabel('Epoch', fontsize=12)
    axes[0, 1].set_ylabel('Accuracy (%)', fontsize=12)
    axes[0, 1].set_title('Training and Validation Accuracy', fontsize=14, fontweight='bold')
    axes[0, 1].legend(fontsize=10)
    axes[0, 1].grid(True, alpha=0.3)
    
    # Plot Recall
    axes[1, 0].plot(epochs, history['train_recall'], 'b-', label='Train Recall', linewidth=2)
    axes[1, 0].plot(epochs, history['val_recall'], 'r-', label='Val Recall', linewidth=2)
    axes[1, 0].set_xlabel('Epoch', fontsize=12)
    axes[1, 0].set_ylabel('Recall (Macro)', fontsize=12)
    axes[1, 0].set_title('Training and Validation Recall', fontsize=14, fontweight='bold')
    axes[1, 0].legend(fontsize=10)
    axes[1, 0].grid(True, alpha=0.3)
    
    # Plot Learning Rate
    axes[1, 1].plot(epochs, history['lr'], 'purple', label='Learning Rate', linewidth=2)
    axes[1, 1].set_xlabel('Epoch', fontsize=12)
    axes[1, 1].set_ylabel('Learning Rate', fontsize=12)
    axes[1, 1].set_title('Learning Rate Schedule', fontsize=14, fontweight='bold')
    axes[1, 1].legend(fontsize=10)
    axes[1, 1].grid(True, alpha=0.3)
    axes[1, 1].set_yscale('log')
    
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    print(f"✓ Saved training history to {save_path}")
    plt.close()


def plot_confusion_matrix(y_true, y_pred, class_names, save_path='confusion_matrix.png'):
    """Vẽ ma trận nhầm lẫn (Confusion Matrix)"""
    cm = confusion_matrix(y_true, y_pred)
    
    plt.figure(figsize=(12, 10))
    sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', 
                xticklabels=class_names, yticklabels=class_names,
                cbar_kws={'label': 'Count'})
    plt.xlabel('Predicted Label', fontsize=12, fontweight='bold')
    plt.ylabel('True Label', fontsize=12, fontweight='bold')
    plt.title('Confusion Matrix', fontsize=14, fontweight='bold')
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    print(f"✓ Saved confusion matrix to {save_path}")
    plt.close()


def print_classification_report(y_true, y_pred, class_names):
    """In báo cáo phân loại chi tiết"""
    print("\n" + "="*70)
    print("CLASSIFICATION REPORT")
    print("="*70)
    print(classification_report(y_true, y_pred, target_names=class_names, digits=4))
    print("="*70)


class EarlyStopping:
    """Early Stopping để ngăn overfitting"""
    def __init__(self, patience=10, min_delta=0, verbose=True):
        self.patience = patience
        self.min_delta = min_delta
        self.verbose = verbose
        self.counter = 0
        self.best_score = None
        self.early_stop = False
        self.val_acc_max = 0
        
    def __call__(self, val_acc):
        score = val_acc
        
        if self.best_score is None:
            self.best_score = score
            self.val_acc_max = val_acc
        elif score < self.best_score + self.min_delta:
            self.counter += 1
            if self.verbose:
                print(f"EarlyStopping counter: {self.counter}/{self.patience}")
            if self.counter >= self.patience:
                self.early_stop = True
        else:
            self.best_score = score
            self.val_acc_max = val_acc
            self.counter = 0


def train_convnext_tiny(data_dir, num_epochs=100, batch_size=32, 
                        lr=1e-4, drop_path_rate=0.0, early_stopping_patience=15,
                        pretrained=False):
    """Train ConvNeXt-Tiny với visualization đầy đủ và early stopping"""
    
    device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
    print(f"Using device: {device}")
    
    # Load data
    train_loader, val_loader, num_classes, class_names = get_dataloaders(
        data_dir, batch_size
    )
    print(f"Number of classes: {num_classes}")
    print(f"Classes: {class_names}")
    
    # Create model
    model = convnext_tiny(num_classes=num_classes, drop_path_rate=drop_path_rate)
    
    # Load pretrained weights nếu cần
    if pretrained:
        try:
            import timm
            pretrained_model = timm.create_model('convnext_tiny', pretrained=True)
            # Copy weights trừ classification head
            pretrained_dict = pretrained_model.state_dict()
            model_dict = model.state_dict()
            
            # Lọc bỏ các layer của head
            pretrained_dict = {k: v for k, v in pretrained_dict.items() 
                             if k in model_dict and 'head' not in k}
            model_dict.update(pretrained_dict)
            model.load_state_dict(model_dict)
            print("✓ Loaded pretrained ImageNet weights (except head)")
        except Exception as e:
            print(f"⚠ Could not load pretrained weights: {e}")
    
    model = model.to(device)
    
    num_params = sum(p.numel() for p in model.parameters())
    print(f"Model: ConvNeXt-Tiny")
    print(f"Number of parameters: {num_params:,}")
    
    # Loss và optimizer
    criterion = nn.CrossEntropyLoss(label_smoothing=0.1)  # Label smoothing giúp tránh overconfident
    
    # Separate learning rates cho backbone và head
    if pretrained:
        backbone_params = [p for n, p in model.named_parameters() if 'head' not in n]
        head_params = [p for n, p in model.named_parameters() if 'head' in n]
        optimizer = optim.AdamW([
            {'params': backbone_params, 'lr': lr * 0.1},  # LR thấp hơn cho pretrained weights
            {'params': head_params, 'lr': lr}
        ], weight_decay=0.05)
    else:
        optimizer = optim.AdamW(model.parameters(), lr=lr, weight_decay=0.05)
    
    # Warmup + Cosine scheduler
    warmup_epochs = 5
    scheduler_cosine = optim.lr_scheduler.CosineAnnealingLR(
        optimizer, T_max=num_epochs - warmup_epochs
    )
    
    # Warm up scheduler
    def warmup_lr_scheduler(epoch):
        if epoch < warmup_epochs:
            return (epoch + 1) / warmup_epochs
        else:
            return 1.0
    
    scheduler_warmup = optim.lr_scheduler.LambdaLR(optimizer, lr_lambda=warmup_lr_scheduler)
    
    # Early stopping
    early_stopping = EarlyStopping(patience=early_stopping_patience, min_delta=0.01, verbose=True)
    
    # History để vẽ biểu đồ
    history = {
        'train_loss': [],
        'train_acc': [],
        'train_recall': [],
        'val_loss': [],
        'val_acc': [],
        'val_recall': [],
        'lr': []
    }
    
    best_val_acc = 0.0
    
    # Training loop
    print("\n" + "="*70)
    print("TRAINING START")
    print("="*70)
    
    for epoch in range(num_epochs):
        print(f"\nEpoch {epoch+1}/{num_epochs}")
        print("-" * 70)
        
        # Train
        train_loss, train_acc, train_recall = train_epoch(model, train_loader, criterion, optimizer, device)
        
        # Validate
        val_loss, val_acc, val_recall, val_preds, val_labels = validate(
            model, val_loader, criterion, device
        )
        
        # Update learning rate
        current_lr = optimizer.param_groups[0]['lr']
        if epoch < warmup_epochs:
            scheduler_warmup.step()
        else:
            scheduler_cosine.step()
        
        # Save history
        history['train_loss'].append(train_loss)
        history['train_acc'].append(train_acc)
        history['train_recall'].append(train_recall)
        history['val_loss'].append(val_loss)
        history['val_acc'].append(val_acc)
        history['val_recall'].append(val_recall)
        history['lr'].append(current_lr)
        
        print(f"Train Loss: {train_loss:.4f} | Train Acc: {train_acc:.2f}% | Train Recall: {train_recall:.4f}")
        print(f"Val Loss: {val_loss:.4f} | Val Acc: {val_acc:.2f}% | Val Recall: {val_recall:.4f}")
        print(f"Learning Rate: {current_lr:.6f}")
        
        # Save best model
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            best_preds = val_preds
            best_labels = val_labels
            
            torch.save({
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'val_acc': val_acc,
                'num_classes': num_classes,
                'class_names': class_names,
            }, 'best_convnext_tiny_original.pth')
            print(f"✓ Saved best model with val_acc: {val_acc:.2f}%")
        
        # Early stopping check
        early_stopping(val_acc)
        if early_stopping.early_stop:
            print(f"\n⚠ Early stopping triggered at epoch {epoch+1}")
            print(f"Best validation accuracy was: {early_stopping.val_acc_max:.2f}%")
            break
    
    print(f"\n{'='*70}")
    print(f"TRAINING COMPLETED!")
    print(f"Best validation accuracy: {best_val_acc:.2f}%")
    print(f"{'='*70}")
    
    # Vẽ các biểu đồ
    print("\nGenerating visualizations...")
    plot_training_history(history, save_path='training_history_original.png')
    plot_confusion_matrix(best_labels, best_preds, class_names, save_path='confusion_matrix_original.png')
    print_classification_report(best_labels, best_preds, class_names)
    
    return model, history


# ==================== Main ====================

if __name__ == "__main__":
    data_dir = "./train_data"  # Thư mục chứa train/ và val/
    
    # KHUYẾN NGHỊ: Dùng pretrained weights cho dataset nhỏ
    model, history = train_convnext_tiny(
        data_dir=data_dir,
        num_epochs=100,
        batch_size=16,  # Giảm batch size nếu dataset nhỏ
        lr=1e-4,  # Learning rate nhỏ cho pretrained
        drop_path_rate=0.0,  # Tắt regularization khi dataset nhỏ
        early_stopping_patience=5,
        pretrained=True  # BẬT PRETRAINED để transfer learning
    )
    
    print("\nAll visualizations saved:")
    print("  - training_history.png (Loss, Accuracy, Recall, LR)")
    print("  - confusion_matrix.png")
    print("  - best_convnext_tiny.pth")
