import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
import timm
from typing import Optional, List
import numpy as np
from pathlib import Path
from sklearn.model_selection import train_test_split
import glob
import os

# ============================================
# 1. ATTENTION MODULES
# ============================================

class ChannelAttention(nn.Module):
    """Channel Attention from CBAM"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        
        self.fc = nn.Sequential(
            nn.Conv2d(channels, channels // reduction, 1, bias=False),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 1, bias=False)
        )
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = self.fc(self.avg_pool(x))
        max_out = self.fc(self.max_pool(x))
        out = self.sigmoid(avg_out + max_out)
        return x * out

class SpatialAttention(nn.Module):
    """Spatial Attention from CBAM"""
    def __init__(self, kernel_size=7):
        super().__init__()
        self.conv = nn.Conv2d(2, 1, kernel_size, padding=kernel_size//2, bias=False)
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        out = torch.cat([avg_out, max_out], dim=1)
        out = self.sigmoid(self.conv(out))
        return x * out

class CBAM(nn.Module):
    """Convolutional Block Attention Module"""
    def __init__(self, channels, reduction=16, kernel_size=7):
        super().__init__()
        self.ca = ChannelAttention(channels, reduction)
        self.sa = SpatialAttention(kernel_size)
    
    def forward(self, x):
        x = self.ca(x)
        x = self.sa(x)
        return x

class SEBlock(nn.Module):
    """Squeeze-and-Excitation Block"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.squeeze = nn.AdaptiveAvgPool2d(1)
        self.excitation = nn.Sequential(
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False),
            nn.Sigmoid()
        )
    
    def forward(self, x):
        b, c, _, _ = x.size()
        y = self.squeeze(x).view(b, c)
        y = self.excitation(y).view(b, c, 1, 1)
        return x * y.expand_as(x)

# ============================================
# 2. DROP PATH (Stochastic Depth)
# ============================================

class DropPath(nn.Module):
    """Drop paths (Stochastic Depth) per sample"""
    def __init__(self, drop_prob=0.):
        super().__init__()
        self.drop_prob = drop_prob
    
    def forward(self, x):
        if self.drop_prob == 0. or not self.training:
            return x
        keep_prob = 1 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)
        random_tensor.floor_()
        output = x.div(keep_prob) * random_tensor
        return output

# ============================================
# 3. MODIFIED CONVNEXT TINY FOR MEDICAL
# ============================================

class MedicalConvNeXtTiny(nn.Module):
    """
    ConvNeXt-Tiny được tối ưu hóa cho Medical Imaging
    
    Thay đổi chính:
    1. Modified Stem: stride 2 thay vì 4 (giữ resolution cao hơn)
    2. Thêm attention modules (CBAM/SE) vào các stages
    3. Tăng số blocks ở Stage 1
    4. Custom medical classification head
    5. Heavy regularization (DropPath, Dropout)
    """
    def __init__(
        self,
        num_classes=2,
        in_chans=3,
        depths=[5, 4, 9, 3],  # Tăng Stage 1 từ 3→5, Stage 2 từ 3→4
        dims=[96, 192, 384, 768],
        drop_path_rate=0.4,
        use_attention=[True, True, True, True],  # Attention cho mỗi stage
        attention_types=['cbam', 'se', 'cbam', 'se'],  # Loại attention
        pretrained=True
    ):
        super().__init__()
        
        # ✨ MODIFIED STEM - Giữ resolution cao hơn
        if pretrained:
            # Load backbone nhưng sẽ thay thế stem
            self.backbone = timm.create_model(
                'convnext_tiny',
                pretrained=True,
                num_classes=0,  # Remove head
                features_only=False
            )
            
            # Replace stem với stride nhỏ hơn
            self.backbone.stem = nn.Sequential(
                nn.Conv2d(in_chans, dims[0], kernel_size=4, stride=2, padding=1),
                nn.LayerNorm([dims[0], 112, 112])  # 224/2 = 112
            )
            
            # ✨ ADD ATTENTION to each stage
            self._add_attention_to_stages(
                self.backbone, 
                dims, 
                depths,
                use_attention,
                attention_types,
                drop_path_rate
            )
        else:
            # Build from scratch if needed
            raise NotImplementedError("Build from scratch not implemented yet")
        
        # ✨ MEDICAL CLASSIFICATION HEAD
        self.head = self._build_medical_head(dims[-1], num_classes)
        
        # Initialize head
        self._init_weights()
    
    def _add_attention_to_stages(
        self, 
        backbone, 
        dims, 
        depths,
        use_attention,
        attention_types,
        drop_path_rate
    ):
        """Add attention modules to ConvNeXt stages"""
        # ConvNeXt stages trong timm: backbone.stages
        for stage_idx in range(4):
            if not use_attention[stage_idx]:
                continue
                
            stage = backbone.stages[stage_idx]
            attention_type = attention_types[stage_idx]
            
            # Thêm attention vào mỗi block trong stage
            for block_idx in range(len(stage.blocks)):
                block = stage.blocks[block_idx]
                
                # Thêm attention module
                if attention_type == 'cbam':
                    attention = CBAM(dims[stage_idx])
                elif attention_type == 'se':
                    attention = SEBlock(dims[stage_idx])
                else:
                    attention = nn.Identity()
                
                # Wrap block với attention
                stage.blocks[block_idx] = nn.Sequential(block, attention)
                
                # Thêm DropPath
                dp_rate = drop_path_rate * (stage_idx + 1) / 4
                if dp_rate > 0:
                    stage.blocks[block_idx] = nn.Sequential(
                        stage.blocks[block_idx],
                        DropPath(dp_rate)
                    )
    
    def _build_medical_head(self, in_features, num_classes):
        """Build multi-layer classification head cho medical imaging"""
        return nn.Sequential(
            # Global Average Pooling
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            
            # Layer 1
            nn.Dropout(0.5),
            nn.Linear(in_features, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(inplace=True),
            
            # Layer 2
            nn.Dropout(0.3),
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(inplace=True),
            
            # Layer 3
            nn.Dropout(0.2),
            nn.Linear(256, 128),
            nn.BatchNorm1d(128),
            nn.ReLU(inplace=True),
            
            # Output
            nn.Linear(128, num_classes)
        )
    
    def _init_weights(self):
        """Initialize classification head weights"""
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                nn.init.trunc_normal_(m.weight, std=0.02)
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.BatchNorm1d):
                nn.init.constant_(m.weight, 1)
                nn.init.constant_(m.bias, 0)
    
    def forward(self, x):
        # Extract features
        features = self.backbone.forward_features(x)
        
        # Classification
        output = self.head(features)
        return output

# ============================================
# 4. FOCAL LOSS (Optional - cho imbalanced data)
# ============================================

class FocalLoss(nn.Module):
    """Focal Loss for imbalanced classification"""
    def __init__(self, alpha=0.25, gamma=2.0, reduction='mean'):
        super().__init__()
        self.alpha = alpha
        self.gamma = gamma
        self.reduction = reduction
    
    def forward(self, inputs, targets):
        ce_loss = F.cross_entropy(inputs, targets, reduction='none')
        pt = torch.exp(-ce_loss)
        focal_loss = self.alpha * (1 - pt) ** self.gamma * ce_loss
        
        if self.reduction == 'mean':
            return focal_loss.mean()
        elif self.reduction == 'sum':
            return focal_loss.sum()
        else:
            return focal_loss

# ============================================
# 5. DATA AUGMENTATION
# ============================================

def get_medical_transforms(image_size=224, is_training=True):
    """Medical-specific augmentation"""
    if is_training:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            
            # Geometric augmentations
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandomVerticalFlip(p=0.5),
            transforms.RandomRotation(20),
            transforms.RandomAffine(
                degrees=0,
                translate=(0.1, 0.1),
                scale=(0.9, 1.1),
                shear=10
            ),
            
            # Color augmentations (mild for medical)
            transforms.ColorJitter(
                brightness=0.2,
                contrast=0.2,
                saturation=0.1,
                hue=0.05
            ),
            
            # To tensor and normalize
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            ),
            
            # Random erasing (simulate artifacts)
            transforms.RandomErasing(p=0.2, scale=(0.02, 0.1))
        ])
    else:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            )
        ])

# ============================================
# 6. DATASET
# ============================================

class MedicalImageDataset(Dataset):
    """Dataset for medical images"""
    def __init__(self, image_paths, labels, transform=None):
        self.image_paths = image_paths
        self.labels = labels
        self.transform = transform
    
    def __len__(self):
        return len(self.image_paths)
    
    def __getitem__(self, idx):
        from PIL import Image
        
        img_path = self.image_paths[idx]
        label = self.labels[idx]
        
        # Load image
        image = Image.open(img_path).convert('RGB')
        
        if self.transform:
            image = self.transform(image)
        
        return image, label

# ============================================
# 7. TRAINING FUNCTIONS
# ============================================

def train_epoch(model, dataloader, criterion, optimizer, device, epoch):
    """Train one epoch"""
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    
    for batch_idx, (images, labels) in enumerate(dataloader):
        images = images.to(device)
        labels = labels.to(device)
        
        # Forward
        optimizer.zero_grad()
        outputs = model(images)
        loss = criterion(outputs, labels)
        
        # Backward
        loss.backward()
        
        # Gradient clipping (optional)
        torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
        
        optimizer.step()
        
        # Statistics
        running_loss += loss.item()
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        # Print progress
        if batch_idx % 10 == 0:
            print(f'Epoch [{epoch}] Batch [{batch_idx}/{len(dataloader)}] '
                  f'Loss: {loss.item():.4f} Acc: {100.*correct/total:.2f}%')
    
    epoch_loss = running_loss / len(dataloader)
    epoch_acc = 100. * correct / total
    
    return epoch_loss, epoch_acc

def validate(model, dataloader, criterion, device):
    """Validate model"""
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    
    all_preds = []
    all_labels = []
    all_probs = []
    
    with torch.no_grad():
        for images, labels in dataloader:
            images = images.to(device)
            labels = labels.to(device)
            
            outputs = model(images)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item()
            
            # Get predictions
            probs = F.softmax(outputs, dim=1)
            _, predicted = outputs.max(1)
            
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
            all_probs.extend(probs.cpu().numpy())
    
    val_loss = running_loss / len(dataloader)
    val_acc = 100. * correct / total
    
    return val_loss, val_acc, all_preds, all_labels, all_probs

# ============================================
# 8. MAIN TRAINING SCRIPT
# ============================================

def main():
    """Main training function"""
    
    # ==================== CONFIG ====================
    CONFIG = {
        'num_classes': 2,
        'image_size': 224,
        'batch_size': 16,
        'num_epochs': 100,
        'learning_rate': 1e-4,
        'weight_decay': 1e-4,
        'device': 'cuda' if torch.cuda.is_available() else 'cpu',
        'num_workers': 4,
        'save_dir': 'checkpoints',
        'use_focal_loss': True,  # Focal Loss cho imbalanced data
    }
    
    print("="*60)
    print("MEDICAL CONVNEXT-TINY TRAINING")
    print("="*60)
    print(f"Device: {CONFIG['device']}")
    print(f"Image Size: {CONFIG['image_size']}")
    print(f"Batch Size: {CONFIG['batch_size']}")
    print(f"Epochs: {CONFIG['num_epochs']}")
    print("="*60)
    
    # Create save directory
    Path(CONFIG['save_dir']).mkdir(exist_ok=True)
    
    # ==================== DATA LOADING ====================
    
    # Đường dẫn tới thư mục chứa dữ liệu
    data_root = Path(r'C:\Users\MIT\Desktop\computer_vision_Copy\train_data')
    
    # Kiểm tra thư mục tồn tại
    if not data_root.exists():
        raise FileNotFoundError(f"Data directory not found: {data_root}")
    
    # Thư mục test
    test_dir = data_root / 'test'
    
    if not test_dir.exists():
        raise FileNotFoundError(f"Test directory not found: {test_dir}")
    
    # Tự động phát hiện các class
    class_folders = sorted([d for d in test_dir.iterdir() if d.is_dir()])
    
    if len(class_folders) == 0:
        raise ValueError(f"No class folders found in {test_dir}")
    
    print(f"\nDetected {len(class_folders)} classes:")
    for i, folder in enumerate(class_folders):
        print(f"  Class {i}: {folder.name}")
    
    # Các extension hình ảnh
    image_extensions = ['*.png', '*.jpg', '*.jpeg', '*.bmp', '*.tif', '*.tiff']
    
    # Thu thập tất cả hình ảnh từ mọi subfolder
    all_paths = []
    all_labels = []
    
    for class_idx, class_folder in enumerate(class_folders):
        class_images = []
        
        # Tìm hình trong thư mục chính và các subfolder (100X, 200X, 400X)
        for root, dirs, files in os.walk(class_folder):
            for ext in image_extensions:
                pattern = os.path.join(root, ext)
                class_images.extend(glob.glob(pattern))
        
        all_paths.extend(sorted(class_images))
        all_labels.extend([class_idx] * len(class_images))
        print(f"  {class_folder.name}: {len(class_images)} images")
    
    # Kiểm tra có dữ liệu không
    if len(all_paths) == 0:
        raise ValueError(f"No images found in {test_dir}")
    
    # Chia train/validation (80/20)
    train_paths, val_paths, train_labels, val_labels = train_test_split(
        all_paths,
        all_labels,
        test_size=0.2,
        random_state=42,
        stratify=all_labels  # Đảm bảo tỉ lệ class cân bằng
    )
    
    print(f"\nDataset Statistics:")
    print(f"Total images: {len(all_paths)}")
    print(f"Train: {len(train_paths)} images ({len(train_paths)/len(all_paths)*100:.1f}%)")
    print(f"Val: {len(val_paths)} images ({len(val_paths)/len(all_paths)*100:.1f}%)")
    print(f"Classes: {[folder.name for folder in class_folders]}")
    
    # Cập nhật CONFIG
    CONFIG['num_classes'] = len(class_folders)
    
    # Transforms
    train_transform = get_medical_transforms(CONFIG['image_size'], is_training=True)
    val_transform = get_medical_transforms(CONFIG['image_size'], is_training=False)
    
    # Datasets
    train_dataset = MedicalImageDataset(train_paths, train_labels, train_transform)
    val_dataset = MedicalImageDataset(val_paths, val_labels, val_transform)
    
    # DataLoaders
    train_loader = DataLoader(
        train_dataset,
        batch_size=CONFIG['batch_size'],
        shuffle=True,
        num_workers=CONFIG['num_workers'],
        pin_memory=True,
        drop_last=True
    )
    
    val_loader = DataLoader(
        val_dataset,
        batch_size=CONFIG['batch_size'],
        shuffle=False,
        num_workers=CONFIG['num_workers'],
        pin_memory=True
    )
    
    # ==================== MODEL ====================
    print("\nInitializing model...")
    model = MedicalConvNeXtTiny(
        num_classes=CONFIG['num_classes'],
        depths=[5, 4, 9, 3],  # Enhanced Stage 1 & 2
        dims=[96, 192, 384, 768],
        drop_path_rate=0.4,
        use_attention=[True, True, True, True],
        attention_types=['cbam', 'se', 'cbam', 'se'],
        pretrained=True
    ).to(CONFIG['device'])
    
    total_params = sum(p.numel() for p in model.parameters())
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"Total parameters: {total_params/1e6:.2f}M")
    print(f"Trainable parameters: {trainable_params/1e6:.2f}M")
    
    # ==================== LOSS & OPTIMIZER ====================
    if CONFIG['use_focal_loss']:
        criterion = FocalLoss(alpha=0.25, gamma=2.0)
        print("Using Focal Loss")
    else:
        criterion = nn.CrossEntropyLoss()
        print("Using Cross Entropy Loss")
    
    # AdamW optimizer
    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=CONFIG['learning_rate'],
        weight_decay=CONFIG['weight_decay']
    )
    
    # Cosine Annealing scheduler
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
        optimizer,
        T_max=CONFIG['num_epochs'],
        eta_min=1e-6
    )
    
    # ==================== TRAINING LOOP ====================
    best_val_acc = 0.0
    best_epoch = 0
    
    print("\n" + "="*60)
    print("STARTING TRAINING")
    print("="*60)
    
    for epoch in range(1, CONFIG['num_epochs'] + 1):
        print(f"\n{'='*60}")
        print(f"Epoch {epoch}/{CONFIG['num_epochs']}")
        print(f"{'='*60}")
        
        # Train
        train_loss, train_acc = train_epoch(
            model, train_loader, criterion, optimizer, CONFIG['device'], epoch
        )
        
        # Validate
        val_loss, val_acc, val_preds, val_labels, val_probs = validate(
            model, val_loader, criterion, CONFIG['device']
        )
        
        # Update learning rate
        scheduler.step()
        current_lr = optimizer.param_groups[0]['lr']
        
        # Print epoch summary
        print(f"\n{'='*60}")
        print(f"Epoch {epoch} Summary:")
        print(f"Train Loss: {train_loss:.4f} | Train Acc: {train_acc:.2f}%")
        print(f"Val Loss: {val_loss:.4f} | Val Acc: {val_acc:.2f}%")
        print(f"Learning Rate: {current_lr:.6f}")
        print(f"{'='*60}")
        
        # Detailed metrics every 5 epochs
        if epoch % 5 == 0:
            from sklearn.metrics import classification_report, confusion_matrix, roc_auc_score
            
            print("\n" + "="*60)
            print("DETAILED METRICS")
            print("="*60)
            
            # Classification report
            print("\nClassification Report:")
            class_names = [folder.name for folder in class_folders]
            print(classification_report(
                val_labels, 
                val_preds,
                target_names=class_names,
                digits=4
            ))
            
            # Confusion matrix
            print("\nConfusion Matrix:")
            cm = confusion_matrix(val_labels, val_preds)
            print(cm)
            
            # ROC-AUC
            val_probs_array = np.array(val_probs)
            if CONFIG['num_classes'] == 2:
                auc = roc_auc_score(val_labels, val_probs_array[:, 1])
                print(f"\nROC-AUC Score: {auc:.4f}")
            
            print("="*60)
        
        # Save best model
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            best_epoch = epoch
            
            checkpoint = {
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'scheduler_state_dict': scheduler.state_dict(),
                'train_loss': train_loss,
                'train_acc': train_acc,
                'val_loss': val_loss,
                'val_acc': val_acc,
                'config': CONFIG
            }
            
            torch.save(
                checkpoint,
                Path(CONFIG['save_dir']) / 'best_model.pth'
            )
            print(f"\n✅ Saved best model! Val Acc: {val_acc:.2f}%")
        
        # Save checkpoint every 10 epochs
        if epoch % 10 == 0:
            torch.save(
                checkpoint,
                Path(CONFIG['save_dir']) / f'checkpoint_epoch_{epoch}.pth'
            )
            print(f"Saved checkpoint at epoch {epoch}")
    
    # ==================== TRAINING COMPLETE ====================
    print("\n" + "="*60)
    print("TRAINING COMPLETE!")
    print("="*60)
    print(f"Best Validation Accuracy: {best_val_acc:.2f}% (Epoch {best_epoch})")
    print(f"Model saved to: {CONFIG['save_dir']}/best_model.pth")
    print("="*60)

if __name__ == '__main__':
    main()
