import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
import timm
from typing import Optional, List
import numpy as np
from pathlib import Path
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    classification_report, confusion_matrix, 
    roc_auc_score, recall_score, precision_score, f1_score
)
import matplotlib.pyplot as plt
import seaborn as sns
import glob
import os

# ============================================
# 1. ATTENTION MODULES
# ============================================

class ChannelAttention(nn.Module):
    """Channel Attention from CBAM"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        
        self.fc = nn.Sequential(
            nn.Conv2d(channels, channels // reduction, 1, bias=False),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 1, bias=False)
        )
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = self.fc(self.avg_pool(x))
        max_out = self.fc(self.max_pool(x))
        out = self.sigmoid(avg_out + max_out)
        return x * out

class SpatialAttention(nn.Module):
    """Spatial Attention from CBAM"""
    def __init__(self, kernel_size=7):
        super().__init__()
        self.conv = nn.Conv2d(2, 1, kernel_size, padding=kernel_size//2, bias=False)
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        out = torch.cat([avg_out, max_out], dim=1)
        out = self.sigmoid(self.conv(out))
        return x * out

class CBAM(nn.Module):
    """Convolutional Block Attention Module"""
    def __init__(self, channels, reduction=16, kernel_size=7):
        super().__init__()
        self.ca = ChannelAttention(channels, reduction)
        self.sa = SpatialAttention(kernel_size)
    
    def forward(self, x):
        x = self.ca(x)
        x = self.sa(x)
        return x

class SEBlock(nn.Module):
    """Squeeze-and-Excitation Block"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.squeeze = nn.AdaptiveAvgPool2d(1)
        self.excitation = nn.Sequential(
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False),
            nn.Sigmoid()
        )
    
    def forward(self, x):
        b, c, _, _ = x.size()
        y = self.squeeze(x).view(b, c)
        y = self.excitation(y).view(b, c, 1, 1)
        return x * y.expand_as(x)

# ============================================
# 2. DROP PATH (Stochastic Depth)
# ============================================

class DropPath(nn.Module):
    """Drop paths (Stochastic Depth) per sample"""
    def __init__(self, drop_prob=0.):
        super().__init__()
        self.drop_prob = drop_prob
    
    def forward(self, x):
        if self.drop_prob == 0. or not self.training:
            return x
        keep_prob = 1 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)
        random_tensor.floor_()
        output = x.div(keep_prob) * random_tensor
        return output

# ============================================
# 3. MODIFIED CONVNEXT TINY FOR MEDICAL
# ============================================

class MedicalConvNeXtTiny(nn.Module):
    """ConvNeXt-Tiny optimized for Medical Imaging"""
    def __init__(
        self,
        num_classes=2,
        in_chans=3,
        depths=[5, 4, 9, 3],
        dims=[96, 192, 384, 768],
        drop_path_rate=0.4,
        use_attention=[True, True, True, True],
        attention_types=['cbam', 'se', 'cbam', 'se'],
        pretrained=True
    ):
        super().__init__()
        
        if pretrained:
            self.backbone = timm.create_model(
                'convnext_tiny',
                pretrained=True,
                num_classes=0,
                features_only=False
            )
            
            self.backbone.stem = nn.Sequential(
                nn.Conv2d(in_chans, dims[0], kernel_size=4, stride=2, padding=1),
                nn.LayerNorm([dims[0], 112, 112])
            )
            
            self._add_attention_to_stages(
                self.backbone, dims, depths, use_attention,
                attention_types, drop_path_rate
            )
        else:
            raise NotImplementedError("Build from scratch not implemented yet")
        
        self.head = self._build_medical_head(dims[-1], num_classes)
        self._init_weights()
    
    def _add_attention_to_stages(self, backbone, dims, depths, use_attention, attention_types, drop_path_rate):
        for stage_idx in range(4):
            if not use_attention[stage_idx]:
                continue
                
            stage = backbone.stages[stage_idx]
            attention_type = attention_types[stage_idx]
            
            for block_idx in range(len(stage.blocks)):
                block = stage.blocks[block_idx]
                
                if attention_type == 'cbam':
                    attention = CBAM(dims[stage_idx])
                elif attention_type == 'se':
                    attention = SEBlock(dims[stage_idx])
                else:
                    attention = nn.Identity()
                
                stage.blocks[block_idx] = nn.Sequential(block, attention)
                
                dp_rate = drop_path_rate * (stage_idx + 1) / 4
                if dp_rate > 0:
                    stage.blocks[block_idx] = nn.Sequential(
                        stage.blocks[block_idx],
                        DropPath(dp_rate)
                    )
    
    def _build_medical_head(self, in_features, num_classes):
        return nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            nn.Dropout(0.5),
            nn.Linear(in_features, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(inplace=True),
            nn.Dropout(0.3),
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(inplace=True),
            nn.Dropout(0.2),
            nn.Linear(256, 128),
            nn.BatchNorm1d(128),
            nn.ReLU(inplace=True),
            nn.Linear(128, num_classes)
        )
    
    def _init_weights(self):
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                nn.init.trunc_normal_(m.weight, std=0.02)
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.BatchNorm1d):
                nn.init.constant_(m.weight, 1)
                nn.init.constant_(m.bias, 0)
    
    def forward(self, x):
        features = self.backbone.forward_features(x)
        output = self.head(features)
        return output

# ============================================
# 4. FOCAL LOSS
# ============================================

class FocalLoss(nn.Module):
    """Focal Loss for imbalanced classification"""
    def __init__(self, alpha=0.25, gamma=2.0, reduction='mean'):
        super().__init__()
        self.alpha = alpha
        self.gamma = gamma
        self.reduction = reduction
    
    def forward(self, inputs, targets):
        ce_loss = F.cross_entropy(inputs, targets, reduction='none')
        pt = torch.exp(-ce_loss)
        focal_loss = self.alpha * (1 - pt) ** self.gamma * ce_loss
        
        if self.reduction == 'mean':
            return focal_loss.mean()
        elif self.reduction == 'sum':
            return focal_loss.sum()
        else:
            return focal_loss

# ============================================
# 5. EARLY STOPPING
# ============================================

class EarlyStopping:
    """Early Stopping to prevent overfitting"""
    def __init__(self, patience=10, min_delta=0.01, verbose=True):
        self.patience = patience
        self.min_delta = min_delta
        self.verbose = verbose
        self.counter = 0
        self.best_score = None
        self.early_stop = False
        self.val_acc_max = 0
        
    def __call__(self, val_acc):
        score = val_acc
        
        if self.best_score is None:
            self.best_score = score
            self.val_acc_max = val_acc
        elif score < self.best_score + self.min_delta:
            self.counter += 1
            if self.verbose:
                print(f"⚠ EarlyStopping counter: {self.counter}/{self.patience}")
            if self.counter >= self.patience:
                self.early_stop = True
        else:
            self.best_score = score
            self.val_acc_max = val_acc
            self.counter = 0

# ============================================
# 6. VISUALIZATION FUNCTIONS
# ============================================

def plot_training_history(history, save_path='training_history.png'):
    """Plot Loss, Accuracy, Recall and Learning Rate"""
    fig, axes = plt.subplots(2, 2, figsize=(16, 12))
    epochs = range(1, len(history['train_loss']) + 1)
    
    # Loss
    axes[0, 0].plot(epochs, history['train_loss'], 'b-', label='Train Loss', linewidth=2)
    axes[0, 0].plot(epochs, history['val_loss'], 'r-', label='Val Loss', linewidth=2)
    axes[0, 0].set_xlabel('Epoch', fontsize=12)
    axes[0, 0].set_ylabel('Loss', fontsize=12)
    axes[0, 0].set_title('Training and Validation Loss', fontsize=14, fontweight='bold')
    axes[0, 0].legend(fontsize=11)
    axes[0, 0].grid(True, alpha=0.3)
    
    # Accuracy
    axes[0, 1].plot(epochs, history['train_acc'], 'b-', label='Train Accuracy', linewidth=2)
    axes[0, 1].plot(epochs, history['val_acc'], 'r-', label='Val Accuracy', linewidth=2)
    axes[0, 1].set_xlabel('Epoch', fontsize=12)
    axes[0, 1].set_ylabel('Accuracy (%)', fontsize=12)
    axes[0, 1].set_title('Training and Validation Accuracy', fontsize=14, fontweight='bold')
    axes[0, 1].legend(fontsize=11)
    axes[0, 1].grid(True, alpha=0.3)
    
    # Recall
    axes[1, 0].plot(epochs, history['train_recall'], 'b-', label='Train Recall', linewidth=2)
    axes[1, 0].plot(epochs, history['val_recall'], 'r-', label='Val Recall', linewidth=2)
    axes[1, 0].set_xlabel('Epoch', fontsize=12)
    axes[1, 0].set_ylabel('Recall (Macro)', fontsize=12)
    axes[1, 0].set_title('Training and Validation Recall', fontsize=14, fontweight='bold')
    axes[1, 0].legend(fontsize=11)
    axes[1, 0].grid(True, alpha=0.3)
    
    # Learning Rate
    axes[1, 1].plot(epochs, history['lr'], 'purple', label='Learning Rate', linewidth=2)
    axes[1, 1].set_xlabel('Epoch', fontsize=12)
    axes[1, 1].set_ylabel('Learning Rate', fontsize=12)
    axes[1, 1].set_title('Learning Rate Schedule', fontsize=14, fontweight='bold')
    axes[1, 1].legend(fontsize=11)
    axes[1, 1].grid(True, alpha=0.3)
    axes[1, 1].set_yscale('log')
    
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    print(f"✓ Saved training history to {save_path}")
    plt.close()

def plot_confusion_matrix(y_true, y_pred, class_names, save_path='confusion_matrix.png'):
    """Plot Confusion Matrix with detailed statistics"""
    cm = confusion_matrix(y_true, y_pred)
    
    plt.figure(figsize=(10, 8))
    sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', 
                xticklabels=class_names, yticklabels=class_names,
                cbar_kws={'label': 'Count'}, annot_kws={'size': 14})
    
    plt.xlabel('Predicted Label', fontsize=13, fontweight='bold')
    plt.ylabel('True Label', fontsize=13, fontweight='bold')
    plt.title('Confusion Matrix', fontsize=15, fontweight='bold', pad=20)
    
    # Add statistics
    if len(class_names) == 2:
        tn, fp, fn, tp = cm.ravel()
        stats_text = f'TN={tn}, FP={fp}, FN={fn}, TP={tp}'
        plt.text(0.5, -0.15, stats_text, ha='center', transform=plt.gca().transAxes,
                fontsize=11, bbox=dict(boxstyle='round', facecolor='wheat', alpha=0.5))
    
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    print(f"✓ Saved confusion matrix to {save_path}")
    plt.close()

# ============================================
# 7. DATA AUGMENTATION & DATASET
# ============================================

def get_medical_transforms(image_size=224, is_training=True):
    """Medical-specific augmentation"""
    if is_training:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandomVerticalFlip(p=0.5),
            transforms.RandomRotation(20),
            transforms.RandomAffine(
                degrees=0, translate=(0.1, 0.1),
                scale=(0.9, 1.1), shear=10
            ),
            transforms.ColorJitter(
                brightness=0.2, contrast=0.2,
                saturation=0.1, hue=0.05
            ),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            ),
            transforms.RandomErasing(p=0.2, scale=(0.02, 0.1))
        ])
    else:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            )
        ])

class MedicalImageDataset(Dataset):
    """Dataset for medical images"""
    def __init__(self, image_paths, labels, transform=None):
        self.image_paths = image_paths
        self.labels = labels
        self.transform = transform
    
    def __len__(self):
        return len(self.image_paths)
    
    def __getitem__(self, idx):
        from PIL import Image
        
        img_path = self.image_paths[idx]
        label = self.labels[idx]
        image = Image.open(img_path).convert('RGB')
        
        if self.transform:
            image = self.transform(image)
        
        return image, label

# ============================================
# 8. TRAINING FUNCTIONS WITH FULL METRICS
# ============================================

def train_epoch(model, dataloader, criterion, optimizer, device, epoch):
    """Train one epoch with full metrics"""
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    
    for batch_idx, (images, labels) in enumerate(dataloader):
        images = images.to(device)
        labels = labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(images)
        loss = criterion(outputs, labels)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
        optimizer.step()
        
        running_loss += loss.item()
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        all_preds.extend(predicted.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())
        
        if batch_idx % 10 == 0:
            print(f'Epoch [{epoch}] Batch [{batch_idx}/{len(dataloader)}] '
                  f'Loss: {loss.item():.4f} Acc: {100.*correct/total:.2f}%')
    
    epoch_loss = running_loss / len(dataloader)
    epoch_acc = 100. * correct / total
    epoch_recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    
    return epoch_loss, epoch_acc, epoch_recall

def validate(model, dataloader, criterion, device):
    """Validate with comprehensive metrics"""
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    all_probs = []
    
    with torch.no_grad():
        for images, labels in dataloader:
            images = images.to(device)
            labels = labels.to(device)
            outputs = model(images)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item()
            probs = F.softmax(outputs, dim=1)
            _, predicted = outputs.max(1)
            
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
            all_probs.extend(probs.cpu().numpy())
    
    val_loss = running_loss / len(dataloader)
    val_acc = 100. * correct / total
    val_recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    
    return val_loss, val_acc, val_recall, all_preds, all_labels, all_probs

def print_detailed_metrics(val_labels, val_preds, val_probs, class_names, num_classes):
    """Print comprehensive evaluation metrics"""
    print("\n" + "="*70)
    print("DETAILED EVALUATION METRICS")
    print("="*70)
    
    # Classification Report
    print("\nClassification Report:")
    print(classification_report(
        val_labels, val_preds,
        target_names=class_names,
        digits=4
    ))
    
    # Confusion Matrix
    print("\nConfusion Matrix:")
    cm = confusion_matrix(val_labels, val_preds)
    print(cm)
    
    if num_classes == 2:
        tn, fp, fn, tp = cm.ravel()
        print(f"\nTrue Negatives: {tn}, False Positives: {fp}")
        print(f"False Negatives: {fn}, True Positives: {tp}")
        
        # Sensitivity and Specificity
        sensitivity = tp / (tp + fn) if (tp + fn) > 0 else 0
        specificity = tn / (tn + fp) if (tn + fp) > 0 else 0
        print(f"\nSensitivity (Recall): {sensitivity:.4f}")
        print(f"Specificity: {specificity:.4f}")
    
    # ROC-AUC
    val_probs_array = np.array(val_probs)
    if num_classes == 2:
        auc = roc_auc_score(val_labels, val_probs_array[:, 1])
        print(f"\nROC-AUC Score: {auc:.4f}")
    
    # Precision, Recall, F1
    precision = precision_score(val_labels, val_preds, average='macro', zero_division=0)
    recall = recall_score(val_labels, val_preds, average='macro', zero_division=0)
    f1 = f1_score(val_labels, val_preds, average='macro', zero_division=0)
    
    print(f"\nMacro-averaged Metrics:")
    print(f"Precision: {precision:.4f}")
    print(f"Recall: {recall:.4f}")
    print(f"F1-Score: {f1:.4f}")
    print("="*70)

# ============================================
# 9. MAIN TRAINING SCRIPT
# ============================================

def main():
    """Main training function with full evaluation"""
    
    CONFIG = {
        'num_classes': 2,
        'image_size': 224,
        'batch_size': 16,
        'num_epochs': 100,
        'learning_rate': 1e-4,
        'weight_decay': 1e-4,
        'device': 'cuda' if torch.cuda.is_available() else 'cpu',
        'num_workers': 4,
        'save_dir': 'checkpoints',
        'use_focal_loss': True,
        'early_stopping_patience': 5,
    }
    
    print("="*70)
    print("MEDICAL CONVNEXT-TINY TRAINING WITH FULL EVALUATION")
    print("="*70)
    print(f"Device: {CONFIG['device']}")
    print(f"Image Size: {CONFIG['image_size']}")
    print(f"Batch Size: {CONFIG['batch_size']}")
    print(f"Epochs: {CONFIG['num_epochs']}")
    print(f"Early Stopping Patience: {CONFIG['early_stopping_patience']}")
    print("="*70)
    
    Path(CONFIG['save_dir']).mkdir(exist_ok=True)
    
    # ==================== DATA LOADING ====================
    data_root = "./train_data"
    
    test_dir = os.path.join(data_root, 'test')

    if not test_dir.exists():
        raise FileNotFoundError(f"Test directory not found: {test_dir}")
    
    class_folders = sorted([d for d in test_dir.iterdir() if d.is_dir()])
    
    if len(class_folders) == 0:
        raise ValueError(f"No class folders found in {test_dir}")
    
    print(f"\nDetected {len(class_folders)} classes:")
    for i, folder in enumerate(class_folders):
        print(f"  Class {i}: {folder.name}")
    
    image_extensions = ['*.png', '*.jpg', '*.jpeg', '*.bmp', '*.tif', '*.tiff']
    
    all_paths = []
    all_labels = []
    
    for class_idx, class_folder in enumerate(class_folders):
        class_images = []
        for root, dirs, files in os.walk(class_folder):
            for ext in image_extensions:
                pattern = os.path.join(root, ext)
                class_images.extend(glob.glob(pattern))
        
        all_paths.extend(sorted(class_images))
        all_labels.extend([class_idx] * len(class_images))
        print(f"  {class_folder.name}: {len(class_images)} images")
    
    if len(all_paths) == 0:
        raise ValueError(f"No images found in {test_dir}")
    
    train_paths, val_paths, train_labels, val_labels = train_test_split(
        all_paths, all_labels, test_size=0.2,
        random_state=42, stratify=all_labels
    )
    
    print(f"\nDataset Statistics:")
    print(f"Total: {len(all_paths)} images")
    print(f"Train: {len(train_paths)} ({len(train_paths)/len(all_paths)*100:.1f}%)")
    print(f"Val: {len(val_paths)} ({len(val_paths)/len(all_paths)*100:.1f}%)")
    
    class_names = [folder.name for folder in class_folders]
    CONFIG['num_classes'] = len(class_folders)
    
    train_transform = get_medical_transforms(CONFIG['image_size'], is_training=True)
    val_transform = get_medical_transforms(CONFIG['image_size'], is_training=False)
    
    train_dataset = MedicalImageDataset(train_paths, train_labels, train_transform)
    val_dataset = MedicalImageDataset(val_paths, val_labels, val_transform)
    
    train_loader = DataLoader(
        train_dataset, batch_size=CONFIG['batch_size'],
        shuffle=True, num_workers=CONFIG['num_workers'],
        pin_memory=True, drop_last=True
    )
    
    val_loader = DataLoader(
        val_dataset, batch_size=CONFIG['batch_size'],
        shuffle=False, num_workers=CONFIG['num_workers'],
        pin_memory=True
    )
    
    # ==================== MODEL ====================
    print("\nInitializing model...")
    model = MedicalConvNeXtTiny(
        num_classes=CONFIG['num_classes'],
        depths=[5, 4, 9, 3],
        dims=[96, 192, 384, 768],
        drop_path_rate=0.4,
        use_attention=[True, True, True, True],
        attention_types=['cbam', 'se', 'cbam', 'se'],
        pretrained=True
    ).to(CONFIG['device'])
    
    total_params = sum(p.numel() for p in model.parameters())
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"Total parameters: {total_params/1e6:.2f}M")
    print(f"Trainable parameters: {trainable_params/1e6:.2f}M")
    
    # ==================== LOSS & OPTIMIZER ====================
    if CONFIG['use_focal_loss']:
        criterion = FocalLoss(alpha=0.25, gamma=2.0)
        print("Using Focal Loss")
    else:
        criterion = nn.CrossEntropyLoss()
        print("Using Cross Entropy Loss")
    
    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=CONFIG['learning_rate'],
        weight_decay=CONFIG['weight_decay']
    )
    
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
        optimizer, T_max=CONFIG['num_epochs'], eta_min=1e-6
    )
    
    early_stopping = EarlyStopping(
        patience=CONFIG['early_stopping_patience'],
        min_delta=0.01, verbose=True
    )
    
    # ==================== TRAINING HISTORY ====================
    history = {
        'train_loss': [], 'train_acc': [], 'train_recall': [],
        'val_loss': [], 'val_acc': [], 'val_recall': [], 'lr': []
    }
    
    best_val_acc = 0.0
    best_epoch = 0
    best_preds = []
    best_labels = []
    best_probs = []
    
    # ==================== TRAINING LOOP ====================
    print("\n" + "="*70)
    print("STARTING TRAINING")
    print("="*70)
    
    for epoch in range(1, CONFIG['num_epochs'] + 1):
        print(f"\n{'='*70}")
        print(f"Epoch {epoch}/{CONFIG['num_epochs']}")
        print(f"{'='*70}")
        
        # Train
        train_loss, train_acc, train_recall = train_epoch(
            model, train_loader, criterion, optimizer, CONFIG['device'], epoch
        )
        
        # Validate
        val_loss, val_acc, val_recall, val_preds, val_labels, val_probs = validate(
            model, val_loader, criterion, CONFIG['device']
        )
        
        scheduler.step()
        current_lr = optimizer.param_groups[0]['lr']
        
        # Save history
        history['train_loss'].append(train_loss)
        history['train_acc'].append(train_acc)
        history['train_recall'].append(train_recall)
        history['val_loss'].append(val_loss)
        history['val_acc'].append(val_acc)
        history['val_recall'].append(val_recall)
        history['lr'].append(current_lr)
        
        # Print epoch summary
        print(f"\n{'='*70}")
        print(f"Epoch {epoch} Summary:")
        print(f"Train Loss: {train_loss:.4f} | Train Acc: {train_acc:.2f}% | Train Recall: {train_recall:.4f}")
        print(f"Val Loss: {val_loss:.4f} | Val Acc: {val_acc:.2f}% | Val Recall: {val_recall:.4f}")
        print(f"Learning Rate: {current_lr:.6f}")
        print(f"{'='*70}")
        
        # Detailed metrics every 5 epochs
        if epoch % 5 == 0:
            print_detailed_metrics(val_labels, val_preds, val_probs, class_names, CONFIG['num_classes'])
        
        # Save best model
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            best_epoch = epoch
            best_preds = val_preds
            best_labels = val_labels
            best_probs = val_probs
            
            checkpoint = {
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'scheduler_state_dict': scheduler.state_dict(),
                'train_loss': train_loss,
                'train_acc': train_acc,
                'val_loss': val_loss,
                'val_acc': val_acc,
                'config': CONFIG,
                'class_names': class_names
            }
            
            torch.save(
                checkpoint,
                Path(CONFIG['save_dir']) / 'best_model.pth'
            )
            print(f"\n✅ Saved best model! Val Acc: {val_acc:.2f}%")
        
        # Checkpoint every 10 epochs
        if epoch % 10 == 0:
            torch.save(
                checkpoint,
                Path(CONFIG['save_dir']) / f'checkpoint_epoch_{epoch}.pth'
            )
            print(f"💾 Saved checkpoint at epoch {epoch}")
        
        # Early stopping
        early_stopping(val_acc)
        if early_stopping.early_stop:
            print(f"\n⚠ Early stopping triggered at epoch {epoch}")
            print(f"Best validation accuracy: {early_stopping.val_acc_max:.2f}%")
            break
    
    # ==================== TRAINING COMPLETE ====================
    print("\n" + "="*70)
    print("TRAINING COMPLETE!")
    print("="*70)
    print(f"Best Validation Accuracy: {best_val_acc:.2f}% (Epoch {best_epoch})")
    print(f"Model saved to: {CONFIG['save_dir']}/best_model.pth")
    print("="*70)
    
    # ==================== FINAL EVALUATION ====================
    print("\n" + "="*70)
    print("FINAL EVALUATION ON BEST MODEL")
    print("="*70)
    
    print_detailed_metrics(best_labels, best_preds, best_probs, class_names, CONFIG['num_classes'])
    
    # ==================== GENERATE VISUALIZATIONS ====================
    print("\nGenerating visualizations...")
    
    plot_training_history(history, save_path=Path(CONFIG['save_dir']) / 'training_history.png')
    plot_confusion_matrix(best_labels, best_preds, class_names, 
                         save_path=Path(CONFIG['save_dir']) / 'confusion_matrix.png')
    
    print("\n" + "="*70)
    print("ALL FILES SAVED:")
    print("="*70)
    print(f"✓ Best model: {CONFIG['save_dir']}/best_model.pth")
    print(f"✓ Training history plot: {CONFIG['save_dir']}/training_history.png")
    print(f"✓ Confusion matrix: {CONFIG['save_dir']}/confusion_matrix.png")
    print("="*70)

if __name__ == '__main__':
    main()
