import matplotlib.pyplot as plt

def plot_training_history(history, save_dir='.', prefix='training_history'):
    """Vẽ biểu đồ Loss + Learning Rate và các metric khác theo style marker + annotate"""
    epochs = list(range(1, len(history['train_loss']) + 1))

    # === Loss + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()

    # Loss
    l1, = ax1.plot(epochs, history['train_loss'], marker='o', linewidth=2, label='Train Loss', color='blue')
    l2, = ax1.plot(epochs, history['val_loss'], marker='s', linewidth=2, label='Val Loss', color='green')

    # Annotate Loss
    for x, y in zip(epochs, history['train_loss']):
        ax1.text(x, y+0.001, f"{y:.3f}", fontsize=9, ha='center', alpha=0.8)
    for x, y in zip(epochs, history['val_loss']):
        ax1.text(x, y+0.001, f"{y:.3f}", fontsize=9, ha='center', alpha=0.8)

    # Learning Rate
    l3, = ax2.plot(epochs, history['lr'], marker='^', linewidth=2, color='red', label='Learning Rate', alpha=0.5)
    ax2.set_ylabel("Learning Rate")
    ax2.set_yscale('log')

    ax1.set_xticks(epochs)
    ax1.set_xlabel("Epoch")
    ax1.set_ylabel("Loss")
    ax1.set_title("Loss và Learning Rate theo Epoch", fontsize=14, fontweight='bold')
    ax1.grid(alpha=0.3)

    # Legend chung
    plt.legend(handles=[l1, l2, l3], loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=3, frameon=False)
