import matplotlib.pyplot as plt

def plot_training_history(history, save_dir='.', prefix='training_history'):
    """Vẽ training history: Loss, Accuracy, Recall + Learning Rate trên trục phụ"""
    epochs = list(range(1, len(history['train_loss']) + 1))

    # Hàm phụ để vẽ Learning Rate trên trục phụ
    def add_lr(ax, epochs, lr):
        l = ax.plot(epochs, lr, marker='^', linewidth=2, color='red', label='Tốc độ học (LR)', alpha=0.4)
        ax.set_ylabel("Learning Rate")
        ax.set_yscale('log')
        return l

    # === Loss + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()
    l1, = ax1.plot(epochs, history['train_loss'], marker='o', linewidth=2, label='Huấn luyện (Train)', color='blue')
    l2, = ax1.plot(epochs, history['val_loss'], marker='s', linewidth=2, label='Kiểm định (Validation)', color='green')
    add_lr(ax2, epochs, history['lr'])
    ax1.set_xlabel("Epoch")
    ax1.set_ylabel("Loss")
    ax1.set_title("Loss và Learning Rate theo Epoch", fontsize=14, fontweight='bold')
    ax1.grid(alpha=0.3)
    plt.legend(handles=[l1,l2], loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=2, frameon=False)
    plt.tight_layout()
    plt.savefig(f"{save_dir}/{prefix}_loss_lr.png", dpi=300)
    plt.close()

    # === Accuracy + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()
    l1, = ax1.plot(epochs, history['train_acc'], marker='o', linewidth=2, label='Huấn luyện (Train)', color='blue')
    l2, = ax1.plot(epochs, history['val_acc'], marker='s', linewidth=2, label='Kiểm định (Validation)', color='green')
    add_lr(ax2, epochs, history['lr'])
    ax1.set_xlabel("Epoch")
    ax1.set_ylabel("Accuracy (%)")
    ax1.set_title("Accuracy và Learning Rate theo Epoch", fontsize=14, fontweight='bold')
    ax1.grid(alpha=0.3)
    plt.legend(handles=[l1,l2], loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=2, frameon=False)
    plt.tight_layout()
    plt.savefig(f"{save_dir}/{prefix}_accuracy.png", dpi=300)
    plt.close()

    # === Recall + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()
    l1, = ax1.plot(epochs, history['train_recall'], marker='o', linewidth=2, label='Huấn luyện (Train)', color='blue')
    l2, = ax1.plot(epochs, history['val_recall'], marker='s', linewidth=2, label='Kiểm định (Validation)', color='green')
    add_lr(ax2, epochs, history['lr'])
    ax1.set_xlabel("Epoch")
    ax1.set_ylabel("Recall (Macro)")
    ax1.set_title("Recall và Learning Rate theo Epoch", fontsize=14, fontweight='bold')
    ax1.grid(alpha=0.3)
    plt.legend(handles=[l1,l2], loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=2, frameon=False)
    plt.tight_layout()
    plt.savefig(f"{save_dir}/{prefix}_recall.png", dpi=300)
    plt.close()

    print(f"✓ Saved all training history plots with Learning Rate to {save_dir}")
