import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
import timm
from typing import Optional, List
import numpy as np
from pathlib import Path
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    classification_report, confusion_matrix, 
    roc_auc_score, recall_score, precision_score, f1_score
)
import matplotlib.pyplot as plt
import seaborn as sns
import glob
import os
from tqdm import tqdm

# ============================================
# 1. ATTENTION MODULES
# ============================================

class ChannelAttention(nn.Module):
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        self.fc = nn.Sequential(
            nn.Conv2d(channels, channels // reduction, 1, bias=False),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 1, bias=False)
        )
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = self.fc(self.avg_pool(x))
        max_out = self.fc(self.max_pool(x))
        return x * self.sigmoid(avg_out + max_out)

class SpatialAttention(nn.Module):
    def __init__(self, kernel_size=7):
        super().__init__()
        self.conv = nn.Conv2d(2, 1, kernel_size, padding=kernel_size//2, bias=False)
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        out = torch.cat([avg_out, max_out], dim=1)
        return x * self.sigmoid(self.conv(out))

class CBAM(nn.Module):
    def __init__(self, channels, reduction=16, kernel_size=7):
        super().__init__()
        self.ca = ChannelAttention(channels, reduction)
        self.sa = SpatialAttention(kernel_size)
    
    def forward(self, x):
        return self.sa(self.ca(x))

class SEBlock(nn.Module):
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.squeeze = nn.AdaptiveAvgPool2d(1)
        self.excitation = nn.Sequential(
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False),
            nn.Sigmoid()
        )
    
    def forward(self, x):
        b, c, _, _ = x.size()
        y = self.squeeze(x).view(b, c)
        y = self.excitation(y).view(b, c, 1, 1)
        return x * y.expand_as(x)

# ============================================
# 2. MODEL (FIXED VERSION)
# ============================================

class MedicalConvNeXtTiny(nn.Module):
    def __init__(self, num_classes=2, drop_path_rate=0.2, pretrained=True):
        super().__init__()
        
        if pretrained:
            self.backbone = timm.create_model(
                'convnext_tiny', pretrained=True, num_classes=0, features_only=False
            )
            
            # Add attention to last 2 stages only
            dims = [96, 192, 384, 768]
            for stage_idx in [2, 3]:
                stage = self.backbone.stages[stage_idx]
                attention = CBAM(dims[stage_idx]) if stage_idx == 2 else SEBlock(dims[stage_idx])
                
                for block_idx in range(len(stage.blocks)):
                    block = stage.blocks[block_idx]
                    stage.blocks[block_idx] = nn.Sequential(block, attention)
        
        # Simpler head with less dropout
        self.head = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            nn.Dropout(0.3),  # Reduced from 0.5
            nn.Linear(768, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(inplace=True),
            nn.Dropout(0.2),  # Reduced from 0.3
            nn.Linear(256, num_classes)
        )
        self._init_weights()
    
    def _init_weights(self):
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                nn.init.trunc_normal_(m.weight, std=0.02)
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.BatchNorm1d):
                nn.init.constant_(m.weight, 1)
                nn.init.constant_(m.bias, 0)
    
    def forward(self, x):
        features = self.backbone.forward_features(x)
        return self.head(features)

# ============================================
# 3. FOCAL LOSS
# ============================================

class FocalLoss(nn.Module):
    def __init__(self, alpha=0.25, gamma=2.0, reduction='mean'):
        super().__init__()
        self.alpha = alpha
        self.gamma = gamma
        self.reduction = reduction
    
    def forward(self, inputs, targets):
        ce_loss = F.cross_entropy(inputs, targets, reduction='none')
        pt = torch.exp(-ce_loss)
        focal_loss = self.alpha * (1 - pt) ** self.gamma * ce_loss
        return focal_loss.mean() if self.reduction == 'mean' else focal_loss

# ============================================
# 4. EARLY STOPPING
# ============================================

class EarlyStopping:
    def __init__(self, patience=10, min_delta=0.001, verbose=True):
        self.patience = patience
        self.min_delta = min_delta
        self.verbose = verbose
        self.counter = 0
        self.best_score = None
        self.early_stop = False
        self.val_acc_max = 0
        
    def __call__(self, val_acc):
        if self.best_score is None:
            self.best_score = val_acc
            self.val_acc_max = val_acc
        elif val_acc < self.best_score + self.min_delta:
            self.counter += 1
            if self.verbose:
                print(f"⚠ EarlyStopping: {self.counter}/{self.patience}")
            if self.counter >= self.patience:
                self.early_stop = True
        else:
            self.best_score = val_acc
            self.val_acc_max = val_acc
            self.counter = 0

# ============================================
# 5. DATASET (LIGHTER AUGMENTATION)
# ============================================

def get_medical_transforms(image_size=224, is_training=True):
    if is_training:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandomVerticalFlip(p=0.3),  # Reduced from 0.5
            transforms.RandomRotation(10),  # Reduced from 15
            transforms.ColorJitter(brightness=0.1, contrast=0.1),  # Reduced
            transforms.ToTensor(),
            transforms.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225])
        ])
    else:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.ToTensor(),
            transforms.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225])
        ])

class MedicalImageDataset(Dataset):
    def __init__(self, image_paths, labels, transform=None):
        self.image_paths = image_paths
        self.labels = labels
        self.transform = transform
    
    def __len__(self):
        return len(self.image_paths)
    
    def __getitem__(self, idx):
        from PIL import Image
        img_path = self.image_paths[idx]
        label = self.labels[idx]
        image = Image.open(img_path).convert('RGB')
        if self.transform:
            image = self.transform(image)
        return image, label

# ============================================
# 6. DATA LOADER
# ============================================

def load_data_smart(data_root):
    data_root = Path(data_root)
    image_extensions = ['*.png', '*.jpg', '*.jpeg', '*.bmp', '*.tif', '*.tiff']
    
    train_dir = data_root / 'train'
    val_dir = data_root / 'validation'
    test_dir = data_root / 'test'
    
    if train_dir.exists() and val_dir.exists():
        print("✓ Found train/ and validation/")
        class_folders = sorted([d for d in train_dir.iterdir() if d.is_dir()])
        
        train_paths, train_labels = [], []
        for class_idx, class_folder in enumerate(class_folders):
            class_images = []
            for ext in image_extensions:
                class_images.extend(glob.glob(str(class_folder / '**' / ext), recursive=True))
            train_paths.extend(sorted(class_images))
            train_labels.extend([class_idx] * len(class_images))
            print(f"  Train {class_folder.name}: {len(class_images)}")
        
        val_paths, val_labels = [], []
        for class_idx, class_folder in enumerate(class_folders):
            val_class_folder = val_dir / class_folder.name
            if not val_class_folder.exists():
                continue
            class_images = []
            for ext in image_extensions:
                class_images.extend(glob.glob(str(val_class_folder / '**' / ext), recursive=True))
            val_paths.extend(sorted(class_images))
            val_labels.extend([class_idx] * len(class_images))
            print(f"  Val {class_folder.name}: {len(class_images)}")
        
        class_names = [f.name for f in class_folders]
        print(f"✓ Total: {len(train_paths)} train, {len(val_paths)} val")
        return train_paths, val_paths, train_labels, val_labels, class_names
    
    elif test_dir.exists():
        print("✓ Found test/ - auto-splitting 80/20")
        class_folders = sorted([d for d in test_dir.iterdir() if d.is_dir()])
        
        all_paths, all_labels = [], []
        for class_idx, class_folder in enumerate(class_folders):
            class_images = []
            for ext in image_extensions:
                class_images.extend(glob.glob(str(class_folder / '**' / ext), recursive=True))
            all_paths.extend(sorted(class_images))
            all_labels.extend([class_idx] * len(class_images))
            print(f"  {class_folder.name}: {len(class_images)}")
        
        train_paths, val_paths, train_labels, val_labels = train_test_split(
            all_paths, all_labels, test_size=0.2, random_state=42, stratify=all_labels
        )
        
        class_names = [f.name for f in class_folders]
        print(f"✓ Split: {len(train_paths)} train, {len(val_paths)} val")
        return train_paths, val_paths, train_labels, val_labels, class_names
    
    else:
        raise FileNotFoundError(f"No valid structure in {data_root}")

# ============================================
# 7. TRAINING WITH GRADUAL UNFREEZING
# ============================================

def train_epoch(model, dataloader, criterion, optimizer, device, epoch):
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    
    pbar = tqdm(dataloader, desc=f'Epoch {epoch:3d} [TRAIN]', colour='green', ncols=100)
    for images, labels in pbar:
        images = images.to(device, non_blocking=True)
        labels = labels.to(device, non_blocking=True)
        
        optimizer.zero_grad()
        outputs = model(images)
        loss = criterion(outputs, labels)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
        optimizer.step()
        
        running_loss += loss.item()
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        all_preds.extend(predicted.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())
        
        pbar.set_postfix({'loss': f'{loss.item():.4f}', 'acc': f'{100.*correct/total:.2f}%'})
    
    epoch_loss = running_loss / len(dataloader)
    epoch_acc = 100. * correct / total
    epoch_recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    return epoch_loss, epoch_acc, epoch_recall

def validate(model, dataloader, criterion, device, epoch=0):
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds, all_labels, all_probs = [], [], []
    
    pbar = tqdm(dataloader, desc=f'Epoch {epoch:3d} [VAL]  ', colour='blue', ncols=100)
    with torch.no_grad():
        for images, labels in pbar:
            images = images.to(device, non_blocking=True)
            labels = labels.to(device, non_blocking=True)
            outputs = model(images)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item()
            probs = F.softmax(outputs, dim=1)
            _, predicted = outputs.max(1)
            
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
            all_probs.extend(probs.cpu().numpy())
            
            pbar.set_postfix({'loss': f'{loss.item():.4f}', 'acc': f'{100.*correct/total:.2f}%'})
    
    val_loss = running_loss / len(dataloader)
    val_acc = 100. * correct / total
    val_recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    return val_loss, val_acc, val_recall, all_preds, all_labels, all_probs

def print_metrics(labels, preds, probs, class_names, num_classes):
    print("\n" + "="*70)
    print("EVALUATION METRICS")
    print("="*70)
    print(classification_report(labels, preds, target_names=class_names, digits=4))
    
    cm = confusion_matrix(labels, preds)
    print(f"\nConfusion Matrix:\n{cm}")
    
    if num_classes == 2:
        tn, fp, fn, tp = cm.ravel()
        print(f"\nTN={tn}, FP={fp}, FN={fn}, TP={tp}")
        print(f"Sensitivity: {tp/(tp+fn):.4f}, Specificity: {tn/(tn+fp):.4f}")
        auc = roc_auc_score(labels, np.array(probs)[:, 1])
        print(f"ROC-AUC: {auc:.4f}")
    
    print("="*70)

def plot_training_history(history, save_path):
    fig, axes = plt.subplots(2, 2, figsize=(15, 10))
    
    # Loss
    axes[0, 0].plot(history['train_loss'], label='Train Loss', linewidth=2)
    axes[0, 0].plot(history['val_loss'], label='Val Loss', linewidth=2)
    axes[0, 0].set_xlabel('Epoch')
    axes[0, 0].set_ylabel('Loss')
    axes[0, 0].set_title('Training & Validation Loss')
    axes[0, 0].legend()
    axes[0, 0].grid(True)
    
    # Accuracy
    axes[0, 1].plot(history['train_acc'], label='Train Acc', linewidth=2)
    axes[0, 1].plot(history['val_acc'], label='Val Acc', linewidth=2)
    axes[0, 1].set_xlabel('Epoch')
    axes[0, 1].set_ylabel('Accuracy (%)')
    axes[0, 1].set_title('Training & Validation Accuracy')
    axes[0, 1].legend()
    axes[0, 1].grid(True)
    
    # Recall
    axes[1, 0].plot(history['train_recall'], label='Train Recall', linewidth=2)
    axes[1, 0].plot(history['val_recall'], label='Val Recall', linewidth=2)
    axes[1, 0].set_xlabel('Epoch')
    axes[1, 0].set_ylabel('Recall')
    axes[1, 0].set_title('Training & Validation Recall')
    axes[1, 0].legend()
    axes[1, 0].grid(True)
    
    # Learning Rate
    axes[1, 1].plot(history['lr'], linewidth=2, color='orange')
    axes[1, 1].set_xlabel('Epoch')
    axes[1, 1].set_ylabel('Learning Rate')
    axes[1, 1].set_title('Learning Rate Schedule')
    axes[1, 1].grid(True)
    
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.close()

def plot_confusion_matrix(labels, preds, class_names, save_path):
    cm = confusion_matrix(labels, preds)
    plt.figure(figsize=(10, 8))
    sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', 
                xticklabels=class_names, yticklabels=class_names)
    plt.title('Confusion Matrix')
    plt.ylabel('True Label')
    plt.xlabel('Predicted Label')
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.close()

# ============================================
# 8. MAIN (FIXED VERSION)
# ============================================

def main():
    CONFIG = {
        'num_classes': 2,
        'image_size': 224,
        'batch_size': 32,
        'num_epochs': 100,
        'learning_rate': 3e-4,  # INCREASED from 1e-4
        'weight_decay': 1e-4,
        'device': 'cuda' if torch.cuda.is_available() else 'cpu',
        'num_workers': 0,
        'save_dir': 'checkpoints',
        'use_focal_loss': False,  # Use CrossEntropyLoss first
        'early_stopping_patience': 15,  # Increased patience
        'unfreeze_epoch': 3,  # Unfreeze backbone after epoch 3
    }
    
    print("="*70)
    print("🚀 MEDICAL CONVNEXT-TINY - FIXED VERSION v2.0")
    print("="*70)
    print(f"Device: {CONFIG['device']}")
    print(f"Batch Size: {CONFIG['batch_size']}")
    print(f"Learning Rate: {CONFIG['learning_rate']:.6f}")
    print(f"Unfreeze Epoch: {CONFIG['unfreeze_epoch']}")
    print("="*70)
    
    if not torch.cuda.is_available():
        print("⚠ WARNING: No CUDA! Use Google Colab for GPU")
        CONFIG['num_workers'] = 0
    
    Path(CONFIG['save_dir']).mkdir(exist_ok=True)
    
    # Load data
    data_root = './train_data'
    train_paths, val_paths, train_labels, val_labels, class_names = load_data_smart(data_root)
    CONFIG['num_classes'] = len(class_names)
    
    # Datasets
    train_transform = get_medical_transforms(CONFIG['image_size'], True)
    val_transform = get_medical_transforms(CONFIG['image_size'], False)
    
    train_dataset = MedicalImageDataset(train_paths, train_labels, train_transform)
    val_dataset = MedicalImageDataset(val_paths, val_labels, val_transform)
    
    train_loader = DataLoader(
        train_dataset, batch_size=CONFIG['batch_size'], shuffle=True,
        num_workers=CONFIG['num_workers'], pin_memory=True, drop_last=True
    )
    
    val_loader = DataLoader(
        val_dataset, batch_size=CONFIG['batch_size'], shuffle=False,
        num_workers=CONFIG['num_workers'], pin_memory=True
    )
    
    # Model
    print("\n✓ Initializing model...")
    model = MedicalConvNeXtTiny(
        num_classes=CONFIG['num_classes'],
        drop_path_rate=0.2,  # Reduced from 0.4
        pretrained=True
    ).to(CONFIG['device'])
    
    # FREEZE BACKBONE INITIALLY
    print("✓ Freezing backbone for warm-up...")
    for param in model.backbone.parameters():
        param.requires_grad = False
    
    total_params = sum(p.numel() for p in model.parameters())
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"✓ Total Parameters: {total_params/1e6:.2f}M")
    print(f"✓ Trainable Parameters: {trainable_params/1e6:.2f}M")
    
    # Loss & Optimizer
    criterion = nn.CrossEntropyLoss() if not CONFIG['use_focal_loss'] else FocalLoss(alpha=0.25, gamma=2.0)
    optimizer = torch.optim.AdamW(
        filter(lambda p: p.requires_grad, model.parameters()),
        lr=CONFIG['learning_rate'],
        weight_decay=CONFIG['weight_decay']
    )
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
        optimizer, T_max=CONFIG['num_epochs'], eta_min=1e-6
    )
    early_stopping = EarlyStopping(patience=CONFIG['early_stopping_patience'], min_delta=0.001)
    
    # History
    history = {
        'train_loss': [], 'train_acc': [], 'train_recall': [],
        'val_loss': [], 'val_acc': [], 'val_recall': [], 'lr': []
    }
    
    best_val_acc = 0.0
    best_epoch = 0
    best_preds, best_labels, best_probs = [], [], []
    
    # Training loop
    print("\n" + "="*70)
    print("🔥 STARTING TRAINING")
    print("="*70)
    
    for epoch in range(1, CONFIG['num_epochs'] + 1):
        # UNFREEZE BACKBONE AFTER WARM-UP
        if epoch == CONFIG['unfreeze_epoch']:
            print(f"\n🔓 UNFREEZING BACKBONE at epoch {epoch}")
            for param in model.backbone.parameters():
                param.requires_grad = True
            
            # Recreate optimizer with all parameters
            optimizer = torch.optim.AdamW(
                model.parameters(),
                lr=CONFIG['learning_rate'] / 10,  # Lower LR for backbone
                weight_decay=CONFIG['weight_decay']
            )
            scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
                optimizer, T_max=CONFIG['num_epochs'] - epoch, eta_min=1e-6
            )
            
            trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
            print(f"✓ Trainable Parameters: {trainable_params/1e6:.2f}M\n")
        
        train_loss, train_acc, train_recall = train_epoch(
            model, train_loader, criterion, optimizer, CONFIG['device'], epoch
        )
        
        val_loss, val_acc, val_recall, val_preds, val_labels, val_probs = validate(
            model, val_loader, criterion, CONFIG['device'], epoch
        )
        
        scheduler.step()
        current_lr = optimizer.param_groups[0]['lr']
        
        history['train_loss'].append(train_loss)
        history['train_acc'].append(train_acc)
        history['train_recall'].append(train_recall)
        history['val_loss'].append(val_loss)
        history['val_acc'].append(val_acc)
        history['val_recall'].append(val_recall)
        history['lr'].append(current_lr)
        
        print(f"\n📊 Epoch {epoch:3d} | Train: {train_acc:.2f}% | Val: {val_acc:.2f}% | LR: {current_lr:.6f}")
        
        if epoch % 5 == 0:
            print_metrics(val_labels, val_preds, val_probs, class_names, CONFIG['num_classes'])
        
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            best_epoch = epoch
            best_preds, best_labels, best_probs = val_preds, val_labels, val_probs
            
            checkpoint = {
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'scheduler_state_dict': scheduler.state_dict(),
                'val_acc': val_acc,
                'config': CONFIG,
                'class_names': class_names
            }
            
            torch.save(checkpoint, Path(CONFIG['save_dir']) / 'best_model.pth')
            print(f"✅ NEW BEST! Val: {val_acc:.2f}% (saved)")
        
        early_stopping(val_acc)
        if early_stopping.early_stop:
            print(f"\n⚠ Early stopping at epoch {epoch}")
            break
    
    print("\n" + "="*70)
    print("🎉 TRAINING COMPLETE!")
    print(f"Best: {best_val_acc:.2f}% (Epoch {best_epoch})")
    print("="*70)
    
    print_metrics(best_labels, best_preds, best_probs, class_names, CONFIG['num_classes'])
    
    plot_training_history(history, Path(CONFIG['save_dir']) / 'training_history.png')
    plot_confusion_matrix(best_labels, best_preds, class_names, Path(CONFIG['save_dir']) / 'confusion_matrix.png')
    
    print(f"\n✓ Saved: {CONFIG['save_dir']}/best_model.pth")
    print(f"✓ Saved: {CONFIG['save_dir']}/training_history.png")
    print(f"✓ Saved: {CONFIG['save_dir']}/confusion_matrix.png")

if __name__ == '__main__':
    main()
