import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
import timm
from typing import Optional, List
import numpy as np
from pathlib import Path
import glob
from PIL import Image

# ============================================
# 1. ATTENTION MODULES
# ============================================

class ChannelAttention(nn.Module):
    """Channel Attention from CBAM"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        
        self.fc = nn.Sequential(
            nn.Conv2d(channels, channels // reduction, 1, bias=False),
            nn.ReLU(inplace=True),
            nn.Conv2d(channels // reduction, channels, 1, bias=False)
        )
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = self.fc(self.avg_pool(x))
        max_out = self.fc(self.max_pool(x))
        out = self.sigmoid(avg_out + max_out)
        return x * out

class SpatialAttention(nn.Module):
    """Spatial Attention from CBAM"""
    def __init__(self, kernel_size=7):
        super().__init__()
        self.conv = nn.Conv2d(2, 1, kernel_size, padding=kernel_size//2, bias=False)
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        out = torch.cat([avg_out, max_out], dim=1)
        out = self.sigmoid(self.conv(out))
        return x * out

class CBAM(nn.Module):
    """Convolutional Block Attention Module"""
    def __init__(self, channels, reduction=16, kernel_size=7):
        super().__init__()
        self.ca = ChannelAttention(channels, reduction)
        self.sa = SpatialAttention(kernel_size)
    
    def forward(self, x):
        x = self.ca(x)
        x = self.sa(x)
        return x

class SEBlock(nn.Module):
    """Squeeze-and-Excitation Block"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        self.squeeze = nn.AdaptiveAvgPool2d(1)
        self.excitation = nn.Sequential(
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False),
            nn.Sigmoid()
        )
    
    def forward(self, x):
        b, c, _, _ = x.size()
        y = self.squeeze(x).view(b, c)
        y = self.excitation(y).view(b, c, 1, 1)
        return x * y.expand_as(x)

class DropPath(nn.Module):
    """Drop paths (Stochastic Depth) per sample"""
    def __init__(self, drop_prob=0.):
        super().__init__()
        self.drop_prob = drop_prob
    
    def forward(self, x):
        if self.drop_prob == 0. or not self.training:
            return x
        keep_prob = 1 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)
        random_tensor.floor_()
        output = x.div(keep_prob) * random_tensor
        return output

# ============================================
# 2. ENHANCED CONVNEXT BLOCK
# ============================================

class EnhancedConvNeXtBlock(nn.Module):
    """ConvNeXt Block với attention"""
    def __init__(self, dim, drop_path=0., layer_scale_init_value=1e-6, attention_type='cbam'):
        super().__init__()
        self.dwconv = nn.Conv2d(dim, dim, kernel_size=7, padding=3, groups=dim)
        self.norm = nn.LayerNorm(dim, eps=1e-6)
        self.pwconv1 = nn.Linear(dim, 4 * dim)
        self.act = nn.GELU()
        self.pwconv2 = nn.Linear(4 * dim, dim)
        
        self.gamma = nn.Parameter(
            layer_scale_init_value * torch.ones((dim)), 
            requires_grad=True
        ) if layer_scale_init_value > 0 else None
        
        self.drop_path = DropPath(drop_path) if drop_path > 0. else nn.Identity()
        
        # Attention
        if attention_type == 'cbam':
            self.attention = CBAM(dim)
        elif attention_type == 'se':
            self.attention = SEBlock(dim)
        else:
            self.attention = nn.Identity()
    
    def forward(self, x):
        input = x
        x = self.dwconv(x)
        x = x.permute(0, 2, 3, 1)
        x = self.norm(x)
        x = self.pwconv1(x)
        x = self.act(x)
        x = self.pwconv2(x)
        if self.gamma is not None:
            x = self.gamma * x
        x = x.permute(0, 3, 1, 2)
        
        # Apply attention
        x = self.attention(x)
        
        x = input + self.drop_path(x)
        return x

# ============================================
# 3. MEDICAL CONVNEXT MODEL
# ============================================

class MedicalConvNeXt(nn.Module):
    """
    ConvNeXt-Tiny Enhanced for Medical Imaging
    Sử dụng pretrained weights và thêm attention modules
    """
    def __init__(
        self,
        num_classes=2,
        drop_path_rate=0.2,
        attention_types=['cbam', 'se', 'cbam', 'se'],
        pretrained=True
    ):
        super().__init__()
        
        # Load pretrained ConvNeXt-Tiny
        if pretrained:
            self.backbone = timm.create_model(
                'convnext_tiny',
                pretrained=True,
                num_classes=0  # Remove classification head
            )
            print("✓ Loaded pretrained ConvNeXt-Tiny weights")
        else:
            raise NotImplementedError("Non-pretrained version not implemented")
        
        # Get feature dimension (768 for tiny)
        self.feature_dim = self.backbone.num_features
        
        # Medical classification head với regularization
        self.head = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            nn.Dropout(0.5),
            nn.Linear(self.feature_dim, 512),
            nn.BatchNorm1d(512),
            nn.ReLU(inplace=True),
            nn.Dropout(0.3),
            nn.Linear(512, 256),
            nn.BatchNorm1d(256),
            nn.ReLU(inplace=True),
            nn.Dropout(0.2),
            nn.Linear(256, num_classes)
        )
        
        self._init_head()
    
    def _init_head(self):
        """Initialize classification head"""
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                nn.init.trunc_normal_(m.weight, std=0.02)
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.BatchNorm1d):
                nn.init.constant_(m.weight, 1)
                nn.init.constant_(m.bias, 0)
    
    def forward(self, x):
        features = self.backbone.forward_features(x)
        output = self.head(features)
        return output

# ============================================
# 4. DATASET CHO MULTI-MAGNIFICATION
# ============================================

class MultiMagnificationDataset(Dataset):
    """
    Dataset cho cấu trúc dữ liệu có nhiều độ phóng đại
    
    Structure:
    dataset/train/benign/40X/*.png
    dataset/train/benign/100X/*.png
    dataset/train/malignant/40X/*.png
    ...
    """
    def __init__(self, root_dir, split='train', transform=None, 
                 magnifications=None, class_names=None):
        """
        Args:
            root_dir: Thư mục gốc (dataset/)
            split: 'train', 'validation', hoặc 'test'
            transform: Augmentation transforms
            magnifications: List độ phóng đại muốn dùng (None = dùng tất cả)
            class_names: List tên classes (None = auto detect)
        """
        self.root_dir = Path(root_dir)
        self.split = split
        self.transform = transform
        
        self.image_paths = []
        self.labels = []
        self.magnifications_list = []
        
        split_dir = self.root_dir / split
        
        if not split_dir.exists():
            raise FileNotFoundError(f"Split directory not found: {split_dir}")
        
        # Auto-detect class folders
        if class_names is None:
            class_folders = sorted([d for d in split_dir.iterdir() if d.is_dir()])
            self.class_names = [f.name for f in class_folders]
        else:
            self.class_names = class_names
            class_folders = [split_dir / cn for cn in class_names]
        
        print(f"\n{'='*60}")
        print(f"Loading {split} data from: {split_dir}")
        print(f"Classes: {self.class_names}")
        
        # Supported image formats
        image_extensions = ['*.png', '*.jpg', '*.jpeg', '*.bmp', '*.tif', '*.tiff']
        
        # Collect images từ mỗi class và magnification
        for class_idx, class_folder in enumerate(class_folders):
            if not class_folder.exists():
                print(f"⚠ Warning: Class folder not found: {class_folder}")
                continue
            
            # Check for magnification folders
            mag_folders = sorted([d for d in class_folder.iterdir() if d.is_dir()])
            
            if len(mag_folders) == 0:
                # Không có magnification folders, load trực tiếp từ class folder
                print(f"  Loading from {class_folder.name}/ (no magnification subfolders)")
                for ext in image_extensions:
                    images = glob.glob(str(class_folder / ext))
                    self.image_paths.extend(images)
                    self.labels.extend([class_idx] * len(images))
                    self.magnifications_list.extend(['unknown'] * len(images))
            else:
                # Có magnification folders
                for mag_folder in mag_folders:
                    mag_name = mag_folder.name
                    
                    # Skip nếu không trong list magnifications
                    if magnifications is not None and mag_name not in magnifications:
                        continue
                    
                    images = []
                    for ext in image_extensions:
                        images.extend(glob.glob(str(mag_folder / ext)))
                    
                    if len(images) > 0:
                        print(f"  {class_folder.name}/{mag_name}: {len(images)} images")
                        self.image_paths.extend(images)
                        self.labels.extend([class_idx] * len(images))
                        self.magnifications_list.extend([mag_name] * len(images))
        
        print(f"Total {split} samples: {len(self.image_paths)}")
        print(f"{'='*60}\n")
        
        if len(self.image_paths) == 0:
            raise ValueError(f"No images found in {split_dir}")
    
    def __len__(self):
        return len(self.image_paths)
    
    def __getitem__(self, idx):
        img_path = self.image_paths[idx]
        label = self.labels[idx]
        magnification = self.magnifications_list[idx]
        
        # Load image
        image = Image.open(img_path).convert('RGB')
        
        if self.transform:
            image = self.transform(image)
        
        return image, label
    
    def get_class_distribution(self):
        """Thống kê phân bố classes"""
        from collections import Counter
        return Counter(self.labels)

# ============================================
# 5. DATA TRANSFORMS
# ============================================

def get_medical_transforms(image_size=224, is_training=True):
    """Medical-specific data augmentation"""
    if is_training:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandomVerticalFlip(p=0.5),
            transforms.RandomRotation(20),
            transforms.RandomAffine(
                degrees=0,
                translate=(0.1, 0.1),
                scale=(0.9, 1.1),
                shear=10
            ),
            transforms.ColorJitter(
                brightness=0.2,
                contrast=0.2,
                saturation=0.1,
                hue=0.05
            ),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            ),
            transforms.RandomErasing(p=0.2, scale=(0.02, 0.1))
        ])
    else:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            )
        ])

# ============================================
# 6. TRAINING FUNCTIONS
# ============================================

def train_epoch(model, dataloader, criterion, optimizer, device, epoch):
    """Train one epoch"""
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    
    for batch_idx, (images, labels) in enumerate(dataloader):
        images = images.to(device)
        labels = labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(images)
        loss = criterion(outputs, labels)
        loss.backward()
        
        # Gradient clipping
        torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
        
        optimizer.step()
        
        running_loss += loss.item()
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        if batch_idx % 10 == 0:
            print(f'Epoch [{epoch}] Batch [{batch_idx}/{len(dataloader)}] '
                  f'Loss: {loss.item():.4f} Acc: {100.*correct/total:.2f}%')
    
    epoch_loss = running_loss / len(dataloader)
    epoch_acc = 100. * correct / total
    
    return epoch_loss, epoch_acc

def validate(model, dataloader, criterion, device):
    """Validate model"""
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    
    all_preds = []
    all_labels = []
    all_probs = []
    
    with torch.no_grad():
        for images, labels in dataloader:
            images = images.to(device)
            labels = labels.to(device)
            
            outputs = model(images)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item()
            
            probs = F.softmax(outputs, dim=1)
            _, predicted = outputs.max(1)
            
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
            all_probs.extend(probs.cpu().numpy())
    
    val_loss = running_loss / len(dataloader)
    val_acc = 100. * correct / total
    
    return val_loss, val_acc, all_preds, all_labels, all_probs

# ============================================
# 7. MAIN TRAINING
# ============================================

def main():
    """Main training function"""
    
    # ==================== CONFIG ====================
    CONFIG = {
        'data_root': './dataset',  # ← THAY ĐỔI PATH NÀY
        'num_classes': 2,  # benign vs malignant
        'image_size': 224,
        'batch_size': 16,
        'num_epochs': 100,
        'learning_rate': 1e-4,
        'weight_decay': 1e-4,
        'device': 'cuda' if torch.cuda.is_available() else 'cpu',
        'num_workers': 4,
        'save_dir': 'checkpoints',
        
        # Magnification options
        'magnifications': None,  # None = dùng tất cả, hoặc ['40X', '100X', '200X', '400X']
        'class_names': ['benign', 'malignant'],
    }
    
    print("="*60)
    print("MEDICAL CONVNEXT-TINY TRAINING")
    print("="*60)
    print(f"Device: {CONFIG['device']}")
    print(f"Data root: {CONFIG['data_root']}")
    print(f"Image size: {CONFIG['image_size']}")
    print(f"Batch size: {CONFIG['batch_size']}")
    print(f"Epochs: {CONFIG['num_epochs']}")
    print("="*60)
    
    Path(CONFIG['save_dir']).mkdir(exist_ok=True)
    
    # ==================== DATA ====================
    train_transform = get_medical_transforms(CONFIG['image_size'], is_training=True)
    val_transform = get_medical_transforms(CONFIG['image_size'], is_training=False)
    
    train_dataset = MultiMagnificationDataset(
        root_dir=CONFIG['data_root'],
        split='train',
        transform=train_transform,
        magnifications=CONFIG['magnifications'],
        class_names=CONFIG['class_names']
    )
    
    val_dataset = MultiMagnificationDataset(
        root_dir=CONFIG['data_root'],
        split='validation',
        transform=val_transform,
        magnifications=CONFIG['magnifications'],
        class_names=CONFIG['class_names']
    )
    
    # Class distribution
    print("Class distribution:")
    train_dist = train_dataset.get_class_distribution()
    val_dist = val_dataset.get_class_distribution()
    for class_idx, class_name in enumerate(CONFIG['class_names']):
        print(f"  {class_name}: Train={train_dist.get(class_idx, 0)}, Val={val_dist.get(class_idx, 0)}")
    
    train_loader = DataLoader(
        train_dataset,
        batch_size=CONFIG['batch_size'],
        shuffle=True,
        num_workers=CONFIG['num_workers'],
        pin_memory=True,
        drop_last=True
    )
    
    val_loader = DataLoader(
        val_dataset,
        batch_size=CONFIG['batch_size'],
        shuffle=False,
        num_workers=CONFIG['num_workers'],
        pin_memory=True
    )
    
    # ==================== MODEL ====================
    print("\nInitializing model...")
    model = MedicalConvNeXt(
        num_classes=CONFIG['num_classes'],
        drop_path_rate=0.2,
        pretrained=True
    ).to(CONFIG['device'])
    
    total_params = sum(p.numel() for p in model.parameters())
    trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"Total parameters: {total_params/1e6:.2f}M")
    print(f"Trainable parameters: {trainable_params/1e6:.2f}M")
    
    # ==================== TRAINING ====================
    criterion = nn.CrossEntropyLoss(label_smoothing=0.1)
    
    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=CONFIG['learning_rate'],
        weight_decay=CONFIG['weight_decay']
    )
    
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
        optimizer,
        T_max=CONFIG['num_epochs'],
        eta_min=1e-6
    )
    
    best_val_acc = 0.0
    
    print("\n" + "="*60)
    print("STARTING TRAINING")
    print("="*60)
    
    for epoch in range(1, CONFIG['num_epochs'] + 1):
        print(f"\n{'='*60}")
        print(f"Epoch {epoch}/{CONFIG['num_epochs']}")
        print(f"{'='*60}")
        
        train_loss, train_acc = train_epoch(
            model, train_loader, criterion, optimizer, CONFIG['device'], epoch
        )
        
        val_loss, val_acc, val_preds, val_labels, val_probs = validate(
            model, val_loader, criterion, CONFIG['device']
        )
        
        scheduler.step()
        current_lr = optimizer.param_groups[0]['lr']
        
        print(f"\n{'='*60}")
        print(f"Epoch {epoch} Summary:")
        print(f"Train Loss: {train_loss:.4f} | Train Acc: {train_acc:.2f}%")
        print(f"Val Loss: {val_loss:.4f} | Val Acc: {val_acc:.2f}%")
        print(f"Learning Rate: {current_lr:.6f}")
        print(f"{'='*60}")
        
        # Detailed metrics every 5 epochs
        if epoch % 5 == 0:
            from sklearn.metrics import classification_report, confusion_matrix
            
            print("\nClassification Report:")
            print(classification_report(
                val_labels, 
                val_preds,
                target_names=CONFIG['class_names'],
                digits=4
            ))
            
            print("\nConfusion Matrix:")
            cm = confusion_matrix(val_labels, val_preds)
            print(cm)
        
        # Save best model
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            
            checkpoint = {
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'val_acc': val_acc,
                'config': CONFIG
            }
            
            torch.save(
                checkpoint,
                Path(CONFIG['save_dir']) / 'best_medical_convnext.pth'
            )
            print(f"\n✅ Saved best model! Val Acc: {val_acc:.2f}%")
    
    print("\n" + "="*60)
    print("TRAINING COMPLETE!")
    print(f"Best Validation Accuracy: {best_val_acc:.2f}%")
    print("="*60)

if __name__ == '__main__':
    main()
