import matplotlib.pyplot as plt

def plot_training_history(history, save_dir='.', prefix='training_history'):
    """Vẽ training history: Loss, Accuracy, Recall + Learning Rate trên trục phụ với legend chung"""
    epochs = list(range(1, len(history['train_loss']) + 1))

    # Hàm phụ để vẽ Learning Rate trên trục phụ và trả về line để đưa vào legend
    def add_lr(ax, epochs, lr):
        l, = ax.plot(epochs, lr, marker='^', linewidth=2, color='red', label='Tốc độ học (Learning Rate)', alpha=0.3)
        ax.set_ylabel("Tốc độ học (Learning Rate)")
        ax.set_yscale('log')
        return [l]

    # === Loss + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()
    l1, = ax1.plot(epochs, history['train_loss'], marker='o', linewidth=2, label='Huấn luyện (Train)', color='blue')
    l2, = ax1.plot(epochs, history['val_loss'], marker='s', linewidth=2, label='Kiểm định (Validation)', color='green')

    ax1.set_ylim(0.4, 0.75)
    ax1.set_xticks(epochs)
    for x, y in zip(epochs, history['train_loss']): ax1.text(x, y+0.015, f"{y:.3f}", fontsize=9, ha='center', alpha=1)
    for x, y in zip(epochs, history['val_loss']): ax1.text(x, y-0.04, f"{y:.3f}", fontsize=9, ha='center', alpha=1)

    lr_lines = add_lr(ax2, epochs, history['lr'])
    ax1.set_xlabel("Lượt huấn luyện (Epoch)")
    ax1.set_ylabel("Giá trị mất mát (Loss)")
    ax1.set_title("GIÁ TRỊ MẤT MÁT THEO TỪNG LƯỢT HUẤN LUYỆN", fontsize=14, fontweight="bold")
    ax1.grid(alpha=0.3)

    # Legend chung bao gồm Learning Rate
    plt.legend(handles=[l1, l2] + lr_lines, loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=3, frameon=False)
    plt.tight_layout()
    plt.savefig(f"{save_dir}/{prefix}_loss_lr.png", dpi=300)
    plt.close()

    # === Accuracy + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()
    l1, = ax1.plot(epochs, [x/100 for x in history['train_acc']], marker='o', linewidth=2, label='Huấn luyện (Train)', color='blue')
    l2, = ax1.plot(epochs, [x/100 for x in history['val_acc']], marker='s', linewidth=2, label='Kiểm định (Validation)', color='green')

    ax1.set_ylim(0.45, 1)
    ax1.set_xticks(epochs)
    for x, y in zip(epochs, [x/100 for x in history['train_acc']]): ax1.text(x, y-0.05, f"{y:.3f}", fontsize=9, ha='center', alpha=1)
    for x, y in zip(epochs, [x/100 for x in history['val_acc']]): ax1.text(x, y+0.02, f"{y:.3f}", fontsize=9, ha='center', alpha=1)
    
    
    lr_lines = add_lr(ax2, epochs, history['lr'])
    ax1.set_xlabel("Lượt huấn luyện (Epoch)")
    ax1.set_ylabel("Độ chính xác tổng thể (Accuracy)")
    ax1.set_title("ĐỘ CHÍNH XÁC TỔNG THỂ THEO TỪNG LƯỢT HUẤN LUYỆN", fontsize=14, fontweight="bold")
    ax1.grid(alpha=0.3)
    plt.legend(handles=[l1, l2] + lr_lines, loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=3, frameon=False)
    plt.tight_layout()
    plt.savefig(f"{save_dir}/{prefix}_accuracy.png", dpi=300)
    plt.close()

    # === Recall + Learning Rate ===
    fig, ax1 = plt.subplots(figsize=(9,5))
    ax2 = ax1.twinx()
    l1, = ax1.plot(epochs, history['train_recall'], marker='o', linewidth=2, label='Huấn luyện (Train)', color='blue')
    l2, = ax1.plot(epochs, history['val_recall'], marker='s', linewidth=2, label='Kiểm định (Validation)', color='green')
    lr_lines = add_lr(ax2, epochs, history['lr'])

    ax1.set_ylim(0.45, 1)
    ax1.set_xticks(epochs)
    for x, y in zip(epochs, history['train_recall']): ax1.text(x, y-0.05, f"{y:.3f}", fontsize=9, ha='center', alpha=1)
    for x, y in zip(epochs, history['val_recall']): ax1.text(x, y+0.02, f"{y:.3f}", fontsize=9, ha='center', alpha=1)

    ax1.set_xlabel("Lượt huấn luyện (Epoch)")
    ax1.set_ylabel("Độ nhạy (Recall)")
    ax1.set_title("ĐỘ NHẠY THEO TỪNG LƯỢT HUẤN LUYỆN", fontsize=14, fontweight="bold")
    ax1.grid(alpha=0.3)
    plt.legend(handles=[l1, l2] + lr_lines, loc="upper center", bbox_to_anchor=(0.5, -0.15), ncol=3, frameon=False)
    plt.tight_layout()
    plt.savefig(f"{save_dir}/{prefix}_recall.png", dpi=300)
    plt.close()

    print(f"✓ Saved all training history plots with Learning Rate to {save_dir}")
    
plot_training_history(history)
