import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
import timm
import numpy as np
from pathlib import Path
import glob
from PIL import Image
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import (
    confusion_matrix, classification_report, 
    roc_curve, auc, precision_recall_curve, 
    average_precision_score, accuracy_score, 
    precision_score, recall_score, f1_score
)

# ============================================
# 1. IMPROVED MODEL - CHỐNG OVERFITTING
# ============================================

class ImprovedMedicalConvNeXt(nn.Module):
    """
    ConvNeXt-Tiny với các kỹ thuật chống overfitting:
    - Dropout cao (0.4)
    - Intermediate layer
    - Stochastic depth (drop_path_rate)
    """
    def __init__(self, num_classes=2, pretrained=True, dropout_rate=0.4):
        super().__init__()
        
        # Load pretrained với drop_path_rate
        if pretrained:
            self.backbone = timm.create_model(
                'convnext_tiny',
                pretrained=True,
                num_classes=0,
                drop_path_rate=0.2  # ✅ STOCHASTIC DEPTH
            )
            print("✓ Loaded pretrained ConvNeXt-Tiny weights with drop_path=0.2")
        else:
            self.backbone = timm.create_model(
                'convnext_tiny',
                pretrained=False,
                num_classes=0,
                drop_path_rate=0.2
            )
        
        self.feature_dim = self.backbone.num_features
        
        # ✅ IMPROVED HEAD - Nhiều regularization hơn
        self.head = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            nn.Dropout(dropout_rate),  # 0.4
            nn.Linear(self.feature_dim, 256),
            nn.LayerNorm(256),
            nn.GELU(),
            nn.Dropout(dropout_rate * 0.5),  # 0.2
            nn.Linear(256, num_classes)
        )
        
        self._init_head()
    
    def _init_head(self):
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                nn.init.trunc_normal_(m.weight, std=0.02)
                if m.bias is not None:
                    nn.init.constant_(m.bias, 0)
    
    def forward(self, x):
        features = self.backbone.forward_features(x)
        return self.head(features)

# ============================================
# 2. DATASET (giữ nguyên)
# ============================================

class MultiMagnificationDataset(Dataset):
    def __init__(self, root_dir, split='train', transform=None, magnifications=None, class_names=None):
        self.root_dir = Path(root_dir)
        self.split = split
        self.transform = transform
        self.image_paths = []
        self.labels = []
        
        split_dir = self.root_dir / split
        if not split_dir.exists():
            raise FileNotFoundError(f"Split directory not found: {split_dir}")
        
        if class_names is None:
            class_folders = sorted([d for d in split_dir.iterdir() if d.is_dir()])
            self.class_names = [f.name for f in class_folders]
        else:
            self.class_names = class_names
            class_folders = [split_dir / cn for cn in class_names]
        
        print(f"\n{'='*60}")
        print(f"Loading {split} data from: {split_dir}")
        print(f"Classes: {self.class_names}")
        
        image_extensions = ['*.png', '*.jpg', '*.jpeg', '*.bmp', '*.tif', '*.tiff']
        
        for class_idx, class_folder in enumerate(class_folders):
            if not class_folder.exists():
                continue
            
            mag_folders = sorted([d for d in class_folder.iterdir() if d.is_dir()])
            
            if len(mag_folders) == 0:
                for ext in image_extensions:
                    images = glob.glob(str(class_folder / ext))
                    self.image_paths.extend(images)
                    self.labels.extend([class_idx] * len(images))
            else:
                for mag_folder in mag_folders:
                    if magnifications and mag_folder.name not in magnifications:
                        continue
                    images = []
                    for ext in image_extensions:
                        images.extend(glob.glob(str(mag_folder / ext)))
                    if images:
                        print(f"  {class_folder.name}/{mag_folder.name}: {len(images)} images")
                        self.image_paths.extend(images)
                        self.labels.extend([class_idx] * len(images))
        
        print(f"Total {split} samples: {len(self.image_paths)}")
        print(f"{'='*60}\n")
    
    def __len__(self):
        return len(self.image_paths)
    
    def __getitem__(self, idx):
        try:
            image = Image.open(self.image_paths[idx]).convert('RGB')
        except:
            image = Image.new('RGB', (224, 224), (0, 0, 0))
        return self.transform(image) if self.transform else image, self.labels[idx]

# ============================================
# 3. IMPROVED DATA TRANSFORMS
# ============================================

def get_improved_transforms(image_size=224, is_training=True):
    """✅ STRONGER AUGMENTATION"""
    if is_training:
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandomVerticalFlip(p=0.5),
            transforms.RandomRotation(20),  # Tăng lên 20
            transforms.RandomAffine(  # ✅ THÊM MỚI
                degrees=0,
                translate=(0.1, 0.1),
                scale=(0.9, 1.1)
            ),
            transforms.ColorJitter(  # ✅ Tăng intensity
                brightness=0.2,
                contrast=0.2,
                saturation=0.1,
                hue=0.05
            ),
            transforms.ToTensor(),
             transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            ),
            transforms.RandomErasing(p=0.3, scale=(0.02, 0.1)),  # ✅ THÊM MỚI
        ])
    return transforms.Compose([
        transforms.Resize((image_size, image_size)),
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225])
    ])

# ============================================
# 4. MIXUP AUGMENTATION
# ============================================

def mixup_data(x, y, alpha=0.2):
    """✅ MIXUP - Kỹ thuật quan trọng nhất chống overfitting"""
    if alpha > 0:
        lam = np.random.beta(alpha, alpha)
    else:
        lam = 1
    
    batch_size = x.size(0)
    index = torch.randperm(batch_size).to(x.device)
    
    mixed_x = lam * x + (1 - lam) * x[index]
    y_a, y_b = y, y[index]
    
    return mixed_x, y_a, y_b, lam

def mixup_criterion(criterion, pred, y_a, y_b, lam):
    """Loss function cho mixup"""
    return lam * criterion(pred, y_a) + (1 - lam) * criterion(pred, y_b)

# ============================================
# 5. EARLY STOPPING
# ============================================

class EarlyStopping:
    def __init__(self, patience=15, min_delta=0.0005, verbose=True):
        self.patience = patience
        self.min_delta = min_delta
        self.verbose = verbose
        self.counter = 0
        self.best_score = None
        self.early_stop = False
        self.val_acc_max = 0
    
    def __call__(self, val_acc):
        if self.best_score is None:
            self.best_score = val_acc
            self.val_acc_max = val_acc
        elif val_acc < self.best_score + self.min_delta:
            self.counter += 1
            if self.verbose and self.counter % 3 == 0:
                print(f'⚠ EarlyStopping counter: {self.counter}/{self.patience}')
            if self.counter >= self.patience:
                self.early_stop = True
        else:
            self.best_score = val_acc
            self.val_acc_max = val_acc
            self.counter = 0
        return self.early_stop

# ============================================
# 6. EVALUATION FUNCTIONS
# ============================================

def plot_confusion_matrix(y_true, y_pred, save_path='confusion_matrix.png'):
    cm = confusion_matrix(y_true, y_pred)
    labels = ['Lành tính (Benign)', 'Ác tính (Malignant)']
    
    plt.figure(figsize=(10, 8))
    sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', xticklabels=labels, yticklabels=labels,
                cbar_kws={'label': 'Số lượng'}, annot_kws={'size': 14, 'weight': 'bold'})
    plt.ylabel('Giá trị thực tế', fontsize=12, fontweight='bold')
    plt.xlabel('Giá trị dự đoán', fontsize=12, fontweight='bold')
    plt.title('MA TRẬN NHẦM LẪN', fontsize=14, fontweight="bold", pad=20)
    
    acc = (cm[0,0] + cm[1,1]) / cm.sum()
    plt.text(0.5, -0.15, f'Độ chính xác: {acc:.2%}', ha='center', va='center',
             transform=plt.gca().transAxes, fontsize=11, fontweight='bold')
    
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.close()

def plot_roc_curve(y_true, y_probs, save_path='roc_curve.png'):
    fpr, tpr, thresholds = roc_curve(y_true, y_probs)
    roc_auc = auc(fpr, tpr)
    optimal_idx = np.argmax(tpr - fpr)
    
    plt.figure(figsize=(10, 8))
    plt.plot(fpr, tpr, 'darkorange', lw=2, label=f'ROC (AUC={roc_auc:.4f})')
    plt.plot([0,1], [0,1], 'navy', lw=2, ls='--', label='Ngẫu nhiên')
    plt.scatter(fpr[optimal_idx], tpr[optimal_idx], marker='o', color='red', s=100, zorder=3)
    plt.xlabel('False Positive Rate', fontsize=12, fontweight='bold')
    plt.ylabel('True Positive Rate', fontsize=12, fontweight='bold')
    plt.title('ĐƯỜNG CONG ROC', fontsize=14, fontweight="bold", pad=20)
    plt.legend(loc="lower right")
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.close()
    return roc_auc

def plot_per_class_metrics(y_true, y_pred, save_path='per_class_metrics.png'):
    precision = precision_score(y_true, y_pred, average=None)
    recall = recall_score(y_true, y_pred, average=None)
    f1 = f1_score(y_true, y_pred, average=None)
    
    labels = ['Lành tính', 'Ác tính']
    x = np.arange(len(labels))
    width = 0.25
    
    fig, ax = plt.subplots(figsize=(10, 6))
    bars1 = ax.bar(x-width, precision, width, label='Precision', color='skyblue', edgecolor='black')
    bars2 = ax.bar(x, recall, width, label='Recall', color='lightcoral', edgecolor='black')
    bars3 = ax.bar(x+width, f1, width, label='F1-Score', color='lightgreen', edgecolor='black')
    
    for bars in [bars1, bars2, bars3]:
        for bar in bars:
            h = bar.get_height()
            ax.text(bar.get_x()+bar.get_width()/2., h, f'{h:.3f}',
                   ha='center', va='bottom', fontsize=10, fontweight='bold')
    
    ax.set_ylabel('Giá trị', fontsize=12, fontweight='bold')
    ax.set_title('CÁC CHỈ SỐ ĐÁNH GIÁ', fontsize=14, fontweight="bold", pad=20)
    ax.set_xticks(x)
    ax.set_xticklabels(labels)
    ax.legend()
    ax.set_ylim([0, 1.1])
    ax.grid(axis='y', alpha=0.3)
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.close()

def comprehensive_evaluation(model, dataloader, device, save_dir='results'):
    Path(save_dir).mkdir(exist_ok=True, parents=True)
    
    model.eval()
    all_preds, all_labels, all_probs = [], [], []
    
    with torch.no_grad():
        for images, labels in dataloader:
            images = images.to(device)
            outputs = model(images)
            probs = F.softmax(outputs, dim=1)
            _, predicted = outputs.max(1)
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.numpy())
            all_probs.extend(probs.cpu().numpy())
    
    y_true = np.array(all_labels)
    y_pred = np.array(all_preds)
    y_probs = np.array(all_probs)[:, 1]
    
    print("\n" + "="*70)
    print("ĐÁNH GIÁ TOÀN DIỆN")
    print("="*70)
    print("\nClassification Report:")
    print(classification_report(y_true, y_pred, 
          target_names=['Lành tính', 'Ác tính'], digits=4))
    
    plot_confusion_matrix(y_true, y_pred, f'{save_dir}/confusion_matrix.png')
    roc_auc = plot_roc_curve(y_true, y_probs, f'{save_dir}/roc_curve.png')
    plot_per_class_metrics(y_true, y_pred, f'{save_dir}/per_class_metrics.png')
    
    cm = confusion_matrix(y_true, y_pred)
    tn, fp, fn, tp = cm.ravel()
    
    print("\n" + "="*70)
    print("TỔNG HỢP")
    print("="*70)
    print(f"Accuracy: {accuracy_score(y_true, y_pred):.4f}")
    print(f"ROC-AUC: {roc_auc:.4f}")
    print(f"Precision (macro): {precision_score(y_true, y_pred, average='macro'):.4f}")
    print(f"Recall (macro): {recall_score(y_true, y_pred, average='macro'):.4f}")
    print(f"F1-Score (macro): {f1_score(y_true, y_pred, average='macro'):.4f}")
    print(f"\nTN={tn}, FP={fp}, FN={fn}, TP={tp}")
    print(f"Specificity: {tn/(tn+fp):.4f}")
    print(f"Sensitivity: {tp/(tp+fn):.4f}")
    print("="*70)
    
    print(f"\n✓ Saved plots to {save_dir}/")
    return {'roc_auc': roc_auc}

# ============================================
# 7. IMPROVED TRAINING FUNCTIONS
# ============================================

def train_epoch_with_mixup(model, dataloader, criterion, optimizer, device, 
                          scaler=None, use_mixup=True, mixup_alpha=0.2):
    """✅ Training với MIXUP"""
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    
    for images, labels in dataloader:
        images, labels = images.to(device), labels.to(device)
        
        # ✅ Apply Mixup (50% chance)
        use_mixup_batch = use_mixup and torch.rand(1).item() < 0.5
        if use_mixup_batch:
            images, labels_a, labels_b, lam = mixup_data(images, labels, mixup_alpha)
        
        optimizer.zero_grad()
        
        if scaler:
            with torch.amp.autocast('cuda'):
                outputs = model(images)
                if use_mixup_batch:
                    loss = mixup_criterion(criterion, outputs, labels_a, labels_b, lam)
                else:
                    loss = criterion(outputs, labels)
            
            scaler.scale(loss).backward()
            # ✅ Gradient clipping
            scaler.unscale_(optimizer)
            torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
            scaler.step(optimizer)
            scaler.update()
        else:
            outputs = model(images)
            if use_mixup_batch:
                loss = mixup_criterion(criterion, outputs, labels_a, labels_b, lam)
            else:
                loss = criterion(outputs, labels)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
            optimizer.step()
        
        running_loss += loss.item()
        _, predicted = outputs.max(1)
        
        if not use_mixup_batch:
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
        else:
            # Approximate accuracy for mixup
            total += labels_a.size(0)
            correct += (lam * predicted.eq(labels_a).sum().item() + 
                       (1-lam) * predicted.eq(labels_b).sum().item())
    
    return running_loss / len(dataloader), 100. * correct / total

def validate(model, dataloader, criterion, device):
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    
    with torch.no_grad():
        for images, labels in dataloader:
            images, labels = images.to(device), labels.to(device)
            outputs = model(images)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item()
            _, predicted = outputs.max(1)
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
    
    return running_loss/len(dataloader), 100.*correct/total

# ============================================
# 8. MAIN
# ============================================

def main():
    # ✅ IMPROVED CONFIG - Chống Overfitting
    CONFIG = {
        'data_root': './train_data',
        'num_classes': 2,
        'batch_size': 16,  # ✅ Giảm xuống 16
        'num_epochs': 50,  # ✅ Giảm xuống 50
        'learning_rate': 1e-4,  # ✅ Giảm xuống 1e-4
        'weight_decay': 0.1,  # ✅ Tăng lên 0.1
        'dropout_rate': 0.4,  # ✅ Tăng lên 0.4
        'mixup_alpha': 0.2,  # ✅ THÊM MỚI
        'device': 'cuda' if torch.cuda.is_available() else 'cpu',
        'save_dir': 'checkpoints',
        'patience': 15,  # ✅ Tăng patience
        'warmup_epochs': 3,  # ✅ Giảm warmup
        'class_names': ['benign', 'malignant'],
    }
    
    print("="*70)
    print("IMPROVED MEDICAL CONVNEXT - ANTI-OVERFITTING")
    print("="*70)
    print(f"✅ Dropout: {CONFIG['dropout_rate']}")
    print(f"✅ Mixup Alpha: {CONFIG['mixup_alpha']}")
    print(f"✅ Batch Size: {CONFIG['batch_size']}")
    print(f"✅ Learning Rate: {CONFIG['learning_rate']}")
    print(f"✅ Weight Decay: {CONFIG['weight_decay']}")
    print("="*70)
    
    Path(CONFIG['save_dir']).mkdir(exist_ok=True)
    
    # Data với stronger augmentation
    train_dataset = MultiMagnificationDataset(
        CONFIG['data_root'], 'train', 
        get_improved_transforms(224, True),  # ✅ IMPROVED
        class_names=CONFIG['class_names']
    )
    val_dataset = MultiMagnificationDataset(
        CONFIG['data_root'], 'validation',
        get_improved_transforms(224, False),
        class_names=CONFIG['class_names']
    )
    
    train_loader = DataLoader(train_dataset, batch_size=CONFIG['batch_size'], 
                             shuffle=True, num_workers=0, pin_memory=True, drop_last=True)
    val_loader = DataLoader(val_dataset, batch_size=CONFIG['batch_size'],
                           shuffle=False, num_workers=0, pin_memory=True)
    
    # ✅ IMPROVED MODEL
    model = ImprovedMedicalConvNeXt(
        num_classes=CONFIG['num_classes'],
        pretrained=True,
        dropout_rate=CONFIG['dropout_rate']
    ).to(CONFIG['device'])
    
    print(f"Total parameters: {sum(p.numel() for p in model.parameters())/1e6:.2f}M")
    
    # ✅ LABEL SMOOTHING
    criterion = nn.CrossEntropyLoss(label_smoothing=0.1)
    
    # Freeze backbone initially
    for param in model.backbone.parameters():
        param.requires_grad = False
    print("\n✓ Backbone frozen for first 3 epochs (warmup)")
    
    optimizer = torch.optim.AdamW(
        filter(lambda p: p.requires_grad, model.parameters()),
        lr=CONFIG['learning_rate'],
        weight_decay=CONFIG['weight_decay']
    )
    
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
        optimizer,
        T_max=CONFIG['num_epochs']-CONFIG['warmup_epochs'],
        eta_min=1e-6
    )
    
    scaler = torch.amp.GradScaler('cuda') if CONFIG['device']=='cuda' else None
    early_stopping = EarlyStopping(patience=CONFIG['patience'])
    
    best_val_acc = 0.0
    
    print("\n" + "="*70)
    print("STARTING TRAINING")
    print("="*70)
    
    # Training loop
    for epoch in range(1, CONFIG['num_epochs']+1):
        print(f"\n{'='*70}")
        print(f"Epoch {epoch}/{CONFIG['num_epochs']}")
        print(f"{'='*70}")
        
        if epoch == CONFIG['warmup_epochs']+1:
            print("\n🔥 Unfreezing backbone...")
            for param in model.backbone.parameters():
                param.requires_grad = True
            optimizer = torch.optim.AdamW(
                model.parameters(),
                lr=CONFIG['learning_rate']*0.1,
                weight_decay=CONFIG['weight_decay']
            )
            print("✓ Backbone unfrozen, LR reduced")
        
        # ✅ Train với MIXUP
        train_loss, train_acc = train_epoch_with_mixup(
            model, train_loader, criterion, optimizer, CONFIG['device'],
            scaler, use_mixup=True, mixup_alpha=CONFIG['mixup_alpha']
        )
        
        val_loss, val_acc = validate(model, val_loader, criterion, CONFIG['device'])
        
        if epoch > CONFIG['warmup_epochs']:
            scheduler.step()
        
        current_lr = optimizer.param_groups[0]['lr']
        
        print(f"\nTrain Loss: {train_loss:.4f} | Train Acc: {train_acc:.2f}%")
        print(f"Val Loss: {val_loss:.4f} | Val Acc: {val_acc:.2f}%")
        print(f"Learning Rate: {current_lr:.6f}")
        print(f"Gap: {train_acc - val_acc:.2f}%")  # ✅ Monitor gap
        
        if val_acc > best_val_acc:
            best_val_acc = val_acc
            torch.save({
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'val_acc': val_acc,
                'train_acc': train_acc
            }, Path(CONFIG['save_dir'])/'best_model.pth')
            print(f"✅ Saved best model! Val Acc: {val_acc:.2f}%")
        
        if early_stopping(val_acc):
            print(f"\n🛑 Early stopping at epoch {epoch}")
            break
    
    # Final evaluation
    print("\n" + "="*70)
    print("FINAL EVALUATION")
    print("="*70)
    
    checkpoint = torch.load(Path(CONFIG['save_dir'])/'best_model.pth')
    model.load_state_dict(checkpoint['model_state_dict'])
    
    eval_results = comprehensive_evaluation(
        model, val_loader, CONFIG['device'], CONFIG['save_dir']
    )
    
    print(f"\n✅ Training complete!")
    print(f"✅ Best Val Acc: {best_val_acc:.2f}%")
    print(f"✅ Best Train Acc: {checkpoint['train_acc']:.2f}%")
    print(f"✅ Train-Val Gap: {checkpoint['train_acc'] - best_val_acc:.2f}%")
    print(f"✅ ROC-AUC: {eval_results['roc_auc']:.4f}")

if __name__ == '__main__':
    main()
