import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader
from torchvision import datasets, transforms
import torch.nn.functional as F
from timm.models.layers import trunc_normal_, DropPath
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import confusion_matrix, recall_score, precision_score, f1_score, classification_report
import numpy as np

# ==================== MedConvNeXt Architecture ====================

class CBAM(nn.Module):
    """Channel and Spatial Attention Module"""
    def __init__(self, channels, reduction=16):
        super().__init__()
        # Channel Attention
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        self.fc = nn.Sequential(
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False)
        )
        
        # Spatial Attention
        self.conv = nn.Conv2d(2, 1, kernel_size=7, padding=3, bias=False)
        self.sigmoid = nn.Sigmoid()
    
    def forward(self, x):
        # Channel Attention
        b, c, _, _ = x.size()
        avg_out = self.fc(self.avg_pool(x).view(b, c))
        max_out = self.fc(self.max_pool(x).view(b, c))
        channel_att = self.sigmoid(avg_out + max_out).view(b, c, 1, 1)
        x = x * channel_att
        
        # Spatial Attention
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        spatial_att = self.sigmoid(self.conv(torch.cat([avg_out, max_out], dim=1)))
        x = x * spatial_att
        
        return x


class Block(nn.Module):
    """ConvNeXt Block with optional attention"""
    def __init__(self, dim, drop_path=0., layer_scale_init_value=1e-6, use_attention=False):
        super().__init__()
        self.dwconv = nn.Conv2d(dim, dim, kernel_size=7, padding=3, groups=dim)
        self.norm = LayerNorm(dim, eps=1e-6)
        self.pwconv1 = nn.Linear(dim, 4 * dim)
        self.act = nn.GELU()
        self.pwconv2 = nn.Linear(4 * dim, dim)
        self.gamma = nn.Parameter(layer_scale_init_value * torch.ones((dim)), 
                                    requires_grad=True) if layer_scale_init_value > 0 else None
        self.drop_path = DropPath(drop_path) if drop_path > 0. else nn.Identity()
        
        # Optional attention
        self.attention = CBAM(dim) if use_attention else None

    def forward(self, x):
        input = x
        x = self.dwconv(x)
        x = x.permute(0, 2, 3, 1)
        x = self.norm(x)
        x = self.pwconv1(x)
        x = self.act(x)
        x = self.pwconv2(x)
        if self.gamma is not None:
            x = self.gamma * x
        x = x.permute(0, 3, 1, 2)
        x = input + self.drop_path(x)
        
        # Apply attention if enabled
        if self.attention is not None:
            x = self.attention(x)
        
        return x


class LayerNorm(nn.Module):
    """LayerNorm hỗ trợ channels_last và channels_first"""
    def __init__(self, normalized_shape, eps=1e-6, data_format="channels_last"):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = eps
        self.data_format = data_format
        self.normalized_shape = (normalized_shape, )
    
    def forward(self, x):
        if self.data_format == "channels_last":
            return F.layer_norm(x, self.normalized_shape, self.weight, self.bias, self.eps)
        elif self.data_format == "channels_first":
            u = x.mean(1, keepdim=True)
            s = (x - u).pow(2).mean(1, keepdim=True)
            x = (x - u) / torch.sqrt(s + self.eps)
            x = self.weight[:, None, None] * x + self.bias[:, None, None]
            return x


class FeaturePyramidNetwork(nn.Module):
    """Multi-scale Feature Aggregation inspired by FPN"""
    def __init__(self, in_channels_list, out_channels=256):
        super().__init__()
        self.lateral_convs = nn.ModuleList()
        self.fpn_convs = nn.ModuleList()
        
        for in_channels in in_channels_list:
            lateral_conv = nn.Conv2d(in_channels, out_channels, kernel_size=1)
            fpn_conv = nn.Conv2d(out_channels, out_channels, kernel_size=3, padding=1)
            self.lateral_convs.append(lateral_conv)
            self.fpn_convs.append(fpn_conv)
    
    def forward(self, features):
        """
        Args:
            features: list of features [stage1, stage2, stage3]
        Returns:
            Fused multi-scale feature
        """
        # Build top-down pathway
        laterals = [lateral_conv(feat) for lateral_conv, feat in zip(self.lateral_convs, features)]
        
        # Top-down fusion
        for i in range(len(laterals) - 1, 0, -1):
            laterals[i - 1] += F.interpolate(
                laterals[i], size=laterals[i - 1].shape[-2:], 
                mode='bilinear', align_corners=False
            )
        
        # Apply 3x3 convs
        fpn_features = [fpn_conv(lateral) for fpn_conv, lateral in zip(self.fpn_convs, laterals)]
        
        # Aggregate all scales with adaptive pooling
        target_size = fpn_features[-1].shape[-2:]  # Use smallest spatial size
        aggregated = []
        for feat in fpn_features:
            if feat.shape[-2:] != target_size:
                feat = F.adaptive_avg_pool2d(feat, target_size)
            aggregated.append(feat)
        
        # Concatenate and reduce channels
        fused = torch.cat(aggregated, dim=1)
        return fused


class MedConvNeXt(nn.Module):
    """Medical ConvNeXt with improvements for medical imaging"""
    def __init__(self, in_chans=3, num_classes=1000, 
                 depths=[3, 3, 9, 3], dims=[96, 192, 384, 768], 
                 drop_path_rate=0.1, layer_scale_init_value=1e-6, 
                 head_init_scale=1., use_fpn=True, use_attention=True,
                 dropout_rate=0.3):
        super().__init__()
        
        self.use_fpn = use_fpn
        self.use_attention = use_attention
        
        # ==================== 改进1: Gentle Stem ====================
        # Thay vì stride=4 ngay, dùng 2 conv stride=2 để giữ chi tiết
        self.downsample_layers = nn.ModuleList()
        stem = nn.Sequential(
            nn.Conv2d(in_chans, dims[0] // 2, kernel_size=3, stride=2, padding=1),  # 224 -> 112
            nn.BatchNorm2d(dims[0] // 2),
            nn.GELU(),
            nn.Conv2d(dims[0] // 2, dims[0], kernel_size=3, stride=2, padding=1),  # 112 -> 56
            LayerNorm(dims[0], eps=1e-6, data_format="channels_first")
        )
        self.downsample_layers.append(stem)
        
        # Downsample layers giữa các stages
        for i in range(3):
            downsample_layer = nn.Sequential(
                LayerNorm(dims[i], eps=1e-6, data_format="channels_first"),
                nn.Conv2d(dims[i], dims[i+1], kernel_size=2, stride=2),
            )
            self.downsample_layers.append(downsample_layer)

        # ==================== Stages with Attention ====================
        self.stages = nn.ModuleList()
        dp_rates = [x.item() for x in torch.linspace(0, drop_path_rate, sum(depths))] 
        cur = 0
        for i in range(4):
            # Chỉ apply attention ở stage cuối (stage 3) để giảm computational cost
            use_att = use_attention and (i >= 2)
            stage = nn.Sequential(
                *[Block(dim=dims[i], drop_path=dp_rates[cur + j], 
                       layer_scale_init_value=layer_scale_init_value,
                       use_attention=use_att) for j in range(depths[i])]
            )
            self.stages.append(stage)
            cur += depths[i]

        # ==================== 改进2: Multi-Scale FPN ====================
        if use_fpn:
            # Aggregate features from stage 1, 2, 3 (skip stage 0 vì quá lớn)
            self.fpn = FeaturePyramidNetwork(
                in_channels_list=[dims[1], dims[2], dims[3]],  # [192, 384, 768]
                out_channels=256
            )
            feature_dim = 256 * 3  # 3 scales concatenated
        else:
            feature_dim = dims[-1]
        
        self.norm = nn.LayerNorm(feature_dim, eps=1e-6)
        
        # ==================== 改进3: Enhanced Classification Head ====================
        # Multi-layer head với gradual dimension reduction
        self.head = nn.Sequential(
            nn.Linear(feature_dim, 256),
            nn.BatchNorm1d(256),
            nn.GELU(),
            nn.Dropout(dropout_rate),
            
            nn.Linear(256, 128),
            nn.BatchNorm1d(128),
            nn.GELU(),
            nn.Dropout(dropout_rate * 0.67),
            
            nn.Linear(128, num_classes)
        )
        
        # Dual pooling: both avg and max
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)

        self.apply(self._init_weights)
        # Init head với scale nhỏ hơn
        for m in self.head.modules():
            if isinstance(m, nn.Linear):
                m.weight.data.mul_(head_init_scale)
                if m.bias is not None:
                    m.bias.data.mul_(head_init_scale)

    def _init_weights(self, m):
        if isinstance(m, (nn.Conv2d, nn.Linear)):
            trunc_normal_(m.weight, std=.02)
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)

    def forward_features(self, x):
        stage_features = []
        
        for i in range(4):
            x = self.downsample_layers[i](x)
            x = self.stages[i](x)
            # Collect features từ stage 1, 2, 3 cho FPN
            if i >= 1 and self.use_fpn:
                stage_features.append(x)
        
        # Multi-scale aggregation
        if self.use_fpn and len(stage_features) == 3:
            x = self.fpn(stage_features)
        
        # Dual pooling
        avg_pool = self.avg_pool(x)
        max_pool = self.max_pool(x)
        x = (avg_pool + max_pool) / 2  # Average both pooling methods
        
        return self.norm(x.flatten(1))

    def forward(self, x):
        x = self.forward_features(x)
        x = self.head(x)
        return x


def medconvnext_tiny(num_classes=1000, drop_path_rate=0.1, use_fpn=True, 
                     use_attention=True, dropout_rate=0.3):
    """MedConvNeXt-Tiny: Optimized for medical imaging"""
    model = MedConvNeXt(
        depths=[3, 3, 9, 3], 
        dims=[96, 192, 384, 768], 
        num_classes=num_classes, 
        drop_path_rate=drop_path_rate,
        use_fpn=use_fpn,
        use_attention=use_attention,
        dropout_rate=dropout_rate
    )
    return model


# ==================== Training Code ====================

def get_dataloaders(data_dir, batch_size=32, img_size=224):
    import os
    
    # Augmentation cho medical images - CHÚ Ý THỨ TỰ
    train_transform = transforms.Compose([
        # 1. PIL Image transforms (trước ToTensor)
        transforms.Resize((img_size, img_size)),
        transforms.RandomHorizontalFlip(p=0.5),
        transforms.RandomVerticalFlip(p=0.5),
        transforms.RandomRotation(degrees=20),
        transforms.ColorJitter(brightness=0.2, contrast=0.2, saturation=0.2, hue=0.1),
        transforms.RandomAffine(degrees=0, translate=(0.1, 0.1), scale=(0.9, 1.1)),
        
        # 2. Convert PIL → Tensor
        transforms.ToTensor(),
        
        # 3. Tensor transforms (sau ToTensor)
        transforms.Normalize(mean=[0.485, 0.456, 0.406], 
                           std=[0.229, 0.224, 0.225]),
        transforms.RandomErasing(p=0.2, scale=(0.02, 0.1)),  # Cutout augmentation
    ])
    
    val_transform = transforms.Compose([
        transforms.Resize((img_size, img_size)),
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.485, 0.456, 0.406], 
                           std=[0.229, 0.224, 0.225])
    ])
    
    train_path = os.path.join(data_dir, 'train')
    val_path = os.path.join(data_dir, 'validation')
    
    if not os.path.exists(train_path):
        raise FileNotFoundError(f"Không tìm thấy thư mục: {train_path}")
    if not os.path.exists(val_path):
        raise FileNotFoundError(f"Không tìm thấy thư mục: {val_path}")
    
    print(f"✓ Loading data from {data_dir}")
    train_dataset = datasets.ImageFolder(train_path, transform=train_transform)
    val_dataset = datasets.ImageFolder(val_path, transform=val_transform)
    
    train_loader = DataLoader(train_dataset, batch_size=batch_size, 
                            shuffle=True, num_workers=4, pin_memory=True)
    val_loader = DataLoader(val_dataset, batch_size=batch_size, 
                          shuffle=False, num_workers=4, pin_memory=True)
    
    class_names = train_dataset.classes
    num_classes = len(class_names)
    
    print(f"✓ Train samples: {len(train_dataset)}")
    print(f"✓ Val samples: {len(val_dataset)}")
    print(f"✓ Classes: {class_names}")
    
    return train_loader, val_loader, num_classes, class_names


def train_epoch(model, dataloader, criterion, optimizer, device, scaler=None):
    model.train()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    
    for inputs, labels in dataloader:
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        
        # Mixed precision training
        if scaler is not None:
            with torch.cuda.amp.autocast():
                outputs = model(inputs)
                loss = criterion(outputs, labels)
            scaler.scale(loss).backward()
            scaler.step(optimizer)
            scaler.update()
        else:
            outputs = model(inputs)
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()
        
        running_loss += loss.item() * inputs.size(0)
        _, predicted = outputs.max(1)
        total += labels.size(0)
        correct += predicted.eq(labels).sum().item()
        
        all_preds.extend(predicted.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())
    
    epoch_loss = running_loss / total
    epoch_acc = 100. * correct / total
    recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    precision = precision_score(all_labels, all_preds, average='macro', zero_division=0)
    f1 = f1_score(all_labels, all_preds, average='macro', zero_division=0)
    
    return epoch_loss, epoch_acc, recall, precision, f1


def validate(model, dataloader, criterion, device):
    model.eval()
    running_loss = 0.0
    correct = 0
    total = 0
    all_preds = []
    all_labels = []
    
    with torch.no_grad():
        for inputs, labels in dataloader:
            inputs, labels = inputs.to(device), labels.to(device)
            outputs = model(inputs)
            loss = criterion(outputs, labels)
            
            running_loss += loss.item() * inputs.size(0)
            _, predicted = outputs.max(1)
            total += labels.size(0)
            correct += predicted.eq(labels).sum().item()
            
            all_preds.extend(predicted.cpu().numpy())
            all_labels.extend(labels.cpu().numpy())
    
    epoch_loss = running_loss / total
    epoch_acc = 100. * correct / total
    recall = recall_score(all_labels, all_preds, average='macro', zero_division=0)
    precision = precision_score(all_labels, all_preds, average='macro', zero_division=0)
    f1 = f1_score(all_labels, all_preds, average='macro', zero_division=0)
    
    return epoch_loss, epoch_acc, recall, precision, f1, all_preds, all_labels


def print_classification_report(y_true, y_pred, class_names):
    print("\n" + "="*70)
    print("CLASSIFICATION REPORT")
    print("="*70)
    print(classification_report(y_true, y_pred, target_names=class_names, digits=4))
    print("="*70)


def plot_confusion_matrix(y_true, y_pred, class_names, save_path='confusion_matrix.png'):
    cm = confusion_matrix(y_true, y_pred)
    labels = ['Lành tính (Benign)', 'Ác tính (Malignant)']
    plt.figure(figsize=(10, 8))
    sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', 
                xticklabels=labels, yticklabels=labels, 
                cbar_kws={'label': 'Count'})
    plt.ylabel('Giá trị thực tế\n(Actual value)', fontsize=12)
    plt.xlabel('Giá trị dự đoán\n(Predicted value)', fontsize=12)
    plt.title('MA TRẬN NHẦM LẪN - MedConvNeXt', fontsize=14, fontweight="bold")
    plt.tight_layout()
    plt.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.close()
    print(f"✓ Saved confusion matrix to {save_path}")


class EarlyStopping:
    def __init__(self, patience=15, min_delta=0, verbose=True):
        self.patience = patience
        self.min_delta = min_delta
        self.verbose = verbose
        self.counter = 0
        self.best_score = None
        self.early_stop = False
        self.val_acc_max = 0
        
    def __call__(self, val_acc):
        score = val_acc
        
        if self.best_score is None:
            self.best_score = score
            self.val_acc_max = val_acc
        elif score < self.best_score + self.min_delta:
            self.counter += 1
            if self.verbose:
                print(f"EarlyStopping counter: {self.counter}/{self.patience}")
            if self.counter >= self.patience:
                self.early_stop = True
        else:
            self.best_score = score
            self.val_acc_max = val_acc
            self.counter = 0


def train_medconvnext(data_dir, num_epochs=100, batch_size=32, 
                      lr=3e-4, drop_path_rate=0.1, early_stopping_patience=15,
                      use_fpn=True, use_attention=True, dropout_rate=0.3,
                      mixed_precision=True):
    """Train MedConvNeXt với tất cả improvements"""
    
    device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
    print(f"Using device: {device}")
    
    # Load data
    train_loader, val_loader, num_classes, class_names = get_dataloaders(data_dir, batch_size)
    print(f"\nNumber of classes: {num_classes}")
    print(f"Classes: {class_names}")
    
    # Create model
    model = medconvnext_tiny(
        num_classes=num_classes, 
        drop_path_rate=drop_path_rate,
        use_fpn=use_fpn,
        use_attention=use_attention,
        dropout_rate=dropout_rate
    )
    model = model.to(device)
    
    num_params = sum(p.numel() for p in model.parameters())
    print(f"\nModel: MedConvNeXt-Tiny")
    print(f"Parameters: {num_params:,}")
    print(f"FPN enabled: {use_fpn}")
    print(f"Attention enabled: {use_attention}")
    
    # Loss với class weights nếu imbalanced
    criterion = nn.CrossEntropyLoss(label_smoothing=0.1)
    
    # Optimizer với weight decay cao hơn
    optimizer = optim.AdamW(model.parameters(), lr=lr, weight_decay=0.05)
    
    # Learning rate scheduler
    warmup_epochs = 5
    scheduler_cosine = optim.lr_scheduler.CosineAnnealingLR(
        optimizer, T_max=num_epochs - warmup_epochs, eta_min=1e-6
    )
    
    def warmup_lr_scheduler(epoch):
        return (epoch + 1) / warmup_epochs if epoch < warmup_epochs else 1.0
    
    scheduler_warmup = optim.lr_scheduler.LambdaLR(optimizer, lr_lambda=warmup_lr_scheduler)
    
    # Mixed precision training
    scaler = torch.cuda.amp.GradScaler() if mixed_precision and device.type == 'cuda' else None
    
    # Early stopping
    early_stopping = EarlyStopping(patience=early_stopping_patience, min_delta=0.001, verbose=True)
    
    # History
    history = {
        'train_loss': [], 'train_acc': [], 'train_recall': [], 'train_precision': [], 'train_f1': [],
        'val_loss': [], 'val_acc': [], 'val_recall': [], 'val_precision': [], 'val_f1': [],
        'lr': []
    }
    
    best_val_f1 = 0.0
    
    print("\n" + "="*70)
    print("TRAINING START - MedConvNeXt")
    print("="*70)
    
    for epoch in range(num_epochs):
        print(f"\nEpoch {epoch+1}/{num_epochs}")
        print("-" * 70)
        
        # Train
        train_loss, train_acc, train_recall, train_prec, train_f1 = train_epoch(
            model, train_loader, criterion, optimizer, device, scaler
        )
        
        # Validate
        val_loss, val_acc, val_recall, val_prec, val_f1, val_preds, val_labels = validate(
            model, val_loader, criterion, device
        )
        
        # Update LR
        current_lr = optimizer.param_groups[0]['lr']
        if epoch < warmup_epochs:
            scheduler_warmup.step()
        else:
            scheduler_cosine.step()
        
        # Save history
        history['train_loss'].append(train_loss)
        history['train_acc'].append(train_acc)
        history['train_recall'].append(train_recall)
        history['train_precision'].append(train_prec)
        history['train_f1'].append(train_f1)
        history['val_loss'].append(val_loss)
        history['val_acc'].append(val_acc)
        history['val_recall'].append(val_recall)
        history['val_precision'].append(val_prec)
        history['val_f1'].append(val_f1)
        history['lr'].append(current_lr)
        
        print(f"Train - Loss: {train_loss:.4f} | Acc: {train_acc:.2f}% | "
              f"Recall: {train_recall:.4f} | Prec: {train_prec:.4f} | F1: {train_f1:.4f}")
        print(f"Val   - Loss: {val_loss:.4f} | Acc: {val_acc:.2f}% | "
              f"Recall: {val_recall:.4f} | Prec: {val_prec:.4f} | F1: {val_f1:.4f}")
        print(f"LR: {current_lr:.6f}")
        
        # Save best model based on F1 score (better for imbalanced data)
        if val_f1 > best_val_f1:
            best_val_f1 = val_f1
            best_preds = val_preds
            best_labels = val_labels
            
            torch.save({
                'epoch': epoch,
                'model_state_dict': model.state_dict(),
                'optimizer_state_dict': optimizer.state_dict(),
                'val_f1': val_f1,
                'val_acc': val_acc,
                'num_classes': num_classes,
                'class_names': class_names,
            }, 'best_medconvnext.pth')
            print(f"✓ Saved best model - F1: {val_f1:.4f}, Acc: {val_acc:.2f}%")
        
        # Early stopping
        early_stopping(val_f1)
        if early_stopping.early_stop:
            print(f"\n⚠ Early stopping at epoch {epoch+1}")
            print(f"Best F1: {early_stopping.val_acc_max:.4f}")
            break
    
    print(f"\n{'='*70}")
    print(f"TRAINING COMPLETED!")
    print(f"Best F1 Score: {best_val_f1:.4f}")
    print(f"{'='*70}")
    
    # Visualizations
    print("\nGenerating visualizations...")
    plot_training_history_enhanced(history)
    plot_confusion_matrix(best_labels, best_preds, class_names)
    print_classification_report(best_labels, best_preds, class_names)
    
    return model, history


