    # Learning Rate
    ax = axes[1, 1]
    ax.plot(epochs, history['lr'], '^-', color='red', linewidth=2)
    ax.set_xlabel('Epoch')
    ax.set_ylabel('Learning Rate')
    ax.set_title('LEARNING RATE SCHEDULE', fontweight='bold')
    ax.set_yscale('log')
    ax.grid(alpha=0.3)
    
    plt.tight_layout()
    plt.savefig(f'{save_dir}/training_history_medconvnext.png', dpi=300, bbox_inches='tight')
