from tqdm.auto import tqdm
import sys

def train_epoch(model, ema, loader, criterion, optimizer, scaler,
                epoch, total_epochs, phase_label,
                accum_steps, amp, grad_clip):
    model.train()
    total_loss, n = 0., 0
    optimizer.zero_grad()
    t_start = time.time()

    bar = tqdm(
        loader,
        desc       = f"Ep {epoch:02d}/{total_epochs} [{phase_label}] TRAIN",
        ncols      = 115,
        unit       = "batch",
        leave      = True,
        bar_format = "{l_bar}{bar}| {n_fmt}/{total_fmt} [{elapsed}<{remaining}] {postfix}",
        file       = sys.stdout,
    )

    for step, (imgs, labels) in enumerate(bar):
        imgs   = imgs.to(DEVICE, non_blocking=True)
        labels = labels.to(DEVICE, non_blocking=True)

        with autocast(enabled=amp):
            loss = criterion(model(imgs), labels) / accum_steps

        if amp: scaler.scale(loss).backward()
        else:   loss.backward()

        if (step+1) % accum_steps == 0 or (step+1) == len(loader):
            if amp:
                scaler.unscale_(optimizer)
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                scaler.step(optimizer); scaler.update()
            else:
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                optimizer.step()
            optimizer.zero_grad()
            if ema: ema.update(model)

        cur_loss = loss.item() * accum_steps
        total_loss += cur_loss * imgs.size(0); n += imgs.size(0)

        bar.set_postfix(
            loss = f"{cur_loss:.4f}",
            avg  = f"{total_loss/n:.4f}",
            lr   = f"{optimizer.param_groups[0]['lr']:.1e}",
            t    = f"{time.time()-t_start:.0f}s",
            refresh=False,
        )

    bar.close()
    return total_loss / n


# ---- Evaluate voi tqdm progress bar ----
@torch.no_grad()
def evaluate(model, loader, criterion, amp, split="val", use_tta=False):
    model.eval()
    total_loss, n = 0., 0
    all_t, all_p  = [], []

    bar = tqdm(
        loader,
        desc    = f"          [{split:5s}] EVAL ",
        ncols   = 115,
        unit    = "batch",
        leave   = False,
        file    = sys.stdout,
    )

    for imgs, labels in bar:
        imgs   = imgs.to(DEVICE, non_blocking=True)
        labels = labels.to(DEVICE, non_blocking=True)
        if use_tta:
            probs  = tta_inference(model, imgs, DEVICE)
            logits = torch.log(probs / (1-probs+1e-8))
        else:
            with autocast(enabled=amp): logits = model(imgs)
            probs = torch.sigmoid(logits)

        total_loss += criterion(logits, labels).item() * imgs.size(0)
        n += imgs.size(0)
        all_t.append(labels.cpu().numpy())
        all_p.append(probs.cpu().float().numpy())

    bar.close()
    all_t = np.concatenate(all_t); all_p = np.concatenate(all_p)
    aucs, mauc = compute_auc(all_t, all_p)
    return total_loss / n, mauc, aucs


print("Training utilities (EarlyStopping + tqdm) san sang")
