# ---- EMA ----
class ModelEMA:
    def __init__(self, model, decay=0.9998):
        self.model = deepcopy(model).eval(); self.decay = decay
        for p in self.model.parameters(): p.requires_grad_(False)
    @torch.no_grad()
    def update(self, model):
        for ep, mp in zip(self.model.parameters(), model.parameters()):
            ep.copy_(self.decay*ep + (1-self.decay)*mp.detach())
    def __call__(self, x): return self.model(x)


# ---- Cosine LR + Warmup ----
def cosine_warmup_scheduler(optimizer, warmup, total, min_lr, base_lr):
    def fn(epoch):
        if epoch < warmup: return (epoch+1)/max(1, warmup)
        t = (epoch-warmup)/max(1, total-warmup)
        return max(min_lr/base_lr, 0.5*(1+math.cos(math.pi*t)))
    return optim.lr_scheduler.LambdaLR(optimizer, fn)


# ---- Early Stopping ----
class EarlyStopping:
    """
    Dung training khi val mAUC khong cai thien sau `patience` epochs.
    mode="max": theo doi AUC (cao hon = tot hon)
    mode="min": theo doi loss (thap hon = tot hon)
    """
    def __init__(self, patience=8, min_delta=1e-4, mode="max"):
        self.patience  = patience
        self.min_delta = min_delta
        self.mode      = mode
        self.counter   = 0
        self.best      = float("-inf") if mode == "max" else float("inf")
        self.triggered = False

    def step(self, value):
        improved = (value > self.best + self.min_delta) if self.mode == "max"                    else (value < self.best - self.min_delta)
        if improved:
            self.best = value; self.counter = 0
        else:
            self.counter += 1
            if self.counter >= self.patience:
                self.triggered = True
        return improved

    @property
    def should_stop(self): return self.triggered

    def status(self):
        return f"ES[{self.counter}/{self.patience}] best={self.best:.4f}"


# ---- TTA ----
@torch.no_grad()
def tta_inference(model, imgs, device):
    preds = []
    for fh in [False, True]:
        for fv in [False, True]:
            x = imgs.to(device)
            if fh: x = torch.flip(x, [3])
            if fv: x = torch.flip(x, [2])
            preds.append(torch.sigmoid(model(x)))
    return torch.stack(preds).mean(0)


# ---- AUC metric ----
def compute_auc(targets, probs):
    aucs = {}
    for i, name in enumerate(NIH_CLASSES):
        try:    aucs[name] = roc_auc_score(targets[:, i], probs[:, i])
        except: aucs[name] = 0.0
    return aucs, float(np.mean(list(aucs.values())))


# ---- Terminal-style logging helpers ----
def fmt_hms(sec):
    sec = max(0, float(sec))
    h, m = int(sec // 3600), int((sec % 3600) // 60)
    s = int(sec % 60)
    return f"{h:02d}:{m:02d}:{s:02d}"

def print_rule(ch='-', n=90):
    print(ch * n, flush=True)


def train_epoch(model, ema, loader, criterion, optimizer, scaler,
                epoch, total_epochs, phase_label,
                accum_steps, amp, grad_clip, log_interval=50):
    model.train()
    total_loss, n = 0.0, 0
    optimizer.zero_grad()
    t_start = time.time()
    num_batches = len(loader)

    print_rule()
    print(f"[TRAIN] epoch={epoch:02d}/{total_epochs} phase={phase_label} batches={num_batches}", flush=True)

    for step, (imgs, labels) in enumerate(loader, start=1):
        imgs   = imgs.to(DEVICE, non_blocking=True)
        labels = labels.to(DEVICE, non_blocking=True)

        with amp_autocast(enabled=amp):
            loss = criterion(model(imgs), labels) / accum_steps

        if amp: scaler.scale(loss).backward()
        else:   loss.backward()

        if step % accum_steps == 0 or step == num_batches:
            if amp:
                scaler.unscale_(optimizer)
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                scaler.step(optimizer); scaler.update()
            else:
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                optimizer.step()
            optimizer.zero_grad()
            if ema: ema.update(model)

        cur_loss = loss.item() * accum_steps
        total_loss += cur_loss * imgs.size(0)
        n += imgs.size(0)

        if (step == 1) or (step % log_interval == 0) or (step == num_batches):
            elapsed = time.time() - t_start
            eta = elapsed / step * (num_batches - step)
            avg = total_loss / max(n, 1)
            lr = optimizer.param_groups[0]["lr"]
            print(
                f"[TRAIN][{epoch:02d}/{total_epochs}][{step:4d}/{num_batches}] "
                f"loss={cur_loss:.4f} avg={avg:.4f} lr={lr:.2e} "
                f"elapsed={fmt_hms(elapsed)} eta={fmt_hms(eta)}",
                flush=True,
            )

    avg_loss = total_loss / max(n, 1)
    print(f"[TRAIN][DONE] epoch={epoch:02d} avg_loss={avg_loss:.4f} time={fmt_hms(time.time()-t_start)}", flush=True)
    return avg_loss


@torch.no_grad()
def evaluate(model, loader, criterion, amp, split="val", use_tta=False, log_interval=50):
    model.eval()
    total_loss, n = 0.0, 0
    all_t, all_p  = [], []
    t_start = time.time()
    num_batches = len(loader)

    print_rule()
    print(f"[EVAL ] split={split} batches={num_batches}", flush=True)

    for step, (imgs, labels) in enumerate(loader, start=1):
        imgs   = imgs.to(DEVICE, non_blocking=True)
        labels = labels.to(DEVICE, non_blocking=True)
        if use_tta:
            probs  = tta_inference(model, imgs, DEVICE)
            logits = torch.log(probs / (1-probs+1e-8))
        else:
            with amp_autocast(enabled=amp):
                logits = model(imgs)
            probs = torch.sigmoid(logits)

        batch_loss = criterion(logits, labels).item()
        total_loss += batch_loss * imgs.size(0)
        n += imgs.size(0)
        all_t.append(labels.cpu().numpy())
        all_p.append(probs.cpu().float().numpy())

        if (step == 1) or (step % log_interval == 0) or (step == num_batches):
            elapsed = time.time() - t_start
            eta = elapsed / step * (num_batches - step)
            avg = total_loss / max(n, 1)
            print(
                f"[EVAL ][{split}][{step:4d}/{num_batches}] "
                f"loss={batch_loss:.4f} avg={avg:.4f} "
                f"elapsed={fmt_hms(elapsed)} eta={fmt_hms(eta)}",
                flush=True,
            )

    all_t = np.concatenate(all_t)
    all_p = np.concatenate(all_p)
    aucs, mauc = compute_auc(all_t, all_p)
    avg_loss = total_loss / max(n, 1)
    print(f"[EVAL ][DONE] split={split} loss={avg_loss:.4f} mAUC={mauc:.4f} time={fmt_hms(time.time()-t_start)}", flush=True)
    return avg_loss, mauc, aucs


