print(f"Phase 1   : epoch 1-{PHASE2_START-1}  (CNN frozen)")
print(f"Phase 2   : epoch {PHASE2_START}-{CFG['epochs']}  (full fine-tune)")
print(f"EarlyStop : patience={CFG['es_patience']}  min_delta={CFG['es_min_delta']}")
print(f"Log intv  : update mAUC every {CFG['log_interval']} batch")
print(SEP)

best_auc    = 0.0
history     = []
train_start = time.time()
max_epochs  = CFG["epochs"]

for epoch in range(1, max_epochs + 1):

    if epoch == PHASE2_START:
        print(SEP)
        print(f"[PHASE SWITCH] epoch={epoch}: unfreeze EfficientNetV2, full fine-tune")
        model.unfreeze_all()
        param_groups = model.get_param_groups(CFG["lr"])
        optimizer    = optim.AdamW(param_groups, weight_decay=CFG["weight_decay"])
        scheduler    = cosine_warmup_scheduler(
            optimizer, 2, CFG["epochs"]-PHASE2_START+1, CFG["min_lr"], CFG["lr"])
        scaler = make_grad_scaler(enabled=CFG["amp"])

    phase_label = "P1-frozen" if epoch < PHASE2_START else "P2-full"
    ep_t0 = time.time()

    print(SEP)
    print(f"[EPOCH START] {epoch:02d}/{max_epochs} phase={phase_label}")

    train_loss, train_auc, train_aucs = train_epoch(
        model, ema, loaders["train"], criterion,
        optimizer, scaler,
        epoch, CFG["epochs"], phase_label,
        CFG["accum_steps"], CFG["amp"], CFG["grad_clip"],
        log_interval=CFG["log_interval"],
    )

    val_model = ema.model if ema else model
    val_loss, val_auc, val_aucs = evaluate(
        val_model, loaders["val"], criterion, CFG["amp"],
        split="val", use_tta=CFG["use_tta"], log_interval=CFG["log_interval"],
    )
    scheduler.step()

    ep_sec    = time.time() - ep_t0
    total_sec = time.time() - train_start
    remaining = (total_sec / epoch) * (max_epochs - epoch)
    lr        = optimizer.param_groups[0]["lr"]

    rec = {
        "epoch": epoch, "train_loss": train_loss,
        "train_mean_auc": train_auc,
        "val_loss": val_loss, "val_mean_auc": val_auc,
        "phase": 1 if epoch < PHASE2_START else 2,
        "ep_sec": round(ep_sec, 1),
        **{f"train_auc_{k}": v for k, v in train_aucs.items()},
        **{f"auc_{k}": v for k, v in val_aucs.items()},
    }
    history.append(rec)
    with open(OUTPUT_DIR / "history.json", "w", encoding="utf-8") as f:
        json.dump(history, f, indent=2)

    is_best = early_stop.step(val_auc)
    if is_best:
        best_auc = val_auc
        save_mdl = ema.model if ema else model
        torch.save(
            {"epoch": epoch, "model": save_mdl.state_dict(),
             "auc": val_auc, "cfg": CFG},
            OUTPUT_DIR / "best_model.pth",
        )

    if epoch % CFG["save_freq"] == 0:
        torch.save(
            {"epoch": epoch, "model": model.state_dict(),
             "optimizer": optimizer.state_dict()},
            OUTPUT_DIR / f"ckpt_ep{epoch:02d}.pth",
        )

    sorted_aucs = sorted(val_aucs.items(), key=lambda x: -x[1])
    mark = "  *** BEST ***" if is_best else ""

    print(SEP)
    print(f"[EPOCH END] {epoch:02d}/{max_epochs} phase={phase_label}{mark}")
    print(f"Time    : ep={fmt_hms(ep_sec)} | total={fmt_hms(total_sec)} | eta={fmt_hms(remaining)}")
    print(f"Loss    : train={train_loss:.4f} | val={val_loss:.4f}")
    print(f"mAUC    : train={train_auc:.4f} | val={val_auc:.4f} | best={best_auc:.4f} | lr={lr:.2e}")
    print(f"ES      : {early_stop.status()}")
    print("Top-3   : " + " | ".join(f"{n[:12]}:{v:.4f}" for n, v in sorted_aucs[:3]))
    print("Worst-3 : " + " | ".join(f"{n[:12]}:{v:.4f}" for n, v in sorted_aucs[-3:]))

    if epoch % 5 == 0 or is_best:
        print("Per-class AUROC:")
        for k, v in sorted_aucs:
            bar_ch = "#" * int(v * 25)
            print(f"  {k:22s}: {v:.4f}  {bar_ch}")

    if early_stop.should_stop:
        print(SEP)
        print(f"[EARLY STOP] epoch {epoch} | no improvement for {CFG['es_patience']} epochs")
        print(f"Best Val mAUC = {best_auc:.4f}")
        break

total_sec = time.time() - train_start
print(SEP)
