# ---- DropPath ----
class DropPath(nn.Module):
    def __init__(self, p=0.): super().__init__(); self.p = p
    def forward(self, x):
        if not self.training or self.p == 0.: return x
        keep = 1-self.p
        s = (x.shape[0],)+(1,)*(x.ndim-1)
        return x/keep*torch.floor(torch.rand(s,device=x.device,dtype=x.dtype)+keep)

# ---- Python Mamba fallback ----
class MambaBlock(nn.Module):
    def __init__(self, d_model, d_state=16, d_conv=4, expand=2):
        super().__init__()
        self.d_inner = int(expand*d_model); self.d_state = d_state
        self.norm    = nn.LayerNorm(d_model)
        self.in_proj = nn.Linear(d_model, self.d_inner*2, bias=False)
        self.conv1d  = nn.Conv1d(self.d_inner,self.d_inner,d_conv,
                                  padding=d_conv-1,groups=self.d_inner)
        self.x_proj  = nn.Linear(self.d_inner, d_state*2+self.d_inner, bias=False)
        self.dt_proj = nn.Linear(self.d_inner, self.d_inner, bias=True)
        A = torch.arange(1,d_state+1,dtype=torch.float32).repeat(self.d_inner,1)
        self.A_log = nn.Parameter(torch.log(A))
        self.D     = nn.Parameter(torch.ones(self.d_inner))
        self.out_proj = nn.Linear(self.d_inner, d_model, bias=False)

    def ssm(self, x):
        B,L,D = x.shape
        A = -torch.exp(self.A_log.float())
        xdb = self.x_proj(x); N = self.d_state
        dt,Bs,C = torch.split(xdb,[D,N,N],dim=-1)
        dt = F.softplus(self.dt_proj(dt))
        dA = torch.exp(dt.unsqueeze(-1)*A)
        dBx = dt.unsqueeze(-1)*Bs.unsqueeze(2)
        h = torch.zeros(B,D,N,device=x.device,dtype=x.dtype)
        ys = []
        for i in range(L):
            h = dA[:,i]*h + dBx[:,i]*x[:,i].unsqueeze(-1)
            # C has shape (B, N); expand on dim=1 so it broadcasts over D, not against it
            ys.append((h * C[:, i].unsqueeze(1)).sum(-1))
        return torch.stack(ys,1)+x*self.D.float()

    def forward(self, x):
        res=x; x=self.norm(x)
        xz=self.in_proj(x); xs,z=xz.chunk(2,-1)
        xs=self.conv1d(xs.transpose(1,2))[...,:x.shape[1]].transpose(1,2)
        xs=F.silu(xs)
        return self.out_proj(self.ssm(xs)*F.silu(z))+res

def build_mamba(d,ds=16,dc=4,ex=2):
    if MAMBA_AVAILABLE: return Mamba(d_model=d,d_state=ds,d_conv=dc,expand=ex)
    return MambaBlock(d,ds,dc,ex)

# ---- Window utils ----
def window_partition(x,ws):
    B,H,W,C=x.shape
    pH=(ws-H%ws)%ws; pW=(ws-W%ws)%ws
    if pH>0 or pW>0: x=F.pad(x,(0,0,0,pW,0,pH))
    _,Hp,Wp,_=x.shape
    x=x.view(B,Hp//ws,ws,Wp//ws,ws,C)
    return x.permute(0,1,3,2,4,5).contiguous().view(-1,ws,ws,C),Hp,Wp

def window_reverse(wins,ws,B,Hp,Wp,H,W):
    x=wins.view(B,Hp//ws,Wp//ws,ws,ws,-1)
    return x.permute(0,1,3,2,4,5).contiguous().view(B,Hp,Wp,-1)[:,:H,:W,:].contiguous()

# ---- Windowed SSM (WSS) ----
class WindowedSSM(nn.Module):
    def __init__(self,dim,window_size=7,d_state=16,d_conv=4,expand=2):
        super().__init__()
        self.ws=window_size
        self.mamba_local  =build_mamba(dim,d_state,d_conv,expand)
        self.mamba_shifted=build_mamba(dim,d_state,d_conv,expand)
        self.norm_local   =nn.LayerNorm(dim)
        self.norm_shifted =nn.LayerNorm(dim)

    def forward(self,x):
        B,H,W,C=x.shape; ws=self.ws
        wins,Hp,Wp=window_partition(x,ws)
        nB=wins.shape[0]
        x_local=window_reverse(
            self.mamba_local(self.norm_local(wins.reshape(nB,ws*ws,C))).reshape(nB,ws,ws,C),
            ws,B,Hp,Wp,H,W)
        sh=ws//2
        xs=torch.roll(x_local,(-sh,-sh),dims=(1,2))
        ws2,Hp2,Wp2=window_partition(xs,ws)
        nB2=ws2.shape[0]
        x_cross=torch.roll(
            window_reverse(
                self.mamba_shifted(self.norm_shifted(ws2.reshape(nB2,ws*ws,C))).reshape(nB2,ws,ws,C),
                ws,B,Hp2,Wp2,H,W),
            (sh,sh),dims=(1,2))
        return x_local+x_cross

# ---- Adaptive Dual-Branch Gating (ADBG) ----
class AdaptiveDualBranchGating(nn.Module):
    def __init__(self,dim):
        super().__init__()
        self.gate_proj=nn.Sequential(nn.Linear(dim*2,dim,bias=False),nn.LayerNorm(dim))
        self.aux_gate =nn.Linear(dim,dim,bias=False)
        self.alpha    =nn.Parameter(torch.tensor(0.5))
    def forward(self,f_ssm,f_conv,skip):
        g_main=torch.sigmoid(self.gate_proj(torch.cat([f_ssm,f_conv],-1)))
        g_aux =torch.sigmoid(self.aux_gate(skip))
        a=torch.sigmoid(self.alpha)
        g=a*g_main+(1-a)*g_aux
        return g*f_ssm+(1-g)*f_conv

# ---- ADBG-WSS-Conv Block ----
class ADBG_WSS_Conv_Block(nn.Module):
    def __init__(self,dim,drop_path=0.,norm=nn.LayerNorm,
                 d_state=16,d_conv=4,expand=2,window_size=7,ffn_expand=2.):
        super().__init__()
        self.norm1=norm(dim)
        self.wss  =WindowedSSM(dim,window_size,d_state,d_conv,expand)
        self.conv3=nn.Sequential(
            nn.Conv2d(dim,dim,3,padding=1,groups=dim,bias=False),
            nn.BatchNorm2d(dim),nn.GELU(),nn.Conv2d(dim,dim,1,bias=False))
        self.conv5d=nn.Sequential(
            nn.Conv2d(dim,dim,3,padding=2,dilation=2,groups=dim,bias=False),
            nn.BatchNorm2d(dim),nn.GELU(),nn.Conv2d(dim,dim,1,bias=False))
        self.cs   =nn.Parameter(torch.tensor(0.5))
        self.c_proj=nn.Linear(dim,dim,bias=False)
        self.adbg =AdaptiveDualBranchGating(dim)
        fd=int(dim*ffn_expand)
        self.norm2=norm(dim)
        self.ffn  =nn.Sequential(nn.Linear(dim,fd,bias=False),nn.GELU(),nn.Linear(fd,dim,bias=False))
        self.drop =DropPath(drop_path)

    def forward(self,inp):
        B,H,W,C=inp.shape
        x=self.norm1(inp)
        f_ssm=self.wss(x)
        xc=x.permute(0,3,1,2)
        sc=torch.sigmoid(self.cs)
        f_conv=self.c_proj((sc*self.conv3(xc)+(1-sc)*self.conv5d(xc)).permute(0,2,3,1))
        x=inp+self.drop(self.adbg(f_ssm,f_conv,skip=inp))
        return x+self.drop(self.ffn(self.norm2(x)))

# ---- Patch helpers ----
class PatchEmbed2D(nn.Module):
    def __init__(self,ps=4,in_ch=3,embed_dim=96,norm=None):
        super().__init__()
        self.proj=nn.Conv2d(in_ch,embed_dim,ps,stride=ps)
        self.norm=norm(embed_dim) if norm else nn.Identity()
    def forward(self,x): return self.norm(self.proj(x).permute(0,2,3,1))

class PatchMerging2D(nn.Module):
    def __init__(self,dim,norm=nn.LayerNorm):
        super().__init__()
        self.norm=norm(4*dim)
        self.red =nn.Linear(4*dim,2*dim,bias=False)
    def forward(self,x):
        B,H,W,C=x.shape
        if H%2==1 or W%2==1: x=F.pad(x,(0,0,0,W%2,0,H%2)); B,H,W,C=x.shape
        x=torch.cat([x[:,i::2,j::2,:] for i in range(2) for j in range(2)],-1)
        return self.red(self.norm(x))

# ---- MedMamba++ Encoder (no head) ----
class MedMambaPlusPlusEncoder(nn.Module):
    CONFIGS = {
        "tiny" : dict(depths=[2,2,4,2], dims=[96,192,384,768]),
        "small": dict(depths=[2,2,9,2], dims=[96,192,384,768]),
        "base" : dict(depths=[2,2,18,2],dims=[128,256,512,1024]),
    }
    def __init__(self,variant="tiny",in_ch=3,drop_path_rate=0.15,
                 d_state=16,window_size=7,ffn_expand=2.):
        super().__init__()
        cfg=self.CONFIGS[variant]
        depths=cfg["depths"]; dims=cfg["dims"]
        dpr=[x.item() for x in torch.linspace(0,drop_path_rate,sum(depths))]
        self.out_dim=dims[-1]
        self.patch_embed=PatchEmbed2D(4,in_ch,dims[0],nn.LayerNorm)
        self.stages=nn.ModuleList()
        self.downsamplers=nn.ModuleList()
        cur=0
        for i,(d,dim) in enumerate(zip(depths,dims)):
            self.stages.append(nn.ModuleList([
                ADBG_WSS_Conv_Block(dim,dpr[cur+j],nn.LayerNorm,d_state,4,2,window_size,ffn_expand)
                for j in range(d)]))
            cur+=d
            self.downsamplers.append(PatchMerging2D(dim) if i<len(depths)-1 else None)
        self.norm=nn.LayerNorm(dims[-1])
        self.avgpool=nn.AdaptiveAvgPool1d(1)
        self._init()

    def _init(self):
        for m in self.modules():
            if isinstance(m,nn.Linear):
                nn.init.trunc_normal_(m.weight,std=0.02)
                if m.bias is not None: nn.init.zeros_(m.bias)
            elif isinstance(m,nn.Conv2d):
                nn.init.kaiming_normal_(m.weight,mode="fan_out")
                if m.bias is not None: nn.init.zeros_(m.bias)
            elif isinstance(m,(nn.LayerNorm,nn.BatchNorm2d)):
                nn.init.ones_(m.weight); nn.init.zeros_(m.bias)

    def forward(self,x):
        x=self.patch_embed(x)
        for stage,ds in zip(self.stages,self.downsamplers):
            for blk in stage: x=blk(x)
            if ds is not None: x=ds(x)
        B,H,W,C=x.shape
        x=self.norm(x).reshape(B,H*W,C).transpose(1,2)
        return self.avgpool(x).flatten(1)

# Quick test
