class EfficientNetV2Encoder(nn.Module):
    """
    EfficientNetV2 backbone (pretrained ImageNet) -- output (B, out_dim).
    Variants (timm):
        tf_efficientnetv2_s  -- 21.5M params, out_dim=1280
        tf_efficientnetv2_m  -- 54.1M params, out_dim=1280
        tf_efficientnetv2_l  -- 118.5M params, out_dim=1280
    """
    def __init__(self, variant="tf_efficientnetv2_s", pretrained=True, drop_rate=0.3):
        super().__init__()
        self.backbone = timm.create_model(
            variant, pretrained=pretrained,
            num_classes=0,      # bo head
            global_pool="avg",  # Global Average Pooling
            drop_rate=drop_rate,
        )
        self.out_dim = self.backbone.num_features
        print(f"EfficientNetV2 ({variant}) | out_dim={self.out_dim} | pretrained={pretrained}")

    def forward(self, x):
        return self.backbone(x)   # (B, out_dim)


