class HybridMedMambaEffV2(nn.Module):
    """
    Hybrid CNN-SSM cho phan loai X-quang nguc.
    Two branches: EfficientNetV2 (CNN) + MedMamba++ (SSM)
    Fused qua Cross-Modal Fusion Gate (CMFG).
    """
    def __init__(self, effv2_variant="tf_efficientnetv2_s", mamba_variant="tiny",
                 num_classes=14, fusion_dim=512, fusion_dropout=0.3,
                 pretrained_eff=True, drop_path_rate=0.15,
                 d_state=16, window_size=7, ffn_expand=2.):
        super().__init__()
        self.cnn_enc = EfficientNetV2Encoder(effv2_variant, pretrained_eff)
        self.ssm_enc = MedMambaPlusPlusEncoder(mamba_variant,
                           drop_path_rate=drop_path_rate, d_state=d_state,
                           window_size=window_size, ffn_expand=ffn_expand)
        self.cmfg = CrossModalFusionGate(
            self.cnn_enc.out_dim, self.ssm_enc.out_dim,
            fusion_dim, fusion_dropout)
        self.classifier = nn.Linear(fusion_dim, num_classes)

    def freeze_cnn(self):
        for p in self.cnn_enc.parameters(): p.requires_grad = False
        print("EfficientNetV2 FROZEN -- chi train MedMamba++ + CMFG + head")

    def unfreeze_all(self):
        for p in self.parameters(): p.requires_grad = True
        print("Tat ca weights UNFROZEN -- full fine-tune")

    def forward(self, x):
        f_cnn = self.cnn_enc(x)           # (B, 1280)
        f_ssm = self.ssm_enc(x)           # (B, 768)
        fused = self.cmfg(f_cnn, f_ssm)   # (B, 512)
        return self.classifier(fused)      # (B, 14)

    def get_param_groups(self, lr_base):
        import re

        named = [(n, p) for n, p in self.named_parameters() if p.requires_grad]

        groups = {
            "head": [],
            "ssm_late": [],
            "ssm_early": [],
            "ssm_embed": [],
            "cnn_late": [],
            "cnn_early": [],
        }

        # Tim block indices exactly, tranh match nham blocks.1 voi blocks.10, blocks.11, ...
        cnn_block_ids = sorted({
            int(m.group(1))
            for n, _ in named
            for m in [re.match(r"^cnn_enc\.backbone\.blocks\.(\d+)\.", n)]
            if m is not None
        })
        split_idx = max(1, len(cnn_block_ids) // 2) if cnn_block_ids else 0
        cnn_early_ids = set(cnn_block_ids[:split_idx])
        cnn_late_ids  = set(cnn_block_ids[split_idx:])

        for n, p in named:
            if n.startswith("cmfg.") or n.startswith("classifier."):
                groups["head"].append(p)
                continue

            if (n.startswith("ssm_enc.patch_embed.")
                or n.startswith("ssm_enc.norm.")
                or n.startswith("ssm_enc.downsamplers.")):
                groups["ssm_embed"].append(p)
                continue

            m = re.match(r"^ssm_enc\.stages\.(\d+)\.", n)
            if m is not None:
                stage_id = int(m.group(1))
                if stage_id in [2, 3]:
                    groups["ssm_late"].append(p)
                else:
                    groups["ssm_early"].append(p)
                continue

            m = re.match(r"^cnn_enc\.backbone\.blocks\.(\d+)\.", n)
            if m is not None:
                block_id = int(m.group(1))
                if block_id in cnn_early_ids:
                    groups["cnn_early"].append(p)
                else:
                    groups["cnn_late"].append(p)
                continue

            # Stem / BN / conv_head / backbone norm... dua vao cnn_early
            if n.startswith("cnn_enc."):
                groups["cnn_early"].append(p)
                continue

            # Fallback an toan
            groups["head"].append(p)

        # Kiem tra trung tham so giua cac groups
        seen = {}
        for gname, params in groups.items():
            unique_params = []
            for p in params:
                pid = id(p)
                if pid in seen:
                    raise RuntimeError(f"Duplicate parameter found in groups: {gname} and {seen[pid]}")
                seen[pid] = gname
                unique_params.append(p)
            groups[gname] = unique_params

        return [
            {"params": groups["head"],      "lr": lr_base,       "name": "head+cmfg"},
            {"params": groups["ssm_late"],  "lr": lr_base*0.3,   "name": "ssm_late"},
            {"params": groups["ssm_early"], "lr": lr_base*0.1,   "name": "ssm_early"},
            {"params": groups["ssm_embed"], "lr": lr_base*0.05,  "name": "ssm_embed"},
            {"params": groups["cnn_late"],  "lr": lr_base*0.1,   "name": "cnn_late"},
            {"params": groups["cnn_early"], "lr": lr_base*0.02,  "name": "cnn_early"},
        ]


