# ---- EMA ----
class ModelEMA:
    def __init__(self, model, decay=0.9998):
        self.model = deepcopy(model).eval(); self.decay = decay
        for p in self.model.parameters(): p.requires_grad_(False)
    @torch.no_grad()
    def update(self, model):
        for ep,mp in zip(self.model.parameters(), model.parameters()):
            ep.copy_(self.decay*ep+(1-self.decay)*mp.detach())
    def __call__(self, x): return self.model(x)

# ---- Cosine LR + Warmup ----
def cosine_warmup_scheduler(optimizer, warmup, total, min_lr, base_lr):
    def fn(epoch):
        if epoch < warmup: return (epoch+1)/max(1,warmup)
        t=(epoch-warmup)/max(1,total-warmup)
        return max(min_lr/base_lr, 0.5*(1+math.cos(math.pi*t)))
    return optim.lr_scheduler.LambdaLR(optimizer, fn)

# ---- TTA ----
@torch.no_grad()
def tta_inference(model, imgs, device):
    preds = []
    for fh in [False,True]:
        for fv in [False,True]:
            x = imgs.to(device)
            if fh: x = torch.flip(x,[3])
            if fv: x = torch.flip(x,[2])
            preds.append(torch.sigmoid(model(x)))
    return torch.stack(preds).mean(0)

# ---- AUC metric ----
def compute_auc(targets, probs):
    aucs = {}
    for i,name in enumerate(NIH_CLASSES):
        try:
            aucs[name] = roc_auc_score(targets[:,i], probs[:,i])
        except:
            aucs[name] = np.nan
    valid = [v for v in aucs.values() if not np.isnan(v)]
    mauc = float(np.mean(valid)) if len(valid) else 0.0
    return aucs, mauc

def _fmt_time(sec):
    sec = int(max(0, sec))
    m, s = divmod(sec, 60)
    h, m = divmod(m, 60)
    return f"{h:d}:{m:02d}:{s:02d}" if h > 0 else f"{m:02d}:{s:02d}"

def _bar(step, total, width=28):
    total = max(1, total)
    frac = min(max(step / total, 0.0), 1.0)
    filled = int(width * frac)
    if filled <= 0:
        return ">" + "." * (width - 1)
    if filled >= width:
        return "=" * width
    return "=" * (filled - 1) + ">" + "." * (width - filled)

def _render_live(stage, epoch, epochs, phase_name, step, total, auc, start_time, extra=None):
    elapsed = time.time() - start_time
    rate = step / max(elapsed, 1e-8)
    remain = (total - step) / max(rate, 1e-8)
    pct = 100.0 * step / max(1, total)
    auc_str = f"{auc:.4f}" if not np.isnan(auc) else "----"
    line = f"[{stage}] {epoch:02d}/{epochs:02d}: {pct:3.0f}%|{_bar(step,total)}| {step}/{total} [{_fmt_time(elapsed)}<{_fmt_time(remain)}, {rate:4.2f}it/s] auroc={auc_str}"
    if extra:
        line += f" {extra}"

    clear_output(wait=True)
    print("="*88)
    print(f"[EPOCH START] {epoch:02d}/{epochs:02d} phase={phase_name}")
    print("-"*88)
    print(line, flush=True)

# ---- Train 1 epoch ----
def train_epoch(model, ema, loader, criterion, optimizer, scaler,
                epoch, epochs, accum_steps, amp, grad_clip,
                phase_name="P1-frozen", auc_update_steps=50):
    model.train()
    total_loss, n = 0., 0
    optimizer.zero_grad(set_to_none=True)

    seen_t, seen_p = [], []
    running_auc = np.nan
    t_start = time.time()
    total_batches = len(loader)

    # render 0%
    _render_live("TRAIN", epoch, epochs, phase_name, 0, total_batches, running_auc, t_start)

    for step,(imgs,labels) in enumerate(loader, start=1):
        imgs   = imgs.to(DEVICE, non_blocking=True)
        labels = labels.to(DEVICE, non_blocking=True)

        with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
            logits = model(imgs)
            loss   = criterion(logits, labels) / accum_steps

        if amp and AMP_ENABLED:
            scaler.scale(loss).backward()
        else:
            loss.backward()

        if (step % accum_steps == 0) or (step == total_batches):
            if amp and AMP_ENABLED:
                scaler.unscale_(optimizer)
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                scaler.step(optimizer)
                scaler.update()
            else:
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                optimizer.step()

            optimizer.zero_grad(set_to_none=True)
            if ema: ema.update(model)

        probs = torch.sigmoid(logits.detach())
        seen_t.append(labels.detach().cpu())
        seen_p.append(probs.detach().cpu())

        batch_loss = loss.item() * accum_steps
        total_loss += batch_loss * imgs.size(0)
        n += imgs.size(0)

        if (step % auc_update_steps == 0) or (step == total_batches):
            y_t = torch.cat(seen_t, dim=0).numpy()
            y_p = torch.cat(seen_p, dim=0).numpy()
            _, running_auc = compute_auc(y_t, y_p)
            _render_live("TRAIN", epoch, epochs, phase_name, step, total_batches, running_auc, t_start)

    y_t = torch.cat(seen_t, dim=0).numpy()
    y_p = torch.cat(seen_p, dim=0).numpy()
    _, epoch_auc = compute_auc(y_t, y_p)
    _render_live("TRAIN", epoch, epochs, phase_name, total_batches, total_batches, epoch_auc, t_start, extra="done")
    return total_loss / max(1, n), epoch_auc

# ---- Evaluate ----
@torch.no_grad()
def evaluate(model, loader, criterion, amp, epoch=None, epochs=None, use_tta=False,
             phase_name="P1-frozen", auc_update_steps=20):
    model.eval()
    total_loss, n = 0., 0
    all_t, all_p  = [], []
    running_auc = np.nan
    t_start = time.time()
    total_batches = len(loader)
    stage = "VALID" if epoch is not None else "EVAL"

    if epoch is not None:
        _render_live(stage, epoch, epochs, phase_name, 0, total_batches, running_auc, t_start)

    for step,(imgs,labels) in enumerate(loader, start=1):
        imgs   = imgs.to(DEVICE, non_blocking=True)
        labels = labels.to(DEVICE, non_blocking=True)

        if use_tta:
            probs = tta_inference(model, imgs, DEVICE)
            logits = torch.log(probs/(1-probs+1e-8))
        else:
            with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
                logits = model(imgs)
            probs = torch.sigmoid(logits)

        batch_loss = criterion(logits, labels).item()
        total_loss += batch_loss * imgs.size(0)
        n += imgs.size(0)

        all_t.append(labels.cpu())
        all_p.append(probs.cpu().float())

        if (step % auc_update_steps == 0) or (step == total_batches):
            y_t = torch.cat(all_t, dim=0).numpy()
            y_p = torch.cat(all_p, dim=0).numpy()
            _, running_auc = compute_auc(y_t, y_p)
            if epoch is not None:
                _render_live(stage, epoch, epochs, phase_name, step, total_batches, running_auc, t_start)

    all_t = torch.cat(all_t).numpy()
    all_p = torch.cat(all_p).numpy()
    aucs, mauc = compute_auc(all_t, all_p)

    if epoch is not None:
        _render_live(stage, epoch, epochs, phase_name, total_batches, total_batches, mauc, t_start, extra="done")

    return total_loss/max(1, n), mauc, aucs

