    for k,v in val_aucs.items():
        bar  = chr(9608)*int(v*20)
        star = " <--" if v==max(val_aucs.values()) else ""
        print(f"    {k:22s}: {v:.4f}  {bar}{star}")

    if val_auc > best_auc + min_delta:
        best_auc = val_auc
        epochs_no_improve = 0
