# ---- EMA ----
class ModelEMA:
    def __init__(self, model, decay=0.9998):
        self.model = deepcopy(model).eval(); self.decay = decay
        for p in self.model.parameters(): p.requires_grad_(False)
    @torch.no_grad()
    def update(self, model):
        for ep,mp in zip(self.model.parameters(), model.parameters()):
            ep.copy_(self.decay*ep+(1-self.decay)*mp.detach())
    def __call__(self, x): return self.model(x)

# ---- Cosine LR + Warmup ----
def cosine_warmup_scheduler(optimizer, warmup, total, min_lr, base_lr):
    def fn(epoch):
        if epoch < warmup: return (epoch+1)/max(1,warmup)
        t=(epoch-warmup)/max(1,total-warmup)
        return max(min_lr/base_lr, 0.5*(1+math.cos(math.pi*t)))
    return optim.lr_scheduler.LambdaLR(optimizer, fn)

# ---- TTA ----
@torch.no_grad()
def tta_inference(model, imgs, device):
    preds = []
    for fh in [False,True]:
        for fv in [False,True]:
            x = imgs.to(device)
            if fh: x = torch.flip(x,[3])
            if fv: x = torch.flip(x,[2])
            preds.append(torch.sigmoid(model(x)))
    return torch.stack(preds).mean(0)

# ---- AUC metric ----
def compute_auc(targets, probs):
    aucs = {}
    for i,name in enumerate(NIH_CLASSES):
        try:
            aucs[name] = roc_auc_score(targets[:,i], probs[:,i])
        except:
            aucs[name] = np.nan
    valid = [v for v in aucs.values() if not np.isnan(v)]
    mauc = float(np.mean(valid)) if len(valid) else 0.0
    return aucs, mauc

def _make_pbar(total, desc):
    pbar = tqdm(
        total=total,
        desc=desc,
        leave=True,
        position=0,
        dynamic_ncols=True,
        mininterval=0.1,
        miniters=1,
        smoothing=0.05,
        bar_format="{l_bar}{bar}| {n_fmt}/{total_fmt} [{elapsed}<{remaining}, {rate_fmt}]"
    )
    # VS Code / Jupyter: ép hiển thị container nếu có
    try:
        if hasattr(pbar, "container"):
            display(pbar.container)
    except Exception:
        pass
    return pbar

def _set_pbar_auroc(pbar, running_auc):
    auc_str = f"{running_auc:.4f}" if not np.isnan(running_auc) else "----"
    try:
        pbar.set_postfix({"auroc": auc_str}, refresh=True)
    except Exception:
        pbar.set_postfix_str(f"auroc={auc_str}", refresh=True)

# ---- Train 1 epoch ----
def train_epoch(model, ema, loader, criterion, optimizer, scaler,
                epoch, epochs, accum_steps, amp, grad_clip, auc_update_steps=50):
    model.train()
    total_loss, n = 0., 0
    optimizer.zero_grad(set_to_none=True)

    seen_t, seen_p = [], []
    running_auc = np.nan

    pbar = _make_pbar(total=len(loader), desc=f"[TRAIN] {epoch:02d}/{epochs:02d}")
    try:
        for step,(imgs,labels) in enumerate(loader, start=1):
            imgs   = imgs.to(DEVICE, non_blocking=True)
            labels = labels.to(DEVICE, non_blocking=True)

            with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
                logits = model(imgs)
                loss   = criterion(logits, labels) / accum_steps

            if amp and AMP_ENABLED:
                scaler.scale(loss).backward()
            else:
                loss.backward()

            if (step % accum_steps == 0) or (step == len(loader)):
                if amp and AMP_ENABLED:
                    scaler.unscale_(optimizer)
                    nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                    scaler.step(optimizer)
                    scaler.update()
                else:
                    nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                    optimizer.step()

                optimizer.zero_grad(set_to_none=True)
                if ema: ema.update(model)

            probs = torch.sigmoid(logits.detach())
            seen_t.append(labels.detach().cpu())
            seen_p.append(probs.detach().cpu())

            batch_loss = loss.item() * accum_steps
            total_loss += batch_loss * imgs.size(0)
            n += imgs.size(0)

            if (step % auc_update_steps == 0) or (step == len(loader)):
                y_t = torch.cat(seen_t, dim=0).numpy()
                y_p = torch.cat(seen_p, dim=0).numpy()
                _, running_auc = compute_auc(y_t, y_p)
                _set_pbar_auroc(pbar, running_auc)

            pbar.update(1)
            if step == 1 or (step % auc_update_steps == 0) or (step == len(loader)):
                pbar.refresh()
    finally:
        pbar.close()

    y_t = torch.cat(seen_t, dim=0).numpy()
    y_p = torch.cat(seen_p, dim=0).numpy()
    _, epoch_auc = compute_auc(y_t, y_p)

    return total_loss / max(1, n), epoch_auc

# ---- Evaluate ----
@torch.no_grad()
def evaluate(model, loader, criterion, amp, epoch=None, epochs=None, use_tta=False, auc_update_steps=20):
    model.eval()
    total_loss, n = 0., 0
    all_t, all_p  = [], []
    running_auc = np.nan

    desc = "[VALID]" if epoch is None else f"[VALID] {epoch:02d}/{epochs:02d}"
    pbar = _make_pbar(total=len(loader), desc=desc)
    try:
        for step,(imgs,labels) in enumerate(loader, start=1):
            imgs   = imgs.to(DEVICE, non_blocking=True)
            labels = labels.to(DEVICE, non_blocking=True)

            if use_tta:
                probs = tta_inference(model, imgs, DEVICE)
                logits = torch.log(probs/(1-probs+1e-8))
            else:
                with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
                    logits = model(imgs)
                probs = torch.sigmoid(logits)

            batch_loss = criterion(logits, labels).item()
            total_loss += batch_loss * imgs.size(0)
            n += imgs.size(0)

            all_t.append(labels.cpu())
            all_p.append(probs.cpu().float())

            if (step % auc_update_steps == 0) or (step == len(loader)):
                y_t = torch.cat(all_t, dim=0).numpy()
                y_p = torch.cat(all_p, dim=0).numpy()
                _, running_auc = compute_auc(y_t, y_p)
                _set_pbar_auroc(pbar, running_auc)

            pbar.update(1)
            if step == 1 or (step % auc_update_steps == 0) or (step == len(loader)):
                pbar.refresh()
    finally:
        pbar.close()

    all_t = torch.cat(all_t).numpy()
    all_p = torch.cat(all_p).numpy()
    aucs, mauc = compute_auc(all_t, all_p)
    return total_loss/max(1, n), mauc, aucs

print("Training utilities OK | tqdm.auto + live AUROC")
