n_tr = len(loaders["train"].dataset)
n_vl = len(loaders["val"].dataset)
n_ts = len(loaders["test"].dataset)
total_p = sum(p.numel() for p in model.parameters())/1e6

print("="*72)
print(f"HybridNet: {CFG['effv2_variant']} x MedMamba++-{CFG['mamba_variant'].capitalize()}")
print(f"  Total params : {total_p:.1f}M")
