NIH_CLASSES = [
    "Atelectasis","Cardiomegaly","Effusion","Infiltration",
    "Mass","Nodule","Pneumonia","Pneumothorax",
    "Consolidation","Edema","Emphysema","Fibrosis",
    "Pleural_Thickening","Hernia",
]
NUM_CLASSES = len(NIH_CLASSES)

class NIHChestXray14(Dataset):
    def __init__(self, csv_path, image_dir, transform=None):
        self.image_dir = Path(image_dir)
        self.transform = transform

        df = pd.read_csv(csv_path).dropna(subset=["Image Index", "Finding Labels"]).copy()
        df["Image Index"] = df["Image Index"].astype(str).str.strip()
        df["Finding Labels"] = df["Finding Labels"].astype(str)

        self.image_names = df["Image Index"].tolist()
        self.labels = np.stack(df["Finding Labels"].apply(self._parse).values).astype(np.float32)
        print(f"  [{Path(csv_path).stem:12s}] {len(self.image_names):6d} anh")

    def _parse(self, s):
        v = np.zeros(NUM_CLASSES, dtype=np.float32)
        for lbl in s.split("|"):
            lbl = lbl.strip()
            if lbl in NIH_CLASSES:
                v[NIH_CLASSES.index(lbl)] = 1.0
        return v

    def __len__(self):
        return len(self.image_names)

    def __getitem__(self, idx):
        img_name = self.image_names[idx]
        img_path = self.image_dir / img_name

        if not img_path.exists():
            raise FileNotFoundError(f"Khong tim thay anh: {img_path}")

        with Image.open(img_path) as img:
            img = img.convert("RGB")
            img = img.copy()

        if self.transform is not None:
            img = self.transform(img)

        label = torch.from_numpy(self.labels[idx])
        return img, label


def get_transforms(split, image_size=224):
    mean, std = [0.485,0.456,0.406], [0.229,0.224,0.225]

    if split == "train":
        return transforms.Compose([
            transforms.Resize((image_size, image_size)),
            transforms.RandomHorizontalFlip(),
            transforms.ToTensor(),
            transforms.Normalize(mean, std),
        ])

    return transforms.Compose([
        transforms.Resize((image_size, image_size)),
        transforms.ToTensor(),
        transforms.Normalize(mean, std),
    ])


def get_dataloaders(split_dir, image_dir, batch_size=4, num_workers=0, image_size=224, pin_memory=False):
    split_dir = Path(split_dir)
    csv_map = {
        "train": split_dir / "train.csv",
        "val":   split_dir / "validation.csv",
        "test":  split_dir / "test.csv"
    }

    print("Dang tai NIH ChestX-ray14...")
    loaders = {}
    for split, csv_path in csv_map.items():
        ds = NIHChestXray14(
            csv_path=csv_path,
            image_dir=image_dir,
            transform=get_transforms("train" if split == "train" else "val", image_size)
        )

        loaders[split] = DataLoader(
            ds,
            batch_size=batch_size,
            shuffle=(split == "train"),
            num_workers=num_workers,
            pin_memory=pin_memory,
            drop_last=(split == "train"),
            persistent_workers=False,
        )
    return loaders


def get_class_frequencies(split_dir):
    df = pd.read_csv(Path(split_dir)/"train.csv")
    df["Finding Labels"] = df["Finding Labels"].fillna("No Finding").astype(str)

    def parse(s):
        v = np.zeros(NUM_CLASSES, np.float32)
        for lbl in s.split("|"):
            lbl = lbl.strip()
            if lbl in NIH_CLASSES:
                v[NIH_CLASSES.index(lbl)] = 1.
        return v

    labels = np.stack(df["Finding Labels"].apply(parse).values)
    freq = torch.from_numpy(labels.mean(0).astype(np.float32))

    print("Positive rate moi class (train.csv):")
    for n, f in zip(NIH_CLASSES, freq):
        print(f"  {n:20s}  {f:.4f}  {chr(9608)*int(f*80)}")
    return freq

