class AsymmetricLoss(nn.Module):
    def __init__(self, gamma_neg=4., gamma_pos=1., clip=0.05,
                 eps=1e-8, class_freq=None, reduction="mean"):
        super().__init__()
        self.gamma_neg=gamma_neg; self.gamma_pos=gamma_pos
        self.clip=clip; self.eps=eps; self.reduction=reduction
        if class_freq is not None:
            w=(1.-class_freq).clamp(min=1e-3).pow(0.5)
            self.register_buffer("class_weight",(w/w.mean()).float())
        else:
            self.class_weight=None

    def forward(self, logits, targets):
        p   = torch.sigmoid(logits)
        p_m = (p-self.clip).clamp(min=0) if self.clip>0 else p
        L_pos = targets   *(1-p).pow(self.gamma_pos)*torch.log(p   +self.eps)
        L_neg = (1-targets)*p_m.pow(self.gamma_neg) *torch.log(1-p_m+self.eps)
        loss  = -(L_pos+L_neg)
        if self.class_weight is not None:
            loss = loss*self.class_weight.to(loss.device)
        return loss.mean() if self.reduction=="mean" else loss.sum()

print("AsymmetricLoss OK")
