print(f"  Batch setup  : {CFG['batch_size']} x {CFG['accum_steps']} = {CFG['batch_size']*CFG['accum_steps']}")
print(f"  DataLoader   : workers={CFG['num_workers']} | pin_memory={CFG['pin_memory']}")
print(f"  Phase 1      : epoch 1-{PHASE2_START-1} (CNN frozen)")
print(f"  Phase 2      : epoch {PHASE2_START}-{CFG['epochs']} (full)")
print("=" * 72)

best_auc = 0.0
history = []

patience = CFG["early_stop_patience"]
min_delta = CFG["early_stop_min_delta"]
epochs_no_improve = 0

for epoch in range(1, CFG["epochs"] + 1):

    if epoch == PHASE2_START:
        print("\n>>> PHASE 2: Unfreeze EfficientNetV2, full fine-tune <<<")
        model.unfreeze_all()
        param_groups = model.get_param_groups(CFG["lr"])
        optimizer = optim.AdamW(param_groups, weight_decay=CFG["weight_decay"])
        scheduler = cosine_warmup_scheduler(
            optimizer, 2, CFG["epochs"] - PHASE2_START + 1, CFG["min_lr"], CFG["lr"]
        )
        scaler = torch.amp.GradScaler("cuda", enabled=(CFG["amp"] and AMP_ENABLED))

    t0 = time.time()
    phase_name = "P1-frozen" if epoch < PHASE2_START else "P2-full"
    print(f"\nEpoch {epoch:02d}/{CFG['epochs']:02d} | phase={phase_name}")

    train_loss, train_auc = train_epoch(
        model=model,
        ema=ema,
        loader=loaders["train"],
        criterion=criterion,
        optimizer=optimizer,
        scaler=scaler,
        epoch=epoch,
        epochs=CFG["epochs"],
        accum_steps=CFG["accum_steps"],
        amp=CFG["amp"],
        grad_clip=CFG["grad_clip"],
        auc_update_steps=CFG["train_auc_update_steps"],
    )

    val_model = ema.model if ema else model
    val_loss, val_auc, val_aucs = evaluate(
        model=val_model,
        loader=loaders["val"],
        criterion=criterion,
        amp=CFG["amp"],
        use_tta=False,
        auc_update_steps=CFG["valid_auc_update_steps"],
    )

    scheduler.step()

    epoch_time = time.time() - t0
    cur_lrs = {g.get("name", f"g{i}"): g["lr"] for i, g in enumerate(optimizer.param_groups)}

    row = {
        "epoch": epoch,
        "phase": 1 if epoch < PHASE2_START else 2,
        "train_loss": float(train_loss),
        "train_mean_auc": float(train_auc),
        "val_loss": float(val_loss),
        "val_mean_auc": float(val_auc),
        "epoch_time_sec": float(epoch_time),
        "lr_groups": cur_lrs,
    }
    history.append(row)
    json.dump(history, open(OUTPUT_DIR/"history.json", "w"), indent=2)

    print(f"Epoch {epoch:02d} done in {epoch_time/60:.1f} min")
    print(f"  Train loss={train_loss:.4f} | Train mAUC={train_auc:.4f}")
    print(f"  Val   loss={val_loss:.4f} | Val   mAUC={val_auc:.4f}")

    improved = (val_auc - best_auc) > min_delta
    if improved:
        best_auc = val_auc
        epochs_no_improve = 0
        torch.save({
            "epoch": epoch,
            "auc": best_auc,
            "model": (ema.model if ema else model).state_dict(),
            "cfg": CFG,
        }, OUTPUT_DIR/"best_model.pth")
        print(f"  >> Best model updated: mAUC={best_auc:.4f}")
    else:
        epochs_no_improve += 1
        print(f"  No improvement ({epochs_no_improve}/{patience})")

    if epoch % CFG["save_freq"] == 0:
        torch.save({
            "epoch": epoch,
            "auc": val_auc,
            "model": model.state_dict(),
            "cfg": CFG,
        }, OUTPUT_DIR/f"checkpoint_epoch_{epoch:03d}.pth")

    if epochs_no_improve >= patience:
        print(f"\nEarly stopping at epoch {epoch:02d} | best val mAUC={best_auc:.4f}")
        break

print("\nTraining finished.")
print(f"Best validation mAUC = {best_auc:.4f}")
