class EfficientNetV2FeatureExtractor(nn.Module):
    """
    EfficientNetV2 backbone (pretrained ImageNet) -- output spatial feature map.
    Muc tieu: lay feature map cuoi cung (B, C, H, W), KHONG global average pooling.
    """
    def __init__(self, variant="tf_efficientnetv2_s", pretrained=True, drop_rate=0.3):
        super().__init__()
        self.backbone = timm.create_model(
            variant,
            pretrained=pretrained,
            num_classes=0,
            global_pool="",   # tat pooling trong head
            drop_rate=drop_rate,
        )
        self.out_channels = self.backbone.num_features
        print(f"EfficientNetV2 ({variant}) | out_channels={self.out_channels} | pretrained={pretrained}")

    def forward(self, x):
        feat = self.backbone.forward_features(x)
        if isinstance(feat, (list, tuple)):
            feat = feat[-1]
        if feat.ndim != 4:
            raise RuntimeError(f"EfficientNetV2 forward_features phai tra ve tensor 4 chieu, nhan duoc {tuple(feat.shape)}")
        return feat   # (B, C, H, W)


