# ---- EMA ----
class ModelEMA:
    def __init__(self, model, decay=0.9998):
        self.model = deepcopy(model).eval()
        self.decay = decay
        for p in self.model.parameters():
            p.requires_grad_(False)

    @torch.no_grad()
    def update(self, model):
        for ep, mp in zip(self.model.parameters(), model.parameters()):
            ep.copy_(self.decay * ep + (1 - self.decay) * mp.detach())

    def state_dict(self):
        return self.model.state_dict()

    def load_state_dict(self, state_dict):
        self.model.load_state_dict(state_dict)

    def __call__(self, x):
        return self.model(x)


# ---- Cosine LR + Warmup ----
def cosine_warmup_scheduler(optimizer, warmup, total, min_lr, base_lr):
    def fn(epoch):
        if epoch < warmup:
            return (epoch + 1) / max(1, warmup)
        t = (epoch - warmup) / max(1, total - warmup)
        return max(min_lr / base_lr, 0.5 * (1 + math.cos(math.pi * t)))
    return optim.lr_scheduler.LambdaLR(optimizer, fn)


# ---- TTA ----
@torch.no_grad()
def tta_inference(model, imgs, device):
    preds = []
    for fh in [False, True]:
        for fv in [False, True]:
            x = imgs.to(device, non_blocking=False)
            if CFG.get("use_channels_last", False) and x.ndim == 4:
                x = x.to(memory_format=torch.channels_last)
            if fh:
                x = torch.flip(x, [3])
            if fv:
                x = torch.flip(x, [2])
            preds.append(torch.sigmoid(model(x)))
    return torch.stack(preds).mean(0)


# ---- AUC metric ----
def compute_auc(targets, probs):
    aucs = {}
    for i, name in enumerate(NIH_CLASSES):
        y_true = targets[:, i]
        y_prob = probs[:, i]
        if np.unique(y_true).size < 2:
            aucs[name] = np.nan
            continue
        try:
            aucs[name] = roc_auc_score(y_true, y_prob)
        except Exception:
            aucs[name] = np.nan
    valid = [v for v in aucs.values() if not np.isnan(v)]
    mauc = float(np.mean(valid)) if len(valid) else np.nan
    return aucs, mauc


def _format_auc(mauc):
    return "nan" if np.isnan(mauc) else f"{mauc:.4f}"


def _live_mauc_from_lists(all_t, all_p):
    if not all_t or not all_p:
        return np.nan
    try:
        t = torch.cat(all_t, dim=0).numpy()
        p = torch.cat(all_p, dim=0).numpy()
        _, mauc = compute_auc(t, p)
        return mauc
    except Exception:
        return np.nan


def _make_pbar(total, desc):
    return tqdm(
        total=total,
        desc=desc,
        leave=True,
        dynamic_ncols=False,
        ascii=True,
        file=sys.stdout,
        mininterval=0.2,
        smoothing=0.05,
        bar_format="{l_bar}{bar}| {n_fmt}/{total_fmt} [{elapsed}<{remaining}, {rate_fmt}{postfix}]",
    )


def _move_image(imgs):
    imgs = imgs.to(DEVICE, non_blocking=bool(CFG["pin_memory"]))
    if CFG.get("use_channels_last", False) and imgs.ndim == 4:
        imgs = imgs.to(memory_format=torch.channels_last)
    return imgs


def save_last_checkpoint(output_dir, epoch, model, ema, optimizer, scheduler, scaler,
                         best_auc, epochs_no_improve, history, phase_name):
    ckpt = {
        "epoch": epoch,
        "model": model.state_dict(),
        "ema": ema.state_dict() if ema is not None else None,
        "optimizer": optimizer.state_dict() if optimizer is not None else None,
        "scheduler": scheduler.state_dict() if scheduler is not None else None,
        "scaler": scaler.state_dict() if scaler is not None else None,
        "best_auc": best_auc,
        "epochs_no_improve": epochs_no_improve,
        "history": history,
        "phase_name": phase_name,
        "cfg": dict(CFG),
    }
    torch.save(ckpt, output_dir / "last_checkpoint.pth")


def load_history_if_exists(output_dir):
    hist_path = Path(output_dir) / "history.json"
    if hist_path.exists():
        try:
            with open(hist_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    return []


def choose_resume_source(output_dir, explicit_path=""):
    explicit_path = (explicit_path or "").strip()
    best_path = Path(output_dir) / "best_model.pth"
    last_path = Path(output_dir) / "last_checkpoint.pth"

    if explicit_path:
        p = Path(explicit_path)
        if p.exists():
            return p, "explicit"
        print(f"[RESUME] resume_path khong ton tai: {p}")

    if last_path.exists():
        return last_path, "last_checkpoint"

    if best_path.exists():
        return best_path, "best_model"

    return None, None


def load_resume_metadata(output_dir, resume_path):
    ckpt = torch.load(resume_path, map_location=DEVICE)
    history = ckpt.get("history", None)
    if history is None:
        history = load_history_if_exists(output_dir)

    meta = {
        "resume_path": str(resume_path),
        "epoch": int(ckpt.get("epoch", 0)),
        "start_epoch": int(ckpt.get("epoch", 0)) + 1,
        "best_auc": float(ckpt.get("best_auc", ckpt.get("auc", 0.0))),
        "epochs_no_improve": int(ckpt.get("epochs_no_improve", 0)),
        "history": history,
        "model_state": ckpt.get("model", None),
        "ema_state": ckpt.get("ema", None),
        "optimizer_state": ckpt.get("optimizer", None),
        "scheduler_state": ckpt.get("scheduler", None),
        "scaler_state": ckpt.get("scaler", None),
        "phase_name": ckpt.get("phase_name", ""),
        "raw": ckpt,
    }
    return meta


def apply_resume_states(meta, model, ema=None, optimizer=None, scheduler=None, scaler=None):
    if meta.get("model_state") is not None:
        model.load_state_dict(meta["model_state"])

    if ema is not None and meta.get("ema_state") is not None:
        ema.load_state_dict(meta["ema_state"])

    if optimizer is not None and meta.get("optimizer_state") is not None:
        optimizer.load_state_dict(meta["optimizer_state"])

    if scheduler is not None and meta.get("scheduler_state") is not None:
        scheduler.load_state_dict(meta["scheduler_state"])

    if scaler is not None and meta.get("scaler_state") is not None:
        scaler.load_state_dict(meta["scaler_state"])


# ---- Train 1 epoch ----
def train_epoch(model, ema, loader, criterion, optimizer, scaler,
                epoch, epochs, accum_steps, amp, grad_clip,
                log_every=20, auc_update_steps=50):
    model.train()
    total_loss, n = 0.0, 0
    running_loss, running_n = 0.0, 0
    all_t, all_p = [], []
    live_mauc = np.nan

    optimizer.zero_grad(set_to_none=True)
    pbar = _make_pbar(len(loader), f"Train {epoch:02d}/{epochs:02d}")

    for step, (imgs, labels) in enumerate(loader, start=1):
        imgs = _move_image(imgs)
        labels = labels.to(DEVICE, non_blocking=bool(CFG["pin_memory"]))

        with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
            logits = model(imgs)
            loss = criterion(logits, labels) / accum_steps

        if amp and AMP_ENABLED:
            scaler.scale(loss).backward()
        else:
            loss.backward()

        if (step % accum_steps == 0) or (step == len(loader)):
            if amp and AMP_ENABLED:
                scaler.unscale_(optimizer)
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                scaler.step(optimizer)
                scaler.update()
            else:
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                optimizer.step()

            optimizer.zero_grad(set_to_none=True)

            if ema is not None:
                ema.update(model)

        batch_loss = loss.item() * accum_steps
        bs = imgs.size(0)
        total_loss += batch_loss * bs
        n += bs
        running_loss += batch_loss * bs
        running_n += bs

        probs = torch.sigmoid(logits.detach())
        all_t.append(labels.detach().cpu())
        all_p.append(probs.detach().cpu().float())

        need_auc_update = (step % max(1, auc_update_steps) == 0) or (step == len(loader))
        if need_auc_update:
            live_mauc = _live_mauc_from_lists(all_t, all_p)

        if (step % log_every == 0) or (step == len(loader)) or need_auc_update:
            avg_loss = running_loss / max(running_n, 1)
            lr = optimizer.param_groups[0]["lr"]
            pbar.set_postfix_str(
                f"loss={batch_loss:.4f}, avg={avg_loss:.4f}, auc={_format_auc(live_mauc)}, lr={lr:.2e}"
            )
            if (step % log_every == 0) or (step == len(loader)):
                running_loss, running_n = 0.0, 0

        pbar.update(1)

    pbar.close()
    _, epoch_mauc = compute_auc(torch.cat(all_t).numpy(), torch.cat(all_p).numpy())
    return total_loss / max(n, 1), epoch_mauc


# ---- Evaluate ----
@torch.no_grad()
def evaluate(model, loader, criterion, amp, epoch=None, epochs=None,
             use_tta=False, log_every=20, auc_update_steps=20):
    model.eval()
    total_loss, n = 0.0, 0
    running_loss, running_n = 0.0, 0
    all_t, all_p = [], []
    live_mauc = np.nan

    desc = "Valid" if epoch is None else f"Valid {epoch:02d}/{epochs:02d}"
    pbar = _make_pbar(len(loader), desc)

    for step, (imgs, labels) in enumerate(loader, start=1):
        imgs = _move_image(imgs)
        labels = labels.to(DEVICE, non_blocking=bool(CFG["pin_memory"]))

        if use_tta:
            probs = tta_inference(model, imgs, DEVICE)
            logits = torch.log(probs / (1 - probs + 1e-8))
        else:
            with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
                logits = model(imgs)
            probs = torch.sigmoid(logits)

        batch_loss = criterion(logits, labels).item()
        bs = imgs.size(0)
        total_loss += batch_loss * bs
        n += bs
        running_loss += batch_loss * bs
        running_n += bs

        all_t.append(labels.detach().cpu())
        all_p.append(probs.detach().cpu().float())

        need_auc_update = (step % max(1, auc_update_steps) == 0) or (step == len(loader))
        if need_auc_update:
            live_mauc = _live_mauc_from_lists(all_t, all_p)

        if (step % log_every == 0) or (step == len(loader)) or need_auc_update:
            avg_loss = running_loss / max(running_n, 1)
            pbar.set_postfix_str(
                f"loss={batch_loss:.4f}, avg={avg_loss:.4f}, auc={_format_auc(live_mauc)}"
            )
            if (step % log_every == 0) or (step == len(loader)):
                running_loss, running_n = 0.0, 0

        pbar.update(1)

    pbar.close()

    all_t = torch.cat(all_t).numpy()
    all_p = torch.cat(all_p).numpy()
    aucs, mauc = compute_auc(all_t, all_p)
    return total_loss / max(n, 1), mauc, aucs

print("Training utilities OK | compact logs + live AUC + fallback resume(best_model -> no last_checkpoint)")
