def ensure_dir(path):
    Path(path).mkdir(parents=True, exist_ok=True)

def save_json(obj, path):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)

def load_json(path, default=None):
    if not Path(path).exists():
        return {} if default is None else default
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

class AverageMeter:
    def __init__(self):
        self.reset()

    def reset(self):
        self.sum = 0.0
        self.count = 0
        self.avg = 0.0

    def update(self, val, n=1):
        self.sum += float(val) * n
        self.count += n
        self.avg = self.sum / max(self.count, 1)

def safe_macro_auc(y_true, y_prob):
    y_true = np.asarray(y_true)
    y_prob = np.asarray(y_prob)

    if y_true.ndim == 1:
        return float(roc_auc_score(y_true, y_prob)) if np.unique(y_true).size >= 2 else float("nan")

    aucs = []
    for c in range(y_true.shape[1]):
        yt = y_true[:, c]
        yp = y_prob[:, c]

        valid = np.isfinite(yt) & np.isfinite(yp)
        yt = yt[valid]
        yp = yp[valid]

        if yt.size == 0:
            continue
        if np.unique(yt).size < 2:
            continue

        try:
            aucs.append(roc_auc_score(yt, yp))
        except ValueError:
            pass

    return float(np.mean(aucs)) if len(aucs) > 0 else float("nan")

def _get_first(d, keys, default=None):
    if not isinstance(d, dict):
        return default
    for k in keys:
        if k in d:
            return d[k]
    return default

def move_optimizer_state_to_device(optimizer, device):
    for state in optimizer.state.values():
        for k, v in state.items():
            if torch.is_tensor(v):
                state[k] = v.to(device)

def build_train_state(epoch, model, optimizer=None, scheduler=None, scaler=None, best_auc=-np.inf, history=None):
    return {
        "epoch": int(epoch),
        "model_state_dict": model.state_dict(),
        "optimizer_state_dict": optimizer.state_dict() if optimizer is not None else None,
        "scheduler_state_dict": scheduler.state_dict() if scheduler is not None else None,
        "scaler_state_dict": scaler.state_dict() if scaler is not None else None,
        "best_auc": float(best_auc),
        "history": history if isinstance(history, dict) else {},
        "cfg": CFG,
    }

def find_resume_file(output_dir):
    output_dir = Path(output_dir)

    # ưu tiên last_checkpoint
    candidates = [
        output_dir / "checkpoints" / "last_checkpoint.pth",
        output_dir / "last_checkpoint.pth",
    ]
    for p in candidates:
        if p.exists():
            return p, "last_checkpoint"

    # fallback best_model
    best_candidates = []
    for folder in [output_dir / "best_models", output_dir]:
        if folder.exists():
            best_candidates += list(folder.glob("best_model*.pth"))
            best_candidates += list(folder.glob("best*.pth"))

    best_candidates = [p for p in best_candidates if p.is_file()]
    if best_candidates:
        best_candidates.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        return best_candidates[0], "best_model"

    return None, None

def load_train_state(resume_path, model, optimizer=None, scheduler=None, scaler=None, device="cpu"):
    ckpt = torch.load(resume_path, map_location="cpu")

    # file cũ chỉ lưu raw state_dict
    if not isinstance(ckpt, dict):
        model.load_state_dict(ckpt, strict=False)
        return 0, -np.inf, {}

    model_state = _get_first(ckpt, ["model_state_dict", "state_dict", "model", "model_state"])
    if model_state is None:
        if all(torch.is_tensor(v) for v in ckpt.values()):
            model_state = ckpt

    if model_state is None:
        raise RuntimeError(f"Không tìm thấy model_state_dict trong file: {resume_path}")

    model.load_state_dict(model_state, strict=False)

    opt_state = _get_first(ckpt, ["optimizer_state_dict", "optimizer"])
    if optimizer is not None and opt_state is not None:
        try:
            optimizer.load_state_dict(opt_state)
            move_optimizer_state_to_device(optimizer, device)
        except Exception as e:
            print(f"[WARN] Không nạp được optimizer_state_dict: {e}")

    sch_state = _get_first(ckpt, ["scheduler_state_dict", "scheduler"])
    if scheduler is not None and sch_state is not None:
        try:
            scheduler.load_state_dict(sch_state)
        except Exception as e:
            print(f"[WARN] Không nạp được scheduler_state_dict: {e}")

    scaler_state = _get_first(ckpt, ["scaler_state_dict", "scaler"])
    if scaler is not None and scaler_state is not None:
        try:
            scaler.load_state_dict(scaler_state)
        except Exception as e:
            print(f"[WARN] Không nạp được scaler_state_dict: {e}")

    best_auc = float(_get_first(ckpt, ["best_auc", "best_score", "best_val_auc", "best_mauc"], default=-np.inf))
    saved_epoch = int(_get_first(ckpt, ["epoch", "current_epoch"], default=-1))
    history = _get_first(ckpt, ["history"], default={})
    if not isinstance(history, dict):
        history = {}

    start_epoch = saved_epoch + 1 if saved_epoch >= 0 else 0
    return start_epoch, best_auc, history
