# =========================
# 4) Dataset
# =========================
PATH_COL_CANDIDATES = ["image_path", "path", "filepath", "full_path", "Image Path"]

def infer_label_columns(df, cfg):
    if cfg["label_cols"] is not None:
        return cfg["label_cols"]

    exclude = set(PATH_COL_CANDIDATES + cfg["filename_col_candidates"] + [
        "Patient ID", "PatientID", "patient_id",
        "Finding Labels", "split", "fold",
        "Frontal/Lateral", "View Position",
        "followup", "Follow-up #", "Age", "Gender", "sex"
    ])

    label_cols = []
    for c in df.columns:
        if c in exclude:
            continue
        s = df[c]
        if pd.api.types.is_numeric_dtype(s):
            # giữ lại cột nhãn dạng 0/1/-1/float
            nunique = s.dropna().nunique()
            if nunique <= 10:
                label_cols.append(c)

    return label_cols

def infer_image_path(row, image_root, filename_col_candidates):
    for c in PATH_COL_CANDIDATES:
        if c in row.index and pd.notna(row[c]) and str(row[c]).strip():
            return str(row[c])

    for c in filename_col_candidates:
        if c in row.index and pd.notna(row[c]) and str(row[c]).strip():
            return str(Path(image_root) / str(row[c]))

    raise KeyError("Không tìm thấy cột đường dẫn ảnh hoặc tên file trong CSV.")

class MultiLabelCSVDataset(Dataset):
    def __init__(self, csv_path, cfg, transform=None):
        self.csv_path = Path(csv_path)
        self.df = pd.read_csv(self.csv_path)
        self.transform = transform
        self.image_root = cfg["image_root"]

        self.label_cols = infer_label_columns(self.df, cfg)
        if len(self.label_cols) == 0:
            raise RuntimeError(f"Không suy ra được label columns từ file: {csv_path}")

        # chuẩn hoá nhãn về float32
        self.df[self.label_cols] = self.df[self.label_cols].astype(np.float32)

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):
        row = self.df.iloc[idx]
        img_path = infer_image_path(row, self.image_root, CFG["filename_col_candidates"])

        img = Image.open(img_path).convert("RGB")
        if self.transform is not None:
            img = self.transform(img)

        target = row[self.label_cols].values.astype(np.float32)
        target = torch.tensor(target, dtype=torch.float32)

        return img, target, img_path

train_tfms = T.Compose([
    T.Resize((CFG["img_size"], CFG["img_size"])),
    T.RandomHorizontalFlip(p=0.5),
    T.RandomRotation(degrees=10),
    T.ToTensor(),
    T.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
])

valid_tfms = T.Compose([
    T.Resize((CFG["img_size"], CFG["img_size"])),
    T.ToTensor(),
    T.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
])

train_ds = MultiLabelCSVDataset(CFG["train_csv"], CFG, transform=train_tfms)
valid_ds = MultiLabelCSVDataset(CFG["valid_csv"], CFG, transform=valid_tfms)

CFG["label_cols"] = train_ds.label_cols
CFG["num_classes"] = len(train_ds.label_cols)

print("Train size:", len(train_ds))
print("Valid size:", len(valid_ds))
print("Num labels:", CFG["num_classes"])
print("Label cols:", CFG["label_cols"])
