print(f"  Fastpath     : channels_last={CFG['use_channels_last']} | amp={CFG['amp']} | image={CFG['image_size']}")
print(f"  Phase 1      : epoch 1-{PHASE2_START-1} (CNN frozen)")
print(f"  Phase 2      : epoch {PHASE2_START}-{CFG['epochs']} (full)")
print("=" * 72)

if start_epoch > CFG["epochs"]:
    print(f">> Da hoan tat den epoch {resume_epoch:02d}. Khong con gi de train tiep.")

patience = CFG["early_stop_patience"]
min_delta = CFG["early_stop_min_delta"]
epochs_no_improve = 0

for epoch in range(start_epoch, CFG["epochs"] + 1):

    if epoch == PHASE2_START:
        print("\n>>> PHASE 2: Unfreeze EfficientNetV2, full fine-tune <<<")
        model.unfreeze_all()
        param_groups = model.get_param_groups(CFG["lr"])
        optimizer = optim.AdamW(param_groups, weight_decay=CFG["weight_decay"])
        scheduler = cosine_warmup_scheduler(
            optimizer, 2, CFG["epochs"] - PHASE2_START + 1, CFG["min_lr"], CFG["lr"]
        )
        scaler = torch.amp.GradScaler("cuda", enabled=(CFG["amp"] and AMP_ENABLED))

    t0 = time.time()
    phase_name = "P1-frozen" if epoch < PHASE2_START else "P2-full"
    print(f"\nEpoch {epoch:02d}/{CFG['epochs']:02d} | phase={phase_name}")

    train_loss = train_epoch(
        model=model,
        ema=ema,
        loader=loaders["train"],
        criterion=criterion,
        optimizer=optimizer,
        scaler=scaler,
        epoch=epoch,
        epochs=CFG["epochs"],
        accum_steps=CFG["accum_steps"],
        amp=CFG["amp"],
        grad_clip=CFG["grad_clip"],
    )

    val_model = ema.model if ema else model
    val_loss, val_auc, val_aucs = evaluate(
        model=val_model,
        loader=loaders["val"],
        criterion=criterion,
        amp=CFG["amp"],
        epoch=epoch,
        epochs=CFG["epochs"],
        use_tta=False,
        auc_update_steps=CFG["valid_auc_update_steps"],
    )
    scheduler.step()

    rec = {
        "epoch": epoch,
        "train_loss": train_loss,
        "train_mean_auc": np.nan,
        "val_loss": val_loss,
        "val_mean_auc": val_auc,
        "phase": 1 if epoch < PHASE2_START else 2,
        **{f"auc_{k}": v for k, v in val_aucs.items()}
    }
    history.append(rec)
    with open(OUTPUT_DIR / "history.json", "w", encoding="utf-8") as f:
        json.dump(history, f, indent=2)

    ph = "P1-frozen" if epoch < PHASE2_START else "P2-full"
    lr = optimizer.param_groups[0]["lr"]
    print("\n" + "-" * 70)
    print(f"Epoch {epoch:02d}/{CFG['epochs']} [{ph}] | {time.time()-t0:.0f}s | LR={lr:.2e}")
    print(f"  Train Loss : {train_loss:.4f}")
    print(f"  Val Loss   : {val_loss:.4f} | Val mAUC  : {val_auc:.4f}")

    best_class_auc = np.nanmax(list(val_aucs.values()))
    for k, v in val_aucs.items():
        vv = 0.0 if np.isnan(v) else v
        bar = chr(9608) * int(vv * 20)
        star = " <--" if vv == best_class_auc else ""
        print(f"    {k:22s}: {vv:.4f}  {bar}{star}")

    # save last checkpoint moi epoch
    torch.save(
        build_ckpt(epoch, model, ema, optimizer, scheduler, scaler, best_auc, history),
        OUTPUT_DIR / "last_checkpoint.pth"
    )

    if val_auc > best_auc + min_delta:
        best_auc = val_auc
        epochs_no_improve = 0
        torch.save(
            build_ckpt(epoch, model, ema, optimizer, scheduler, scaler, best_auc, history),
            OUTPUT_DIR / "best_model.pth"
        )
        print(f"  *** Best mAUC: {best_auc:.4f} -> saved ***")
    else:
        epochs_no_improve += 1
        print(f"  No improvement: {epochs_no_improve}/{patience}")

    if epoch % CFG["save_freq"] == 0:
        torch.save(
            build_ckpt(epoch, model, ema, optimizer, scheduler, scaler, best_auc, history),
            OUTPUT_DIR / f"ckpt_ep{epoch:02d}.pth"
        )

    if epochs_no_improve >= patience:
        print(f"\nEarly stopping triggered at epoch {epoch} (best mAUC={best_auc:.4f})")
        break

print("=" * 70)
print(f"Training xong! Best Val mAUC = {best_auc:.4f}")
