# ---- EMA ----
class ModelEMA:
    def __init__(self, model, decay=0.9998):
        self.model = deepcopy(model).eval()
        self.decay = decay
        for p in self.model.parameters():
            p.requires_grad_(False)

    @torch.no_grad()
    def update(self, model):
        for ep, mp in zip(self.model.parameters(), model.parameters()):
            ep.copy_(self.decay * ep + (1 - self.decay) * mp.detach())

    def __call__(self, x):
        return self.model(x)


# ---- Cosine LR + Warmup ----
def cosine_warmup_scheduler(optimizer, warmup, total, min_lr, base_lr):
    def fn(epoch):
        if epoch < warmup:
            return (epoch + 1) / max(1, warmup)
        t = (epoch - warmup) / max(1, total - warmup)
        return max(min_lr / base_lr, 0.5 * (1 + math.cos(math.pi * t)))
    return optim.lr_scheduler.LambdaLR(optimizer, fn)


# ---- TTA ----
@torch.no_grad()
def tta_inference(model, imgs, device):
    preds = []
    for fh in [False, True]:
        for fv in [False, True]:
            x = imgs.to(device, non_blocking=False)
            if CFG.get("use_channels_last", False) and x.ndim == 4:
                x = x.to(memory_format=torch.channels_last)
            if fh:
                x = torch.flip(x, [3])
            if fv:
                x = torch.flip(x, [2])
            preds.append(torch.sigmoid(model(x)))
    return torch.stack(preds).mean(0)


# ---- AUC metric ----
def compute_auc(targets, probs):
    aucs = {}
    for i, name in enumerate(NIH_CLASSES):
        y_true = np.asarray(targets[:, i])
        y_prob = np.asarray(probs[:, i])

        valid_mask = np.isfinite(y_true) & np.isfinite(y_prob)
        y_true = y_true[valid_mask]
        y_prob = y_prob[valid_mask]

        if len(y_true) == 0 or np.unique(y_true).size < 2:
            aucs[name] = np.nan
            continue

        try:
            aucs[name] = roc_auc_score(y_true, y_prob)
        except Exception:
            aucs[name] = np.nan
    valid = [v for v in aucs.values() if not np.isnan(v)]
    mauc = float(np.mean(valid)) if len(valid) else 0.0
    return aucs, mauc


def find_resume_file(output_dir):
    output_dir = Path(output_dir)
    last_ckpt = output_dir / "last_checkpoint.pth"
    if last_ckpt.exists():
        return last_ckpt, "last_checkpoint"

    best_ckpt = output_dir / "best_model.pth"
    if best_ckpt.exists():
        return best_ckpt, "best_model"

    return None, None


def move_optimizer_state_to_device(optimizer, device):
    for state in optimizer.state.values():
        for k, v in state.items():
            if torch.is_tensor(v):
                state[k] = v.to(device)


def build_ckpt(epoch, model, ema, optimizer, scheduler, scaler, best_auc, history):
    return {
        "epoch": epoch,
        "model": model.state_dict(),
        "ema_model": ema.model.state_dict() if ema is not None else None,
        "optimizer": optimizer.state_dict() if optimizer is not None else None,
        "scheduler": scheduler.state_dict() if scheduler is not None else None,
        "scaler": scaler.state_dict() if scaler is not None else None,
        "best_auc": best_auc,
        "auc": best_auc,
        "history": history,
        "cfg": CFG,
    }


def _make_pbar(total, desc):
    return tqdm(
        total=total,
        desc=desc,
        leave=True,
        dynamic_ncols=False,
        ascii=True,
        file=sys.stdout,
        mininterval=0.2,
        smoothing=0.05,
        bar_format="{l_bar}{bar}| {n_fmt}/{total_fmt} [{elapsed}<{remaining}, {rate_fmt}{postfix}]",
    )


def _move_image(imgs):
    imgs = imgs.to(DEVICE, non_blocking=bool(CFG["pin_memory"]))
    if CFG.get("use_channels_last", False) and imgs.ndim == 4:
        imgs = imgs.to(memory_format=torch.channels_last)
    return imgs


# ---- Train 1 epoch ----
def train_epoch(model, ema, loader, criterion, optimizer, scaler,
                epoch, epochs, accum_steps, amp, grad_clip):
    model.train()
    total_loss, n = 0.0, 0
    optimizer.zero_grad(set_to_none=True)

    pbar = _make_pbar(len(loader), f"Train {epoch:02d}/{epochs:02d}")

    for step, (imgs, labels) in enumerate(loader, start=1):
        imgs = _move_image(imgs)
        labels = labels.to(DEVICE, non_blocking=bool(CFG["pin_memory"]))

        with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
            logits = model(imgs)
            loss = criterion(logits, labels) / accum_steps

        if amp and AMP_ENABLED:
            scaler.scale(loss).backward()
        else:
            loss.backward()

        if (step % accum_steps == 0) or (step == len(loader)):
            if amp and AMP_ENABLED:
                scaler.unscale_(optimizer)
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                scaler.step(optimizer)
                scaler.update()
            else:
                nn.utils.clip_grad_norm_(model.parameters(), grad_clip)
                optimizer.step()

            optimizer.zero_grad(set_to_none=True)

            if ema is not None:
                ema.update(model)

        batch_loss = loss.item() * accum_steps
        total_loss += batch_loss * imgs.size(0)
        n += imgs.size(0)

        pbar.set_postfix_str(f"loss={batch_loss:.4f}")
        pbar.update(1)

    pbar.close()
    return total_loss / max(n, 1)


# ---- Evaluate ----
@torch.no_grad()
def evaluate(model, loader, criterion, amp, epoch=None, epochs=None, use_tta=False, auc_update_steps=20):
    model.eval()
    total_loss, n = 0.0, 0
    all_t, all_p = [], []

    desc = "Valid" if epoch is None else f"Valid {epoch:02d}/{epochs:02d}"
    pbar = _make_pbar(len(loader), desc)

    for step, (imgs, labels) in enumerate(loader, start=1):
        imgs = _move_image(imgs)
        labels = labels.to(DEVICE, non_blocking=bool(CFG["pin_memory"]))

        if use_tta:
            probs = tta_inference(model, imgs, DEVICE)
            logits = torch.log(probs / (1 - probs + 1e-8))
        else:
            with torch.amp.autocast(device_type=AMP_DEVICE_TYPE, enabled=(amp and AMP_ENABLED)):
                logits = model(imgs)
            probs = torch.sigmoid(logits)

        batch_loss = criterion(logits, labels).item()
        total_loss += batch_loss * imgs.size(0)
        n += imgs.size(0)

        all_t.append(labels.detach().cpu())
        all_p.append(probs.detach().cpu().float())

        if (step % auc_update_steps == 0) or (step == len(loader)):
            y_t = torch.cat(all_t, dim=0).numpy()
            y_p = torch.cat(all_p, dim=0).numpy()
            _, running_auc = compute_auc(y_t, y_p)
            auc_str = f"{running_auc:.4f}" if not np.isnan(running_auc) else "----"
            pbar.set_postfix_str(f"auroc={auc_str}")

        pbar.update(1)

    pbar.close()

    all_t = torch.cat(all_t).numpy()
    all_p = torch.cat(all_p).numpy()
    aucs, mauc = compute_auc(all_t, all_p)
    return total_loss / max(n, 1), mauc, aucs

print("Training utilities OK | CUDA fastpath + no train AUROC")
