class CrossModalFusionGate(nn.Module):
    """
    Cross-Modal Fusion Gate (CMFG):
    Ket hop feature CNN (EfficientNetV2) va SSM (MedMamba++) qua gate hoc duoc.
    """
    def __init__(self, cnn_dim, ssm_dim, fusion_dim=512, dropout=0.3):
        super().__init__()
        # Align ca 2 ve cung fusion_dim
        self.cnn_proj = nn.Sequential(
            nn.Linear(cnn_dim, fusion_dim, bias=False),
            nn.LayerNorm(fusion_dim),
        )
        self.ssm_proj = nn.Sequential(
            nn.Linear(ssm_dim, fusion_dim, bias=False),
            nn.LayerNorm(fusion_dim),
        )
        # Content-aware gate tu ca 2 nhanh
        self.gate = nn.Sequential(
            nn.Linear(fusion_dim*2, fusion_dim, bias=False),
            nn.LayerNorm(fusion_dim),
            nn.Sigmoid(),
        )
        # Cross-branch residual (CNN attend vao SSM va nguoc lai)
        self.cross_proj = nn.Sequential(
            nn.Linear(fusion_dim*2, fusion_dim, bias=False),
            nn.GELU(),
        )
        # FFN refinement
        self.ffn = nn.Sequential(
            nn.Linear(fusion_dim, fusion_dim*2, bias=False),
            nn.GELU(),
            nn.Dropout(dropout),
            nn.Linear(fusion_dim*2, fusion_dim, bias=False),
            nn.LayerNorm(fusion_dim),
        )
        self.drop = nn.Dropout(dropout)

    def forward(self, f_cnn, f_ssm):
        fc = self.cnn_proj(f_cnn)          # (B, D)
        fs = self.ssm_proj(f_ssm)          # (B, D)
        cat2  = torch.cat([fc, fs], dim=-1)   # (B, 2D)
        g     = self.gate(cat2)               # (B, D)
        gated = g*fc + (1-g)*fs              # weighted mix
        cross = self.cross_proj(cat2)         # cross residual
        fused = self.ffn(gated + cross)
        return self.drop(fused)

