print(f"  DataLoader   : workers={CFG['num_workers']} | pin_memory={CFG['pin_memory']}")
print(f"  Fastpath     : channels_last={CFG['use_channels_last']} | amp={CFG['amp']} | image={CFG['image_size']}")
print(f"  Phase 1      : epoch 1-{PHASE2_START-1} (CNN frozen)")
print(f"  Phase 2      : epoch {PHASE2_START}-{CFG['epochs']} (full)")
print("=" * 72)

if start_epoch > CFG["epochs"]:
    print(f">> Da hoan tat den epoch {resume_epoch:02d}. Khong con gi de train tiep.")

patience = CFG["early_stop_patience"]
min_delta = CFG["early_stop_min_delta"]
epochs_no_improve = 0

for epoch in range(start_epoch, CFG["epochs"] + 1):

    if (epoch == PHASE2_START) and (not force_resume_frozen):
        print("\n>>> PHASE 2: Unfreeze EfficientNetV2, full fine-tune <<<")
        model.unfreeze_all()
        param_groups = model.get_param_groups(CFG["lr"])
