class FeatureBridge(nn.Module):
    """
    1x1 linear projection:
        (B, 1280, 7, 7) -> (B, 256, 7, 7)
    Sau do flatten theo khong gian de thanh token:
        (B, 256, 7, 7) -> (B, 49, 256)
    """
    def __init__(self, in_channels, token_dim=256, dropout=0.10):
        super().__init__()
        self.proj = nn.Sequential(
            nn.Conv2d(in_channels, token_dim, kernel_size=1, bias=False),
            nn.BatchNorm2d(token_dim),
            nn.GELU(),
            nn.Dropout2d(dropout),
        )
        self.token_dim = token_dim

    def forward_map(self, x):
        return self.proj(x)

    def forward_tokens(self, x):
        x = self.forward_map(x)                     # (B, D, H, W)
        tokens = x.flatten(2).transpose(1, 2)      # (B, H*W, D)
        return tokens

    def forward(self, x):
        return self.forward_tokens(x)


