class MedMambaTokenStage(nn.Module):
    """
    MedMamba stage de xu ly token sau khi CNN da trich xuat feature map.
    Dau vao thuc te la token (B, 49, D), sau do reshape ve (B, 7, 7, D)
    de giu cau truc 2D cho ADBG + WSS + Conv.
    """
    CONFIGS = {
        "tiny" : dict(depth=8),
        "small": dict(depth=16),
        "base" : dict(depth=24),
    }

    def __init__(self, variant="tiny", dim=256, drop_path_rate=0.15,
                 d_state=16, window_size=7, ffn_expand=2.):
        super().__init__()
        depth = self.CONFIGS[variant]["depth"]
        dpr = [x.item() for x in torch.linspace(0, drop_path_rate, depth)]
        self.blocks = nn.ModuleList([
            ADBG_WSS_Conv_Block(
                dim=dim,
                drop_path=dpr[i],
                norm=nn.LayerNorm,
                d_state=d_state,
                d_conv=4,
                expand=2,
                window_size=window_size,
                ffn_expand=ffn_expand,
            )
            for i in range(depth)
        ])
        self.norm = nn.LayerNorm(dim)
        self.out_dim = dim
        self.depth = depth

    def forward_grid(self, x):
        for blk in self.blocks:
            x = blk(x)
        return self.norm(x)

    def forward_tokens(self, tokens, hw=None):
        B, L, C = tokens.shape
        if hw is None:
            side = int(round(L ** 0.5))
            if side * side != L:
                raise ValueError(f"Khong the suy ra H=W tu L={L}")
            H = W = side
        else:
            H, W = hw
            if H * W != L:
                raise ValueError(f"H*W={H*W} khong khop L={L}")
        x = tokens.reshape(B, H, W, C)
        x = self.forward_grid(x)
        return x.reshape(B, H * W, C)

    def forward(self, tokens, hw=None):
        return self.forward_tokens(tokens, hw=hw)


class HybridMedMambaEffV2(nn.Module):
    """
    Serial hybrid dung voi so do de cuong:

        Input image
        -> EfficientNetV2 feature map      (B, 1280, 7, 7)
        -> 1x1 linear projection           (B,  256, 7, 7)
        -> patch token / flatten           (B,   49, 256)
        -> MedMamba token stage            (B,   49, 256)
        -> global average pooling          (B,  256)
        -> classification head             (B,   14)
    """
    def __init__(self, effv2_variant="tf_efficientnetv2_s", mamba_variant="tiny",
                 num_classes=14, token_dim=256, bridge_dropout=0.10,
                 head_dropout=0.30, pretrained_eff=True, drop_path_rate=0.15,
                 d_state=16, window_size=7, ffn_expand=2.):
        super().__init__()
        self.cnn = EfficientNetV2FeatureExtractor(effv2_variant, pretrained_eff)
        self.bridge = FeatureBridge(
            in_channels=self.cnn.out_channels,
            token_dim=token_dim,
            dropout=bridge_dropout,
        )
        self.med = MedMambaTokenStage(
            variant=mamba_variant,
            dim=token_dim,
            drop_path_rate=drop_path_rate,
            d_state=d_state,
            window_size=window_size,
            ffn_expand=ffn_expand,
        )
        self.head = nn.Sequential(
            nn.LayerNorm(token_dim),
            nn.Dropout(head_dropout),
            nn.Linear(token_dim, num_classes),
        )

    def freeze_cnn(self):
        for p in self.cnn.parameters():
            p.requires_grad = False
        print("EfficientNetV2 FROZEN -- chi train bridge + MedMamba + head")

    def unfreeze_all(self):
        for p in self.parameters():
            p.requires_grad = True
        print("Tat ca weights UNFROZEN -- full fine-tune")

    def forward_features(self, x, return_aux=False):
        fmap = self.cnn(x)                             # (B, 1280, 7, 7)
        pmap = self.bridge.forward_map(fmap)           # (B, 256, 7, 7)
        B, C, H, W = pmap.shape
        tokens = pmap.flatten(2).transpose(1, 2)       # (B, 49, 256)
        enc_tokens = self.med(tokens, hw=(H, W))       # (B, 49, 256)
        pooled = enc_tokens.mean(dim=1)                # (B, 256)

        if return_aux:
            return {
                "feature_map": fmap,
                "projected_map": pmap,
                "tokens": tokens,
                "encoded_tokens": enc_tokens,
                "pooled": pooled,
                "hw": (H, W),
            }
        return pooled

    def forward(self, x):
        pooled = self.forward_features(x, return_aux=False)
        return self.head(pooled)

    def get_param_groups(self, lr_base):
        import re

        named = [(n, p) for n, p in self.named_parameters() if p.requires_grad]
        groups = {
            "head": [],
            "med_late": [],
            "med_early": [],
            "bridge": [],
            "cnn_late": [],
            "cnn_early": [],
        }

        cnn_block_ids = sorted({
            int(m.group(1))
            for n, _ in named
            for m in [re.match(r"^cnn\.backbone\.blocks\.(\d+)\.", n)]
            if m is not None
        })
        cnn_split = max(1, len(cnn_block_ids) // 2) if cnn_block_ids else 0
        cnn_early_ids = set(cnn_block_ids[:cnn_split])
        cnn_late_ids = set(cnn_block_ids[cnn_split:])

        med_block_ids = sorted({
            int(m.group(1))
            for n, _ in named
            for m in [re.match(r"^med\.blocks\.(\d+)\.", n)]
            if m is not None
        })
        med_split = max(1, len(med_block_ids) // 2) if med_block_ids else 0
        med_early_ids = set(med_block_ids[:med_split])
        med_late_ids = set(med_block_ids[med_split:])

        for n, p in named:
            if n.startswith("head."):
                groups["head"].append(p)
                continue

            if n.startswith("bridge."):
                groups["bridge"].append(p)
                continue

            m = re.match(r"^med\.blocks\.(\d+)\.", n)
            if m is not None:
                block_id = int(m.group(1))
                if block_id in med_late_ids:
                    groups["med_late"].append(p)
                else:
                    groups["med_early"].append(p)
                continue

            if n.startswith("med."):
                groups["med_early"].append(p)
                continue

            m = re.match(r"^cnn\.backbone\.blocks\.(\d+)\.", n)
            if m is not None:
                block_id = int(m.group(1))
                if block_id in cnn_late_ids:
                    groups["cnn_late"].append(p)
                else:
                    groups["cnn_early"].append(p)
                continue

            if n.startswith("cnn."):
                groups["cnn_early"].append(p)
                continue

            groups["head"].append(p)

        seen = {}
        for gname, params in groups.items():
            unique_params = []
            for p in params:
                pid = id(p)
                if pid in seen:
                    raise RuntimeError(f"Duplicate parameter found in groups: {gname} and {seen[pid]}")
                seen[pid] = gname
                unique_params.append(p)
            groups[gname] = unique_params

        return [
            {"params": groups["head"],      "lr": lr_base,       "name": "head"},
            {"params": groups["med_late"],  "lr": lr_base * 0.5, "name": "med_late"},
            {"params": groups["med_early"], "lr": lr_base * 0.25,"name": "med_early"},
            {"params": groups["bridge"],    "lr": lr_base * 0.5, "name": "bridge"},
            {"params": groups["cnn_late"],  "lr": lr_base * 0.1, "name": "cnn_late"},
            {"params": groups["cnn_early"], "lr": lr_base * 0.02,"name": "cnn_early"},
        ]


