# -*- coding: utf-8 -*-
"""
Hybrid EfficientNetV2-S + MedMamba-style training script for NIH ChestX-ray14.
Improvements included:
- Adaptive Dual-Branch Gating
- Windowed Selective Scan
- Asymmetric Loss
- Clean tqdm logging with loss + AUC
- Auto resume from last checkpoint, fallback to best_model
- Windows-friendly multi-worker DataLoader
- RTX 4060 8GB oriented defaults

Expected split files from your data.ipynb:
    dataset/train.csv
    dataset/validation.csv
    dataset/test.csv
"""

from __future__ import annotations

import gc
import json
import math
import os
import random
import time
import warnings
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np
import pandas as pd
from PIL import Image
from sklearn.metrics import roc_auc_score
from sklearn.exceptions import UndefinedMetricWarning
from tqdm.auto import tqdm

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.amp import GradScaler, autocast
from torch.utils.data import DataLoader, Dataset, Sampler
try:
    from torchvision import transforms
    from torchvision.models import efficientnet_v2_s, EfficientNet_V2_S_Weights
except Exception as e:
    raise RuntimeError(
        "Torchvision import lỗi. Cần cài đúng cặp phiên bản torch/torchvision tương thích. "
        f"Lỗi gốc: {e}"
    )


# =========================
# 1. Cấu hình
# =========================
@dataclass
class CFG:
    # Đường dẫn gốc: nên để cùng cấp với thư mục dataset như notebook chia dữ liệu của bạn
    base_dir: str = "."
    dataset_dir: str = "dataset"
    output_dir: str = "runs/hybrid_effv2s_medmamba"

    train_csv: str = "dataset/train.csv"
    valid_csv: str = "dataset/validation.csv"
    test_csv: str = "dataset/test.csv"

    # Thư mục tìm ảnh NIH. Có thể thêm/bớt tùy máy.
    image_search_roots: Tuple[str, ...] = (
        "dataset/images",
        "dataset/images*",
        "images",
        "images*",
        "dataset",
    )

    seed: int = 42
    image_size: int = 224
    in_channels: int = 3
    num_classes: int = 14
    include_no_finding: bool = False

    # Tối ưu cho RTX 4060 8GB
    batch_size: int = 8
    grad_accum_steps: int = 2           # effective batch = 16
    epochs: int = 20
    warmup_epochs: int = 1
    num_workers: int = 6
    prefetch_factor: int = 2
    pin_memory: bool = True
    persistent_workers: bool = True

    lr_backbone: float = 1.0e-4
    lr_head: float = 3.0e-4
    weight_decay: float = 1.0e-4
    max_grad_norm: float = 1.0
    label_smoothing: float = 0.0

    # Asymmetric Loss
    asl_gamma_neg: float = 4.0
    asl_gamma_pos: float = 1.0
    asl_clip: float = 0.05
    asl_eps: float = 1.0e-8

    # Hybrid model
    embed_dim: int = 256
    depth: int = 6
    window_size: int = 4
    mlp_ratio: float = 2.0
    drop_rate: float = 0.2
    drop_path_rate: float = 0.1
    pretrained_backbone: bool = True

    # Resume / checkpoint
    checkpoint_name: str = "last_checkpoint.pth"
    best_name: str = "best_model.pth"
    history_name: str = "history.json"
    labels_name: str = "labels.json"
    image_index_name: str = "image_index.json"
    save_every_steps: int = 400  # step checkpoint trong epoch

    # Logging
    train_auc_every: int = 50
    auc_buffer_size: int = 2048

    # Hiệu năng
    use_amp: bool = True
    channels_last: bool = True
    allow_tf32: bool = True

    # Thực nghiệm
    freeze_backbone_epochs: int = 1


CFG = CFG()


# =========================
# 2. Tiện ích chung
# =========================
def set_seed(seed: int = 42) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def setup_runtime(cfg: CFG) -> torch.device:
    warnings.filterwarnings("ignore", category=UndefinedMetricWarning)
    warnings.filterwarnings("ignore", message=".*is not defined in that case.*")
    warnings.filterwarnings("ignore", message=".*No positive class found in y_true.*")

    torch.backends.cudnn.benchmark = True
    if hasattr(torch, "set_float32_matmul_precision"):
        torch.set_float32_matmul_precision("high")
    if torch.cuda.is_available() and cfg.allow_tf32:
        torch.backends.cuda.matmul.allow_tf32 = True
        torch.backends.cudnn.allow_tf32 = True
    return torch.device("cuda" if torch.cuda.is_available() else "cpu")


def ensure_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    return path


def save_json(path: Path, obj: dict) -> None:
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)


def load_json(path: Path, default=None):
    if not path.exists():
        return default
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


# =========================
# 3. Nhãn NIH ChestX-ray14
# =========================
NIH_14_LABELS = [
    "Atelectasis",
    "Cardiomegaly",
    "Effusion",
    "Infiltration",
    "Mass",
    "Nodule",
    "Pneumonia",
    "Pneumothorax",
    "Consolidation",
    "Edema",
    "Emphysema",
    "Fibrosis",
    "Pleural_Thickening",
    "Hernia",
]


def build_label_names(cfg: CFG, all_dfs: Sequence[pd.DataFrame], labels_path: Path) -> List[str]:
    cached = load_json(labels_path)
    if cached and isinstance(cached, list) and len(cached) > 0:
        return cached

    label_names: List[str]
    joined = pd.concat(all_dfs, axis=0, ignore_index=True)

    if all(label in joined.columns for label in NIH_14_LABELS):
        label_names = NIH_14_LABELS.copy()
    elif "Finding Labels" in joined.columns:
        found = set()
        for txt in joined["Finding Labels"].fillna("No Finding").astype(str).tolist():
            for x in txt.split("|"):
                x = x.strip()
                if not x or x == "No Finding":
                    continue
                found.add(x)
        # Giữ thứ tự chuẩn NIH nếu có
        label_names = [x for x in NIH_14_LABELS if x in found]
        extras = sorted(found - set(label_names))
        label_names.extend(extras)
    else:
        # fallback: lấy cột nhị phân khả nghi
        candidate_cols = []
        for col in joined.columns:
            vals = set(pd.Series(joined[col]).dropna().astype(str).unique().tolist())
            if vals.issubset({"0", "1", "0.0", "1.0"}) and col not in {"Patient ID", "Image Index"}:
                candidate_cols.append(col)
        label_names = candidate_cols[: cfg.num_classes]

    if cfg.include_no_finding and "No Finding" not in label_names:
        label_names = ["No Finding"] + label_names

    save_json(labels_path, label_names)
    return label_names


# =========================
# 4. Tìm ảnh theo file name
# =========================
def expand_roots(base_dir: Path, patterns: Sequence[str]) -> List[Path]:
    roots: List[Path] = []
    for pattern in patterns:
        matches = list(base_dir.glob(pattern))
        if matches:
            roots.extend([m for m in matches if m.exists()])
        else:
            p = base_dir / pattern
            if p.exists():
                roots.append(p)
    uniq = []
    seen = set()
    for r in roots:
        rp = r.resolve()
        if rp not in seen:
            seen.add(rp)
            uniq.append(r)
    return uniq


def build_or_load_image_index(base_dir: Path, cfg: CFG, cache_path: Path) -> Dict[str, str]:
    cached = load_json(cache_path)
    if isinstance(cached, dict) and len(cached) > 0:
        return cached

    roots = expand_roots(base_dir, cfg.image_search_roots)
    image_index: Dict[str, str] = {}
    exts = {".png", ".jpg", ".jpeg", ".bmp"}
    for root in roots:
        if root.is_file() and root.suffix.lower() in exts:
            image_index[root.name] = str(root)
            continue
        for p in root.rglob("*"):
            if p.is_file() and p.suffix.lower() in exts:
                image_index[p.name] = str(p)

    if len(image_index) == 0:
        raise FileNotFoundError(
            "Không tìm thấy ảnh. Hãy kiểm tra lại CFG.image_search_roots cho đúng vị trí ảnh NIH."
        )

    save_json(cache_path, image_index)
    return image_index


# =========================
# 5. Dataset
# =========================
class NIHChestXrayDataset(Dataset):
    def __init__(
        self,
        df: pd.DataFrame,
        image_index: Dict[str, str],
        label_names: Sequence[str],
        transform=None,
    ):
        self.df = df.reset_index(drop=True).copy()
        self.image_index = image_index
        self.label_names = list(label_names)
        self.transform = transform

        if "Image Index" not in self.df.columns:
            raise ValueError("CSV phải có cột 'Image Index'.")

        self.df["Image Index"] = self.df["Image Index"].astype(str)
        self.targets = self._build_targets(self.df)

        missing_files = [img for img in self.df["Image Index"].tolist() if img not in self.image_index]
        if len(missing_files) > 0:
            preview = missing_files[:5]
            raise FileNotFoundError(
                f"Thiếu {len(missing_files)} ảnh trong image_index. Ví dụ: {preview}"
            )

    def _build_targets(self, df: pd.DataFrame) -> np.ndarray:
        n = len(df)
        y = np.zeros((n, len(self.label_names)), dtype=np.float32)

        if all(col in df.columns for col in self.label_names):
            for j, col in enumerate(self.label_names):
                y[:, j] = pd.to_numeric(df[col], errors="coerce").fillna(0).astype(np.float32).to_numpy()
            return y

        if "Finding Labels" not in df.columns:
            raise ValueError(
                "CSV phải có một trong hai dạng: cột one-hot theo nhãn hoặc cột 'Finding Labels'."
            )

        findings = df["Finding Labels"].fillna("No Finding").astype(str).tolist()
        label_to_idx = {lb: i for i, lb in enumerate(self.label_names)}
        for i, txt in enumerate(findings):
            items = [x.strip() for x in txt.split("|") if x.strip()]
            if len(items) == 0:
                continue
            for item in items:
                if item == "No Finding":
                    if "No Finding" in label_to_idx:
                        y[i, label_to_idx["No Finding"]] = 1.0
                    continue
                if item in label_to_idx:
                    y[i, label_to_idx[item]] = 1.0
        return y

    def __len__(self) -> int:
        return len(self.df)

    def __getitem__(self, idx: int):
        row = self.df.iloc[idx]
        img_name = row["Image Index"]
        img_path = self.image_index[img_name]

        image = Image.open(img_path).convert("RGB")
        if self.transform is not None:
            image = self.transform(image)

        target = torch.from_numpy(self.targets[idx])
        return image, target


# =========================
# 6. Sampler có thể resume giữa epoch
# =========================
class ResumableRandomSampler(Sampler[int]):
    def __init__(self, data_source: Dataset, seed: int = 42, epoch: int = 0, start_index: int = 0):
        self.data_source = data_source
        self.seed = int(seed)
        self.epoch = int(epoch)
        self.start_index = int(max(0, start_index))

    def __iter__(self):
        g = torch.Generator()
        g.manual_seed(self.seed + self.epoch)
        indices = torch.randperm(len(self.data_source), generator=g).tolist()
        if self.start_index > 0:
            indices = indices[self.start_index :]
        return iter(indices)

    def __len__(self):
        return max(0, len(self.data_source) - self.start_index)


# =========================
# 7. Augmentation
# =========================
def build_transforms(cfg: CFG):
    imagenet_mean = [0.485, 0.456, 0.406]
    imagenet_std = [0.229, 0.224, 0.225]

    train_tfms = transforms.Compose([
        transforms.Resize((cfg.image_size, cfg.image_size)),
        transforms.RandomAffine(degrees=7, translate=(0.02, 0.02), scale=(0.98, 1.02)),
        transforms.ToTensor(),
        transforms.Normalize(mean=imagenet_mean, std=imagenet_std),
    ])

    valid_tfms = transforms.Compose([
        transforms.Resize((cfg.image_size, cfg.image_size)),
        transforms.ToTensor(),
        transforms.Normalize(mean=imagenet_mean, std=imagenet_std),
    ])
    return train_tfms, valid_tfms


# =========================
# 8. Các khối mô hình
# =========================
class DropPath(nn.Module):
    def __init__(self, drop_prob: float = 0.0):
        super().__init__()
        self.drop_prob = float(drop_prob)

    def forward(self, x):
        if self.drop_prob == 0.0 or not self.training:
            return x
        keep_prob = 1.0 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)
        random_tensor.floor_()
        return x.div(keep_prob) * random_tensor


class LayerNorm2d(nn.Module):
    def __init__(self, num_channels: int, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(num_channels))
        self.bias = nn.Parameter(torch.zeros(num_channels))
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        mean = x.mean(dim=1, keepdim=True)
        var = (x - mean).pow(2).mean(dim=1, keepdim=True)
        x = (x - mean) / torch.sqrt(var + self.eps)
        return self.weight[:, None, None] * x + self.bias[:, None, None]


class ConvBNAct(nn.Sequential):
    def __init__(self, in_ch, out_ch, kernel_size=3, stride=1, padding=None, groups=1, bias=False):
        if padding is None:
            padding = kernel_size // 2
        super().__init__(
            nn.Conv2d(in_ch, out_ch, kernel_size, stride, padding, groups=groups, bias=bias),
            nn.BatchNorm2d(out_ch),
            nn.GELU(),
        )


class AdaptiveDualBranchGate(nn.Module):
    def __init__(self, channels: int, reduction: int = 4):
        super().__init__()
        hidden = max(channels // reduction, 16)
        self.pool = nn.AdaptiveAvgPool2d(1)
        self.fc1 = nn.Conv2d(channels, hidden, kernel_size=1, bias=True)
        self.act = nn.GELU()
        self.fc2 = nn.Conv2d(hidden, 2, kernel_size=1, bias=True)

    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        g = self.pool(x)
        g = self.fc2(self.act(self.fc1(g))).flatten(1)
        g = torch.softmax(g, dim=1)
        return g[:, 0].view(-1, 1, 1, 1), g[:, 1].view(-1, 1, 1, 1)


class ConvBranch(nn.Module):
    def __init__(self, channels: int, mlp_ratio: float = 2.0, drop: float = 0.0):
        super().__init__()
        hidden = int(channels * mlp_ratio)
        self.block = nn.Sequential(
            ConvBNAct(channels, channels, kernel_size=3, groups=channels),
            ConvBNAct(channels, hidden, kernel_size=1),
            nn.Dropout(drop),
            nn.Conv2d(hidden, channels, kernel_size=1, bias=False),
            nn.BatchNorm2d(channels),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.block(x)


def window_partition(x: torch.Tensor, window_size: int):
    # x: [B, C, H, W]
    B, C, H, W = x.shape
    pad_h = (window_size - H % window_size) % window_size
    pad_w = (window_size - W % window_size) % window_size
    if pad_h > 0 or pad_w > 0:
        x = F.pad(x, (0, pad_w, 0, pad_h))
    Hp, Wp = x.shape[-2:]
    x = x.view(B, C, Hp // window_size, window_size, Wp // window_size, window_size)
    x = x.permute(0, 2, 4, 3, 5, 1).contiguous().view(-1, window_size * window_size, C)
    return x, (H, W, Hp, Wp)


def window_reverse(windows: torch.Tensor, window_size: int, shape_info: Tuple[int, int, int, int], B: int):
    H, W, Hp, Wp = shape_info
    C = windows.shape[-1]
    x = windows.view(B, Hp // window_size, Wp // window_size, window_size, window_size, C)
    x = x.permute(0, 5, 1, 3, 2, 4).contiguous().view(B, C, Hp, Wp)
    x = x[:, :, :H, :W]
    return x


class WindowedSelectiveScan2D(nn.Module):
    """
    Phiên bản thực dụng, chạy thuần PyTorch trên Windows/CUDA.
    Không phụ thuộc custom CUDA kernel của Mamba/VMamba.
    Ý tưởng:
    - local depthwise conv giữ ngữ cảnh gần
    - quét chọn lọc trong từng cửa sổ nhỏ
    - forward + backward scan để giảm lệch hướng
    """
    def __init__(self, channels: int, window_size: int = 4, drop: float = 0.0):
        super().__init__()
        self.channels = channels
        self.window_size = window_size
        self.pre_norm = LayerNorm2d(channels)
        self.local_dw = nn.Conv2d(channels, channels, kernel_size=3, padding=1, groups=channels, bias=False)
        self.in_proj = nn.Linear(channels, channels * 3)
        self.out_proj = nn.Linear(channels, channels)
        self.dropout = nn.Dropout(drop)

    @staticmethod
    def _scan(delta: torch.Tensor, value: torch.Tensor) -> torch.Tensor:
        # delta, value: [B*, L, C]
        Bn, L, C = delta.shape
        state = torch.zeros((Bn, C), device=delta.device, dtype=delta.dtype)
        outs = []
        for t in range(L):
            state = delta[:, t] * state + (1.0 - delta[:, t]) * value[:, t]
            outs.append(state)
        return torch.stack(outs, dim=1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x: [B, C, H, W]
        B = x.shape[0]
        x = self.pre_norm(x)
        x = self.local_dw(x) + x

        windows, shape_info = window_partition(x, self.window_size)  # [B*nw, L, C]
        q, v, g = self.in_proj(windows).chunk(3, dim=-1)
        delta = torch.sigmoid(q)
        value = torch.tanh(v)
        gate = torch.sigmoid(g)

        y_fwd = self._scan(delta, value)
        y_bwd = torch.flip(self._scan(torch.flip(delta, dims=[1]), torch.flip(value, dims=[1])), dims=[1])
        y = 0.5 * (y_fwd + y_bwd)
        y = gate * y
        y = self.out_proj(y)
        y = self.dropout(y)
        y = window_reverse(y, self.window_size, shape_info, B)
        return y


class AdaptiveMedMambaBlock(nn.Module):
    def __init__(
        self,
        channels: int,
        window_size: int = 4,
        mlp_ratio: float = 2.0,
        drop: float = 0.0,
        drop_path: float = 0.0,
    ):
        super().__init__()
        self.norm = LayerNorm2d(channels)
        self.conv_branch = ConvBranch(channels, mlp_ratio=mlp_ratio, drop=drop)
        self.ssm_branch = WindowedSelectiveScan2D(channels, window_size=window_size, drop=drop)
        self.gate = AdaptiveDualBranchGate(channels)
        self.fuse = nn.Sequential(
            nn.Conv2d(channels, channels, kernel_size=1, bias=False),
            nn.BatchNorm2d(channels),
        )
        self.drop_path = DropPath(drop_path)
        self.mlp = nn.Sequential(
            LayerNorm2d(channels),
            nn.Conv2d(channels, int(channels * mlp_ratio), kernel_size=1),
            nn.GELU(),
            nn.Dropout(drop),
            nn.Conv2d(int(channels * mlp_ratio), channels, kernel_size=1),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        residual = x
        z = self.norm(x)
        conv_out = self.conv_branch(z)
        ssm_out = self.ssm_branch(z)
        g_conv, g_ssm = self.gate(z)
        z = g_conv * conv_out + g_ssm * ssm_out
        z = self.fuse(z)
        x = residual + self.drop_path(z)
        x = x + self.drop_path(self.mlp(x))
        return x


class HybridEfficientNetV2MedMamba(nn.Module):
    def __init__(self, cfg: CFG, num_classes: int):
        super().__init__()
        weights = EfficientNet_V2_S_Weights.IMAGENET1K_V1 if cfg.pretrained_backbone else None
        backbone = efficientnet_v2_s(weights=weights)
        self.backbone = backbone.features  # [B, 1280, 7, 7] tại 224x224
        self.proj = nn.Sequential(
            nn.Conv2d(1280, cfg.embed_dim, kernel_size=1, bias=False),
            nn.BatchNorm2d(cfg.embed_dim),
            nn.GELU(),
        )

        dpr = torch.linspace(0, cfg.drop_path_rate, cfg.depth).tolist()
        self.blocks = nn.Sequential(*[
            AdaptiveMedMambaBlock(
                channels=cfg.embed_dim,
                window_size=cfg.window_size,
                mlp_ratio=cfg.mlp_ratio,
                drop=cfg.drop_rate,
                drop_path=dpr[i],
            )
            for i in range(cfg.depth)
        ])

        self.head_norm = LayerNorm2d(cfg.embed_dim)
        self.dropout = nn.Dropout(cfg.drop_rate)
        self.classifier = nn.Linear(cfg.embed_dim, num_classes)

    def set_backbone_trainable(self, trainable: bool) -> None:
        for p in self.backbone.parameters():
            p.requires_grad = trainable

    def forward_features(self, x: torch.Tensor) -> torch.Tensor:
        x = self.backbone(x)
        x = self.proj(x)
        x = self.blocks(x)
        x = self.head_norm(x)
        x = F.adaptive_avg_pool2d(x, output_size=1).flatten(1)
        return x

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.forward_features(x)
        x = self.dropout(x)
        return self.classifier(x)


# =========================
# 9. Loss + metric
# =========================
class AsymmetricLoss(nn.Module):
    def __init__(self, gamma_neg=4.0, gamma_pos=1.0, clip=0.05, eps=1e-8):
        super().__init__()
        self.gamma_neg = gamma_neg
        self.gamma_pos = gamma_pos
        self.clip = clip
        self.eps = eps

    def forward(self, logits: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        targets = targets.float()
        xs_pos = torch.sigmoid(logits)
        xs_neg = 1.0 - xs_pos

        if self.clip is not None and self.clip > 0:
            xs_neg = (xs_neg + self.clip).clamp(max=1.0)

        los_pos = targets * torch.log(xs_pos.clamp(min=self.eps))
        los_neg = (1.0 - targets) * torch.log(xs_neg.clamp(min=self.eps))
        loss = los_pos + los_neg

        if self.gamma_neg > 0 or self.gamma_pos > 0:
            pt0 = xs_pos * targets
            pt1 = xs_neg * (1.0 - targets)
            pt = pt0 + pt1
            one_sided_gamma = self.gamma_pos * targets + self.gamma_neg * (1.0 - targets)
            one_sided_w = torch.pow(1.0 - pt, one_sided_gamma)
            loss *= one_sided_w

        return -loss.mean()


@torch.no_grad()
def safe_macro_auc(y_true: np.ndarray, y_prob: np.ndarray) -> float:
    aucs = []
    for i in range(y_true.shape[1]):
        col = y_true[:, i]
        if np.unique(col).size < 2:
            continue
        aucs.append(roc_auc_score(col, y_prob[:, i]))
    return float(np.mean(aucs)) if len(aucs) > 0 else float("nan")


class RollingAUCMeter:
    def __init__(self, max_samples: int = 2048):
        self.max_samples = max_samples
        self.targets: List[np.ndarray] = []
        self.probs: List[np.ndarray] = []
        self.total = 0

    def update(self, target: torch.Tensor, prob: torch.Tensor) -> None:
        t = target.detach().cpu().numpy().astype(np.float32)
        p = prob.detach().cpu().numpy().astype(np.float32)
        self.targets.append(t)
        self.probs.append(p)
        self.total += len(t)
        while self.total > self.max_samples and len(self.targets) > 0:
            removed_t = self.targets.pop(0)
            self.probs.pop(0)
            self.total -= len(removed_t)

    def compute(self) -> float:
        if len(self.targets) == 0:
            return float("nan")
        y_true = np.concatenate(self.targets, axis=0)
        y_prob = np.concatenate(self.probs, axis=0)
        return safe_macro_auc(y_true, y_prob)


# =========================
# 10. Optimizer / scheduler
# =========================
def build_optimizer(model: HybridEfficientNetV2MedMamba, cfg: CFG):
    backbone_params = []
    head_params = []
    for name, p in model.named_parameters():
        if not p.requires_grad:
            continue
        if name.startswith("backbone."):
            backbone_params.append(p)
        else:
            head_params.append(p)

    optimizer = torch.optim.AdamW(
        [
            {"params": backbone_params, "lr": cfg.lr_backbone},
            {"params": head_params, "lr": cfg.lr_head},
        ],
        weight_decay=cfg.weight_decay,
    )
    return optimizer


def build_scheduler(optimizer, cfg: CFG):
    warmup_epochs = max(1, cfg.warmup_epochs)
    total_cosine = max(1, cfg.epochs - warmup_epochs)
    warmup = torch.optim.lr_scheduler.LinearLR(optimizer, start_factor=0.2, end_factor=1.0, total_iters=warmup_epochs)
    cosine = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=total_cosine, eta_min=1e-6)
    scheduler = torch.optim.lr_scheduler.SequentialLR(
        optimizer,
        schedulers=[warmup, cosine],
        milestones=[warmup_epochs],
    )
    return scheduler


# =========================
# 11. DataLoader
# =========================
def make_loader(dataset, batch_size, shuffle, cfg: CFG, sampler=None):
    num_workers = int(max(0, min(cfg.num_workers, (os.cpu_count() or 2) - 1 if (os.cpu_count() or 2) > 1 else 0)))
    kwargs = dict(
        dataset=dataset,
        batch_size=batch_size,
        shuffle=(shuffle and sampler is None),
        sampler=sampler,
        num_workers=num_workers,
        pin_memory=cfg.pin_memory,
        persistent_workers=(cfg.persistent_workers and num_workers > 0),
        drop_last=False,
    )
    if num_workers > 0:
        kwargs["prefetch_factor"] = cfg.prefetch_factor
    return DataLoader(**kwargs)


# =========================
# 12. Checkpoint / history
# =========================
def checkpoint_paths(output_dir: Path, cfg: CFG):
    return {
        "last": output_dir / cfg.checkpoint_name,
        "best": output_dir / cfg.best_name,
        "history": output_dir / cfg.history_name,
        "labels": output_dir / cfg.labels_name,
        "image_index": output_dir / cfg.image_index_name,
    }


def atomic_save(obj: dict, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    torch.save(obj, tmp)
    tmp.replace(path)


def save_checkpoint(
    path: Path,
    model: nn.Module,
    optimizer,
    scheduler,
    scaler,
    epoch: int,
    step_in_epoch: int,
    best_auc: float,
    history: dict,
    label_names: Sequence[str],
    cfg: CFG,
) -> None:
    ckpt = {
        "epoch": epoch,
        "step_in_epoch": step_in_epoch,
        "model": model.state_dict(),
        "optimizer": optimizer.state_dict(),
        "scheduler": scheduler.state_dict(),
        "scaler": scaler.state_dict() if scaler is not None else None,
        "best_auc": best_auc,
        "history": history,
        "label_names": list(label_names),
        "cfg": asdict(cfg),
    }
    atomic_save(ckpt, path)


def load_checkpoint_if_available(paths: dict, model, optimizer, scheduler, scaler, device):
    start_epoch = 0
    step_in_epoch = 0
    best_auc = -float("inf")
    history = {"train_loss": [], "train_auc": [], "valid_loss": [], "valid_auc": []}
    resumed_from = None

    ckpt_path = None
    if paths["last"].exists():
        ckpt_path = paths["last"]
        resumed_from = "last_checkpoint"
    elif paths["best"].exists():
        ckpt_path = paths["best"]
        resumed_from = "best_model"

    if ckpt_path is None:
        return start_epoch, step_in_epoch, best_auc, history, resumed_from

    ckpt = torch.load(ckpt_path, map_location=device)
    model.load_state_dict(ckpt["model"], strict=False)
    best_auc = ckpt.get("best_auc", best_auc)
    history = ckpt.get("history", history)
    start_epoch = int(ckpt.get("epoch", -1))
    step_in_epoch = int(ckpt.get("step_in_epoch", 0))

    if resumed_from == "last_checkpoint":
        if "optimizer" in ckpt and ckpt["optimizer"] is not None:
            optimizer.load_state_dict(ckpt["optimizer"])
        if "scheduler" in ckpt and ckpt["scheduler"] is not None:
            scheduler.load_state_dict(ckpt["scheduler"])
        if scaler is not None and ckpt.get("scaler") is not None:
            scaler.load_state_dict(ckpt["scaler"])
    else:
        # fallback: chỉ có best model thì bắt đầu epoch kế tiếp từ đầu epoch
        step_in_epoch = 0

    return start_epoch, step_in_epoch, best_auc, history, resumed_from


# =========================
# 13. Train / eval
# =========================
@torch.no_grad()
def evaluate(model, loader, criterion, device, cfg: CFG):
    model.eval()
    losses = []
    all_targets = []
    all_probs = []

    pbar = tqdm(loader, desc="Valid", leave=False)
    for images, targets in pbar:
        images = images.to(device, non_blocking=True)
        targets = targets.to(device, non_blocking=True)
        if cfg.channels_last:
            images = images.contiguous(memory_format=torch.channels_last)

        with autocast(device_type="cuda", enabled=(device.type == "cuda" and cfg.use_amp)):
            logits = model(images)
            loss = criterion(logits, targets)

        probs = torch.sigmoid(logits)
        losses.append(loss.item())
        all_targets.append(targets.detach().cpu().numpy().astype(np.float32))
        all_probs.append(probs.detach().cpu().numpy().astype(np.float32))

        if len(all_targets) > 0:
            tmp_auc = safe_macro_auc(np.concatenate(all_targets), np.concatenate(all_probs))
        else:
            tmp_auc = float("nan")
        pbar.set_postfix(loss=f"{np.mean(losses):.4f}", auc=f"{tmp_auc:.4f}")

    y_true = np.concatenate(all_targets, axis=0)
    y_prob = np.concatenate(all_probs, axis=0)
    return float(np.mean(losses)), safe_macro_auc(y_true, y_prob)


def train_one_epoch(
    model,
    loader,
    criterion,
    optimizer,
    scaler,
    device,
    epoch,
    cfg: CFG,
    output_paths: dict,
    scheduler,
    best_auc: float,
    history: dict,
    label_names: Sequence[str],
):
    model.train()
    losses = []
    full_targets = []
    full_probs = []
    rolling_auc = RollingAUCMeter(max_samples=cfg.auc_buffer_size)

    pbar = tqdm(loader, desc=f"Train {epoch + 1:02d}/{cfg.epochs:02d}", leave=False)
    optimizer.zero_grad(set_to_none=True)

    for step, (images, targets) in enumerate(pbar, start=1):
        images = images.to(device, non_blocking=True)
        targets = targets.to(device, non_blocking=True)
        if cfg.channels_last:
            images = images.contiguous(memory_format=torch.channels_last)

        with autocast(device_type="cuda", enabled=(device.type == "cuda" and cfg.use_amp)):
            logits = model(images)
            loss = criterion(logits, targets)
            loss_for_backward = loss / cfg.grad_accum_steps

        scaler.scale(loss_for_backward).backward()

        if step % cfg.grad_accum_steps == 0:
            scaler.unscale_(optimizer)
            torch.nn.utils.clip_grad_norm_(model.parameters(), cfg.max_grad_norm)
            scaler.step(optimizer)
            scaler.update()
            optimizer.zero_grad(set_to_none=True)

        probs = torch.sigmoid(logits.detach())
        rolling_auc.update(targets, probs)
        losses.append(loss.item())
        full_targets.append(targets.detach().cpu().numpy().astype(np.float32))
        full_probs.append(probs.detach().cpu().numpy().astype(np.float32))

        if step % cfg.train_auc_every == 0:
            live_auc = rolling_auc.compute()
        elif len(losses) == 1:
            live_auc = rolling_auc.compute()
        else:
            live_auc = rolling_auc.compute()

        current_lrs = [pg["lr"] for pg in optimizer.param_groups]
        pbar.set_postfix(
            loss=f"{np.mean(losses):.4f}",
            auc=f"{live_auc:.4f}",
            lr=f"{max(current_lrs):.2e}",
        )

        if step % cfg.save_every_steps == 0:
            save_checkpoint(
                output_paths["last"],
                model,
                optimizer,
                scheduler,
                scaler,
                epoch=epoch,
                step_in_epoch=step,
                best_auc=best_auc,
                history=history,
                label_names=label_names,
                cfg=cfg,
            )

    if len(loader) % cfg.grad_accum_steps != 0:
        scaler.unscale_(optimizer)
        torch.nn.utils.clip_grad_norm_(model.parameters(), cfg.max_grad_norm)
        scaler.step(optimizer)
        scaler.update()
        optimizer.zero_grad(set_to_none=True)

    train_loss = float(np.mean(losses))
    train_auc = safe_macro_auc(np.concatenate(full_targets), np.concatenate(full_probs))
    return train_loss, train_auc


# =========================
# 14. Main
# =========================
def run_training(cfg: CFG):
    set_seed(cfg.seed)
    device = setup_runtime(cfg)

    base_dir = Path(cfg.base_dir).resolve()
    output_dir = ensure_dir(base_dir / cfg.output_dir)
    paths = checkpoint_paths(output_dir, cfg)

    train_csv = (base_dir / cfg.train_csv).resolve()
    valid_csv = (base_dir / cfg.valid_csv).resolve()
    test_csv = (base_dir / cfg.test_csv).resolve()
    for p in [train_csv, valid_csv, test_csv]:
        if not p.exists():
            raise FileNotFoundError(f"Không tìm thấy file split: {p}")

    train_df = pd.read_csv(train_csv)
    valid_df = pd.read_csv(valid_csv)
    test_df = pd.read_csv(test_csv)

    label_names = build_label_names(cfg, [train_df, valid_df, test_df], paths["labels"])
    image_index = build_or_load_image_index(base_dir, cfg, paths["image_index"])

    train_tfms, valid_tfms = build_transforms(cfg)
    train_ds = NIHChestXrayDataset(train_df, image_index, label_names, transform=train_tfms)
    valid_ds = NIHChestXrayDataset(valid_df, image_index, label_names, transform=valid_tfms)
    test_ds = NIHChestXrayDataset(test_df, image_index, label_names, transform=valid_tfms)

    model = HybridEfficientNetV2MedMamba(cfg, num_classes=len(label_names)).to(device)
    if cfg.channels_last:
        model = model.to(memory_format=torch.channels_last)

    optimizer = build_optimizer(model, cfg)
    scheduler = build_scheduler(optimizer, cfg)
    scaler = GradScaler("cuda", enabled=(device.type == "cuda" and cfg.use_amp))
    criterion = AsymmetricLoss(
        gamma_neg=cfg.asl_gamma_neg,
        gamma_pos=cfg.asl_gamma_pos,
        clip=cfg.asl_clip,
        eps=cfg.asl_eps,
    )

    start_epoch, resume_step, best_auc, history, resumed_from = load_checkpoint_if_available(
        paths, model, optimizer, scheduler, scaler, device
    )

    if resumed_from == "last_checkpoint":
        print(f"Resume từ last checkpoint | epoch={start_epoch + 1} | step={resume_step}")
    elif resumed_from == "best_model":
        print(f"Không có last checkpoint. Dùng best_model để train tiếp từ epoch={start_epoch + 1}")
    else:
        print("Bắt đầu train mới")

    print(f"Device: {device}")
    print(f"Train/Valid/Test: {len(train_ds)}/{len(valid_ds)}/{len(test_ds)}")
    print(f"Số nhãn: {len(label_names)} | {label_names}")

    for epoch in range(start_epoch, cfg.epochs):
        epoch_start = time.time()

        backbone_trainable = epoch >= cfg.freeze_backbone_epochs
        model.set_backbone_trainable(backbone_trainable)

        # Resume đúng giữa epoch bằng sampler có offset
        start_index = 0
        if resumed_from == "last_checkpoint" and epoch == start_epoch and resume_step > 0:
            start_index = resume_step * cfg.batch_size

        train_sampler = ResumableRandomSampler(train_ds, seed=cfg.seed, epoch=epoch, start_index=start_index)
        train_loader = make_loader(train_ds, cfg.batch_size, shuffle=False, cfg=cfg, sampler=train_sampler)
        valid_loader = make_loader(valid_ds, cfg.batch_size, shuffle=False, cfg=cfg)

        train_loss, train_auc = train_one_epoch(
            model=model,
            loader=train_loader,
            criterion=criterion,
            optimizer=optimizer,
            scaler=scaler,
            device=device,
            epoch=epoch,
            cfg=cfg,
            output_paths=paths,
            scheduler=scheduler,
            best_auc=best_auc,
            history=history,
            label_names=label_names,
        )

        valid_loss, valid_auc = evaluate(model, valid_loader, criterion, device, cfg)
        scheduler.step()

        history.setdefault("train_loss", []).append(train_loss)
        history.setdefault("train_auc", []).append(train_auc)
        history.setdefault("valid_loss", []).append(valid_loss)
        history.setdefault("valid_auc", []).append(valid_auc)

        # Sau khi xong epoch thì reset step resume
        resume_step = 0
        resumed_from = None

        save_checkpoint(
            paths["last"],
            model,
            optimizer,
            scheduler,
            scaler,
            epoch=epoch + 1,
            step_in_epoch=0,
            best_auc=best_auc,
            history=history,
            label_names=label_names,
            cfg=cfg,
        )

        improved = valid_auc > best_auc
        if improved:
            best_auc = valid_auc
            save_checkpoint(
                paths["best"],
                model,
                optimizer,
                scheduler,
                scaler,
                epoch=epoch + 1,
                step_in_epoch=0,
                best_auc=best_auc,
                history=history,
                label_names=label_names,
                cfg=cfg,
            )

        save_json(paths["history"], history)

        elapsed = time.time() - epoch_start
        print(
            f"Epoch {epoch + 1:02d}/{cfg.epochs:02d} | "
            f"train_loss={train_loss:.4f} train_auc={train_auc:.4f} | "
            f"valid_loss={valid_loss:.4f} valid_auc={valid_auc:.4f} | "
            f"best_auc={best_auc:.4f} | {elapsed/60:.1f} min"
        )

        gc.collect()
        if device.type == "cuda":
            torch.cuda.empty_cache()

    # test với best model
    if paths["best"].exists():
        best_ckpt = torch.load(paths["best"], map_location=device)
        model.load_state_dict(best_ckpt["model"], strict=False)

    test_loader = make_loader(test_ds, cfg.batch_size, shuffle=False, cfg=cfg)
    test_loss, test_auc = evaluate(model, test_loader, criterion, device, cfg)
    print(f"TEST | loss={test_loss:.4f} auc={test_auc:.4f}")

    result = {
        "best_valid_auc": best_auc,
        "test_auc": test_auc,
        "history_path": str(paths["history"]),
        "best_model_path": str(paths["best"]),
        "last_checkpoint_path": str(paths["last"]),
        "label_names": label_names,
    }
    return result


if __name__ == "__main__":
    result = run_training(CFG)
    print(json.dumps(result, indent=2, ensure_ascii=False))
