NIH_14_LABELS = [
    "Atelectasis",
    "Cardiomegaly",
    "Effusion",
    "Infiltration",
    "Mass",
    "Nodule",
    "Pneumonia",
    "Pneumothorax",
    "Consolidation",
    "Edema",
    "Emphysema",
    "Fibrosis",
    "Pleural_Thickening",
    "Hernia",
]


def build_label_names(cfg: CFG, all_dfs: Sequence[pd.DataFrame], labels_path: Path) -> List[str]:
    cached = load_json(labels_path)
    if cached and isinstance(cached, list) and len(cached) > 0:
        return cached

    label_names: List[str]
    joined = pd.concat(all_dfs, axis=0, ignore_index=True)

    if all(label in joined.columns for label in NIH_14_LABELS):
        label_names = NIH_14_LABELS.copy()
    elif "Finding Labels" in joined.columns:
        found = set()
        for txt in joined["Finding Labels"].fillna("No Finding").astype(str).tolist():
            for x in txt.split("|"):
                x = x.strip()
                if not x or x == "No Finding":
                    continue
                found.add(x)
        # Giữ thứ tự chuẩn NIH nếu có
        label_names = [x for x in NIH_14_LABELS if x in found]
        extras = sorted(found - set(label_names))
        label_names.extend(extras)
    else:
        # fallback: lấy cột nhị phân khả nghi
        candidate_cols = []
        for col in joined.columns:
            vals = set(pd.Series(joined[col]).dropna().astype(str).unique().tolist())
            if vals.issubset({"0", "1", "0.0", "1.0"}) and col not in {"Patient ID", "Image Index"}:
                candidate_cols.append(col)
        label_names = candidate_cols[: cfg.num_classes]

    if cfg.include_no_finding and "No Finding" not in label_names:
        label_names = ["No Finding"] + label_names

    save_json(labels_path, label_names)
    return label_names
