class DropPath(nn.Module):
    def __init__(self, drop_prob: float = 0.0):
        super().__init__()
        self.drop_prob = float(drop_prob)

    def forward(self, x):
        if self.drop_prob == 0.0 or not self.training:
            return x
        keep_prob = 1.0 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)
        random_tensor.floor_()
        return x.div(keep_prob) * random_tensor


class LayerNorm2d(nn.Module):
    def __init__(self, num_channels: int, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(num_channels))
        self.bias = nn.Parameter(torch.zeros(num_channels))
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        mean = x.mean(dim=1, keepdim=True)
        var = (x - mean).pow(2).mean(dim=1, keepdim=True)
        x = (x - mean) / torch.sqrt(var + self.eps)
        return self.weight[:, None, None] * x + self.bias[:, None, None]


class ConvBNAct(nn.Sequential):
    def __init__(self, in_ch, out_ch, kernel_size=3, stride=1, padding=None, groups=1, bias=False):
        if padding is None:
            padding = kernel_size // 2
        super().__init__(
            nn.Conv2d(in_ch, out_ch, kernel_size, stride, padding, groups=groups, bias=bias),
            nn.BatchNorm2d(out_ch),
            nn.GELU(),
        )


class AdaptiveDualBranchGate(nn.Module):
    def __init__(self, channels: int, reduction: int = 4):
        super().__init__()
        hidden = max(channels // reduction, 16)
        self.pool = nn.AdaptiveAvgPool2d(1)
        self.fc1 = nn.Conv2d(channels, hidden, kernel_size=1, bias=True)
        self.act = nn.GELU()
        self.fc2 = nn.Conv2d(hidden, 2, kernel_size=1, bias=True)

    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        g = self.pool(x)
        g = self.fc2(self.act(self.fc1(g))).flatten(1)
        g = torch.softmax(g, dim=1)
        return g[:, 0].view(-1, 1, 1, 1), g[:, 1].view(-1, 1, 1, 1)


class ConvBranch(nn.Module):
    def __init__(self, channels: int, mlp_ratio: float = 2.0, drop: float = 0.0):
        super().__init__()
        hidden = int(channels * mlp_ratio)
        self.block = nn.Sequential(
            ConvBNAct(channels, channels, kernel_size=3, groups=channels),
            ConvBNAct(channels, hidden, kernel_size=1),
            nn.Dropout(drop),
            nn.Conv2d(hidden, channels, kernel_size=1, bias=False),
            nn.BatchNorm2d(channels),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.block(x)


def window_partition(x: torch.Tensor, window_size: int):
    # x: [B, C, H, W]
    B, C, H, W = x.shape
    pad_h = (window_size - H % window_size) % window_size
    pad_w = (window_size - W % window_size) % window_size
    if pad_h > 0 or pad_w > 0:
        x = F.pad(x, (0, pad_w, 0, pad_h))
    Hp, Wp = x.shape[-2:]
    x = x.view(B, C, Hp // window_size, window_size, Wp // window_size, window_size)
    x = x.permute(0, 2, 4, 3, 5, 1).contiguous().view(-1, window_size * window_size, C)
    return x, (H, W, Hp, Wp)


def window_reverse(windows: torch.Tensor, window_size: int, shape_info: Tuple[int, int, int, int], B: int):
    H, W, Hp, Wp = shape_info
    C = windows.shape[-1]
    x = windows.view(B, Hp // window_size, Wp // window_size, window_size, window_size, C)
    x = x.permute(0, 5, 1, 3, 2, 4).contiguous().view(B, C, Hp, Wp)
    x = x[:, :, :H, :W]
    return x


class WindowedSelectiveScan2D(nn.Module):
    """
    Phiên bản thực dụng, chạy thuần PyTorch trên Windows/CUDA.
    Không phụ thuộc custom CUDA kernel của Mamba/VMamba.
    Ý tưởng:
    - local depthwise conv giữ ngữ cảnh gần
    - quét chọn lọc trong từng cửa sổ nhỏ
    - forward + backward scan để giảm lệch hướng
    """
    def __init__(self, channels: int, window_size: int = 4, drop: float = 0.0):
        super().__init__()
        self.channels = channels
        self.window_size = window_size
        self.pre_norm = LayerNorm2d(channels)
        self.local_dw = nn.Conv2d(channels, channels, kernel_size=3, padding=1, groups=channels, bias=False)
        self.in_proj = nn.Linear(channels, channels * 3)
        self.out_proj = nn.Linear(channels, channels)
        self.dropout = nn.Dropout(drop)

    @staticmethod
    def _scan(delta: torch.Tensor, value: torch.Tensor) -> torch.Tensor:
        # delta, value: [B*, L, C]
        Bn, L, C = delta.shape
        state = torch.zeros((Bn, C), device=delta.device, dtype=delta.dtype)
        outs = []
        for t in range(L):
            state = delta[:, t] * state + (1.0 - delta[:, t]) * value[:, t]
            outs.append(state)
        return torch.stack(outs, dim=1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x: [B, C, H, W]
        B = x.shape[0]
        x = self.pre_norm(x)
        x = self.local_dw(x) + x

        windows, shape_info = window_partition(x, self.window_size)  # [B*nw, L, C]
        q, v, g = self.in_proj(windows).chunk(3, dim=-1)
        delta = torch.sigmoid(q)
        value = torch.tanh(v)
        gate = torch.sigmoid(g)

        y_fwd = self._scan(delta, value)
        y_bwd = torch.flip(self._scan(torch.flip(delta, dims=[1]), torch.flip(value, dims=[1])), dims=[1])
        y = 0.5 * (y_fwd + y_bwd)
        y = gate * y
        y = self.out_proj(y)
        y = self.dropout(y)
        y = window_reverse(y, self.window_size, shape_info, B)
        return y


class AdaptiveMedMambaBlock(nn.Module):
    def __init__(
        self,
        channels: int,
        window_size: int = 4,
        mlp_ratio: float = 2.0,
        drop: float = 0.0,
        drop_path: float = 0.0,
    ):
        super().__init__()
        self.norm = LayerNorm2d(channels)
        self.conv_branch = ConvBranch(channels, mlp_ratio=mlp_ratio, drop=drop)
        self.ssm_branch = WindowedSelectiveScan2D(channels, window_size=window_size, drop=drop)
        self.gate = AdaptiveDualBranchGate(channels)
        self.fuse = nn.Sequential(
            nn.Conv2d(channels, channels, kernel_size=1, bias=False),
            nn.BatchNorm2d(channels),
        )
        self.drop_path = DropPath(drop_path)
        self.mlp = nn.Sequential(
            LayerNorm2d(channels),
            nn.Conv2d(channels, int(channels * mlp_ratio), kernel_size=1),
            nn.GELU(),
            nn.Dropout(drop),
            nn.Conv2d(int(channels * mlp_ratio), channels, kernel_size=1),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        residual = x
        z = self.norm(x)
        conv_out = self.conv_branch(z)
        ssm_out = self.ssm_branch(z)
        g_conv, g_ssm = self.gate(z)
        z = g_conv * conv_out + g_ssm * ssm_out
        z = self.fuse(z)
        x = residual + self.drop_path(z)
        x = x + self.drop_path(self.mlp(x))
        return x


class HybridEfficientNetV2MedMamba(nn.Module):
    def __init__(self, cfg: CFG, num_classes: int):
        super().__init__()
        weights = EfficientNet_V2_S_Weights.IMAGENET1K_V1 if cfg.pretrained_backbone else None
        backbone = efficientnet_v2_s(weights=weights)
        self.backbone = backbone.features  # [B, 1280, 7, 7] tại 224x224
        self.proj = nn.Sequential(
            nn.Conv2d(1280, cfg.embed_dim, kernel_size=1, bias=False),
            nn.BatchNorm2d(cfg.embed_dim),
            nn.GELU(),
        )

        dpr = torch.linspace(0, cfg.drop_path_rate, cfg.depth).tolist()
        self.blocks = nn.Sequential(*[
            AdaptiveMedMambaBlock(
                channels=cfg.embed_dim,
                window_size=cfg.window_size,
                mlp_ratio=cfg.mlp_ratio,
                drop=cfg.drop_rate,
                drop_path=dpr[i],
            )
            for i in range(cfg.depth)
        ])

        self.head_norm = LayerNorm2d(cfg.embed_dim)
        self.dropout = nn.Dropout(cfg.drop_rate)
        self.classifier = nn.Linear(cfg.embed_dim, num_classes)

    def set_backbone_trainable(self, trainable: bool) -> None:
        for p in self.backbone.parameters():
            p.requires_grad = trainable

    def forward_features(self, x: torch.Tensor) -> torch.Tensor:
        x = self.backbone(x)
        x = self.proj(x)
        x = self.blocks(x)
        x = self.head_norm(x)
        x = F.adaptive_avg_pool2d(x, output_size=1).flatten(1)
        return x

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.forward_features(x)
        x = self.dropout(x)
        return self.classifier(x)
