class AsymmetricLoss(nn.Module):
    def __init__(self, gamma_neg=4.0, gamma_pos=1.0, clip=0.05, eps=1e-8):
        super().__init__()
        self.gamma_neg = gamma_neg
        self.gamma_pos = gamma_pos
        self.clip = clip
        self.eps = eps

    def forward(self, logits: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        targets = targets.float()
        xs_pos = torch.sigmoid(logits)
        xs_neg = 1.0 - xs_pos

        if self.clip is not None and self.clip > 0:
            xs_neg = (xs_neg + self.clip).clamp(max=1.0)

        los_pos = targets * torch.log(xs_pos.clamp(min=self.eps))
        los_neg = (1.0 - targets) * torch.log(xs_neg.clamp(min=self.eps))
        loss = los_pos + los_neg

        if self.gamma_neg > 0 or self.gamma_pos > 0:
            pt0 = xs_pos * targets
            pt1 = xs_neg * (1.0 - targets)
            pt = pt0 + pt1
            one_sided_gamma = self.gamma_pos * targets + self.gamma_neg * (1.0 - targets)
            one_sided_w = torch.pow(1.0 - pt, one_sided_gamma)
            loss *= one_sided_w

        return -loss.mean()


@torch.no_grad()
def safe_macro_auc(y_true: np.ndarray, y_prob: np.ndarray) -> float:
    aucs = []
    for i in range(y_true.shape[1]):
        col = y_true[:, i]
        if np.unique(col).size < 2:
            continue
        aucs.append(roc_auc_score(col, y_prob[:, i]))
    return float(np.mean(aucs)) if len(aucs) > 0 else float("nan")


class RollingAUCMeter:
    def __init__(self, max_samples: int = 2048):
        self.max_samples = max_samples
        self.targets: List[np.ndarray] = []
        self.probs: List[np.ndarray] = []
        self.total = 0

    def update(self, target: torch.Tensor, prob: torch.Tensor) -> None:
        t = target.detach().cpu().numpy().astype(np.float32)
        p = prob.detach().cpu().numpy().astype(np.float32)
        self.targets.append(t)
        self.probs.append(p)
        self.total += len(t)
        while self.total > self.max_samples and len(self.targets) > 0:
            removed_t = self.targets.pop(0)
            self.probs.pop(0)
            self.total -= len(removed_t)

    def compute(self) -> float:
        if len(self.targets) == 0:
            return float("nan")
        y_true = np.concatenate(self.targets, axis=0)
        y_prob = np.concatenate(self.probs, axis=0)
        return safe_macro_auc(y_true, y_prob)
