def make_loader(dataset, batch_size, shuffle, cfg: CFG, sampler=None):
    num_workers = int(max(0, min(cfg.num_workers, (os.cpu_count() or 2) - 1 if (os.cpu_count() or 2) > 1 else 0)))
    kwargs = dict(
        dataset=dataset,
        batch_size=batch_size,
        shuffle=(shuffle and sampler is None),
        sampler=sampler,
        num_workers=num_workers,
        pin_memory=cfg.pin_memory,
        persistent_workers=(cfg.persistent_workers and num_workers > 0),
        drop_last=False,
    )
    if num_workers > 0:
        kwargs["prefetch_factor"] = cfg.prefetch_factor
    return DataLoader(**kwargs)
