# =========================
# 14. Main
# =========================
def run_training(cfg: CFG):
    set_seed(cfg.seed)
    device = setup_runtime(cfg)

    base_dir = Path(cfg.base_dir).resolve()
    output_dir = ensure_dir(base_dir / cfg.output_dir)
    paths = checkpoint_paths(output_dir, cfg)

    train_csv = (base_dir / cfg.train_csv).resolve()
    valid_csv = (base_dir / cfg.valid_csv).resolve()
    test_csv = (base_dir / cfg.test_csv).resolve()
    for p in [train_csv, valid_csv, test_csv]:
        if not p.exists():
            raise FileNotFoundError(f"Không tìm thấy file split: {p}")

    train_df = pd.read_csv(train_csv)
    valid_df = pd.read_csv(valid_csv)
    test_df = pd.read_csv(test_csv)

    label_names = build_label_names(cfg, [train_df, valid_df, test_df], paths["labels"])
    image_index = build_or_load_image_index(base_dir, cfg, paths["image_index"])

    train_tfms, valid_tfms = build_transforms(cfg)
    train_ds = NIHChestXrayDataset(train_df, image_index, label_names, transform=train_tfms)
    valid_ds = NIHChestXrayDataset(valid_df, image_index, label_names, transform=valid_tfms)
    test_ds = NIHChestXrayDataset(test_df, image_index, label_names, transform=valid_tfms)

    model = HybridEfficientNetV2MedMamba(cfg, num_classes=len(label_names)).to(device)
    if cfg.channels_last:
        model = model.to(memory_format=torch.channels_last)

    optimizer = build_optimizer(model, cfg)
    scheduler = build_scheduler(optimizer, cfg)
    scaler = GradScaler("cuda", enabled=(device.type == "cuda" and cfg.use_amp))
    criterion = AsymmetricLoss(
        gamma_neg=cfg.asl_gamma_neg,
        gamma_pos=cfg.asl_gamma_pos,
        clip=cfg.asl_clip,
        eps=cfg.asl_eps,
    )

    start_epoch, resume_step, best_auc, history, resumed_from = load_checkpoint_if_available(
        paths, model, optimizer, scheduler, scaler, device
    )

    if resumed_from == "last_checkpoint":
        print(f"Resume từ last checkpoint | epoch={start_epoch + 1} | step={resume_step}")
    elif resumed_from == "best_model":
        print(f"Không có last checkpoint. Dùng best_model để train tiếp từ epoch={start_epoch + 1}")
    else:
        print("Bắt đầu train mới")

    print(f"Device: {device}")
    print(f"Train/Valid/Test: {len(train_ds)}/{len(valid_ds)}/{len(test_ds)}")
    print(f"Số nhãn: {len(label_names)} | {label_names}")

    for epoch in range(start_epoch, cfg.epochs):
        epoch_start = time.time()

        backbone_trainable = epoch >= cfg.freeze_backbone_epochs
        model.set_backbone_trainable(backbone_trainable)

        # Resume đúng giữa epoch bằng sampler có offset
        start_index = 0
        if resumed_from == "last_checkpoint" and epoch == start_epoch and resume_step > 0:
            start_index = resume_step * cfg.batch_size

        train_sampler = ResumableRandomSampler(train_ds, seed=cfg.seed, epoch=epoch, start_index=start_index)
        train_loader = make_loader(train_ds, cfg.batch_size, shuffle=False, cfg=cfg, sampler=train_sampler)
        valid_loader = make_loader(valid_ds, cfg.batch_size, shuffle=False, cfg=cfg)

        train_loss, train_auc = train_one_epoch(
            model=model,
            loader=train_loader,
            criterion=criterion,
            optimizer=optimizer,
            scaler=scaler,
            device=device,
            epoch=epoch,
            cfg=cfg,
            output_paths=paths,
            scheduler=scheduler,
            best_auc=best_auc,
            history=history,
            label_names=label_names,
        )

        valid_loss, valid_auc = evaluate(model, valid_loader, criterion, device, cfg)
        scheduler.step()

        history.setdefault("train_loss", []).append(train_loss)
        history.setdefault("train_auc", []).append(train_auc)
        history.setdefault("valid_loss", []).append(valid_loss)
        history.setdefault("valid_auc", []).append(valid_auc)

        # Sau khi xong epoch thì reset step resume
        resume_step = 0
        resumed_from = None

        save_checkpoint(
            paths["last"],
            model,
            optimizer,
            scheduler,
            scaler,
            epoch=epoch + 1,
            step_in_epoch=0,
            best_auc=best_auc,
            history=history,
            label_names=label_names,
            cfg=cfg,
        )

        improved = valid_auc > best_auc
        if improved:
            best_auc = valid_auc
            save_checkpoint(
                paths["best"],
                model,
                optimizer,
                scheduler,
                scaler,
                epoch=epoch + 1,
                step_in_epoch=0,
                best_auc=best_auc,
                history=history,
                label_names=label_names,
                cfg=cfg,
            )

        save_json(paths["history"], history)

        elapsed = time.time() - epoch_start
        print(
            f"Epoch {epoch + 1:02d}/{cfg.epochs:02d} | "
            f"train_loss={train_loss:.4f} train_auc={train_auc:.4f} | "
            f"valid_loss={valid_loss:.4f} valid_auc={valid_auc:.4f} | "
            f"best_auc={best_auc:.4f} | {elapsed/60:.1f} min"
        )

        gc.collect()
        if device.type == "cuda":
            torch.cuda.empty_cache()

    # test với best model
    if paths["best"].exists():
        best_ckpt = torch.load(paths["best"], map_location=device)
        model.load_state_dict(best_ckpt["model"], strict=False)

    test_loader = make_loader(test_ds, cfg.batch_size, shuffle=False, cfg=cfg)
    test_loss, test_auc = evaluate(model, test_loader, criterion, device, cfg)
    print(f"TEST | loss={test_loss:.4f} auc={test_auc:.4f}")

    result = {
        "best_valid_auc": best_auc,
        "test_auc": test_auc,
        "history_path": str(paths["history"]),
        "best_model_path": str(paths["best"]),
        "last_checkpoint_path": str(paths["last"]),
        "label_names": label_names,
    }
    return result


if __name__ == "__main__":
    result = run_training(CFG)
    print(json.dumps(result, indent=2, ensure_ascii=False))
