def checkpoint_paths(output_dir: Path, cfg: CFG):
    return {
        "last": output_dir / cfg.checkpoint_name,
        "best": output_dir / cfg.best_name,
        "history": output_dir / cfg.history_name,
        "labels": output_dir / cfg.labels_name,
        "image_index": output_dir / cfg.image_index_name,
    }


def atomic_save(obj: dict, path: Path) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    torch.save(obj, tmp)
    tmp.replace(path)


def save_checkpoint(
    path: Path,
    model: nn.Module,
    optimizer,
    scheduler,
    scaler,
    epoch: int,
    step_in_epoch: int,
    best_auc: float,
    history: dict,
    label_names: Sequence[str],
    cfg: CFG,
) -> None:
    ckpt = {
        "epoch": epoch,
        "step_in_epoch": step_in_epoch,
        "model": model.state_dict(),
        "optimizer": optimizer.state_dict(),
        "scheduler": scheduler.state_dict(),
        "scaler": scaler.state_dict() if scaler is not None else None,
        "best_auc": best_auc,
        "history": history,
        "label_names": list(label_names),
        "cfg": asdict(cfg),
    }
    atomic_save(ckpt, path)


def load_checkpoint_if_available(paths: dict, model, optimizer, scheduler, scaler, device):
    start_epoch = 0
    step_in_epoch = 0
    best_auc = -float("inf")
    history = {"train_loss": [], "train_auc": [], "valid_loss": [], "valid_auc": []}
    resumed_from = None

    ckpt_path = None
    if paths["last"].exists():
        ckpt_path = paths["last"]
        resumed_from = "last_checkpoint"
    elif paths["best"].exists():
        ckpt_path = paths["best"]
        resumed_from = "best_model"

    if ckpt_path is None:
        return start_epoch, step_in_epoch, best_auc, history, resumed_from

    ckpt = torch.load(ckpt_path, map_location=device)
    model.load_state_dict(ckpt["model"], strict=False)
    best_auc = ckpt.get("best_auc", best_auc)
    history = ckpt.get("history", history)
    start_epoch = int(ckpt.get("epoch", -1))
    step_in_epoch = int(ckpt.get("step_in_epoch", 0))

    if resumed_from == "last_checkpoint":
        if "optimizer" in ckpt and ckpt["optimizer"] is not None:
            optimizer.load_state_dict(ckpt["optimizer"])
        if "scheduler" in ckpt and ckpt["scheduler"] is not None:
            scheduler.load_state_dict(ckpt["scheduler"])
        if scaler is not None and ckpt.get("scaler") is not None:
            scaler.load_state_dict(ckpt["scaler"])
    else:
        # fallback: chỉ có best model thì bắt đầu epoch kế tiếp từ đầu epoch
        step_in_epoch = 0

    return start_epoch, step_in_epoch, best_auc, history, resumed_from
