def draw_each_column(dataframe, dataset_name="Dataset", max_categories=20):
    df = dataframe.copy()

    for column in df.columns:
        plt.figure(figsize=(10, 5))

        missing_count = df[column].isna().sum()
        missing_percent = df[column].isna().mean() * 100

        # Cột số
        if pd.api.types.is_numeric_dtype(df[column]):
            valid_data = df[column].dropna()

            plt.hist(
                valid_data,
                bins=30,
                edgecolor="black"
            )

            plt.xlabel(column)
            plt.ylabel("Tần suất")
            plt.title(
                f"{dataset_name} - Phân bố {column}\n"
                f"Dữ liệu thiếu: {missing_count} "
                f"({missing_percent:.2f}%)"
            )

        # Cột phân loại
        else:
            values = (
                df[column]
                .fillna("Thiếu")
                .astype(str)
                .str.strip()
                .value_counts()
            )

            # Nếu có quá nhiều giá trị, chỉ hiển thị các giá trị phổ biến nhất
            if len(values) > max_categories:
                top_values = values.head(max_categories)
                other_count = values.iloc[max_categories:].sum()

                values = pd.concat([
                    top_values,
                    pd.Series({"Khác": other_count})
                ])

            plt.bar(
                values.index,
                values.values,
                edgecolor="black"
            )

            plt.xlabel(column)
            plt.ylabel("Số lượng")
            plt.title(
                f"{dataset_name} - Phân bố {column}\n"
                f"Dữ liệu thiếu: {missing_count} "
                f"({missing_percent:.2f}%)"
            )

            plt.xticks(
                rotation=45,
                ha="right"
            )

        plt.tight_layout()
        plt.show()
