import pandas as pd
import matplotlib.pyplot as plt


def draw_each_column(dataframe, dataset_name="Dataset", max_categories=20):
    df = dataframe.copy()

    for column in df.columns:
        missing_count = df[column].isna().sum()

        # Cột phân loại
        if not pd.api.types.is_numeric_dtype(df[column]):
            valid_counts = (
                df[column]
                .dropna()
                .astype(str)
                .str.strip()
                .value_counts()
            )

            # Giới hạn số lượng giá trị hiển thị
            if len(valid_counts) > max_categories:
                top_counts = valid_counts.head(max_categories)
                other_count = valid_counts.iloc[max_categories:].sum()

                valid_counts = pd.concat([
                    top_counts,
                    pd.Series({"Khác": other_count})
                ])

            # Luôn thêm dữ liệu thiếu ở vị trí cuối cùng
            values = pd.concat([
                valid_counts,
                pd.Series({"Dữ liệu thiếu": missing_count})
            ])

            plt.figure(figsize=(11, 5))
            bars = plt.bar(values.index, values.values)

            for bar, value in zip(bars, values.values):
                plt.text(
                    bar.get_x() + bar.get_width() / 2,
                    bar.get_height(),
                    str(value),
                    ha="center",
                    va="bottom"
                )

            plt.title(f"{dataset_name} - {column}")
            plt.xlabel(column)
            plt.ylabel("Số lượng")
            plt.xticks(rotation=45, ha="right")
            plt.tight_layout()
            plt.show()
