        valid_data = df[column].dropna()

        # Bỏ qua cột hoàn toàn không có dữ liệu hợp lệ
        if valid_data.empty:
            labels = ["Dữ liệu thiếu"]
            counts = [missing_count]

        # Cột số
        elif pd.api.types.is_numeric_dtype(df[column]):
            unique_count = valid_data.nunique()

            # Số lượng giá trị khác nhau ít: vẽ từng giá trị
            if unique_count <= 30:
                value_counts = (
                    valid_data
                    .value_counts()
                    .sort_index()
                )

                labels = [
                    str(value)
                    for value in value_counts.index
                ]

                counts = value_counts.values.tolist()

            # Số lượng giá trị khác nhau nhiều: dùng histogram
            else:
                histogram_counts, bin_edges = np.histogram(
                    valid_data,
                    bins=numeric_bins
                )

                labels = [
                    f"{bin_edges[index]:.1f}–{bin_edges[index + 1]:.1f}"
                    for index in range(len(histogram_counts))
                ]

                counts = histogram_counts.tolist()

            # Chỉ thêm cột thiếu nếu thực sự có NaN
            if missing_count > 0:
                labels.append("Dữ liệu thiếu")
                counts.append(missing_count)

        # Cột phân loại
        else:
            value_counts = (
                valid_data
                .astype(str)
                .str.strip()
                .value_counts()
            )

            # Giữ toàn bộ giá trị, không giới hạn top N
            labels = value_counts.index.tolist()
            counts = value_counts.values.tolist()

            # Thêm dữ liệu thiếu ở cuối
            if missing_count > 0:
                labels.append("Dữ liệu thiếu")
                counts.append(missing_count)

        plt.figure(figsize=(max(10, len(labels) * 0.55), 5))

        bars = plt.bar(
            range(len(labels)),
            counts
        )

        # Hiển thị số lượng trên từng cột
        for bar, count in zip(bars, counts):
            plt.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height(),
                str(count),
                ha="center",
                va="bottom",
                fontsize=8
            )

        plt.xticks(
            range(len(labels)),
            labels,
            rotation=45,
            ha="right"
        )

        plt.title(f"{dataset_name} - Phân bố trường {column}")
        plt.xlabel(column)
        plt.ylabel("Số lượng")
        plt.tight_layout()
        plt.show()
