def draw_all_fields(dataframe, dataset_name="Dataset", numeric_bins=20):
    df = dataframe.copy()

    # Luôn duyệt toàn bộ trường
    for column in df.columns:
        series = df[column]
        missing_count = series.isna().sum()

        # Trường số
        if pd.api.types.is_numeric_dtype(series):
            valid_values = series.dropna()

            histogram_counts, bin_edges = np.histogram(
                valid_values,
                bins=numeric_bins
            )

            labels = [
                f"{bin_edges[i]:.1f}–{bin_edges[i + 1]:.1f}"
                for i in range(len(histogram_counts))
            ]

            counts = histogram_counts.tolist()

        # Trường phân loại
        else:
            cleaned_series = (
                series
                .astype("string")
                .str.strip()
            )

            value_counts = (
                cleaned_series
                .dropna()
                .value_counts()
            )

            labels = value_counts.index.astype(str).tolist()
            counts = value_counts.values.tolist()

        # Chỉ thêm cột thiếu ở cuối khi trường đó có NaN
        if missing_count > 0:
            labels.append("Dữ liệu thiếu")
            counts.append(missing_count)

        # Vẫn vẽ trường không có dữ liệu thiếu
        plt.figure(
            figsize=(max(10, len(labels) * 0.55), 5)
        )

        bars = plt.bar(
            range(len(labels)),
            counts
        )

        for bar, count in zip(bars, counts):
            plt.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height(),
                str(count),
                ha="center",
                va="bottom",
                fontsize=8
            )

        plt.xticks(
            range(len(labels)),
            labels,
            rotation=45,
            ha="right"
        )

        plt.title(f"{dataset_name} - {column}")
