import pandas as pd
import matplotlib.pyplot as plt


def draw_each_column(
    dataframe,
    dataset_name="Dataset",
    numeric_groups=10
):
    df = dataframe.copy()

    default_color = "#1f77b4"
    missing_color = "red"

    for column in df.columns:
        series = df[column]

        missing_count = series.isna().sum()
        missing_percent = series.isna().mean() * 100

        # =====================================================
        # CỘT SỐ: GOM THÀNH CÁC KHOẢNG
        # =====================================================
        if pd.api.types.is_numeric_dtype(series):
            valid_data = series.dropna()

            # Cột chỉ có một giá trị duy nhất
            if valid_data.nunique() <= 1:
                grouped_counts = valid_data.value_counts().sort_index()

            # Cột có ít giá trị khác nhau: giữ từng giá trị
            elif valid_data.nunique() <= numeric_groups:
                grouped_counts = valid_data.value_counts().sort_index()

            # Cột có nhiều giá trị: gom thành khoảng
            else:
                grouped_data = pd.cut(
                    valid_data,
                    bins=numeric_groups,
                    include_lowest=True,
                    duplicates="drop"
                )

                grouped_counts = (
                    grouped_data
                    .value_counts(sort=False)
                )

            labels = [
                str(value)
                for value in grouped_counts.index
            ]

            counts = grouped_counts.values.tolist()

        # =====================================================
        # CỘT PHÂN LOẠI: GOM THEO GIÁ TRỊ
        # =====================================================
        else:
            valid_data = (
                series
                .dropna()
                .astype(str)
                .str.strip()
            )

            grouped_counts = valid_data.value_counts()

            labels = grouped_counts.index.tolist()
            counts = grouped_counts.values.tolist()

        # Màu cho các nhóm dữ liệu bình thường
        colors = [default_color] * len(labels)

        # Thêm dữ liệu thiếu vào cuối cùng
        if missing_count > 0:
            labels.append("Dữ liệu thiếu")
            counts.append(missing_count)
            colors.append(missing_color)

        # Kích thước biểu đồ phụ thuộc số nhóm
        figure_width = max(10, len(labels) * 0.75)

        plt.figure(figsize=(figure_width, 5))

        positions = range(len(labels))

        bars = plt.bar(
            positions,
            counts,
            color=colors,
            edgecolor="black"
        )

        # Hiển thị số lượng trên cột
        for bar, count in zip(bars, counts):
            plt.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height(),
                f"{count:,}",
                ha="center",
                va="bottom",
                fontsize=8
            )

        plt.xticks(
            positions,
            labels,
            rotation=45,
            ha="right"
        )

        plt.xlabel(column)
        plt.ylabel("Số lượng")

        plt.title(
            f"{dataset_name} - Phân bố {column}\n"
            f"Dữ liệu thiếu: {missing_count:,} "
            f"({missing_percent:.2f}%)"
        )

        plt.tight_layout()
        plt.show()
