        missing_percent = series.isna().mean() * 100

        # Chuẩn hóa chuỗi nhưng vẫn giữ NaN
        if not pd.api.types.is_numeric_dtype(series):
            valid_series = (
                series
                .dropna()
                .astype(str)
                .str.strip()
            )

            # Giữ toàn bộ giá trị phân loại, không gom nhóm
            value_counts = valid_series.value_counts()
        else:
            # Giữ từng giá trị số chính xác, không chia khoảng
            value_counts = (
                series
                .dropna()
                .value_counts()
                .sort_index()
            )

        labels = value_counts.index.astype(str).tolist()
        counts = value_counts.values.tolist()

        # Thêm dữ liệu thiếu vào vị trí cuối cùng
        if missing_count > 0:
            labels.append("Dữ liệu thiếu")
            counts.append(missing_count)

