def draw_each_column_raw(dataframe, dataset_name="Dataset"):
    df = dataframe.copy()

    for column in df.columns:
        series = df[column]

        missing_count = series.isna().sum()
        missing_percent = series.isna().mean() * 100

        # Không làm mất NaN khi chuẩn hóa chuỗi
        if pd.api.types.is_object_dtype(series) or pd.api.types.is_string_dtype(series):
            valid_series = (
                series
                .dropna()
                .astype(str)
                .str.strip()
            )
        else:
            valid_series = series.dropna()

        # Đếm từng giá trị chính xác
        # Không dùng hist, cut, bin hoặc khoảng
        value_counts = valid_series.value_counts(sort=False)

        # Sắp xếp cột số theo đúng giá trị tăng dần
        if pd.api.types.is_numeric_dtype(series):
            value_counts = value_counts.sort_index()

        labels = [
            str(value)
            for value in value_counts.index
        ]

        counts = value_counts.tolist()

        # Thêm dữ liệu thiếu vào cột cuối cùng
        if missing_count > 0:
            labels.append("Dữ liệu thiếu")
            counts.append(missing_count)

        positions = list(range(len(labels)))

        # Cột có nhiều giá trị cần biểu đồ rộng hơn
        figure_width = max(12, len(labels) * 0.35)

        plt.figure(figsize=(figure_width, 6))

        bars = plt.bar(
            positions,
            counts,
            edgecolor="black"
        )

        # Tô đỏ cột dữ liệu thiếu
        if missing_count > 0:
            bars[-1].set_color("red")

        # Hiển thị số lượng trên cột
        # Không hiện số trên tất cả cột nếu số giá trị quá lớn
        if len(labels) <= 100:
            for bar, count in zip(bars, counts):
                plt.text(
                    bar.get_x() + bar.get_width() / 2,
                    bar.get_height(),
                    str(count),
                    ha="center",
                    va="bottom",
                    fontsize=8
                )

        # Bắt buộc dùng vị trí category, không dùng trục số liên tục
        plt.xticks(
            ticks=positions,
            labels=labels,
            rotation=90,
            fontsize=8
        )

        plt.xlabel(column)
        plt.ylabel("Số lượng")

        plt.title(
            f"{dataset_name} - Phân bố {column}\n"
            f"Dữ liệu thiếu: {missing_count} "
            f"({missing_percent:.2f}%)"
        )

        plt.tight_layout()
        plt.show()
