import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def draw_each_column(
    dataframe,
    dataset_name="Dataset",
    max_categories=20,
    numeric_bins=30
):
    df = dataframe.copy()

    # Màu mặc định của Matplotlib và màu đỏ cho dữ liệu thiếu
    default_color = plt.rcParams[
        "axes.prop_cycle"
    ].by_key()["color"][0]

    missing_color = "red"

    for column in df.columns:
        series = df[column]
        missing_count = series.isna().sum()
        missing_percent = series.isna().mean() * 100

        # =====================================================
        # CỘT SỐ
        # =====================================================
        if pd.api.types.is_numeric_dtype(series):
            valid_data = series.dropna()

            histogram_counts, bin_edges = np.histogram(
                valid_data,
                bins=numeric_bins
            )

            labels = [
                f"{bin_edges[index]:.1f}–{bin_edges[index + 1]:.1f}"
                for index in range(len(histogram_counts))
            ]

            counts = histogram_counts.tolist()
            colors = [default_color] * len(counts)

            # Thêm dữ liệu thiếu vào cột cuối cùng
            if missing_count > 0:
                labels.append("Dữ liệu thiếu")
                counts.append(missing_count)
                colors.append(missing_color)

            figure_width = max(12, len(labels) * 0.5)
            plt.figure(figsize=(figure_width, 5))

            bars = plt.bar(
                range(len(labels)),
                counts,
                color=colors,
                edgecolor="black"
            )

            plt.xticks(
                range(len(labels)),
                labels,
                rotation=45,
                ha="right"
            )

        # =====================================================
        # CỘT PHÂN LOẠI
        # =====================================================
        else:
            valid_values = (
                series
                .dropna()
                .astype(str)
                .str.strip()
                .value_counts()
            )

            # Giới hạn số nhóm nhưng vẫn giữ dữ liệu thiếu ở cuối
            if len(valid_values) > max_categories:
                top_values = valid_values.head(max_categories)
                other_count = valid_values.iloc[max_categories:].sum()

                valid_values = pd.concat([
                    top_values,
                    pd.Series({"Khác": other_count})
                ])

            labels = valid_values.index.tolist()
            counts = valid_values.values.tolist()
            colors = [default_color] * len(counts)

            # Thêm dữ liệu thiếu vào cuối cùng
            if missing_count > 0:
                labels.append("Dữ liệu thiếu")
                counts.append(missing_count)
                colors.append(missing_color)

            figure_width = max(10, len(labels) * 0.65)
            plt.figure(figsize=(figure_width, 5))

            bars = plt.bar(
                range(len(labels)),
                counts,
                color=colors,
                edgecolor="black"
            )

            plt.xticks(
                range(len(labels)),
                labels,
                rotation=45,
                ha="right"
            )

        # Hiển thị số lượng trên mỗi cột
        for bar, count in zip(bars, counts):
            plt.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height(),
                f"{count:,}",
                ha="center",
                va="bottom",
                fontsize=8
            )

        plt.xlabel(column)
        plt.ylabel("Số lượng")

        plt.title(
            f"{dataset_name} - Phân bố {column}\n"
            f"Dữ liệu thiếu: {missing_count:,} "
            f"({missing_percent:.2f}%)"
        )

        plt.tight_layout()
        plt.show()
