import pandas as pd
import matplotlib.pyplot as plt


def draw_each_column(dataframe, dataset_name="Dataset", max_categories=20):
    df = dataframe.copy()

    for column in df.columns:
        fig, ax = plt.subplots(figsize=(10, 5))

        missing_count = df[column].isna().sum()
        missing_percent = df[column].isna().mean() * 100

        # =====================================================
        # CỘT SỐ
        # =====================================================
        if pd.api.types.is_numeric_dtype(df[column]):
            valid_data = df[column].dropna()

            if not valid_data.empty:
                counts, bins, patches = ax.hist(
                    valid_data,
                    bins=30,
                    edgecolor="black"
                )

                # Nếu có dữ liệu thiếu, thêm cột đỏ ở cuối histogram
                if missing_count > 0:
                    bin_width = bins[1] - bins[0]

                    missing_x = bins[-1] + bin_width

                    ax.bar(
                        missing_x,
                        missing_count,
                        width=bin_width * 0.8,
                        color="red",
                        edgecolor="black"
                    )

                    # Hiển thị số lượng phía trên cột thiếu
                    ax.text(
                        missing_x,
                        missing_count,
                        str(missing_count),
                        ha="center",
                        va="bottom"
                    )

                    # Thêm nhãn "Dữ liệu thiếu" vào cuối trục X
                    current_ticks = list(ax.get_xticks())

                    current_tick_labels = [
                        f"{tick:g}"
                        for tick in current_ticks
                    ]

                    ax.set_xticks(
                        current_ticks + [missing_x]
                    )

                    ax.set_xticklabels(
                        current_tick_labels + ["Dữ liệu thiếu"],
                        rotation=45,
                        ha="right"
                    )

                    ax.set_xlim(
                        bins[0],
                        missing_x + bin_width
                    )

            # Trường hợp toàn bộ cột đều là NaN
            elif missing_count > 0:
                ax.bar(
                    ["Dữ liệu thiếu"],
                    [missing_count],
                    color="red",
                    edgecolor="black"
                )

                ax.text(
                    0,
                    missing_count,
                    str(missing_count),
                    ha="center",
                    va="bottom"
                )

            ax.set_xlabel(column)
            ax.set_ylabel("Tần suất")

        # =====================================================
        # CỘT PHÂN LOẠI
        # =====================================================
        else:
            # Không đưa NaN vào value_counts ngay từ đầu
            values = (
                df[column]
                .dropna()
                .astype(str)
                .str.strip()
                .value_counts()
            )

            # Giới hạn các nhóm dữ liệu hợp lệ
            if len(values) > max_categories:
                top_values = values.head(max_categories)
                other_count = values.iloc[max_categories:].sum()

                values = pd.concat([
                    top_values,
                    pd.Series({"Khác": other_count})
                ])

            labels = values.index.tolist()
            counts = values.values.tolist()

            # Màu mặc định cho dữ liệu bình thường
            colors = [
                plt.rcParams["axes.prop_cycle"].by_key()["color"][0]
            ] * len(labels)

            # Thêm dữ liệu thiếu ở vị trí cuối cùng
            if missing_count > 0:
                labels.append("Dữ liệu thiếu")
                counts.append(missing_count)
                colors.append("red")

            bars = ax.bar(
                labels,
                counts,
                color=colors,
                edgecolor="black"
            )

            # Hiển thị số lượng trên cột dữ liệu thiếu
            if missing_count > 0:
                missing_bar = bars[-1]

                ax.text(
                    missing_bar.get_x() + missing_bar.get_width() / 2,
                    missing_bar.get_height(),
                    str(missing_count),
                    ha="center",
                    va="bottom"
                )

            ax.set_xlabel(column)
            ax.set_ylabel("Số lượng")

            ax.tick_params(
                axis="x",
                labelrotation=45
            )

            for label in ax.get_xticklabels():
                label.set_horizontalalignment("right")

        ax.set_title(
            f"{dataset_name} - Phân bố {column}\n"
            f"Dữ liệu thiếu: {missing_count} "
            f"({missing_percent:.2f}%)"
        )

        plt.tight_layout()
        plt.show()
