def read_column_names(names_file):
    attribute_names = []
    class_values = []

    with Path(names_file).open(
        mode="r",
        encoding="utf-8"
    ) as file:
        for raw_line in file:
            line = raw_line.strip()

            # Bỏ dòng trống và dòng chú thích
            if not line or line.startswith("|"):
                continue

            # Dòng định nghĩa thuộc tính
            if ":" in line:
                attribute_name = line.split(":", 1)[0].strip()

                # Chuẩn hóa tên cột sang snake_case
                attribute_name = attribute_name.replace("-", "_")

                attribute_names.append(attribute_name)

            # Dòng khai báo các nhãn: >50K, <=50K.
            elif line.endswith(".") and "," in line:
                class_values = [
                    value.strip()
                    for value in line[:-1].split(",")
                ]

    # adult.names không khai báo tên cột target,
    # chỉ khai báo giá trị >50K và <=50K
    column_names = attribute_names + ["income"]

    return column_names, class_values


column_names, income_classes = read_column_names(COLUMN_NAME_PATH)

print(column_names)
print(income_classes)
