def missing_report(dataframe):
    # Tạo bản sao để không thay đổi dữ liệu gốc
    df = dataframe.copy()

    # Xóa khoảng trắng đầu và cuối trong các cột dạng chuỗi
    string_columns = df.select_dtypes(
        include=["object", "string"]
    ).columns

    for column in string_columns:
        df[column] = (
            df[column]
            .astype("string")
            .str.strip()
        )

    # Tìm các ô chứa đúng ký tự "?"
    missing_mask = df.isna()

    # Tạo bảng thống kê
    missing_report = pd.DataFrame({
        "Tên cột": df.columns,
        "Dữ liệu thiếu": missing_mask.sum().values,
        "Tỷ lệ thiếu (%)": (
            missing_mask.mean().values * 100
        ).round(2)
    })

    # Chỉ giữ lại các cột có dữ liệu thiếu
    missing_report = missing_report[
        missing_report["Dữ liệu thiếu"] > 0
    ].reset_index(drop=True)

    return missing_report

train_missing_report = missing_report(train_df)
print("DỮ LIỆU THIẾU TRONG TRAIN")
print(train_missing_report.to_string(index=False))

test_missing_report = missing_report(test_df)
print("\nDỮ LIỆU THIẾU TRONG TEST")
print(test_missing_report.to_string(index=False))
