def thong_ke_va_ve_tuoi(df, title="Phân bố độ tuổi"):
    age = df["age"].dropna()

    # Tứ phân vị và ngoại biên
    q1, median, q3 = age.quantile([0.25, 0.5, 0.75])
    iqr = q3 - q1
    lower = q1 - 1.5 * iqr
    upper = q3 + 1.5 * iqr

    outliers = age[(age < lower) | (age > upper)]

    # Thống kê mô tả
    statistics = pd.Series({
        "Số lượng": age.count(),
        "Trung bình": round(age.mean(), 2),
        "Trung vị": median,
        "Mốt": ", ".join(map(str, age.mode().astype(int))),
        "Nhỏ nhất": age.min(),
        "Lớn nhất": age.max(),
        "Khoảng biến thiên": age.max() - age.min(),
        "Q1": q1,
        "Q2": median,
        "Q3": q3,
        "IQR": iqr,
        "Độ lệch chuẩn": round(age.std(), 2),
        "Ngưỡng ngoại biên dưới": lower,
        "Ngưỡng ngoại biên trên": upper,
        "Số điểm ngoại biên": outliers.count()
    })

    print("THỐNG KÊ ĐỘ TUỔI")
    print(statistics)

    # Đếm riêng từng tuổi, không gom nhóm
    age_counts = age.value_counts().sort_index()

    plt.figure(figsize=(15, 6))
    plt.bar(age_counts.index, age_counts.values)

    plt.axvline(
        age.mean(),
        linestyle="--",
        label=f"Trung bình: {age.mean():.2f}"
    )

    plt.axvline(
        median,
        linestyle="--",
        label=f"Trung vị: {median:.0f}"
    )

    plt.title(title)
    plt.xlabel("Độ tuổi")
    plt.ylabel("Số lượng người")
    plt.xticks(range(int(age.min()), int(age.max()) + 1, 2))
    plt.grid(axis="y", linestyle="--", alpha=0.4)
    plt.legend()
    plt.tight_layout()
    plt.show()

    return statistics, outliers
