import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def thong_ke_va_ve_tuoi(df, title="Phân bố độ tuổi"):
    # Chuẩn hóa dữ liệu tuổi
    age = pd.to_numeric(df["age"], errors="coerce").dropna()

    if age.empty:
        raise ValueError("Cột age không có dữ liệu hợp lệ.")

    # Thống kê xu hướng tập trung
    count = age.count()
    mean_age = age.mean()
    median_age = age.median()
    mode_age = age.mode().astype(int).tolist()

    # Thống kê độ phân tán
    min_age = age.min()
    max_age = age.max()
    age_range = max_age - min_age
    std_age = age.std()

    q1 = age.quantile(0.25)
    q3 = age.quantile(0.75)
    iqr = q3 - q1

    # Median Absolute Deviation
    mad = np.median(np.abs(age - median_age))

    # Ngoại biên theo quy tắc IQR
    lower_bound = q1 - 1.5 * iqr
    upper_bound = q3 + 1.5 * iqr

    outliers = age[
        (age < lower_bound) |
        (age > upper_bound)
    ]

    outlier_count = outliers.count()
    outlier_rate = outlier_count / count * 100

    # Đếm từng tuổi riêng biệt, không gom nhóm
    age_counts = age.value_counts().sort_index()

    # Nội dung bảng thống kê
    statistics_rows = [
        ["Số mẫu", f"{count:,}", ""],
        ["Trung bình", f"{mean_age:.2f}", ""],
        ["Trung vị", f"{median_age:.0f}", ""],
        ["Yếu vị", ", ".join(map(str, mode_age)), ""],
        ["Độ lệch chuẩn", f"{std_age:.2f}", ""],
        ["MAD", f"{mad:.2f}", ""],
        ["Nhỏ nhất", f"{min_age:.0f}", ""],
        ["Lớn nhất", f"{max_age:.0f}", ""],
        ["Khoảng biến thiên", f"{age_range:.0f}", ""],
        ["Q1", f"{q1:.2f}", ""],
        ["Q3", f"{q3:.2f}", ""],
        ["IQR", f"{iqr:.2f}", ""],
        ["Ngoại biên", f"{outlier_count:,}", f"{outlier_rate:.2f}%"],
        ["Ngưỡng dưới", f"{lower_bound:.2f}", ""],
        ["Ngưỡng trên", f"{upper_bound:.2f}", ""]
    ]

    # Tạo bố cục biểu đồ và bảng
    fig = plt.figure(figsize=(20, 8))

    grid = fig.add_gridspec(
        nrows=1,
        ncols=2,
        width_ratios=[3.2, 1.3],
        wspace=0.06
    )

    # =========================
    # Biểu đồ phân bố tuổi
    # =========================
    ax_chart = fig.add_subplot(grid[0])

    bars = ax_chart.bar(
        age_counts.index,
        age_counts.values,
        width=0.8
    )

    # Hiển thị số lượng trên từng cột
    for bar, value in zip(bars, age_counts.values):
        ax_chart.text(
            bar.get_x() + bar.get_width() / 2,
            bar.get_height(),
            f"{value}",
            ha="center",
            va="bottom",
            rotation=90,
            fontsize=6
        )

    ax_chart.axvline(
        mean_age,
        linestyle="--",
        linewidth=2,
        label=f"Trung bình: {mean_age:.2f}"
    )

    ax_chart.axvline(
        median_age,
        linestyle="-.",
        linewidth=2,
        label=f"Trung vị: {median_age:.0f}"
    )

    for index, mode in enumerate(mode_age):
        ax_chart.axvline(
            mode,
            linestyle=":",
            linewidth=2,
            label=f"Yếu vị: {mode}" if index == 0 else None
        )

    ax_chart.axvline(
        upper_bound,
        linestyle="--",
        linewidth=2,
        label=f"Ngưỡng ngoại biên: {upper_bound:.0f}"
    )

    ax_chart.set_title(title, fontsize=16, fontweight="bold")
    ax_chart.set_xlabel("Độ tuổi", fontsize=12)
    ax_chart.set_ylabel("Số lượng người", fontsize=12)

    # Hiển thị từng tuổi liên tục
    ax_chart.set_xticks(
        range(int(min_age), int(max_age) + 1)
    )

    ax_chart.tick_params(
        axis="x",
        rotation=90,
        labelsize=8
    )

    ax_chart.grid(
        axis="y",
        linestyle="--",
        alpha=0.35
    )

    ax_chart.legend()

    # =========================
    # Bảng thống kê
    # =========================
    ax_table = fig.add_subplot(grid[1])
    ax_table.axis("off")

    table = ax_table.table(
        cellText=statistics_rows,
        colLabels=["Chỉ số", "Giá trị", "Tỷ lệ"],
        colWidths=[0.48, 0.32, 0.25],
        cellLoc="right",
        colLoc="center",
        loc="center"
    )

    table.auto_set_font_size(False)
    table.set_fontsize(12)
    table.scale(1, 2.1)

    # Định dạng tiêu đề bảng
    for column in range(3):
        cell = table[(0, column)]
        cell.set_facecolor("#4472C4")
        cell.set_text_props(
            color="white",
            fontweight="bold",
            ha="center"
        )

    # Định dạng các hàng
    for row in range(1, len(statistics_rows) + 1):
        # Cột tên chỉ số
        table[(row, 0)].set_facecolor("#4472C4")
        table[(row, 0)].set_text_props(
            color="white",
            fontweight="bold",
            ha="left"
        )

        # Cột giá trị và tỷ lệ
        table[(row, 1)].set_facecolor("#D9E2F3")
        table[(row, 2)].set_facecolor("#D9E2F3")

    ax_table.set_title(
        "Thống kê cơ bản",
        fontsize=16,
        fontweight="bold",
        pad=15
    )

    plt.tight_layout()
    plt.show()

    # Trả về bảng thống kê dạng DataFrame
    statistics_df = pd.DataFrame(
        statistics_rows,
        columns=["Chỉ số", "Giá trị", "Tỷ lệ"]
    )

    return statistics_df, outliers
