import pandas as pd
import matplotlib.pyplot as plt


def ve_boxplot_tuoi(df, title="Boxplot độ tuổi"):
    age = pd.to_numeric(df["age"], errors="coerce").dropna()

    # Các giá trị thống kê
    q1 = age.quantile(0.25)
    median = age.median()
    q3 = age.quantile(0.75)

    iqr = q3 - q1
    lower_limit = q1 - 1.5 * iqr
    upper_limit = q3 + 1.5 * iqr

    # Giá trị thực tế tại hai đầu râu
    lower_whisker = age[age >= lower_limit].min()
    upper_whisker = age[age <= upper_limit].max()

    plt.figure(figsize=(14, 4))

    plt.boxplot(
        age,
        vert=False,
        showmeans=True,
        meanline=False
    )

    # Ghi chú Q1
    plt.annotate(
        f"Q1 = {q1:.0f}",
        xy=(q1, 1),
        xytext=(q1, 1.25),
        ha="center",
        arrowprops={"arrowstyle": "->"}
    )

    # Ghi chú trung vị
    plt.annotate(
        f"Trung vị = {median:.0f}",
        xy=(median, 1),
        xytext=(median, 0.7),
        ha="center",
        arrowprops={"arrowstyle": "->"}
    )

    # Ghi chú Q3
    plt.annotate(
        f"Q3 = {q3:.0f}",
        xy=(q3, 1),
        xytext=(q3, 1.25),
        ha="center",
        arrowprops={"arrowstyle": "->"}
    )

    # Ghi chú râu dưới
    plt.annotate(
        f"Râu dưới = {lower_whisker:.0f}",
        xy=(lower_whisker, 1),
        xytext=(lower_whisker, 0.7),
        ha="center",
        arrowprops={"arrowstyle": "->"}
    )

    # Ghi chú râu trên
    plt.annotate(
        f"Râu trên = {upper_whisker:.0f}",
        xy=(upper_whisker, 1),
        xytext=(upper_whisker, 0.7),
        ha="center",
        arrowprops={"arrowstyle": "->"}
    )

    # Chú thích điểm ngoại biên
    if (age > upper_whisker).any():
        first_outlier = age[age > upper_whisker].min()

        plt.annotate(
            "Điểm ngoại biên",
            xy=(first_outlier, 1),
            xytext=(first_outlier + 3, 1.25),
            ha="center",
            arrowprops={"arrowstyle": "->"}
        )

    plt.title(title)
    plt.xlabel("Độ tuổi")
    plt.yticks([])
    plt.grid(axis="x", linestyle="--", alpha=0.4)
    plt.tight_layout()
    plt.show()
