import pandas as pd
import matplotlib.pyplot as plt


def thong_ke_va_ve_tuoi(df, title="Phân bố độ tuổi"):
    # Lấy cột tuổi và loại bỏ giá trị thiếu
    age = pd.to_numeric(df["age"], errors="coerce").dropna()

    # Đo lường xu hướng tập trung
    mean_age = age.mean()
    median_age = age.median()
    mode_age = age.mode().astype(int).tolist()

    # Đo lường độ phân tán
    min_age = age.min()
    max_age = age.max()
    age_range = max_age - min_age
    std_age = age.std()

    # Tứ phân vị
    q1 = age.quantile(0.25)
    q2 = age.quantile(0.50)
    q3 = age.quantile(0.75)
    iqr = q3 - q1

    # Xác định ngoại biên theo quy tắc IQR
    lower_bound = q1 - 1.5 * iqr
    upper_bound = q3 + 1.5 * iqr

    outliers = age[
        (age < lower_bound) |
        (age > upper_bound)
    ]

    # Tạo bảng thống kê
    statistics = pd.DataFrame({
        "Chỉ số": [
            "Số lượng",
            "Trung bình",
            "Trung vị",
            "Yếu vị",
            "Nhỏ nhất",
            "Lớn nhất",
            "Khoảng biến thiên",
            "Tứ phân vị Q1",
            "Tứ phân vị Q2",
            "Tứ phân vị Q3",
            "Khoảng tứ phân vị IQR",
            "Độ lệch chuẩn",
            "Ngưỡng ngoại biên dưới",
            "Ngưỡng ngoại biên trên",
            "Số điểm ngoại biên"
        ],
        "Giá trị": [
            int(age.count()),
            round(mean_age, 2),
            round(median_age, 2),
            ", ".join(map(str, mode_age)),
            int(min_age),
            int(max_age),
            int(age_range),
            round(q1, 2),
            round(q2, 2),
            round(q3, 2),
            round(iqr, 2),
            round(std_age, 2),
            round(lower_bound, 2),
            round(upper_bound, 2),
            int(outliers.count())
        ]
    })

    print("MÔ TẢ THỐNG KÊ CƠ BẢN VỀ ĐỘ TUỔI")
    display(statistics)

    print("Các độ tuổi được xác định là ngoại biên:")
    print(sorted(outliers.astype(int).unique()))

    # Đếm số người ở từng độ tuổi, không gom nhóm
    age_counts = age.value_counts().sort_index()

    # Vẽ biểu đồ
    plt.figure(figsize=(12, 7))

    plt.bar(
        age_counts.index,
        age_counts.values,
        width=0.8,
        label="Số lượng người"
    )

    # Đường trung bình
    plt.axvline(
        mean_age,
        linestyle="--",
        linewidth=2,
        label=f"Trung bình: {mean_age:.2f}"
    )

    # Đường trung vị
    plt.axvline(
        median_age,
        linestyle="-.",
        linewidth=2,
        label=f"Trung vị: {median_age:.0f}"
    )

    # Đường yếu vị
    for index, mode in enumerate(mode_age):
        plt.axvline(
            mode,
            linestyle=":",
            linewidth=2,
            label=f"Yếu vị: {mode}" if index == 0 else None
        )

    # Ngưỡng ngoại biên trên
    plt.axvline(
        upper_bound,
        linestyle="--",
        linewidth=2,
        label=f"Ngưỡng ngoại biên: {upper_bound:.0f}"
    )

    plt.title(title, fontsize=14)
    plt.xlabel("Độ tuổi")
    plt.ylabel("Số người")

    # Hiển thị từng tuổi liên tiếp trên trục X
    plt.xticks(
        range(int(min_age), int(max_age) + 1),
        rotation=90
    )

    plt.grid(
        axis="y",
        linestyle="--",
        alpha=0.4
    )

    plt.legend()
    plt.tight_layout()
    plt.show()

    return statistics, outliers
