    # Gộp giá trị thiếu thành một nhóm để lập bảng tần suất
    train_display = train_workclass.fillna("Không xác định")
    test_display = test_workclass.fillna("Không xác định")

    train_count = train_display.value_counts()
    test_count = test_display.value_counts()

    train_percent = (
        train_display.value_counts(normalize=True) * 100
    )

    test_percent = (
        test_display.value_counts(normalize=True) * 100
    )

    # Danh sách toàn bộ nhóm xuất hiện trong hai tập
    categories = train_count.index.union(test_count.index)

    statistics = pd.DataFrame({
        "Nhóm công việc": categories,
        "Số lượng (Huấn luyện)": [
            train_count.get(category, 0)
            for category in categories
        ],
        "Tỷ lệ (Huấn luyện)": [
            train_percent.get(category, 0)
            for category in categories
        ],
        "Số lượng (Kiểm thử)": [
            test_count.get(category, 0)
            for category in categories
        ],
        "Tỷ lệ (Kiểm thử)": [
            test_percent.get(category, 0)
            for category in categories
        ]
    })

    # Chênh lệch tỷ lệ theo điểm phần trăm
    statistics["Chênh lệch tỷ lệ"] = (
        statistics["Tỷ lệ (Kiểm thử)"]
        - statistics["Tỷ lệ (Huấn luyện)"]
    ).abs()

    statistics = statistics.sort_values(
        "Số lượng (Huấn luyện)",
        ascending=False
    ).reset_index(drop=True)

    # Định dạng phần trăm
    for column in [
        "Tỷ lệ (Huấn luyện)",
        "Tỷ lệ (Kiểm thử)",
        "Chênh lệch tỷ lệ"
    ]:
        statistics[column] = statistics[column].round(2)

    print("PHÂN BỐ CÁC NHÓM WORKCLASS")
    display(statistics)

    # Vẽ biểu đồ theo tỷ lệ để so sánh hai tập
    plot_data = statistics.set_index("Nhóm công việc")[
        ["Tỷ lệ (Huấn luyện)", "Tỷ lệ (Kiểm thử)"]
    ]

    ax = plot_data.plot(
        kind="bar",
        figsize=(11, 6),
        width=0.8
    )

    ax.set_title(
        "Phân bố nhóm công việc trong tập huấn luyện và tập kiểm thử",
        fontsize=13,
        fontweight="bold"
    )

    ax.set_xlabel("Nhóm công việc")
    ax.set_ylabel("Tỷ lệ (%)")
    ax.tick_params(axis="x", rotation=45)
    ax.grid(axis="y", linestyle="--", alpha=0.4)
    ax.legend(
        ["Tập huấn luyện", "Tập kiểm thử"]
    )

    plt.tight_layout()
    plt.show()

    return summary, statistics
