import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.patches import Patch
from IPython.display import display


def thong_ke_workclass(train_df, test_df):
    """
    Thống kê thuộc tính workclass và vẽ hai biểu đồ riêng:
    - Tập huấn luyện
    - Tập kiểm thử

    Dữ liệu thiếu:
    - Bao gồm ?, chuỗi rỗng và NaN
    - Được đặt ở cột cuối cùng
    - Hiển thị bằng màu đỏ

    Số liệu tỷ lệ được ghi bình thường trên tất cả các cột.
    """

    column = "workclass"
    missing_label = "Dữ liệu thiếu"

    # Kiểm tra cột workclass
    for dataset_name, df in {
        "tập huấn luyện": train_df,
        "tập kiểm thử": test_df
    }.items():
        if column not in df.columns:
            raise KeyError(
                f"Không tìm thấy cột '{column}' trong {dataset_name}."
            )

    # Làm sạch dữ liệu
    def clean_workclass(df):
        workclass = (
            df[column]
            .astype("string")
            .str.strip()
        )

        missing_values = [
            "?",
            "",
            "nan",
            "NaN",
            "none",
            "None",
            "<NA>"
        ]

        workclass = workclass.mask(
            workclass.isin(missing_values),
            pd.NA
        )

        return workclass

    train_workclass = clean_workclass(train_df)
    test_workclass = clean_workclass(test_df)

    # Hàm lấy mốt
    def get_mode(series):
        valid_data = series.dropna()

        if valid_data.empty:
            return "Không có"

        return valid_data.mode().iloc[0]

    # ==================================================
    # 1. Bảng thống kê tổng quát
    # ==================================================
    summary = pd.DataFrame({
        "Chỉ số": [
            "Số lượng mẫu",
            "Số nhóm hợp lệ",
            "Số dữ liệu thiếu",
            "Tỷ lệ dữ liệu thiếu",
            "Mốt"
        ],
        "Tập huấn luyện": [
            len(train_workclass),
            train_workclass.nunique(dropna=True),
            train_workclass.isna().sum(),
            f"{train_workclass.isna().mean() * 100:.2f}%",
            get_mode(train_workclass)
        ],
        "Tập kiểm thử": [
            len(test_workclass),
            test_workclass.nunique(dropna=True),
            test_workclass.isna().sum(),
            f"{test_workclass.isna().mean() * 100:.2f}%",
            get_mode(test_workclass)
        ]
    })

    print("THỐNG KÊ TỔNG QUÁT THUỘC TÍNH WORKCLASS")
    display(summary)

    # Chuyển dữ liệu thiếu thành một nhóm riêng
    train_display = train_workclass.fillna(missing_label)
    test_display = test_workclass.fillna(missing_label)

    # Tần số
    train_count = train_display.value_counts()
    test_count = test_display.value_counts()

    # Tỷ lệ phần trăm
    train_percent = (
        train_display.value_counts(normalize=True) * 100
    )

    test_percent = (
        test_display.value_counts(normalize=True) * 100
    )

    # Lấy toàn bộ nhóm xuất hiện trong cả hai tập
    all_categories = set(train_count.index).union(
        set(test_count.index)
    )

    # Loại nhóm dữ liệu thiếu khỏi danh sách sắp xếp
    valid_categories = [
        category
        for category in all_categories
        if category != missing_label
    ]

    # Sắp xếp giảm dần theo tỷ lệ trong tập huấn luyện
    valid_categories = sorted(
        valid_categories,
        key=lambda category: (
            train_percent.get(category, 0),
            test_percent.get(category, 0)
        ),
        reverse=True
    )

    # Kiểm tra có dữ liệu thiếu hay không
    has_missing = (
        train_workclass.isna().any()
        or test_workclass.isna().any()
    )

    categories = valid_categories.copy()

    # Đặt nhóm dữ liệu thiếu ở cuối
    if has_missing:
        categories.append(missing_label)

    # ==================================================
    # 2. Bảng phân bố chi tiết
    # ==================================================
    statistics = pd.DataFrame({
        "Nhóm công việc": categories,
        "Số lượng (Huấn luyện)": [
            int(train_count.get(category, 0))
            for category in categories
        ],
        "Tỷ lệ (Huấn luyện) (%)": [
            train_percent.get(category, 0)
            for category in categories
        ],
        "Số lượng (Kiểm thử)": [
            int(test_count.get(category, 0))
            for category in categories
        ],
        "Tỷ lệ (Kiểm thử) (%)": [
            test_percent.get(category, 0)
            for category in categories
        ]
    })

    # Chênh lệch tuyệt đối theo điểm phần trăm
    statistics["Chênh lệch tỷ lệ (điểm %)"] = (
        statistics["Tỷ lệ (Kiểm thử) (%)"]
        - statistics["Tỷ lệ (Huấn luyện) (%)"]
    ).abs()

    percentage_columns = [
        "Tỷ lệ (Huấn luyện) (%)",
        "Tỷ lệ (Kiểm thử) (%)",
        "Chênh lệch tỷ lệ (điểm %)"
    ]

    statistics[percentage_columns] = (
        statistics[percentage_columns].round(2)
    )

    print("PHÂN BỐ CÁC NHÓM WORKCLASS")
    display(statistics)

    # Dùng cùng giới hạn trục Y để dễ so sánh hai biểu đồ
    max_percentage = max(
        statistics["Tỷ lệ (Huấn luyện) (%)"].max(),
        statistics["Tỷ lệ (Kiểm thử) (%)"].max()
    )

    y_limit = max_percentage * 1.15

    if y_limit == 0:
        y_limit = 1

    # ==================================================
    # 3. Hàm vẽ biểu đồ
    # ==================================================
    def ve_bieu_do(percentage_column, title):
        # Cột dữ liệu thiếu màu đỏ, các cột khác màu xanh
        colors = [
            "red" if category == missing_label
            else "tab:blue"
            for category in statistics["Nhóm công việc"]
        ]

        fig, ax = plt.subplots(figsize=(10, 6))

        bars = ax.bar(
            statistics["Nhóm công việc"],
            statistics[percentage_column],
            color=colors,
            width=0.75
        )

        ax.set_title(
            title,
            fontsize=13,
            fontweight="bold"
        )

        ax.set_xlabel(
            "Nhóm công việc",
            fontsize=11
        )

        ax.set_ylabel(
            "Tỷ lệ (%)",
            fontsize=11
        )

        ax.set_ylim(0, y_limit)

        ax.tick_params(
            axis="x",
            rotation=45,
            labelsize=9
        )

        for label in ax.get_xticklabels():
            label.set_horizontalalignment("right")

        ax.grid(
            axis="y",
            linestyle="--",
            alpha=0.4
        )

        ax.set_axisbelow(True)

        # Ghi tỷ lệ bình thường trên tất cả các cột
        for bar, percentage in zip(
            bars,
            statistics[percentage_column]
        ):
            ax.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height() + y_limit * 0.01,
                f"{percentage:.2f}%",
                ha="center",
                va="bottom",
                fontsize=9,
                fontweight="normal"
            )

        # Chú giải màu
        legend_items = [
            Patch(
                facecolor="tab:blue",
                label="Dữ liệu hợp lệ"
            )
        ]

        if has_missing:
            legend_items.append(
                Patch(
                    facecolor="red",
                    label="Dữ liệu thiếu"
                )
            )

        ax.legend(
            handles=legend_items,
            loc="upper right"
        )

        plt.tight_layout()
        plt.show()

    # ==================================================
    # 4. Biểu đồ tập huấn luyện
    # ==================================================
    ve_bieu_do(
        percentage_column="Tỷ lệ (Huấn luyện) (%)",
        title="Phân bố nhóm công việc trong tập huấn luyện"
    )

    # ==================================================
    # 5. Biểu đồ tập kiểm thử
    # ==================================================
    ve_bieu_do(
        percentage_column="Tỷ lệ (Kiểm thử) (%)",
        title="Phân bố nhóm công việc trong tập kiểm thử"
    )

    return summary, statistics

workclass_summary, workclass_statistics = thong_ke_workclass(
    train_df,
    test_df
)
