import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display


def thong_ke_workclass(train_df, test_df):
    """
    Thống kê và trực quan hóa thuộc tính workclass.

    Mỗi nhóm công việc gồm:
    - Cột bên trái: số lượng.
    - Cột bên phải: tỷ lệ (%).

    Dữ liệu thiếu:
    - Bao gồm ?, chuỗi rỗng và NaN.
    - Được đặt ở cuối biểu đồ.
    - Được hiển thị bằng màu đỏ.

    Hàm tạo hai biểu đồ riêng:
    - Tập huấn luyện.
    - Tập kiểm thử.
    """

    column = "workclass"
    missing_label = "Dữ liệu thiếu"

    # Nhãn tiếng Việt dùng để hiển thị
    workclass_labels = {
        "Federal-gov": "Liên bang",
        "State-gov": "Tiểu bang",
        "Local-gov": "Địa phương",
        "Private": "Tư nhân",
        "Self-emp-inc": "Tự doanh có CT",
        "Self-emp-not-inc": "Tự doanh không CT",
        "Without-pay": "Không lương",
        "Never-worked": "Chưa từng làm việc",
        missing_label: missing_label
    }

    # ==================================================
    # 1. Kiểm tra dữ liệu đầu vào
    # ==================================================
    datasets = {
        "tập huấn luyện": train_df,
        "tập kiểm thử": test_df
    }

    for dataset_name, df in datasets.items():
        if column not in df.columns:
            raise KeyError(
                f"Không tìm thấy cột '{column}' "
                f"trong {dataset_name}."
            )

    # ==================================================
    # 2. Làm sạch thuộc tính workclass
    # ==================================================
    def clean_workclass(df):
        workclass = (
            df[column]
            .astype("string")
            .str.strip()
        )

        # Các giá trị được xem là dữ liệu thiếu
        missing_values = [
            "?",
            "",
            "nan",
            "NaN",
            "none",
            "None",
            "<NA>"
        ]

        workclass = workclass.mask(
            workclass.isin(missing_values),
            pd.NA
        )

        return workclass

    train_workclass = clean_workclass(train_df)
    test_workclass = clean_workclass(test_df)

    # Hàm lấy mốt an toàn
    def get_mode(series):
        valid_data = series.dropna()

        if valid_data.empty:
            return "Không có"

        mode_value = valid_data.mode().iloc[0]

        return workclass_labels.get(
            mode_value,
            mode_value
        )

    # ==================================================
    # 3. Bảng thống kê tổng quát
    # ==================================================
    summary = pd.DataFrame({
        "Chỉ số": [
            "Số lượng mẫu",
            "Số nhóm hợp lệ",
            "Số dữ liệu thiếu",
            "Tỷ lệ dữ liệu thiếu",
            "Mốt"
        ],
        "Tập huấn luyện": [
            len(train_workclass),
            train_workclass.nunique(dropna=True),
            int(train_workclass.isna().sum()),
            f"{train_workclass.isna().mean() * 100:.2f}%",
            get_mode(train_workclass)
        ],
        "Tập kiểm thử": [
            len(test_workclass),
            test_workclass.nunique(dropna=True),
            int(test_workclass.isna().sum()),
            f"{test_workclass.isna().mean() * 100:.2f}%",
            get_mode(test_workclass)
        ]
    })

    print("THỐNG KÊ TỔNG QUÁT THUỘC TÍNH WORKCLASS")
    display(summary)

    # ==================================================
    # 4. Tính số lượng và tỷ lệ của từng nhóm
    # ==================================================
    train_display = train_workclass.fillna(missing_label)
    test_display = test_workclass.fillna(missing_label)

    # Số lượng
    train_count = train_display.value_counts()
    test_count = test_display.value_counts()

    # Tỷ lệ phần trăm
    train_percent = (
        train_display.value_counts(normalize=True) * 100
    )

    test_percent = (
        test_display.value_counts(normalize=True) * 100
    )

    # Lấy tất cả nhóm xuất hiện trong hai tập
    all_categories = set(train_count.index).union(
        set(test_count.index)
    )

    # Không đưa dữ liệu thiếu vào phần sắp xếp
    valid_categories = [
        category
        for category in all_categories
        if category != missing_label
    ]

    # Sắp xếp giảm dần theo tỷ lệ của tập huấn luyện
    valid_categories = sorted(
        valid_categories,
        key=lambda category: (
            train_percent.get(category, 0),
            test_percent.get(category, 0)
        ),
        reverse=True
    )

    # Chỉ thêm cột dữ liệu thiếu khi thực sự có dữ liệu thiếu
    has_missing = (
        train_workclass.isna().any()
        or test_workclass.isna().any()
    )

    categories = valid_categories.copy()

    if has_missing:
        categories.append(missing_label)

    # ==================================================
    # 5. Bảng phân bố chi tiết
    # ==================================================
    statistics = pd.DataFrame({
        "Nhóm gốc": categories,
        "Nhóm công việc": [
            workclass_labels.get(category, category)
            for category in categories
        ],
        "Số lượng (Huấn luyện)": [
            int(train_count.get(category, 0))
            for category in categories
        ],
        "Tỷ lệ (Huấn luyện) (%)": [
            train_percent.get(category, 0)
            for category in categories
        ],
        "Số lượng (Kiểm thử)": [
            int(test_count.get(category, 0))
            for category in categories
        ],
        "Tỷ lệ (Kiểm thử) (%)": [
            test_percent.get(category, 0)
            for category in categories
        ]
    })

    # Chênh lệch tỷ lệ giữa hai tập
    statistics["Chênh lệch (điểm %)"] = (
        statistics["Tỷ lệ (Kiểm thử) (%)"]
        - statistics["Tỷ lệ (Huấn luyện) (%)"]
    ).abs()

    percentage_columns = [
        "Tỷ lệ (Huấn luyện) (%)",
        "Tỷ lệ (Kiểm thử) (%)",
        "Chênh lệch (điểm %)"
    ]

    statistics[percentage_columns] = (
        statistics[percentage_columns].round(2)
    )

    print("PHÂN BỐ CÁC NHÓM WORKCLASS")

    display(
        statistics.drop(columns=["Nhóm gốc"])
    )

    # ==================================================
    # 6. Hàm vẽ biểu đồ
    # ==================================================
    def ve_bieu_do(
        count_column,
        percentage_column,
        title
    ):
        labels = statistics["Nhóm công việc"].tolist()
        original_categories = statistics["Nhóm gốc"].tolist()

        counts = statistics[count_column].to_numpy(
            dtype=float
        )

        percentages = statistics[
            percentage_column
        ].to_numpy(dtype=float)

        x = np.arange(len(labels))
        bar_width = 0.36

        # Trục trái biểu diễn số lượng
        fig, ax_count = plt.subplots(
            figsize=(12, 6)
        )

        # Trục phải biểu diễn tỷ lệ
        ax_percent = ax_count.twinx()

        # Màu cột số lượng
        count_colors = [
            "red"
            if category == missing_label
            else "tab:blue"
            for category in original_categories
        ]

        # Màu cột tỷ lệ
        percent_colors = [
            "red"
            if category == missing_label
            else "tab:orange"
            for category in original_categories
        ]

        # Cột số lượng nằm bên trái
        count_bars = ax_count.bar(
            x - bar_width / 2,
            counts,
            width=bar_width,
            color=count_colors,
            alpha=0.85
        )

        # Cột tỷ lệ nằm bên phải
        percent_bars = ax_percent.bar(
            x + bar_width / 2,
            percentages,
            width=bar_width,
            color=percent_colors,
            alpha=0.85
        )

        # Tiêu đề
        ax_count.set_title(
            title,
            fontsize=13,
            fontweight="bold",
            pad=15
        )

        # Nhãn các trục
        ax_count.set_xlabel(
            "Nhóm công việc "
            "(cột trái: số lượng; cột phải: tỷ lệ)",
            fontsize=11
        )

        ax_count.set_ylabel(
            "Số lượng",
            fontsize=11
        )

        ax_percent.set_ylabel(
            "Tỷ lệ (%)",
            fontsize=11
        )

        # Nhãn trục X
        ax_count.set_xticks(x)

        ax_count.set_xticklabels(
            labels,
            rotation=45,
            ha="right",
            fontsize=9
        )

        # Giới hạn trục
        max_count = counts.max() if len(counts) else 1
        max_percent = (
            percentages.max()
            if len(percentages)
            else 1
        )

        if max_count == 0:
            max_count = 1

        if max_percent == 0:
            max_percent = 1

        ax_count.set_ylim(
            0,
            max_count * 1.18
        )

        ax_percent.set_ylim(
            0,
            max_percent * 1.18
        )

        # Lưới ngang theo trục số lượng
        ax_count.grid(
            axis="y",
            linestyle="--",
            alpha=0.35
        )

        ax_count.set_axisbelow(True)

        # Ghi số lượng trên các cột bên trái
        for bar, value in zip(
            count_bars,
            counts
        ):
            ax_count.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height() + max_count * 0.012,
                f"{int(value):,}",
                ha="center",
                va="bottom",
                fontsize=8,
                fontweight="normal"
            )

        # Ghi tỷ lệ trên các cột bên phải
        for bar, value in zip(
            percent_bars,
            percentages
        ):
            ax_percent.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height() + max_percent * 0.012,
                f"{value:.2f}%",
                ha="center",
                va="bottom",
                fontsize=8,
                fontweight="normal"
            )

        # Không hiển thị chú giải
        plt.tight_layout()
        plt.show()

    # ==================================================
    # 7. Biểu đồ tập huấn luyện
    # ==================================================
    ve_bieu_do(
        count_column="Số lượng (Huấn luyện)",
        percentage_column="Tỷ lệ (Huấn luyện) (%)",
        title=(
            "Phân bố nhóm công việc "
            "trong tập huấn luyện"
        )
    )

    # ==================================================
    # 8. Biểu đồ tập kiểm thử
    # ==================================================
    ve_bieu_do(
        count_column="Số lượng (Kiểm thử)",
        percentage_column="Tỷ lệ (Kiểm thử) (%)",
        title=(
            "Phân bố nhóm công việc "
            "trong tập kiểm thử"
        )
    )

    return summary, statistics
