import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display


def thong_ke_workclass(train_df, test_df):
    """
    Thống kê và vẽ phân bố thuộc tính workclass.

    Đặc điểm biểu đồ:
    - Tập huấn luyện và tập kiểm thử được vẽ riêng.
    - Mỗi nhóm công việc được biểu diễn bằng một cột.
    - Trên cột hiển thị:
          Số lượng
          Tỷ lệ %
    - Nhóm dữ liệu thiếu nằm cuối và có màu đỏ.
    - Không hiển thị chú giải.
    """

    column = "workclass"
    missing_label = "Dữ liệu thiếu"

    # Nhãn tiếng Việt dùng trong bảng và biểu đồ
    workclass_labels = {
        "Federal-gov": "Liên bang",
        "State-gov": "Tiểu bang",
        "Local-gov": "Địa phương",
        "Private": "Tư nhân",
        "Self-emp-inc": "Tự doanh có CT",
        "Self-emp-not-inc": "Tự doanh không CT",
        "Without-pay": "Không lương",
        "Never-worked": "Chưa từng làm việc",
        missing_label: missing_label
    }

    # ==================================================
    # 1. Kiểm tra dữ liệu đầu vào
    # ==================================================
    for dataset_name, df in {
        "tập huấn luyện": train_df,
        "tập kiểm thử": test_df
    }.items():
        if column not in df.columns:
            raise KeyError(
                f"Không tìm thấy cột '{column}' trong {dataset_name}."
            )

    # ==================================================
    # 2. Làm sạch dữ liệu workclass
    # ==================================================
    def clean_workclass(df):
        data = (
            df[column]
            .astype("string")
            .str.strip()
        )

        missing_mask = (
            data.isna()
            | data.str.lower().isin([
                "?",
                "",
                "nan",
                "none",
                "<na>"
            ])
        )

        return data.mask(missing_mask, pd.NA)

    train_workclass = clean_workclass(train_df)
    test_workclass = clean_workclass(test_df)

    # Hàm lấy mốt
    def get_mode(series):
        valid_data = series.dropna()

        if valid_data.empty:
            return "Không có"

        mode_value = valid_data.mode().iloc[0]

        return workclass_labels.get(
            mode_value,
            mode_value
        )

    # ==================================================
    # 3. Bảng thống kê tổng quát
    # ==================================================
    summary = pd.DataFrame({
        "Chỉ số": [
            "Số lượng mẫu",
            "Số nhóm hợp lệ",
            "Số dữ liệu thiếu",
            "Tỷ lệ dữ liệu thiếu",
            "Mốt"
        ],
        "Tập huấn luyện": [
            len(train_workclass),
            train_workclass.nunique(dropna=True),
            int(train_workclass.isna().sum()),
            f"{train_workclass.isna().mean() * 100:.2f}%",
            get_mode(train_workclass)
        ],
        "Tập kiểm thử": [
            len(test_workclass),
            test_workclass.nunique(dropna=True),
            int(test_workclass.isna().sum()),
            f"{test_workclass.isna().mean() * 100:.2f}%",
            get_mode(test_workclass)
        ]
    })

    print("THỐNG KÊ TỔNG QUÁT THUỘC TÍNH WORKCLASS")
    display(summary)

    # ==================================================
    # 4. Tính số lượng và tỷ lệ
    # ==================================================
    train_display = train_workclass.fillna(missing_label)
    test_display = test_workclass.fillna(missing_label)

    train_count = train_display.value_counts()
    test_count = test_display.value_counts()

    train_percent = (
        train_display.value_counts(normalize=True) * 100
    )

    test_percent = (
        test_display.value_counts(normalize=True) * 100
    )

    # Lấy toàn bộ nhóm hợp lệ xuất hiện trong hai tập
    all_categories = set(train_count.index).union(
        set(test_count.index)
    )

    valid_categories = [
        category
        for category in all_categories
        if category != missing_label
    ]

    # Sắp xếp theo tỷ lệ giảm dần trong tập huấn luyện
    valid_categories = sorted(
        valid_categories,
        key=lambda category: (
            train_percent.get(category, 0),
            test_percent.get(category, 0)
        ),
        reverse=True
    )

    # Danh sách dùng cho bảng thống kê
    table_categories = valid_categories.copy()

    if (
        train_workclass.isna().any()
        or test_workclass.isna().any()
    ):
        table_categories.append(missing_label)

    # ==================================================
    # 5. Bảng phân bố chi tiết
    # ==================================================
    statistics = pd.DataFrame({
        "Nhóm công việc": [
            workclass_labels.get(category, category)
            for category in table_categories
        ],
        "Số lượng (Huấn luyện)": [
            int(train_count.get(category, 0))
            for category in table_categories
        ],
        "Tỷ lệ (Huấn luyện) (%)": [
            train_percent.get(category, 0)
            for category in table_categories
        ],
        "Số lượng (Kiểm thử)": [
            int(test_count.get(category, 0))
            for category in table_categories
        ],
        "Tỷ lệ (Kiểm thử) (%)": [
            test_percent.get(category, 0)
            for category in table_categories
        ]
    })

    statistics["Chênh lệch (điểm %)"] = (
        statistics["Tỷ lệ (Kiểm thử) (%)"]
        - statistics["Tỷ lệ (Huấn luyện) (%)"]
    ).abs()

    percentage_columns = [
        "Tỷ lệ (Huấn luyện) (%)",
        "Tỷ lệ (Kiểm thử) (%)",
        "Chênh lệch (điểm %)"
    ]

    statistics[percentage_columns] = (
        statistics[percentage_columns].round(2)
    )

    print("PHÂN BỐ CÁC NHÓM WORKCLASS")
    display(statistics)

    # ==================================================
    # 6. Hàm định dạng số theo kiểu Việt Nam
    # ==================================================
    def format_integer(value):
        return f"{int(value):,}".replace(",", ".")

    def format_percentage(value):
        return f"{value:.2f}".replace(".", ",")

    # ==================================================
    # 7. Hàm vẽ một biểu đồ
    # ==================================================
    def ve_bieu_do(
        data_series,
        title
    ):
        counts = data_series.value_counts()

        # Các nhóm hợp lệ giữ cùng thứ tự
        chart_categories = [
            category
            for category in valid_categories
            if counts.get(category, 0) > 0
        ]

        # Chỉ thêm cột dữ liệu thiếu khi tập hiện tại có thiếu
        if counts.get(missing_label, 0) > 0:
            chart_categories.append(missing_label)

        labels = [
            workclass_labels.get(category, category)
            for category in chart_categories
        ]

        values = np.array([
            int(counts.get(category, 0))
            for category in chart_categories
        ])

        total = int(values.sum())

        percentages = (
            values / total * 100
            if total > 0
            else np.zeros(len(values))
        )

        colors = [
            "red"
            if category == missing_label
            else "tab:blue"
            for category in chart_categories
        ]

        x = np.arange(len(labels))

        fig, ax = plt.subplots(figsize=(12, 6))

        bars = ax.bar(
            x,
            values,
            width=0.7,
            color=colors
        )

        ax.set_title(
            title,
            fontsize=13,
            fontweight="bold",
            pad=15
        )

        ax.set_xlabel(
            "Nhóm công việc",
            fontsize=11
        )

        ax.set_ylabel(
            "Số lượng mẫu",
            fontsize=11
        )

        ax.set_xticks(x)

        ax.set_xticklabels(
            labels,
            rotation=45,
            ha="right",
            fontsize=9
        )

        max_count = values.max() if len(values) > 0 else 1

        if max_count == 0:
            max_count = 1

        # Tạo khoảng trống để ghi số liệu trên cột
        ax.set_ylim(0, max_count * 1.20)

        ax.grid(
            axis="y",
            linestyle="--",
            alpha=0.35
        )

        ax.set_axisbelow(True)

        # Ghi số lượng và tỷ lệ trên từng cột
        for bar, count, percentage in zip(
            bars,
            values,
            percentages
        ):
            count_text = format_integer(count)
            percent_text = format_percentage(percentage)

            ax.text(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height() + max_count * 0.012,
                f"{count_text}\n{percent_text}%",
                ha="center",
                va="bottom",
                fontsize=8,
                fontweight="normal"
            )

        # Không hiển thị legend
        plt.tight_layout()
        plt.show()

    # ==================================================
    # 8. Biểu đồ tập huấn luyện
    # ==================================================
    ve_bieu_do(
        data_series=train_display,
        title="Phân bố nhóm công việc trong tập huấn luyện"
    )

    # ==================================================
    # 9. Biểu đồ tập kiểm thử
    # ==================================================
    ve_bieu_do(
        data_series=test_display,
        title="Phân bố nhóm công việc trong tập kiểm thử"
    )

    return summary, statistics
