import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display


def thong_ke_va_ve_tuoi(df, title="Phân bố độ tuổi"):
    # Chuẩn hóa cột tuổi và loại bỏ giá trị thiếu
    age = pd.to_numeric(
        df["age"],
        errors="coerce"
    ).dropna()

    if age.empty:
        raise ValueError("Cột age không có dữ liệu hợp lệ.")

    # Đo lường xu hướng tập trung
    mean_age = age.mean()
    median_age = age.median()
    mode_age = age.mode().astype(int).tolist()

    # Đo lường độ phân tán
    min_age = age.min()
    max_age = age.max()
    age_range = max_age - min_age
    std_age = age.std()

    # Tứ phân vị
    q1 = age.quantile(0.25)
    q2 = age.quantile(0.50)
    q3 = age.quantile(0.75)
    iqr = q3 - q1

    # Ngưỡng ngoại biên theo quy tắc IQR
    lower_bound = q1 - 1.5 * iqr
    upper_bound = q3 + 1.5 * iqr

    outliers = age[
        (age < lower_bound) |
        (age > upper_bound)
    ]

    outlier_ages = sorted(
        outliers.astype(int).unique()
    )

    outlier_rate = (
        outliers.count() / age.count() * 100
    )

    # Một bảng thống kê duy nhất
    statistics = pd.DataFrame({
        "Chỉ số": [
            "Số lượng",
            "Trung bình",
            "Trung vị",
            "Yếu vị",
            "Nhỏ nhất",
            "Lớn nhất",
            "Khoảng biến thiên",
            "Tứ phân vị Q1",
            "Tứ phân vị Q2",
            "Tứ phân vị Q3",
            "Khoảng tứ phân vị IQR",
            "Độ lệch chuẩn",
            "Ngưỡng ngoại biên dưới",
            "Ngưỡng ngoại biên trên",
            "Số điểm ngoại biên",
            "Tỷ lệ ngoại biên",
            "Các độ tuổi ngoại biên"
        ],
        "Giá trị": [
            f"{age.count():,}",
            f"{mean_age:.2f}",
            f"{median_age:.2f}",
            ", ".join(map(str, mode_age)),
            f"{min_age:.0f}",
            f"{max_age:.0f}",
            f"{age_range:.0f}",
            f"{q1:.2f}",
            f"{q2:.2f}",
            f"{q3:.2f}",
            f"{iqr:.2f}",
            f"{std_age:.2f}",
            f"{lower_bound:.2f}",
            f"{upper_bound:.2f}",
            f"{outliers.count():,}",
            f"{outlier_rate:.2f}%",
            ", ".join(map(str, outlier_ages))
        ]
    })

    print("MÔ TẢ THỐNG KÊ CƠ BẢN VỀ ĐỘ TUỔI")
    display(statistics)

    # Đếm số người theo từng tuổi, không gom nhóm
    age_counts = age.value_counts().sort_index()

    # Vẽ biểu đồ không có đường chú thích
    plt.figure(figsize=(12, 7))

    plt.bar(
        age_counts.index,
        age_counts.values,
        width=0.8
    )

    plt.title(title, fontsize=14)
    plt.xlabel("Độ tuổi")
    plt.ylabel("Số người")

    # Hiển thị từng tuổi liên tiếp
    plt.xticks(
        range(int(min_age), int(max_age) + 1),
        rotation=90
    )

    plt.grid(
        axis="y",
        linestyle="--",
        alpha=0.4
    )

    plt.tight_layout()
    plt.show()

    return statistics, outliers
