from IPython.display import display
import pandas as pd


def kiem_tra_ngoai_bien_test(
    train_df,
    test_df,
    column="age"
):
    train_data = pd.to_numeric(
        train_df[column],
        errors="coerce"
    ).dropna()

    test_data = pd.to_numeric(
        test_df[column],
        errors="coerce"
    ).dropna()

    # Tính ngưỡng từ tập huấn luyện
    q1_train = train_data.quantile(0.25)
    q3_train = train_data.quantile(0.75)
    iqr_train = q3_train - q1_train

    lower_bound = q1_train - 1.5 * iqr_train
    upper_bound = q3_train + 1.5 * iqr_train

    # Áp dụng ngưỡng huấn luyện lên tập kiểm thử
    test_outliers = test_data[
        (test_data < lower_bound) |
        (test_data > upper_bound)
    ]

    outlier_values = sorted(
        test_outliers.astype(int).unique()
    )

    outlier_rate = (
        len(test_outliers) / len(test_data) * 100
    )

    report = pd.DataFrame({
        "Chỉ số": [
            "Số mẫu kiểm thử",
            "Q1 của tập huấn luyện",
            "Q3 của tập huấn luyện",
            "IQR của tập huấn luyện",
            "Ngưỡng ngoại biên dưới",
            "Ngưỡng ngoại biên trên",
            "Số ngoại biên trong tập kiểm thử",
            "Tỷ lệ ngoại biên",
            "Các độ tuổi ngoại biên"
        ],
        "Giá trị": [
            f"{len(test_data):,}",
            f"{q1_train:.2f}",
            f"{q3_train:.2f}",
            f"{iqr_train:.2f}",
            f"{lower_bound:.2f}",
            f"{upper_bound:.2f}",
            f"{len(test_outliers):,}",
            f"{outlier_rate:.2f}%",
            ", ".join(map(str, outlier_values))
        ]
    })

    print("KIỂM TRA NGOẠI BIÊN TRONG TẬP KIỂM THỬ")
    display(report)

    return report, test_outliers

test_outlier_report, test_outliers = kiem_tra_ngoai_bien_test(
    train_df,
    test_df,
    column="age"
)
