import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.ticker import FuncFormatter


def ve_bieu_do_workclass(
    df,
    title,
    column="workclass"
):
    """
    Vẽ phân bố workclass:
    - Một cột cho mỗi nhóm.
    - Trục trái: số lượng mẫu.
    - Trục phải: tỷ lệ (%).
    - Trên cột hiển thị số lượng và tỷ lệ.
    - Dữ liệu thiếu nằm cuối và có màu đỏ.
    - Không hiển thị legend.
    """

    if column not in df.columns:
        raise KeyError(
            f"Không tìm thấy cột '{column}' trong DataFrame."
        )

    missing_label = "Dữ liệu thiếu"

    # Nhãn tiếng Việt
    workclass_labels = {
        "Federal-gov": "Liên bang",
        "State-gov": "Tiểu bang",
        "Local-gov": "Địa phương",
        "Private": "Tư nhân",
        "Self-emp-inc": "Tự doanh có CT",
        "Self-emp-not-inc": "Tự doanh không CT",
        "Without-pay": "Không lương",
        "Never-worked": "Chưa từng làm việc",
        missing_label: missing_label
    }

    # Làm sạch dữ liệu
    workclass = (
        df[column]
        .astype("string")
        .str.strip()
    )

    missing_mask = (
        workclass.isna()
        | workclass.str.lower().isin([
            "?",
            "",
            "nan",
            "none",
            "<na>"
        ])
    )

    workclass = workclass.mask(
        missing_mask,
        missing_label
    )

    # Đếm số lượng từng nhóm
    counts = workclass.value_counts()

    # Tách dữ liệu hợp lệ và dữ liệu thiếu
    valid_counts = counts.drop(
        labels=[missing_label],
        errors="ignore"
    ).sort_values(ascending=False)

    # Luôn đặt dữ liệu thiếu ở cuối
    if missing_label in counts.index:
        counts = pd.concat([
            valid_counts,
            pd.Series({
                missing_label: counts[missing_label]
            })
        ])
    else:
        counts = valid_counts

    categories = counts.index.tolist()
    values = counts.to_numpy(dtype=int)
    total = len(workclass)

    percentages = values / total * 100

    labels = [
        workclass_labels.get(category, category)
        for category in categories
    ]

    # Cột dữ liệu thiếu màu đỏ
    colors = [
        "red" if category == missing_label
        else "tab:blue"
        for category in categories
    ]

    x = np.arange(len(categories))

    # Tạo biểu đồ
    fig, ax_count = plt.subplots(
        figsize=(12, 6)
    )

    bars = ax_count.bar(
        x,
        values,
        width=0.7,
        color=colors
    )

    # Tiêu đề và trục X
    ax_count.set_title(
        title,
        fontsize=13,
        fontweight="bold",
        pad=15
    )

    ax_count.set_xlabel(
        "Nhóm công việc",
        fontsize=11
    )

    ax_count.set_xticks(x)

    ax_count.set_xticklabels(
        labels,
        rotation=45,
        ha="right",
        fontsize=9
    )

    # Trục Y bên trái: số lượng
    ax_count.set_ylabel(
        "Số lượng mẫu",
        fontsize=11
    )

    max_count = values.max() if len(values) > 0 else 1
    count_limit = max_count * 1.22

    ax_count.set_ylim(
        0,
        count_limit
    )

    ax_count.yaxis.set_major_formatter(
        FuncFormatter(
            lambda value, position:
            f"{int(value):,}".replace(",", ".")
        )
    )

    ax_count.grid(
        axis="y",
        linestyle="--",
        alpha=0.35
    )

    ax_count.set_axisbelow(True)

    # Trục Y bên phải: tỷ lệ phần trăm
    ax_percent = ax_count.twinx()

    percent_limit = count_limit / total * 100

    ax_percent.set_ylim(
        0,
        percent_limit
    )

    ax_percent.set_ylabel(
        "Tỷ lệ (%)",
        fontsize=11,
        labelpad=12
    )

    ax_percent.yaxis.set_major_formatter(
        FuncFormatter(
            lambda value, position:
            f"{value:.0f}%"
        )
    )

    ax_percent.tick_params(
        axis="y",
        right=True,
        labelright=True
    )

    ax_percent.spines[
        "right"
    ].set_visible(True)

    # Ghi số lượng và tỷ lệ trên đầu cột
    for bar, count, percentage in zip(
        bars,
        values,
        percentages
    ):
        count_text = (
            f"{count:,}"
            .replace(",", ".")
        )

        percentage_text = (
            f"{percentage:.2f}"
            .replace(".", ",")
        )

        ax_count.text(
            bar.get_x() + bar.get_width() / 2,
            bar.get_height() + max_count * 0.012,
            f"{count_text}\n{percentage_text}%",
            ha="center",
            va="bottom",
            fontsize=8
        )

    # Chừa không gian cho trục bên phải
    fig.subplots_adjust(
        left=0.08,
        right=0.90,
        bottom=0.25,
        top=0.88
    )

    plt.show()

    # Trả về bảng thống kê
    statistics = pd.DataFrame({
        "Nhóm công việc": labels,
        "Số lượng": values,
        "Tỷ lệ (%)": percentages.round(2)
    })

    return statistics
