    age_counts = age.value_counts().sort_index()

    plt.figure(figsize=(12, 7))

    plt.bar(
        age_counts.index,
        age_counts.values,
        width=0.8,
        color=color
    )

    plt.title(title, fontsize=14)
    plt.xlabel("Độ tuổi")
    plt.ylabel("Số người")

    plt.xticks(
        range(int(min_age), int(max_age) + 1),
        rotation=90
    )

    plt.grid(
        axis="y",
        linestyle="--",
        alpha=0.4
    )

    plt.tight_layout()
    plt.show()

    return statistics, outliers
