import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display


def lay_du_lieu_tuoi(df):
    """Chuyển cột age sang số và loại bỏ giá trị thiếu."""
    age = pd.to_numeric(df["age"], errors="coerce").dropna()

    if age.empty:
        raise ValueError("Cột age không có dữ liệu hợp lệ.")

    return age


def tinh_thong_ke_tuoi(age):
    """Tính các chỉ số thống kê và xác định ngoại biên."""
    q1 = age.quantile(0.25)
    q2 = age.quantile(0.50)
    q3 = age.quantile(0.75)
    iqr = q3 - q1

    lower_bound = q1 - 1.5 * iqr
    upper_bound = q3 + 1.5 * iqr

    outliers = age[
        (age < lower_bound) |
        (age > upper_bound)
    ]

    mode_age = age.mode().tolist()
    outlier_ages = sorted(outliers.unique())

    statistics = pd.DataFrame({
        "Chỉ số": [
            "Số lượng",
            "Trung bình",
            "Trung vị",
            "Mốt",
            "Nhỏ nhất",
            "Lớn nhất",
            "Khoảng biến thiên",
            "Tứ phân vị Q1",
            "Tứ phân vị Q2",
            "Tứ phân vị Q3",
            "Khoảng tứ phân vị IQR",
            "Độ lệch chuẩn",
            "Ngưỡng ngoại biên dưới",
            "Ngưỡng ngoại biên trên",
            "Số điểm ngoại biên",
            "Tỷ lệ ngoại biên",
            "Các độ tuổi ngoại biên"
        ],
        "Giá trị": [
            f"{age.count():,}",
            f"{age.mean():.2f}",
            f"{age.median():.2f}",
            ", ".join(f"{x:g}" for x in mode_age),
            f"{age.min():.0f}",
            f"{age.max():.0f}",
            f"{age.max() - age.min():.0f}",
            f"{q1:.2f}",
            f"{q2:.2f}",
            f"{q3:.2f}",
            f"{iqr:.2f}",
            f"{age.std():.2f}",
            f"{lower_bound:.2f}",
            f"{upper_bound:.2f}",
            f"{outliers.count():,}",
            f"{outliers.count() / age.count() * 100:.2f}%",
            ", ".join(f"{x:g}" for x in outlier_ages)
        ]
    })

    return statistics, outliers


def hien_thi_thong_ke_tuoi(statistics):
    """Hiển thị bảng thống kê."""
    print("MÔ TẢ THỐNG KÊ CƠ BẢN VỀ ĐỘ TUỔI")
    display(statistics)


def ve_phan_bo_tuoi(
    age,
    title="Phân bố độ tuổi",
    color="steelblue"
):
    """Vẽ biểu đồ tần suất theo từng độ tuổi."""
    age_counts = age.value_counts().sort_index()

    min_age = int(age.min())
    max_age = int(age.max())

    plt.figure(figsize=(12, 7))

    plt.bar(
        age_counts.index,
        age_counts.values,
        width=0.8,
        color=color
    )

    plt.title(title, fontsize=14)
    plt.xlabel("Độ tuổi")
    plt.ylabel("Số người")

    plt.xticks(
        range(min_age, max_age + 1),
        rotation=90
    )

    plt.grid(
        axis="y",
        linestyle="--",
        alpha=0.4
    )

    plt.tight_layout()
    plt.show()


def thong_ke_va_ve_tuoi(
    df,
    title="Phân bố độ tuổi",
    color="steelblue"
):
    """Hàm tổng hợp để chạy toàn bộ quy trình."""
    age = lay_du_lieu_tuoi(df)
    statistics, outliers = tinh_thong_ke_tuoi(age)

    hien_thi_thong_ke_tuoi(statistics)
    ve_phan_bo_tuoi(age, title, color)

    return statistics, outliers
