import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.ticker import FuncFormatter
from IPython.display import display


def ve_bieu_do_workclass(
    df,
    title,
    column="workclass",
    bar_color="tab:blue",
    missing_color="red"
):
    """
    Thống kê và vẽ phân bố thuộc tính workclass.

    Tham số:
    - df: DataFrame cần phân tích.
    - title: Tiêu đề biểu đồ.
    - column: Tên thuộc tính, mặc định là workclass.
    - bar_color: Màu của các nhóm dữ liệu hợp lệ.
    - missing_color: Màu của nhóm dữ liệu thiếu.

    Kết quả:
    - Bảng thống kê tổng quát.
    - Bảng phân bố chi tiết từng nhóm.
    - Biểu đồ cột:
        + Trục trái: số người.
        + Trục phải: tỷ lệ (%).
        + Dữ liệu thiếu nằm cuối biểu đồ.
        + Trên mỗi cột hiển thị số lượng và tỷ lệ.
    """

    # ==================================================
    # 1. Kiểm tra dữ liệu đầu vào
    # ==================================================
    if column not in df.columns:
        raise KeyError(
            f"Không tìm thấy cột '{column}' trong DataFrame."
        )

    missing_label = "Dữ liệu thiếu"

    # Nhãn tiếng Việt
    workclass_labels = {
        "Federal-gov": "Liên bang",
        "State-gov": "Tiểu bang",
        "Local-gov": "Địa phương",
        "Private": "Tư nhân",
        "Self-emp-inc": "Tự doanh có công ty",
        "Self-emp-not-inc": "Tự doanh không công ty",
        "Without-pay": "Không lương",
        "Never-worked": "Chưa từng làm việc",
        missing_label: missing_label
    }

    # ==================================================
    # 2. Làm sạch dữ liệu
    # ==================================================
    workclass = (
        df[column]
        .astype("string")
        .str.strip()
    )

    missing_mask = (
        workclass.isna()
        | workclass.str.lower().isin([
            "?",
            "",
            "nan",
            "none",
            "<na>"
        ])
    )

    total = len(workclass)
    missing_count = int(missing_mask.sum())
    valid_count = total - missing_count

    # Thay dữ liệu thiếu bằng nhãn riêng
    workclass = workclass.mask(
        missing_mask,
        missing_label
    )

    # Chỉ lấy dữ liệu hợp lệ
    valid_workclass = workclass[
        workclass != missing_label
    ]

    # ==================================================
    # 3. Thống kê tổng quát
    # ==================================================
    number_of_categories = valid_workclass.nunique()

    if not valid_workclass.empty:
        mode_original = valid_workclass.mode().iloc[0]

        mode_label = workclass_labels.get(
            mode_original,
            mode_original
        )

        mode_count = int(
            (valid_workclass == mode_original).sum()
        )

        mode_percentage = (
            mode_count / total * 100
            if total > 0
            else 0
        )
    else:
        mode_label = "Không có"
        mode_count = 0
        mode_percentage = 0

    missing_percentage = (
        missing_count / total * 100
        if total > 0
        else 0
    )

    summary = pd.DataFrame({
        "Chỉ số": [
            "Số lượng mẫu",
            "Số giá trị hợp lệ",
            "Số dữ liệu thiếu",
            "Tỷ lệ dữ liệu thiếu",
            "Số nhóm hợp lệ",
            "Mốt",
            "Tần số của mốt",
            "Tỷ lệ của mốt"
        ],
        "Giá trị": [
            f"{total:,}".replace(",", "."),
            f"{valid_count:,}".replace(",", "."),
            f"{missing_count:,}".replace(",", "."),
            f"{missing_percentage:.2f}%".replace(".", ","),
            number_of_categories,
            mode_label,
            f"{mode_count:,}".replace(",", "."),
            f"{mode_percentage:.2f}%".replace(".", ",")
        ]
    })

    print("MÔ TẢ THỐNG KÊ CƠ BẢN THUỘC TÍNH WORKCLASS")
    display(summary)

    # ==================================================
    # 4. Thống kê chi tiết từng nhóm
    # ==================================================
    counts = workclass.value_counts()

    # Sắp xếp nhóm hợp lệ theo số lượng giảm dần
    valid_counts = counts.drop(
        labels=[missing_label],
        errors="ignore"
    ).sort_values(ascending=False)

    # Đặt dữ liệu thiếu ở cuối
    if missing_label in counts.index:
        missing_series = pd.Series(
            {missing_label: counts[missing_label]},
            dtype=counts.dtype
        )

        counts = pd.concat([
            valid_counts,
            missing_series
        ])
    else:
        counts = valid_counts

    categories = counts.index.tolist()
    values = counts.to_numpy(dtype=int)

    percentages = (
        values / total * 100
        if total > 0
        else np.zeros(len(values))
    )

    labels = [
        workclass_labels.get(category, category)
        for category in categories
    ]

    statistics = pd.DataFrame({
        "Nhóm công việc": labels,
        "Số người": values,
        "Tỷ lệ (%)": percentages.round(2)
    })

    print("PHÂN BỐ CHI TIẾT THUỘC TÍNH WORKCLASS")
    display(statistics)

    # ==================================================
    # 5. Xác định màu cho từng cột
    # ==================================================
    colors = [
        missing_color
        if category == missing_label
        else bar_color
        for category in categories
    ]

    x = np.arange(len(categories))

    # ==================================================
    # 6. Tạo biểu đồ
    # ==================================================
    fig, ax_count = plt.subplots(
        figsize=(12, 5)
    )

    bars = ax_count.bar(
        x,
        values,
        width=0.7,
        color=colors
    )

    # Tiêu đề và trục X
    ax_count.set_title(
        title,
        fontsize=13
    )

    ax_count.set_xlabel(
        "Nhóm công việc",
        fontsize=11
    )

    ax_count.set_xticks(x)

    ax_count.set_xticklabels(
        labels,
        rotation=45,
        ha="right",
        fontsize=9
    )

    # ==================================================
    # 7. Trục Y bên trái: số người
    # ==================================================
    ax_count.set_ylabel(
        "Số người",
        fontsize=11
    )

    max_count = (
        values.max()
        if len(values) > 0
        else 1
    )

    if max_count == 0:
        max_count = 1

    count_limit = max_count * 1.22

    ax_count.set_ylim(
        0,
        count_limit
    )

    ax_count.yaxis.set_major_formatter(
        FuncFormatter(
            lambda value, position:
            f"{int(value):,}".replace(",", ".")
        )
    )

    ax_count.grid(
        axis="y",
        linestyle="--",
        alpha=0.35
    )

    ax_count.set_axisbelow(True)

    # ==================================================
    # 8. Trục Y bên phải: tỷ lệ phần trăm
    # ==================================================
    ax_percent = ax_count.twinx()

    percent_limit = (
        count_limit / total * 100
        if total > 0
        else 100
    )

    ax_percent.set_ylim(
        0,
        percent_limit
    )

    ax_percent.set_ylabel(
        "Tỷ lệ (%)",
        fontsize=11,
        labelpad=12
    )

    ax_percent.yaxis.set_major_formatter(
        FuncFormatter(
            lambda value, position:
            f"{value:.0f}%"
        )
    )

    ax_percent.tick_params(
        axis="y",
        right=True,
        labelright=True
    )

    ax_percent.spines[
        "right"
    ].set_visible(True)

    # ==================================================
    # 9. Ghi số lượng và tỷ lệ trên đầu cột
    # ==================================================
    for bar, count, percentage in zip(
        bars,
        values,
        percentages
    ):
        count_text = (
            f"{count:,}"
            .replace(",", ".")
        )

        percentage_text = (
            f"{percentage:.2f}"
            .replace(".", ",")
        )

        ax_count.text(
            bar.get_x() + bar.get_width() / 2,
            bar.get_height() + max_count * 0.012,
            f"{count_text}\n{percentage_text}%",
            ha="center",
            va="bottom",
            fontsize=8
        )

    # Chừa khoảng trống cho nhãn trục và tên nhóm
    fig.subplots_adjust(
        left=0.08,
        right=0.90,
        bottom=0.25,
        top=0.88
    )

    plt.show()

    return summary, statistics
