from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from IPython.display import display

pd.set_option("display.max_columns", None)

FILE_NAMES = {
    "names": "adult.names",
    "train": "adult.data",
    "test": "adult.test",
}


def resolve_file(filename):
    """Tìm file trong thư mục hiện tại, dataset/ hoặc /mnt/data."""
    for folder in (Path.cwd(), Path.cwd() / "dataset", Path("/mnt/data")):
        path = folder / filename
        if path.exists():
            return path
    raise FileNotFoundError(f"Không tìm thấy file: {filename}")


PATHS = {key: resolve_file(name) for key, name in FILE_NAMES.items()}
