WORKCLASS_LABELS = {
    "Federal-gov": "Liên bang",
    "State-gov": "Tiểu bang",
    "Local-gov": "Địa phương",
    "Private": "Tư nhân",
    "Self-emp-inc": "Tự doanh có công ty",
    "Self-emp-not-inc": "Tự doanh không công ty",
    "Without-pay": "Không lương",
    "Never-worked": "Chưa từng làm việc",
}

MISSING_LABEL = "Dữ liệu thiếu"


def categorical_data(df, column):
    """Chuẩn hóa một cột phân loại và giữ dữ liệu thiếu thành một nhóm riêng."""
    if column not in df:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    values = df[column].astype("string").str.strip()
    return values.fillna(MISSING_LABEL).replace({"?": MISSING_LABEL, "": MISSING_LABEL})


def categorical_summary(df, column, labels=None):
    """Tạo bảng tổng quát và bảng phân bố cho cột phân loại."""
    labels = labels or {}
    values = categorical_data(df, column)
    valid = values[values != MISSING_LABEL]
    counts = values.value_counts()

    if MISSING_LABEL in counts:
        counts = pd.concat([counts.drop(MISSING_LABEL), counts.loc[[MISSING_LABEL]]])

    mode = valid.mode().iloc[0] if not valid.empty else None
    mode_count = int((valid == mode).sum()) if mode is not None else 0
    total, missing = len(values), int((values == MISSING_LABEL).sum())

    summary = pd.Series({
        "Số lượng mẫu": f"{total:,}",
        "Số giá trị hợp lệ": f"{total - missing:,}",
        "Số dữ liệu thiếu": f"{missing:,}",
        "Tỷ lệ dữ liệu thiếu": f"{missing / total * 100:.2f}%",
        "Số nhóm hợp lệ": valid.nunique(),
        "Mốt": labels.get(mode, mode) if mode is not None else "Không có",
        "Tần số của mốt": f"{mode_count:,}",
        "Tỷ lệ của mốt": f"{mode_count / total * 100:.2f}%",
    }, name="Giá trị").rename_axis("Chỉ số").to_frame()

    detail = pd.DataFrame({
        "Nhóm": [labels.get(value, value) for value in counts.index],
        "Số lượng": counts.values,
        "Tỷ lệ (%)": (counts.values / total * 100).round(2),
    })
    return summary, detail


def plot_categorical(df, column, title=None, labels=None):
    """Vẽ biểu đồ số lượng; tỷ lệ được ghi ngay trên từng cột."""
    _, detail = categorical_summary(df, column, labels)
    title = title or column

    plt.figure(figsize=(12, 5))
    bars = plt.bar(detail["Nhóm"], detail["Số lượng"])

    for bar, percent in zip(bars, detail["Tỷ lệ (%)"]):
        plt.text(
            bar.get_x() + bar.get_width() / 2,
            bar.get_height(),
            f"{int(bar.get_height()):,}\n{percent:.2f}%",
            ha="center",
            va="bottom",
            fontsize=8,
        )

    plt.title(f"Phân bố {title}")
    plt.xlabel(title)
    plt.ylabel("Số lượng")
    plt.xticks(rotation=45, ha="right")
    plt.grid(axis="y", linestyle="--", alpha=0.35)
    plt.tight_layout()
    plt.show()


def analyze_categorical(df, column, title=None, labels=None):
    summary, detail = categorical_summary(df, column, labels)
    display(summary)
    display(detail)
    plot_categorical(df, column, title, labels)
    return summary, detail
