# ============================================================
# CHỈNH TÊN VÀ MÀU BIỂU ĐỒ TẠI ĐÂY
# Có thể dùng tên màu: "steelblue", "orange", ...
# hoặc mã HEX: "#4C78A8", "#F58518", ...
# ============================================================
CHART_CONFIG = {
    "age": {
        "title": "độ tuổi",                       # Nhãn trục X
        "distribution_title": "Phân bố độ tuổi", # Tên biểu đồ phân bố
        "boxplot_title": "Boxplot độ tuổi",       # Tên biểu đồ boxplot
        "color": "#4C78A8",                       # Màu biểu đồ phân bố
        "box_color": "#F58518",                   # Màu boxplot
    },
    "workclass": {
        "title": "tầng lớp lao động",             # Nhãn trục X
        "chart_title": "Phân bố tầng lớp lao động", # Tên biểu đồ
        "color": "#59A14F",                       # Màu các cột
    },
}


def numeric_data(df, column):
    """Lấy một cột số hợp lệ."""
    if column not in df:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    values = pd.to_numeric(df[column], errors="coerce").dropna()
    if values.empty:
        raise ValueError(f"Cột '{column}' không có dữ liệu số hợp lệ.")
    return values


def format_values(values, limit=20):
    """Rút gọn danh sách dài khi hiển thị."""
    unique_values = sorted(pd.unique(values))
    text = ", ".join(f"{value:g}" for value in unique_values[:limit])
    return text + (" ..." if len(unique_values) > limit else "")


def numeric_summary(df, column):
    """Thống kê xu hướng tập trung, độ phân tán và ngoại biên theo IQR."""
    values = numeric_data(df, column)
    q1, median, q3 = values.quantile([0.25, 0.50, 0.75])
    iqr = q3 - q1
    lower, upper = q1 - 1.5 * iqr, q3 + 1.5 * iqr
    outliers = values[(values < lower) | (values > upper)]

    summary = pd.Series({
        "Số lượng": f"{values.size:,}",
        "Trung bình": f"{values.mean():.2f}",
        "Trung vị": f"{median:.2f}",
        "Mốt": format_values(values.mode()),
        "Nhỏ nhất": f"{values.min():g}",
        "Lớn nhất": f"{values.max():g}",
        "Khoảng biến thiên": f"{values.max() - values.min():g}",
        "Q1": f"{q1:.2f}",
        "Q2": f"{median:.2f}",
        "Q3": f"{q3:.2f}",
        "IQR": f"{iqr:.2f}",
        "Độ lệch chuẩn": f"{values.std():.2f}",
        "Ngưỡng ngoại biên dưới": f"{lower:.2f}",
        "Ngưỡng ngoại biên trên": f"{upper:.2f}",
        "Số điểm ngoại biên": f"{outliers.size:,}",
        "Tỷ lệ ngoại biên": f"{outliers.size / values.size * 100:.2f}%",
        "Các giá trị ngoại biên": format_values(outliers),
    }, name="Giá trị").rename_axis("Chỉ số").to_frame()

    return summary, outliers


def plot_numeric(
    df,
    column,
    title=None,
    color="#4C78A8",
    box_color="#F58518",
    distribution_title=None,
    boxplot_title=None,
):
    """Vẽ phân bố và boxplot; cho phép đổi tên và màu bằng tham số."""
    values = numeric_data(df, column)
    title = title or column
    distribution_title = distribution_title or f"Phân bố {title}"
    boxplot_title = boxplot_title or f"Boxplot {title}"

    plt.figure(figsize=(12, 5))
    if values.nunique() <= 100:
        values.value_counts().sort_index().plot.bar(width=0.8, color=color)
    else:
        plt.hist(values, bins="auto", color=color)

    plt.title(distribution_title)
    plt.xlabel(title)
    plt.ylabel("Số lượng")
    plt.grid(axis="y", linestyle="--", alpha=0.35)
    plt.tight_layout()
    plt.show()

    plt.figure(figsize=(12, 2.5))
    plt.boxplot(
        values,
        vert=False,
        patch_artist=True,
        boxprops={"facecolor": box_color},
    )
    plt.title(boxplot_title)
    plt.xlabel(title)
    plt.yticks([])
    plt.grid(axis="x", linestyle="--", alpha=0.35)
    plt.tight_layout()
    plt.show()


def analyze_numeric(
    df,
    column,
    title=None,
    color="#4C78A8",
    box_color="#F58518",
    distribution_title=None,
    boxplot_title=None,
):
    summary, outliers = numeric_summary(df, column)
    display(summary)
    plot_numeric(
        df,
        column,
        title=title,
        color=color,
        box_color=box_color,
        distribution_title=distribution_title,
        boxplot_title=boxplot_title,
    )
    return summary, outliers
