def analyze_numeric(
    df,
    column,
    dataset_name="Dữ liệu",
    chart_name=None,
    color="#4C78A8",
    box_color=None,
):
    """Thống kê và vẽ biểu đồ cho một cột số của một DataFrame."""
    if column not in df.columns:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    values = pd.to_numeric(df[column], errors="coerce").dropna()

    if values.empty:
        raise ValueError(f"Cột '{column}' không có dữ liệu số hợp lệ.")

    chart_name = chart_name or f"Phân bố {column}"
    box_color = box_color or color

    q1 = values.quantile(0.25)
    median = values.median()
    q3 = values.quantile(0.75)
    iqr = q3 - q1

    lower_limit = q1 - 1.5 * iqr
    upper_limit = q3 + 1.5 * iqr

    outliers = values[
        (values < lower_limit)
        | (values > upper_limit)
    ]

    modes = sorted(values.mode().tolist())
    mode_text = ", ".join(f"{value:g}" for value in modes[:20])

    if len(modes) > 20:
        mode_text += " ..."

    outlier_values = sorted(outliers.unique().tolist())
    outlier_text = ", ".join(
        f"{value:g}"
        for value in outlier_values[:20]
    )

    if len(outlier_values) > 20:
        outlier_text += " ..."

    summary = pd.Series({
        "Số lượng": f"{values.size:,}",
        "Trung bình": f"{values.mean():.2f}",
        "Trung vị": f"{median:.2f}",
        "Mốt": mode_text,
        "Nhỏ nhất": f"{values.min():g}",
        "Lớn nhất": f"{values.max():g}",
        "Khoảng biến thiên": f"{values.max() - values.min():g}",
        "Q1": f"{q1:.2f}",
        "Q2": f"{median:.2f}",
        "Q3": f"{q3:.2f}",
        "IQR": f"{iqr:.2f}",
        "Độ lệch chuẩn": f"{values.std():.2f}",
        "Ngưỡng ngoại biên dưới": f"{lower_limit:.2f}",
        "Ngưỡng ngoại biên trên": f"{upper_limit:.2f}",
        "Số điểm ngoại biên": f"{outliers.size:,}",
        "Tỷ lệ ngoại biên": f"{outliers.size / values.size * 100:.2f}%",
        "Các giá trị ngoại biên": outlier_text or "Không có",
    }, name="Giá trị").rename_axis("Chỉ số").to_frame()

    print(f"THỐNG KÊ {column.upper()} - {dataset_name.upper()}")
    display(summary)

    plt.figure(figsize=(12, 5))

    if values.nunique() <= 100:
        values.value_counts().sort_index().plot.bar(
            width=0.8,
            color=color,
        )
    else:
        plt.hist(
            values,
            bins="auto",
            color=color,
        )

    plt.title(chart_name)
    plt.xlabel(column)
    plt.ylabel("Số lượng")
    plt.grid(axis="y", linestyle="--", alpha=0.35)
    plt.tight_layout()
    plt.show()

    plt.figure(figsize=(12, 2.5))
    plt.boxplot(
        values,
        vert=False,
        patch_artist=True,
        boxprops={"facecolor": box_color},
    )

    plt.title(f"{chart_name} - Boxplot")
    plt.xlabel(column)
    plt.yticks([])
    plt.grid(axis="x", linestyle="--", alpha=0.35)
    plt.tight_layout()
    plt.show()

    return summary, outliers
