def analyze_numeric(
    df,
    column,
    dataset_name="Dữ liệu",
    chart_name=None,
    color="#4C78A8",
    box_color=None,
    x_label=None,
    y_label="Số lượng",
    show_annotations=True,
):
    """Thống kê và vẽ biểu đồ cho một cột số của một DataFrame."""

    if column not in df.columns:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    values = pd.to_numeric(
        df[column],
        errors="coerce"
    ).dropna()

    if values.empty:
        raise ValueError(
            f"Cột '{column}' không có dữ liệu số hợp lệ."
        )

    chart_name = chart_name or f"Phân bố {column}"
    box_color = box_color or color
    x_label = x_label or column

    # =========================
    # TÍNH TOÁN THỐNG KÊ
    # =========================
    q1 = values.quantile(0.25)
    median = values.median()
    q3 = values.quantile(0.75)

    iqr = q3 - q1

    lower_limit = q1 - 1.5 * iqr
    upper_limit = q3 + 1.5 * iqr

    # Giá trị thực tế tại hai đầu râu
    lower_whisker = values[
        values >= lower_limit
    ].min()

    upper_whisker = values[
        values <= upper_limit
    ].max()

    outliers = values[
        (values < lower_limit)
        | (values > upper_limit)
    ]

    # =========================
    # XỬ LÝ MỐT
    # =========================
    modes = sorted(values.mode().tolist())

    mode_text = ", ".join(
        f"{value:g}"
        for value in modes[:20]
    )

    if len(modes) > 20:
        mode_text += " ..."

    # =========================
    # XỬ LÝ GIÁ TRỊ NGOẠI BIÊN
    # =========================
    outlier_values = sorted(
        outliers.unique().tolist()
    )

    outlier_text = ", ".join(
        f"{value:g}"
        for value in outlier_values[:20]
    )

    if len(outlier_values) > 20:
        outlier_text += " ..."

    # =========================
    # BẢNG THỐNG KÊ
    # =========================
    summary = pd.Series({
        "Số lượng": f"{values.size:,}",
        "Trung bình": f"{values.mean():.2f}",
        "Trung vị": f"{median:.2f}",
        "Mốt": mode_text,
        "Nhỏ nhất": f"{values.min():g}",
        "Lớn nhất": f"{values.max():g}",
        "Khoảng biến thiên": (
            f"{values.max() - values.min():g}"
        ),
        "Q1": f"{q1:.2f}",
        "Q2": f"{median:.2f}",
        "Q3": f"{q3:.2f}",
        "IQR": f"{iqr:.2f}",
        "Độ lệch chuẩn": f"{values.std():.2f}",
        "Ngưỡng ngoại biên dưới": (
            f"{lower_limit:.2f}"
        ),
        "Ngưỡng ngoại biên trên": (
            f"{upper_limit:.2f}"
        ),
        "Râu dưới thực tế": (
            f"{lower_whisker:.2f}"
        ),
        "Râu trên thực tế": (
            f"{upper_whisker:.2f}"
        ),
        "Số điểm ngoại biên": (
            f"{outliers.size:,}"
        ),
        "Tỷ lệ ngoại biên": (
            f"{outliers.size / values.size * 100:.2f}%"
        ),
        "Các giá trị ngoại biên": (
            outlier_text or "Không có"
        ),
    }, name="Giá trị").rename_axis(
        "Chỉ số"
    ).to_frame()

    print(
        f"THỐNG KÊ {column.upper()} "
        f"- {dataset_name.upper()}"
    )

    display(summary)

    # =========================
    # BIỂU ĐỒ TẦN SUẤT
    # =========================
    figure, axis = plt.subplots(
        figsize=(12, 5)
    )

    if values.nunique() <= 100:
        frequency = (
            values
            .value_counts()
            .sort_index()
        )

        axis.bar(
            frequency.index.astype(str),
            frequency.values,
            width=0.8,
            color=color,
        )

        # Tránh label trục X bị chồng
        if len(frequency) > 20:
            axis.tick_params(
                axis="x",
                labelrotation=45
            )

    else:
        axis.hist(
            values,
            bins="auto",
            color=color,
        )

    axis.set_title(
        f"Biểu đồ tần suất {chart_name}"
    )

    axis.set_xlabel(x_label)
    axis.set_ylabel(y_label)

    axis.grid(
        axis="y",
        linestyle="--",
        alpha=0.35
    )

    figure.tight_layout()
    plt.show()

    # =========================
    # BOXPLOT
    # =========================
    figure, axis = plt.subplots(
        figsize=(12, 4)
    )

    axis.boxplot(
        values,
        vert=False,
        patch_artist=True,

        boxprops={
            "facecolor": box_color,
            "edgecolor": "black",
        },

        medianprops={
            "color": "black",
            "linewidth": 1.5,
        },

        whiskerprops={
            "color": "black",
        },

        capprops={
            "color": "black",
        },

        flierprops={
            "marker": "o",
            "markerfacecolor": "white",
            "markeredgecolor": "black",
            "markersize": 5,
        },
    )

    # =========================
    # CHÚ THÍCH BOXPLOT
    # =========================
    if show_annotations:

        # Q1
        axis.annotate(
            f"Q1 = {q1:.0f}",
            xy=(q1, 1.05),
            xytext=(q1, 1.30),
            ha="center",
            va="bottom",
            arrowprops={
                "arrowstyle": "->"
            },
        )

        # Q2 - Trung vị
        axis.annotate(
            f"Trung vị (Q2) = {median:.0f}",
            xy=(median, 0.95),
            xytext=(median, 0.65),
            ha="center",
            va="top",
            arrowprops={
                "arrowstyle": "->"
            },
        )

        # Q3
        axis.annotate(
            f"Q3 = {q3:.0f}",
            xy=(q3, 1.05),
            xytext=(q3, 1.30),
            ha="center",
            va="bottom",
            arrowprops={
                "arrowstyle": "->"
            },
        )

        # Râu dưới
        axis.annotate(
            f"Hạn biên dưới\n= {lower_whisker:.0f}",
            xy=(lower_whisker, 0.98),
            xytext=(lower_whisker, 0.65),
            ha="center",
            va="top",
            arrowprops={
                "arrowstyle": "->"
            },
        )

        # Râu trên
        axis.annotate(
            f"Hạn biên trên\n= {upper_whisker:.0f}",
            xy=(upper_whisker, 0.98),
            xytext=(upper_whisker, 0.65),
            ha="center",
            va="top",
            arrowprops={
                "arrowstyle": "->"
            },
        )

        # Ngoại biên phía trên
        upper_outliers = values[
            values > upper_whisker
        ]

        if not upper_outliers.empty:
            first_upper_outlier = (
                upper_outliers.min()
            )

            axis.annotate(
                "Điểm ngoại biên",
                xy=(first_upper_outlier, 1.03),
                xytext=(first_upper_outlier, 1.30),
                ha="center",
                va="bottom",
                arrowprops={
                    "arrowstyle": "->"
                },
            )

        # Ngoại biên phía dưới
        lower_outliers = values[
            values < lower_whisker
        ]

        if not lower_outliers.empty:
            first_lower_outlier = (
                lower_outliers.max()
            )

            axis.annotate(
                "Điểm ngoại biên",
                xy=(first_lower_outlier, 1.03),
                xytext=(first_lower_outlier, 1.30),
                ha="center",
                va="bottom",
                arrowprops={
                    "arrowstyle": "->"
                },
            )

        # Mở rộng chiều cao để chú thích không bị cắt
        axis.set_ylim(0.5, 1.5)

    axis.set_title(
        f"Biểu đồ {chart_name}",
        pad=12
    )

    axis.set_xlabel(x_label)
    axis.set_yticks([])

    axis.grid(
        axis="x",
        linestyle="--",
        alpha=0.4
    )

    figure.tight_layout()
    plt.show()

    return summary, outliers
