def show_missing(df, dataset_name):
    """Hiển thị dữ liệu thiếu của đúng một tập dữ liệu."""
    report = pd.DataFrame({
        "Dữ liệu thiếu": df.isna().sum(),
        "Tỷ lệ thiếu (%)": df.isna().mean().mul(100).round(2),
    })

    report = report[report["Dữ liệu thiếu"] > 0]

    print(f"Dữ liệu thiếu - {dataset_name}")
    display(report)

    return report
