MISSING_LABEL = "Dữ liệu thiếu"

def analyze_categorical(
    df,
    column,
    dataset_name="Dữ liệu",
    chart_name=None,
    color="#59A14F",
    missing_color="#E15759",
    labels=None,
    label_width=12,
    x_label=None,
    y_label="Số lượng",
):
    """Thống kê và vẽ biểu đồ cho một cột phân loại của một DataFrame."""
    if column not in df.columns:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    labels = labels or {}
    chart_name = chart_name or f"Phân bố {column}"
    x_label = x_label or column

    values = (
        df[column]
        .astype("string")
        .str.strip()
        .fillna(MISSING_LABEL)
        .replace({
            "?": MISSING_LABEL,
            "": MISSING_LABEL,
        })
    )

    valid_values = values[values != MISSING_LABEL]
    counts = values.value_counts()

    # Luôn đặt nhóm dữ liệu thiếu ở cuối biểu đồ.
    if MISSING_LABEL in counts.index:
        counts = pd.concat([
            counts.drop(MISSING_LABEL),
            counts.loc[[MISSING_LABEL]],
        ])

    total = len(values)
    missing_count = int((values == MISSING_LABEL).sum())

    if valid_values.empty:
        mode = None
        mode_count = 0
    else:
        mode = valid_values.mode().iloc[0]
        mode_count = int((valid_values == mode).sum())

    summary = pd.Series({
        "Số lượng mẫu": f"{total:,}",
        "Số giá trị hợp lệ": f"{total - missing_count:,}",
        "Số dữ liệu thiếu": f"{missing_count:,}",
        "Tỷ lệ dữ liệu thiếu": f"{missing_count / total * 100:.2f}%",
        "Số nhóm hợp lệ": valid_values.nunique(),
        "Mốt": labels.get(mode, mode) if mode is not None else "Không có",
        "Tần số của mốt": f"{mode_count:,}",
        "Tỷ lệ của mốt": f"{mode_count / total * 100:.2f}%",
    }, name="Giá trị").rename_axis("Chỉ số").to_frame()

    display_labels = [
        labels.get(value, value)
        for value in counts.index
    ]

    detail = pd.DataFrame({
        "Nhóm": display_labels,
        "Số lượng": counts.values,
        "Tỷ lệ (%)": (
            counts.values / total * 100
        ).round(2),
    })

    print(f"THỐNG KÊ {column.upper()} - {dataset_name.upper()}")
    display(summary)
    display(detail)

    # Label dài tự xuống dòng.
    wrapped_labels = [
        fill(str(label), width=label_width)
        for label in display_labels
    ]

    # Dữ liệu thiếu luôn có màu đỏ mặc định.
    bar_colors = [
        missing_color if value == MISSING_LABEL else color
        for value in counts.index
    ]

    # Tự tăng chiều rộng để label không bị chen hoặc tràn.
    figure_width = max(10, min(22, len(counts) * 1.5))
    figure, axis = plt.subplots(figsize=(figure_width, 6))

    bars = axis.bar(
        wrapped_labels,
        detail["Số lượng"],
        color=bar_colors,
    )

    for bar, percent in zip(bars, detail["Tỷ lệ (%)"]):
        axis.annotate(
            f"{int(bar.get_height()):,}\n{percent:.2f}%",
            xy=(
                bar.get_x() + bar.get_width() / 2,
                bar.get_height(),
            ),
            xytext=(0, 4),
            textcoords="offset points",
            ha="center",
            va="bottom",
            fontsize=8,
            clip_on=False,
        )

    max_count = detail["Số lượng"].max()
    axis.set_ylim(
        0,
        max_count * 1.18 if max_count > 0 else 1,
    )

    axis.set_title(f"Biểu đồ tần suất phân bổ {chart_name}")
    axis.set_xlabel(x_label)
    axis.set_ylabel(y_label)
    axis.tick_params(axis="x", labelrotation=0)
    axis.grid(axis="y", linestyle="--", alpha=0.35)
    figure.tight_layout(pad=1.5)
    plt.show()

    return summary, detail
