MISSING_LABEL = "Dữ liệu thiếu"

def analyze_categorical(
    df,
    column,
    dataset_name="Dữ liệu",
    chart_name=None,
    color="steelblue",
    missing_color="#E15759",
    labels=None,
    label_width=25,
    x_label="Số lượng",
    y_label=None,
):

    if column not in df.columns:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    labels = labels or {}
    chart_name = chart_name or column
    y_label = y_label or column

    # Chuẩn hóa dữ liệu.
    values = (
        df[column]
        .astype("string")
        .str.strip()
        .fillna(MISSING_LABEL)
        .replace({
            "?": MISSING_LABEL,
            "": MISSING_LABEL,
        })
    )

    total = len(values)

    if total == 0:
        raise ValueError("DataFrame không có dữ liệu để phân tích.")

    valid_values = values[values != MISSING_LABEL]

    # Đếm tần số, mặc định sắp xếp giảm dần.
    counts = values.value_counts()

    # Luôn đặt nhóm dữ liệu thiếu ở cuối bảng và cuối biểu đồ.
    if MISSING_LABEL in counts.index:
        counts = pd.concat([
            counts.drop(index=MISSING_LABEL),
            counts.loc[[MISSING_LABEL]],
        ])

    missing_count = int((values == MISSING_LABEL).sum())
    valid_count = total - missing_count

    # Xác định mốt, không tính dữ liệu thiếu.
    if valid_values.empty:
        mode = None
        mode_count = 0
        mode_percent = 0
    else:
        mode = valid_values.mode().iloc[0]
        mode_count = int((valid_values == mode).sum())
        mode_percent = mode_count / total * 100

    mode_display = (
        labels.get(mode, mode)
        if mode is not None
        else "Không có"
    )

    # Bảng thống kê tổng quát.
    summary = pd.Series(
        {
            "Số lượng mẫu": f"{total:,}",
            "Số giá trị hợp lệ": f"{valid_count:,}",
            "Số dữ liệu thiếu": f"{missing_count:,}",
            "Tỷ lệ dữ liệu thiếu": f"{missing_count / total * 100:.2f}%",
            "Số nhóm hợp lệ": int(valid_values.nunique()),
            "Mốt": mode_display,
            "Tần số của mốt": f"{mode_count:,}",
            "Tỷ lệ của mốt": f"{mode_percent:.2f}%",
        },
        name="Giá trị",
    ).rename_axis("Chỉ số").to_frame()

    # Chuyển giá trị gốc thành nhãn hiển thị.
    display_labels = [
        labels.get(value, value)
        for value in counts.index
    ]

    # Bảng chi tiết.
    detail = pd.DataFrame({
        "Nhóm dữ liệu": display_labels,
        "Số lượng": counts.to_numpy(),
        "Tỷ lệ (%)": (counts.to_numpy() / total * 100).round(2),
    })

    # Hiển thị kết quả.
    print(f"THỐNG KÊ {column.upper()} - {dataset_name.upper()}")
    display(summary)
    display(detail)

    # Tự xuống dòng đối với nhãn dài.
    wrapped_labels = [
        "\n".join(
            fill(part, width=label_width)
            for part in str(label).split("\n")
            )
        for label in display_labels
    ]

    # Nhóm dữ liệu thiếu có màu riêng.
    bar_colors = [
        missing_color if value == MISSING_LABEL else color
        for value in counts.index
    ]

    # Tự điều chỉnh chiều cao biểu đồ theo số nhóm.
    figure_height = max(6, min(18, len(counts) * 0.7),)
    figure, axis = plt.subplots(figsize=(9, figure_height))

    # Biểu đồ thanh ngang:
    # Trục X là số lượng.
    # Trục Y là nhóm dữ liệu.
    bars = axis.barh(
        wrapped_labels,
        detail["Số lượng"],
        color=bar_colors,
    )

    # Đưa nhóm có tần số lớn nhất lên trên.
    # Dữ liệu thiếu vẫn nằm cuối danh sách, phía dưới.
    axis.invert_yaxis()

    # Gắn số lượng và tỷ lệ bên phải mỗi thanh.
    for bar, percent in zip(
        bars,
        detail["Tỷ lệ (%)"],
    ):
        count = int(bar.get_width())

        axis.annotate(
            f"{count:,}\n({percent:.2f}%)",
            xy=(bar.get_width(),bar.get_y() + bar.get_height() / 2,),
            xytext=(6, 0),
            textcoords="offset points",
            ha="left",
            va="center",
            fontsize=10,
            clip_on=False,
        )

    max_count = detail["Số lượng"].max()

    # Chừa khoảng trống bên phải để hiển thị nhãn số liệu.
    axis.set_xlim(0, max_count * 1.1 if max_count > 0 else 1,)
    axis.set_title(f"Biểu đồ tần suất phân bố {chart_name}", fontsize=14)
    axis.set_xlabel(x_label, fontsize=14)
    axis.set_ylabel(y_label, fontsize=14)
    axis.grid(axis="x", linestyle="--", alpha=0.35)
    axis.set_axisbelow(True)
    plt.gca().xaxis.set_major_formatter(FuncFormatter(lambda value, position: f"{value:,.0f}"))
    figure.tight_layout(pad=1)
    plt.show()

    return summary, detail
