def analyze_numeric(
    df,
    column,
    dataset_name="Dữ liệu",
    chart_name=None,
    color="#4C78A8",
    box_color=None,
    x_label=None,
    y_label="Số lượng",
    show_boxplot_detail=False,
):
    # =========================
    # KIỂM TRA DỮ LIỆU
    # =========================
    if column not in df.columns:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    values = pd.to_numeric(df[column], errors="coerce").dropna()

    if values.empty:
        raise ValueError(f"Cột '{column}' không có dữ liệu số hợp lệ.")

    chart_name = chart_name or f"Phân bố {column}"
    box_color = box_color or color
    x_label = x_label or column

    # =========================
    # THỐNG KÊ
    # =========================
    q1 = values.quantile(0.25)
    median = values.median()
    q3 = values.quantile(0.75)

    iqr = q3 - q1

    lower_limit = q1 - 1.5 * iqr
    upper_limit = q3 + 1.5 * iqr

    # Vị trí râu thực tế
    lower_whisker = values[values >= lower_limit].min()

    upper_whisker = values[values <= upper_limit].max()

    # Điểm ngoại biên
    outliers = values[(values < lower_limit) | (values > upper_limit)]

    # Mốt
    modes = sorted(values.mode().tolist())

    mode_text = ", ".join(
        f"{value:g}"
        for value in modes[:20]
    )

    if len(modes) > 20:
        mode_text += " ..."

    # Danh sách giá trị ngoại biên
    outlier_values = sorted(
        outliers.unique().tolist()
    )

    outlier_text = ", ".join(
        f"{value:g}"
        for value in outlier_values[:20]
    )

    if len(outlier_values) > 20:
        outlier_text += " ..."

    # =========================
    # BẢNG THỐNG KÊ
    # =========================
    summary = pd.Series({
        "Số lượng": f"{values.size:,}",
        "Trung bình": f"{values.mean():,.2f}",
        "Trung vị": f"{median:,.2f}",
        "Mốt": mode_text,
        "Nhỏ nhất": f"{values.min():,.0f}",
        "Lớn nhất": f"{values.max():,.0f}",
        "Khoảng biến thiên": f"{values.max() - values.min():,.0f}",
        "Q1": f"{q1:,.2f}",
        "Q2": f"{median:,.2f}",
        "Q3": f"{q3:,.2f}",
        "IQR": f"{iqr:,.2f}",
        "Độ lệch chuẩn": f"{values.std():,.2f}",
        "Ngưỡng ngoại biên dưới": f"{lower_limit:,.2f}",
        "Ngưỡng ngoại biên trên": f"{upper_limit:,.2f}",
        "Râu dưới thực tế": f"{lower_whisker:,.2f}",
        "Râu trên thực tế": f"{upper_whisker:,.2f}",
        "Số điểm ngoại biên": f"{outliers.size:,}",
        "Tỷ lệ ngoại biên": (
            f"{outliers.size / values.size * 100:.2f}%"
        ),
        "Các giá trị ngoại biên": outlier_text or "Không có",
    }, name="Giá trị").rename_axis("Chỉ số").to_frame()

    print(
        f"THỐNG KÊ {column.upper()} "
        f"- {dataset_name.upper()}"
    )

    display(summary)

    # =========================
    # BIỂU ĐỒ 1: TẦN SUẤT
    # =========================
    plt.figure(figsize=(12, 6))

    if values.nunique() <= 100:
        frequency = (values.value_counts().sort_index())
        plt.bar(
            frequency.index.astype(str),
            frequency.values,
            width=0.8,
            color=color,
        )

        if len(frequency) > 20:
            plt.xticks(rotation=90,ha="center",)

    else:
        plt.hist(values, bins="auto",color=color,)
        plt.gca().xaxis.set_major_formatter(
            FuncFormatter(lambda value, position: f"{value:,.0f}")
        )

    plt.title(f"Biểu đồ tần suất {chart_name}")
    plt.xlabel(x_label)
    plt.ylabel(y_label)
    plt.grid(axis="y",linestyle="--",alpha=0.35)
    plt.margins(x=0.01)
    plt.tight_layout()
    plt.show()

    # =========================
    # CẤU HÌNH CHUNG CHO BOXPLOT
    # =========================
    boxplot_options = {
        "vert": False,
        "patch_artist": True,
        "showmeans": False,
        "meanline": False,
        "boxprops": {
            "facecolor": box_color,
            "edgecolor": "black",
        },
        "medianprops": {
            "color": "black",
            "linewidth": 1.5,
        },
        "whiskerprops": {
            "color": "black",
        },
        "capprops": {
            "color": "black",
        },
        "flierprops": {
            "marker": "o",
            "markerfacecolor": "white",
            "markeredgecolor": "black",
            "markersize": 5,
        },
    }

    # =========================
    # BIỂU ĐỒ 2: BOXPLOT THƯỜNG
    # =========================
    plt.figure(figsize=(12, 2.5))
    plt.boxplot(values, **boxplot_options)
    plt.title(f"Biểu đồ {chart_name}")
    plt.xlabel(x_label)
    plt.yticks([])
    plt.grid(axis="x", linestyle="--",alpha=0.4,)
    plt.gca().xaxis.set_major_formatter(
            FuncFormatter(lambda value, position: f"{value:,.0f}")
        )
    plt.tight_layout()
    plt.show()

    # =========================
    # BIỂU ĐỒ 3: BOXPLOT CHI TIẾT
    # =========================
    if show_boxplot_detail:
        plt.figure(figsize=(12, 3))
        plt.boxplot(values, **boxplot_options,)

        annotations = [
            {
                "text": f"Q1\n = {q1:,g}",
                "value": q1,
                "point_y": 1.08,
                "text_y": 1.30,
            },
            {
                "text": (
                    f"Trung vị\n(Q2) = {median:,g}"
                ),
                "value": median,
                "point_y": 0.92,
                "text_y": 0.65,
            },
            {
                "text": f"Q3\n = {q3:,g}",
                "value": q3,
                "point_y": 1.08,
                "text_y": 1.30,
            },
            {
                "text": (
                    f"Hạn biên\ndưới"
                    f"= {lower_whisker:,g}"
                ),
                "value": lower_whisker,
                "point_y": 0.95,
                "text_y": 0.65,
            },
            {
                "text": (
                    f"Hạn biên\ntrên"
                    f"= {upper_whisker:,g}"
                ),
                "value": upper_whisker,
                "point_y": 0.95,
                "text_y": 0.65,
            },
        ]

        for item in annotations:
            plt.annotate(
                item["text"],
                xy=(
                    item["value"],
                    item["point_y"],
                ),
                xytext=(
                    item["value"],
                    item["text_y"],
                ),
                ha="center",
                arrowprops={
                    "arrowstyle": "->"
                },
            )

        # Ngoại biên phía dưới
        lower_outliers = outliers[outliers < lower_whisker]

        if not lower_outliers.empty:
            first_lower_outlier = (lower_outliers.max())

            plt.annotate(
                "Điểm ngoại biên",
                xy=(
                    first_lower_outlier,
                    1.04,
                ),
                xytext=(
                    first_lower_outlier,
                    1.30,
                ),
                ha="center",
                arrowprops={
                    "arrowstyle": "->"
                },
            )

        # Ngoại biên phía trên
        upper_outliers = outliers[outliers > upper_whisker]

        if not upper_outliers.empty:
            first_upper_outlier = (
                upper_outliers.min()
            )

            plt.annotate(
                "Điểm ngoại biên",
                xy=(
                    first_upper_outlier,
                    1.04,
                ),
                xytext=(
                    first_upper_outlier,
                    1.30,
                ),
                ha="center",
                arrowprops={
                    "arrowstyle": "->"
                },
            )

        plt.title(f"Biểu đồ {chart_name}")
        plt.xlabel(x_label)
        plt.yticks([])
        plt.ylim(0.5, 1.5)
        plt.grid(axis="x",linestyle="--",alpha=0.4,)
        plt.gca().xaxis.set_major_formatter(FuncFormatter(lambda value, position: f"{value:,.0f}"))
        plt.tight_layout()
        plt.show()

    return summary, outliers
