# =========================================================
# LOGISTIC REGRESSION CHO BỘ DỮ LIỆU ADULT
# =========================================================

from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import (
    accuracy_score,
    classification_report,
    confusion_matrix,
    ConfusionMatrixDisplay,
    f1_score,
    precision_score,
    recall_score,
    roc_auc_score,
    RocCurveDisplay,
)
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder, StandardScaler

# ---------------------------------------------------------
# 1. TÁCH ĐẶC TRƯNG VÀ NHÃN
# ---------------------------------------------------------

# education và education_num biểu diễn cùng thông tin.
# Giữ education_num và loại education để tránh trùng lặp.
columns_to_drop = ["income", "education"]

X_train = train_df.drop(columns=columns_to_drop).copy()
X_test = test_df.drop(columns=columns_to_drop).copy()

# <=50K = 0, >50K = 1
y_train = (train_df["income"] == ">50K").astype(int)
y_test = (test_df["income"] == ">50K").astype(int)

# ---------------------------------------------------------
# 2. XÁC ĐỊNH CỘT SỐ VÀ CỘT PHÂN LOẠI
# ---------------------------------------------------------

numeric_columns = X_train.select_dtypes(include="number").columns.tolist()
categorical_columns = X_train.select_dtypes(exclude="number").columns.tolist()

print("Cột số:")
print(numeric_columns)

print("\nCột phân loại:")
print(categorical_columns)

# ---------------------------------------------------------
# 3. TIỀN XỬ LÝ CỘT SỐ
# ---------------------------------------------------------

numeric_pipeline = Pipeline(
    steps=[
        # Thay dữ liệu thiếu bằng trung vị
        ("imputer", SimpleImputer(strategy="median")),

        # Chuẩn hóa dữ liệu số
        ("scaler", StandardScaler()),
    ]
)

# ---------------------------------------------------------
# 4. TIỀN XỬ LÝ CỘT PHÂN LOẠI
# ---------------------------------------------------------

categorical_pipeline = Pipeline(
    steps=[
        # Thay dữ liệu thiếu bằng giá trị xuất hiện nhiều nhất
        ("imputer", SimpleImputer(strategy="most_frequent")),

        # Chuyển dữ liệu phân loại thành dữ liệu số
        (
            "onehot",
            OneHotEncoder(
                handle_unknown="ignore",
                sparse_output=True,
            ),
        ),
    ]
)

# ---------------------------------------------------------
# 5. KẾT HỢP CÁC BƯỚC TIỀN XỬ LÝ
# ---------------------------------------------------------

preprocessor = ColumnTransformer(
    transformers=[
        ("numeric", numeric_pipeline, numeric_columns),
        ("categorical", categorical_pipeline, categorical_columns),
    ]
)

# ---------------------------------------------------------
# 6. TẠO PIPELINE LOGISTIC REGRESSION
# ---------------------------------------------------------

logistic_model = Pipeline(
    steps=[
        ("preprocessor", preprocessor),
        (
            "classifier",
            LogisticRegression(
                max_iter=2000,
                solver="liblinear",
                random_state=42,
            ),
        ),
    ]
)

# ---------------------------------------------------------
# 7. HUẤN LUYỆN MÔ HÌNH
# ---------------------------------------------------------

logistic_model.fit(X_train, y_train)

# ---------------------------------------------------------
# 8. DỰ ĐOÁN TRÊN TẬP TEST
# ---------------------------------------------------------

y_pred = logistic_model.predict(X_test)

# Xác suất thuộc lớp >50K
y_probability = logistic_model.predict_proba(X_test)[:, 1]

# ---------------------------------------------------------
# 9. ĐÁNH GIÁ MÔ HÌNH
# ---------------------------------------------------------

results = pd.DataFrame(
    {
        "Chỉ số": [
            "Accuracy",
            "Precision",
            "Recall",
            "F1-score",
            "ROC-AUC",
        ],
        "Giá trị": [
            accuracy_score(y_test, y_pred),
            precision_score(y_test, y_pred, zero_division=0),
            recall_score(y_test, y_pred, zero_division=0),
            f1_score(y_test, y_pred, zero_division=0),
            roc_auc_score(y_test, y_probability),
        ],
    }
)

results["Giá trị"] = results["Giá trị"].round(4)

display(results)

print("\nBáo cáo phân loại:")
print(
    classification_report(
        y_test,
        y_pred,
        target_names=["<=50K", ">50K"],
        digits=4,
        zero_division=0,
    )
)

# ---------------------------------------------------------
# 10. MA TRẬN NHẦM LẪN
# ---------------------------------------------------------

ConfusionMatrixDisplay(
    confusion_matrix=confusion_matrix(y_test, y_pred),
    display_labels=["<=50K", ">50K"],
).plot(cmap="Blues")

plt.title("Ma trận nhầm lẫn của Logistic Regression")
plt.xlabel("Nhãn dự đoán")
plt.ylabel("Nhãn thực tế")
plt.show()

# ---------------------------------------------------------
# 11. ĐƯỜNG CONG ROC
# ---------------------------------------------------------

RocCurveDisplay.from_predictions(
    y_test,
    y_probability,
    name="Logistic Regression",
)

plt.title("Đường cong ROC của Logistic Regression")
plt.show()
