# =========================================================

# Thay đổi đường dẫn nếu hai file nằm ở thư mục khác
train_path = "adult.data"
test_path = "adult.test"

train_df = pd.read_csv(
    train_path,
    names=columns,
    sep=",",
    skipinitialspace=True,
    na_values="?"
)

# adult.test có một dòng mô tả ở đầu nên cần skiprows=1
test_df = pd.read_csv(
    test_path,
    names=columns,
    sep=",",
    skipinitialspace=True,
    skiprows=1,
    na_values="?"
)


# =========================================================
# 3. LÀM SẠCH DỮ LIỆU
# =========================================================

# Xóa khoảng trắng thừa trong tất cả cột chuỗi
for column in train_df.select_dtypes(include="object").columns:
    train_df[column] = train_df[column].str.strip()

for column in test_df.select_dtypes(include="object").columns:
    test_df[column] = test_df[column].str.strip()

# Nhãn trong adult.test có dạng <=50K. và >50K.
test_df["income"] = test_df["income"].str.rstrip(".")

# Loại bỏ các dòng có dữ liệu bị thiếu
train_df = train_df.dropna().reset_index(drop=True)
test_df = test_df.dropna().reset_index(drop=True)

print("Kích thước tập huấn luyện:", train_df.shape)
print("Kích thước tập kiểm tra:", test_df.shape)


# =========================================================
# 4. CHIA BIẾN ĐẦU VÀO VÀ NHÃN
# =========================================================

X_train = train_df.drop(columns="income")
y_train = train_df["income"]

X_test = test_df.drop(columns="income")
y_test = test_df["income"]


# =========================================================
# 5. XÁC ĐỊNH CỘT PHÂN LOẠI VÀ CỘT SỐ
# =========================================================

categorical_columns = X_train.select_dtypes(
    include=["object", "category"]
).columns.tolist()

numeric_columns = X_train.select_dtypes(
    exclude=["object", "category"]
).columns.tolist()

print("\nCác cột phân loại:")
print(categorical_columns)

print("\nCác cột số:")
print(numeric_columns)


# =========================================================
# 6. TẠO BỘ TIỀN XỬ LÝ
# =========================================================

preprocessor = ColumnTransformer(
    transformers=[
        (
            "categorical",
            OneHotEncoder(
                handle_unknown="ignore"
            ),
            categorical_columns
        ),
        (
            "numeric",
            StandardScaler(),
            numeric_columns
        )
    ]
)


# =========================================================
# 7. TẠO PIPELINE LOGISTIC REGRESSION
# =========================================================

model = Pipeline(
    steps=[
        (
            "preprocessor",
            preprocessor
        ),
        (
            "classifier",
            LogisticRegression(
                solver="liblinear",
                max_iter=2000,
                random_state=42
            )
        )
    ]
)


