preprocessor = ColumnTransformer(
    transformers=[
        (
            "categorical",
            OneHotEncoder(
                handle_unknown="ignore"
            ),
            categorical_columns,
        ),
        (
            "numeric",
            "passthrough",
            numeric_columns,
        ),
    ]
)


# ---------------------------------------------------------
