logistic_model = Pipeline(
    steps=[
        (
            "preprocessor",
            preprocessor,
        ),
        (
            "classifier",
            LogisticRegression(
                max_iter=2000,
                solver="liblinear",
                random_state=42,
            ),
        ),
    ]
)


# ---------------------------------------------------------
# 6. HUẤN LUYỆN MÔ HÌNH
# ---------------------------------------------------------

logistic_model.fit(X_train, y_train)


