# =========================================================
# 1. Lấy capital_gain dương trong tập train
# =========================================================

positive_capital_gain = train_df.loc[
    train_df["capital_gain"] > 0,
    "capital_gain"
].dropna()

if positive_capital_gain.empty:
    raise ValueError("Không có giá trị capital_gain lớn hơn 0.")


# =========================================================
# 2. Tính ngưỡng tứ phân vị từ tập train
# =========================================================

_, capital_gain_bins = pd.qcut(
    positive_capital_gain,
    q=4,
    retbins=True,
    duplicates="drop"
)

# Mở rộng hai đầu để xử lý giá trị ngoài phạm vi train
capital_gain_bins[0] = float("-inf")
capital_gain_bins[-1] = float("inf")

# Tạo nhãn tự động
quartile_labels = [
    f"Q{i + 1}"
    for i in range(len(capital_gain_bins) - 1)
]


# =========================================================
# 3. Hàm gom nhóm capital_gain
# =========================================================

def group_capital_gain(series, bins, labels):
    result = pd.Series(
        "Không có lợi nhuận",
        index=series.index,
        dtype="object"
    )

    positive_mask = series > 0

    result.loc[positive_mask] = pd.cut(
        series.loc[positive_mask],
        bins=bins,
        labels=labels,
        include_lowest=True
    ).astype(str)

    category_order = [
        "Không có lợi nhuận",
        *labels
    ]

    return pd.Categorical(
        result,
        categories=category_order,
        ordered=True
    )


# =========================================================
# 4. Áp dụng cho train và test
# =========================================================

train_df["capital_gain_group"] = group_capital_gain(
    train_df["capital_gain"],
    capital_gain_bins,
    quartile_labels
)

test_df["capital_gain_group"] = group_capital_gain(
    test_df["capital_gain"],
    capital_gain_bins,
    quartile_labels
)


# =========================================================
# 5. Kiểm tra kết quả
# =========================================================

