def encode_native_country(series):
    series = series.astype("string").str.strip()

    return pd.Series(
        np.select(
            [
                series.eq("United-States"),
                series.notna() & series.ne("United-States"),
            ],
            [
                1,
                2,
            ],
            default=np.nan,
        ),
        index=series.index,
    ).astype("Int64")


