def read_column_names(path):
    """Đọc tên cột và các nhãn income từ adult.names."""
    lines = [
        line.strip()
        for line in Path(path).read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.lstrip().startswith("|")
    ]

    columns = [
        line.split(":", 1)[0].strip().replace("-", "_")
        for line in lines
        if ":" in line
    ]

    income_classes = next(
        (
            line[:-1].split(", ")
            for line in lines
            if line.endswith(".") and "," in line
        ),
        [],
    )

    return columns + ["income"], income_classes


def load_adult(path, columns, is_test=False):
    """Đọc một tập Adult và chuẩn hóa nhãn income."""
    df = pd.read_csv(
        path,
        names=columns,
        sep=r",\s*",
        engine="python",
        skiprows=1 if is_test else 0,
        na_values="?",
    )

    df["income"] = df["income"].astype("string").str.rstrip(".")
    return df


column_names, income_classes = read_column_names(PATHS["names"])

train_df = load_adult(
    PATHS["train"],
    column_names,
)

test_df = load_adult(
    PATHS["test"],
    column_names,
    is_test=True,
)

print("Tên cột:", column_names)
print("Nhãn income:", income_classes)
