# ---------------------------------------------------------

results = pd.DataFrame(
    {
        "Chỉ số": [
            "Accuracy",
            "Precision",
            "Recall",
            "F1-score",
            "ROC-AUC",
        ],
        "Giá trị": [
            accuracy_score(y_test, y_pred),
            precision_score(
                y_test,
                y_pred,
                zero_division=0,
            ),
            recall_score(
                y_test,
                y_pred,
                zero_division=0,
            ),
            f1_score(
                y_test,
                y_pred,
                zero_division=0,
            ),
            roc_auc_score(
                y_test,
                y_probability,
            ),
        ],
    }
)

results["Giá trị"] = results["Giá trị"].round(4)


# ---------------------------------------------------------
