import matplotlib.pyplot as plt
import pandas as pd

age_labels = [
    "17 - 28",
    "29 - 37",
    "38 - 48",
    ">=49"
]

# Chia nhóm dựa trên tập train
train_df["age_group"], age_bins = pd.qcut(
    train_df["age"],
    q=4,
    labels=age_labels,
    retbins=True,
    duplicates="drop"
)

# Mở rộng biên để chứa mọi giá trị trong test
age_bins[0] = float("-inf")
age_bins[-1] = float("inf")

# Áp dụng đúng ngưỡng của train cho test
test_df["age_group"] = pd.cut(
    test_df["age"],
    bins=age_bins,
    labels=age_labels,
    include_lowest=True,
    right=True
)

group_order = age_labels

train_counts = (
    train_df["age_group"]
    .value_counts()
    .reindex(group_order, fill_value=0)
)

test_counts = (
    test_df["age_group"]
    .value_counts()
    .reindex(group_order, fill_value=0)
)

age_group_counts = pd.DataFrame({
    "Train": train_counts,
    "Test": test_counts
})

train_total = train_counts.sum()
test_total = test_counts.sum()

age_group_percent = pd.DataFrame({
    "Train": train_counts / train_total * 100,
    "Test": test_counts / test_total * 100
})

ax = age_group_counts.plot(
    kind="bar",
    figsize=(9, 5),
    width=0.8
)

ax.set_title("Biểu đồ tần suất phân bổ nhóm tuổi")
ax.set_xlabel("Nhóm tuổi")
ax.set_ylabel("Số người")

# Nhãn nằm trên trục X
ax.set_xticklabels(age_labels, rotation=0)

ax.legend(
    ["Huấn luyện", "Kiểm tra"],
    title="Tập dữ liệu"
)

ax.grid(
    axis="y",
    linestyle="--",
    alpha=0.4
)

for container, dataset_name in zip(
    ax.containers,
    ["Train", "Test"]
):
    labels = []

    for group_name, bar in zip(group_order, container):
        count = int(bar.get_height())

        percent = age_group_percent.loc[
            group_name,
            dataset_name
        ]

        labels.append(
            f"{count:,}\n{percent:.1f}%"
        )

    ax.bar_label(
        container,
        labels=labels,
        padding=3,
        fontsize=9
    )

ax.set_ylim(
    0,
    age_group_counts.to_numpy().max() * 1.18
)

ax.yaxis.set_major_formatter(
    StrMethodFormatter("{x:,.0f}")
)

plt.tight_layout()
plt.show()
