# >50K  = 1
y_train = (train_df["income"] == ">50K").astype(int)
y_test = (test_df["income"] == ">50K").astype(int)


# ---------------------------------------------------------
# 2. KIỂM TRA DỮ LIỆU THIẾU
# ---------------------------------------------------------

train_missing = X_train.isna().sum().sum()
test_missing = X_test.isna().sum().sum()

print("Số giá trị thiếu trong tập train:", train_missing)
print("Số giá trị thiếu trong tập test:", test_missing)

# Phiên bản baseline này không sử dụng SimpleImputer.
# Do đó dữ liệu không được chứa NaN.
if train_missing > 0 or test_missing > 0:
    raise ValueError(
        "Dữ liệu đang chứa giá trị thiếu. "
        "Hãy xử lý dữ liệu thiếu trước hoặc thêm SimpleImputer."
    )


# ---------------------------------------------------------
# 3. XÁC ĐỊNH CỘT SỐ VÀ CỘT PHÂN LOẠI
# ---------------------------------------------------------

numeric_columns = X_train.select_dtypes(
    include="number"
).columns.tolist()

categorical_columns = X_train.select_dtypes(
    exclude="number"
).columns.tolist()

