groups_to_merge = ["Without-pay", "Never-worked"]

for data in [train_df, test_df]:
    data["workclass"] = data["workclass"].replace(
        groups_to_merge,
        "No-paid-work",
    )

# Thay giá trị thiếu để hiển thị trên biểu đồ
train_workclass = train_df["workclass"].fillna("Missing")
test_workclass = test_df["workclass"].fillna("Missing")

# Lấy đầy đủ danh sách nhóm từ cả train và test
group_order = sorted(
    set(train_workclass.unique())
    | set(test_workclass.unique())
)

# Đếm số lượng
train_counts = (
    train_workclass
    .value_counts()
    .reindex(group_order, fill_value=0)
)

test_counts = (
    test_workclass
    .value_counts()
    .reindex(group_order, fill_value=0)
)

# Tạo bảng dữ liệu
workclass_counts = pd.DataFrame({
    "Train": train_counts,
    "Test": test_counts,
})

# Tính tỷ lệ phần trăm
workclass_percent = pd.DataFrame({
    "Train": train_counts / train_counts.sum() * 100,
    "Test": test_counts / test_counts.sum() * 100,
})

# Vẽ biểu đồ cột ngang
ax = workclass_counts.plot(
    kind="barh",
    figsize=(10, 6),
    width=0.8,
)

ax.set_title("Phân bố loại hình công việc")
ax.set_xlabel("Số người")
ax.set_ylabel("Loại hình công việc")

ax.legend(
    ["Huấn luyện", "Kiểm tra"],
    title="Tập dữ liệu",
)

ax.grid(
    axis="x",
    linestyle="--",
    alpha=0.4,
)

# Ghi số lượng và tỷ lệ lên từng cột
for container, dataset_name in zip(
    ax.containers,
    ["Train", "Test"],
):
    labels = []

    for group_name, bar in zip(group_order, container):
        count = int(bar.get_width())

        percent = workclass_percent.loc[
            group_name,
            dataset_name,
        ]

        labels.append(
            f"{count:,} ({percent:.1f}%)"
        )

    ax.bar_label(
        container,
        labels=labels,
        padding=3,
        fontsize=8,
    )

# Tạo khoảng trống để nhãn không bị cắt
ax.set_xlim(
    0,
    workclass_counts.to_numpy().max() * 1.28,
)

ax.xaxis.set_major_formatter(
    StrMethodFormatter("{x:,.0f}")
)

plt.tight_layout()
plt.show()
