# =========================================================
# LOGISTIC REGRESSION BASELINE CHO BỘ DỮ LIỆU ADULT
# Chỉ tiền xử lý bắt buộc: One-Hot Encoding
# =========================================================

import pandas as pd
import matplotlib.pyplot as plt

from IPython.display import display

from sklearn.compose import ColumnTransformer
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import (
    accuracy_score,
    classification_report,
    confusion_matrix,
    ConfusionMatrixDisplay,
    f1_score,
    precision_score,
    recall_score,
    roc_auc_score,
    RocCurveDisplay,
)
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder


# ---------------------------------------------------------
# 1. TÁCH ĐẶC TRƯNG VÀ NHÃN
# ---------------------------------------------------------
columns_to_drop = ["income"]

X_train = train_df.drop(columns=columns_to_drop).copy()
X_test = test_df.drop(columns=columns_to_drop).copy()

# Chuyển nhãn:
# <=50K = 0
# >50K  = 1
y_train = (train_df["income"] == ">50K").astype(int)
y_test = (test_df["income"] == ">50K").astype(int)


# ---------------------------------------------------------
# 2. KIỂM TRA DỮ LIỆU THIẾU
# ---------------------------------------------------------

train_missing = X_train.isna().sum().sum()
test_missing = X_test.isna().sum().sum()

print("Số giá trị thiếu trong tập train:", train_missing)
print("Số giá trị thiếu trong tập test:", test_missing)

# Phiên bản baseline này không sử dụng SimpleImputer.
# Do đó dữ liệu không được chứa NaN.
if train_missing > 0 or test_missing > 0:
    raise ValueError(
        "Dữ liệu đang chứa giá trị thiếu. "
        "Hãy xử lý dữ liệu thiếu trước hoặc thêm SimpleImputer."
    )


# ---------------------------------------------------------
# 3. XÁC ĐỊNH CỘT SỐ VÀ CỘT PHÂN LOẠI
# ---------------------------------------------------------

numeric_columns = X_train.select_dtypes(
    include="number"
).columns.tolist()

categorical_columns = X_train.select_dtypes(
    exclude="number"
).columns.tolist()

print("\nCột số:")
print(numeric_columns)

print("\nCột phân loại:")
print(categorical_columns)


# ---------------------------------------------------------
# 4. TIỀN XỬ LÝ TỐI THIỂU
# ---------------------------------------------------------

# Cột số được giữ nguyên.
# Cột phân loại bắt buộc phải chuyển thành dữ liệu số.
preprocessor = ColumnTransformer(
    transformers=[
        (
            "categorical",
            OneHotEncoder(
                handle_unknown="ignore"
            ),
            categorical_columns,
        ),
        (
            "numeric",
            "passthrough",
            numeric_columns,
        ),
    ]
)


# ---------------------------------------------------------
# 5. TẠO PIPELINE LOGISTIC REGRESSION
# ---------------------------------------------------------

logistic_model = Pipeline(
    steps=[
        (
            "preprocessor",
            preprocessor,
        ),
        (
            "classifier",
            LogisticRegression(
                max_iter=2000,
                solver="liblinear",
                random_state=42,
            ),
        ),
    ]
)


# ---------------------------------------------------------
# 6. HUẤN LUYỆN MÔ HÌNH
# ---------------------------------------------------------

logistic_model.fit(X_train, y_train)


# ---------------------------------------------------------
# 7. DỰ ĐOÁN TRÊN TẬP TEST
# ---------------------------------------------------------

y_pred = logistic_model.predict(X_test)

# Xác suất mẫu thuộc lớp >50K
y_probability = logistic_model.predict_proba(X_test)[:, 1]


# ---------------------------------------------------------
# 8. TÍNH CÁC CHỈ SỐ ĐÁNH GIÁ
# ---------------------------------------------------------

results = pd.DataFrame(
    {
        "Chỉ số": [
            "Accuracy",
            "Precision",
            "Recall",
            "F1-score",
            "ROC-AUC",
        ],
        "Giá trị": [
            accuracy_score(y_test, y_pred),
            precision_score(
                y_test,
                y_pred,
                zero_division=0,
            ),
            recall_score(
                y_test,
                y_pred,
                zero_division=0,
            ),
            f1_score(
                y_test,
                y_pred,
                zero_division=0,
            ),
            roc_auc_score(
                y_test,
                y_probability,
            ),
        ],
    }
)

results["Giá trị"] = results["Giá trị"].round(4)


# ---------------------------------------------------------
# 9. HIỂN THỊ BẢNG KẾT QUẢ
# ---------------------------------------------------------

display(
    results.style
    .format({"Giá trị": "{:.4f}"})
    .hide(axis="index")
    .background_gradient(
        subset=["Giá trị"],
        vmin=0,
        vmax=1,
    )
    .set_caption(
        "KẾT QUẢ LOGISTIC REGRESSION BASELINE"
    )
    .set_properties(
        **{
            "text-align": "center",
            "padding": "8px",
        }
    )
    .set_table_styles(
        [
            {
                "selector": "caption",
                "props": [
                    ("font-size", "18px"),
                    ("font-weight", "bold"),
                    ("margin-bottom", "10px"),
                ],
            },
            {
                "selector": "th",
                "props": [
                    ("text-align", "center"),
                    ("font-weight", "bold"),
                ],
            },
        ]
    )
)


# ---------------------------------------------------------
# 10. BÁO CÁO PHÂN LOẠI
# ---------------------------------------------------------

report = classification_report(
    y_test,
    y_pred,
    target_names=["<=50K", ">50K"],
    output_dict=True,
    digits=4,
    zero_division=0,
)

report_df = pd.DataFrame(report).transpose()

report_df = report_df.rename(
    columns={
        "precision": "Precision",
        "recall": "Recall",
        "f1-score": "F1-score",
        "support": "Support",
    }
)

display(
    report_df.style
    .format(
        {
            "Precision": "{:.4f}",
            "Recall": "{:.4f}",
            "F1-score": "{:.4f}",
            "Support": "{:.0f}",
        }
    )
    .background_gradient(
        subset=[
            "Precision",
            "Recall",
            "F1-score",
        ],
        vmin=0,
        vmax=1,
    )
    .set_caption("BÁO CÁO PHÂN LOẠI")
    .set_properties(
        **{
            "text-align": "center",
            "padding": "8px",
        }
    )
    .set_table_styles(
        [
            {
                "selector": "caption",
                "props": [
                    ("font-size", "18px"),
                    ("font-weight", "bold"),
                    ("margin-bottom", "10px"),
                ],
            },
            {
                "selector": "th",
                "props": [
                    ("text-align", "center"),
                    ("font-weight", "bold"),
                ],
            },
        ]
    )
)


# ---------------------------------------------------------
# 11. MA TRẬN NHẦM LẪN
# ---------------------------------------------------------

confusion = confusion_matrix(y_test, y_pred)
ConfusionMatrixDisplay(confusion_matrix=confusion, display_labels=["<=50K", ">50K"],).plot()
plt.title("Ma trận nhầm lẫn")
plt.xlabel("Giá trị dự đoán\n(Predicted value)")
plt.ylabel("Giá trị thực tế\n(Actual value)")
plt.tight_layout()
plt.show()

# ---------------------------------------------------------
# 12. ĐƯỜNG CONG ROC
# ---------------------------------------------------------

display = RocCurveDisplay.from_predictions(
    y_test,
    y_probability,
    name="Logistic Regression",
)

ax = display.ax_

ax.plot(
    [0, 1],
    [0, 1],
    color="red",
    linestyle="--",
    linewidth=1.5,
    label="Dự đoán ngẫu nhiên",
)

ax.set_title("Biểu đồ AUROC")

# Chỉnh nhãn trục X và Y
ax.set_xlabel("Tỷ lệ dương tính giả\n(False Positive Rate)")
ax.set_ylabel("Tỷ lệ dương tính thật\n(True Positive Rate)")

ax.legend()

plt.tight_layout()
plt.show()
