# Gộp hai nhóm ít dữ liệu
groups_to_merge = [
    "Without-pay",
    "Never-worked",
]

for data in [train_df, test_df]:
    data["workclass"] = data["workclass"].replace(
        groups_to_merge,
        "No-paid-work",
    )


# Nhãn tiếng Việt
WORKCLASS_LABELS = {
    "Federal-gov": "Liên bang",
    "State-gov": "Tiểu bang",
    "Local-gov": "Địa phương",
    "Private": "Tư nhân",
    "Self-emp-inc": "Tự kinh doanh\n(Có lập công ty)",
    "Self-emp-not-inc": "Tự kinh doanh\n(Không lập công ty)",
    "No-paid-work": "Không có lương",
    "Missing": "Dữ liệu thiếu",
}


# Thay giá trị thiếu để hiển thị
train_workclass = train_df["workclass"].fillna("Missing")
test_workclass = test_df["workclass"].fillna("Missing")


# Đếm số lượng
train_counts = train_workclass.value_counts()
test_counts = test_workclass.value_counts()


# Tính tổng số quan sát của từng nhóm
total_counts = train_counts.add(
    test_counts,
    fill_value=0,
)


# Sắp xếp tăng dần theo tổng số lượng
# và luôn đặt dữ liệu thiếu ở đáy biểu đồ
other_groups = (
    total_counts
    .drop(index="Missing", errors="ignore")
    .sort_values(ascending=True)
    .index
    .tolist()
)

group_order = []

if "Missing" in total_counts.index:
    group_order.append("Missing")

group_order.extend(other_groups)


# Sắp xếp dữ liệu theo cùng thứ tự
train_counts = train_counts.reindex(
    group_order,
    fill_value=0,
)

