import numpy as np
import pandas as pd

from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.metrics import accuracy_score, f1_score
from sklearn.model_selection import train_test_split
from sklearn.naive_bayes import BernoulliNB
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import (
    KBinsDiscretizer,
    OneHotEncoder,
)
from sklearn.tree import DecisionTreeClassifier


# Các cột cần điền dữ liệu thiếu
MISSING_COLUMNS = [
    "workclass",
    "occupation",
    "native_country",
]


def split_observed_data(
    X,
    y,
    test_size=0.2,
    random_state=42,
):
    """
    Chia các dòng có dữ liệu thành tập huấn luyện và xác thực.

    Các lớp chỉ có một quan sát luôn được giữ trong tập huấn luyện
    để mô hình có thể nhận biết lớp đó.
    """
    class_counts = y.value_counts()

    rare_mask = y.map(class_counts).lt(2)

    X_rare = X.loc[rare_mask]
    y_rare = y.loc[rare_mask]

    X_common = X.loc[~rare_mask]
    y_common = y.loc[~rare_mask]

    X_train, X_valid, y_train, y_valid = train_test_split(
        X_common,
        y_common,
        test_size=test_size,
        random_state=random_state,
        stratify=y_common,
    )

    # Thêm các lớp hiếm vào tập huấn luyện
    if len(X_rare) > 0:
        X_train = pd.concat(
            [X_train, X_rare],
            axis=0,
        )

        y_train = pd.concat(
            [y_train, y_rare],
            axis=0,
        )

    return X_train, X_valid, y_train, y_valid


def create_imputation_model(X, method):
    """
    Tạo pipeline điền khuyết bằng Decision Tree
    hoặc Naive Bayes.
    """
    numeric_columns = (
        X.select_dtypes(include=np.number)
        .columns
        .tolist()
    )

    categorical_columns = [
        column
        for column in X.columns
        if column not in numeric_columns
    ]

    categorical_pipeline = Pipeline(
        steps=[
            (
                "imputer",
                SimpleImputer(
                    strategy="most_frequent",
                ),
            ),
            (
                "onehot",
                OneHotEncoder(
                    handle_unknown="ignore",
                ),
            ),
        ]
    )

    if method == "decision_tree":
        numeric_pipeline = Pipeline(
            steps=[
                (
                    "imputer",
                    SimpleImputer(
                        strategy="median",
                    ),
                ),
            ]
        )

        classifier = DecisionTreeClassifier(
            max_depth=15,
            min_samples_leaf=5,
            random_state=42,
        )

    elif method == "naive_bayes":
        # Chia biến số thành các khoảng trước khi dùng BernoulliNB
        numeric_pipeline = Pipeline(
            steps=[
                (
                    "imputer",
                    SimpleImputer(
                        strategy="median",
                    ),
                ),
                (
                    "binning",
                    KBinsDiscretizer(
                        n_bins=10,
                        encode="onehot",
                        strategy="quantile",
                    ),
                ),
            ]
        )

        classifier = BernoulliNB(
            alpha=1.0,
        )

    else:
        raise ValueError(
            "method phải là 'decision_tree' hoặc 'naive_bayes'"
        )

    preprocessor = ColumnTransformer(
        transformers=[
            (
                "numeric",
                numeric_pipeline,
                numeric_columns,
            ),
            (
                "categorical",
                categorical_pipeline,
                categorical_columns,
            ),
        ]
    )

    return Pipeline(
        steps=[
            (
                "preprocessor",
                preprocessor,
            ),
            (
                "classifier",
                classifier,
            ),
        ]
    )


def impute_missing_values(
    train_data,
    test_data,
    target_columns,
    method,
):
    """
    Huấn luyện mô hình trên các dòng không thiếu của tập train,
    sau đó dự đoán giá trị thiếu cho cả train và test.
    """
    train_result = train_data.copy()
    test_result = test_data.copy()

    evaluation_results = []

    for target_column in target_columns:
        print(
            f"\nĐang xử lý: {target_column} "
            f"bằng {method}"
        )

        # Chuyển sang object để có thể gán giá trị dự đoán
        train_result[target_column] = (
            train_result[target_column]
            .astype("object")
        )

        test_result[target_column] = (
            test_result[target_column]
            .astype("object")
        )

        observed_mask = (
            train_result[target_column]
            .notna()
        )

        # Không sử dụng biến cần dự đoán và income
        predictor_columns = [
            column
            for column in train_result.columns
            if column not in [
                target_column,
                "income",
            ]
        ]

        X_observed = train_result.loc[
            observed_mask,
            predictor_columns,
        ]

        y_observed = train_result.loc[
            observed_mask,
            target_column,
        ]

        # Chia train và validation
        (
            X_train,
            X_valid,
            y_train,
            y_valid,
        ) = split_observed_data(
            X_observed,
            y_observed,
        )

        model = create_imputation_model(
            X_train,
            method,
        )

        # Đánh giá mô hình điền khuyết
        model.fit(
            X_train,
            y_train,
        )

        y_valid_pred = model.predict(
            X_valid,
        )

        accuracy = accuracy_score(
            y_valid,
            y_valid_pred,
        )

        macro_f1 = f1_score(
            y_valid,
            y_valid_pred,
            average="macro",
            zero_division=0,
        )

        evaluation_results.append({
            "Thuộc tính": target_column,
            "Phương pháp": method,
            "Accuracy": accuracy,
            "Macro-F1": macro_f1,
        })

        print(f"Accuracy: {accuracy:.4f}")
        print(f"Macro-F1: {macro_f1:.4f}")

        # Huấn luyện lại trên toàn bộ dữ liệu có giá trị
        model.fit(
            X_observed,
            y_observed,
        )

        # Điền thiếu cho tập train
        train_missing_mask = (
            train_result[target_column]
            .isna()
        )

        if train_missing_mask.any():
            train_result.loc[
                train_missing_mask,
                target_column,
            ] = model.predict(
                train_result.loc[
                    train_missing_mask,
                    predictor_columns,
                ]
            )

        # Điền thiếu cho tập test
        test_missing_mask = (
            test_result[target_column]
            .isna()
        )

        if test_missing_mask.any():
            test_result.loc[
                test_missing_mask,
                target_column,
            ] = model.predict(
                test_result.loc[
                    test_missing_mask,
                    predictor_columns,
                ]
            )

    evaluation_df = pd.DataFrame(
        evaluation_results
    )

    return (
        train_result,
        test_result,
        evaluation_df,
    )
