MISSING_LABEL = "Dữ liệu thiếu"


def analyze_categorical(
    df,
    column,
    dataset_name="Dữ liệu",
    chart_name=None,
    color="steelblue",
    missing_color="#E15759",
    labels=None,
    label_width=25,
    x_label="Số lượng",
    y_label=None,
    decimal_places=3,  # Số chữ số thập phân
):
    if column not in df.columns:
        raise KeyError(f"Không tìm thấy cột '{column}'.")

    if not isinstance(decimal_places, int) or decimal_places < 0:
        raise ValueError("decimal_places phải là số nguyên không âm.")

    labels = labels or {}
    chart_name = chart_name or column
    y_label = y_label or column

    # Chuẩn hóa dữ liệu.
    values = (
        df[column]
        .astype("string")
        .str.strip()
        .fillna(MISSING_LABEL)
        .replace({
            "?": MISSING_LABEL,
            "": MISSING_LABEL,
        })
    )

    total = len(values)

    if total == 0:
        raise ValueError("DataFrame không có dữ liệu để phân tích.")

    valid_values = values[values != MISSING_LABEL]

    # Đếm tần số và sắp xếp giảm dần.
    counts = values.value_counts()

    # Đặt dữ liệu thiếu ở cuối.
    if MISSING_LABEL in counts.index:
        counts = pd.concat([
            counts.drop(index=MISSING_LABEL),
            counts.loc[[MISSING_LABEL]],
        ])

    missing_count = int((values == MISSING_LABEL).sum())
    valid_count = total - missing_count

    # Xác định mốt, không tính dữ liệu thiếu.
    if valid_values.empty:
        mode = None
        mode_count = 0
        mode_percent = 0
    else:
        mode = valid_values.mode().iloc[0]
        mode_count = int((valid_values == mode).sum())
        mode_percent = mode_count / total * 100

    mode_display = (
        labels.get(mode, mode)
        if mode is not None
        else "Không có"
    )

    missing_percent = missing_count / total * 100

    # Bảng thống kê tổng quát.
    summary = pd.Series(
        {
            "Số lượng mẫu": f"{total:,}",
            "Số giá trị hợp lệ": f"{valid_count:,}",
            "Số dữ liệu thiếu": f"{missing_count:,}",
            "Tỷ lệ dữ liệu thiếu": (
                f"{missing_percent:.{decimal_places}f}%"
            ),
            "Số nhóm hợp lệ": int(valid_values.nunique()),
            "Mốt": mode_display,
            "Tần số của mốt": f"{mode_count:,}",
            "Tỷ lệ của mốt": (
                f"{mode_percent:.{decimal_places}f}%"
            ),
        },
        name="Giá trị",
    ).rename_axis("Chỉ số").to_frame()

    # Chuyển giá trị gốc thành nhãn hiển thị.
    display_labels = [
        labels.get(value, value)
        for value in counts.index
    ]

    percentages = counts.to_numpy() / total * 100

    # Bảng chi tiết.
    detail = pd.DataFrame({
        "Nhóm dữ liệu": display_labels,
        "Số lượng": counts.to_numpy(),
        "Tỷ lệ (%)": percentages.round(decimal_places),
    })

    print(f"THỐNG KÊ {column.upper()} - {dataset_name.upper()}")
    display(summary)
    display(detail)

    # Giữ xuống dòng có sẵn và tự ngắt nhãn dài.
    wrapped_labels = [
        "\n".join(
            fill(part, width=label_width)
            for part in str(label).split("\n")
        )
        for label in display_labels
    ]

    # Dữ liệu thiếu có màu riêng.
    bar_colors = [
        missing_color if value == MISSING_LABEL else color
        for value in counts.index
    ]

    # Điều chỉnh chiều cao theo số nhóm.
    figure_height = max(
        6,
        min(18, len(counts) * 0.7),
    )

    figure, axis = plt.subplots(
        figsize=(10, figure_height)
    )

    bars = axis.barh(
        wrapped_labels,
        detail["Số lượng"],
        color=bar_colors,
    )

    axis.invert_yaxis()

    # Hiển thị số lượng và tỷ lệ.
    for bar, percent in zip(
        bars,
        detail["Tỷ lệ (%)"],
    ):
        count = int(bar.get_width())

        axis.annotate(
            f"{count:,}\n{percent:.{decimal_places}f}%",
            xy=(
                bar.get_width(),
                bar.get_y() + bar.get_height() / 2,
            ),
            xytext=(6, 0),
            textcoords="offset points",
            ha="left",
            va="center",
            fontsize=10,
            linespacing=1.15,
            clip_on=False,
        )

    max_count = detail["Số lượng"].max()

    axis.set_xlim(
        0,
        max_count * 1.12 if max_count > 0 else 1,
    )

    axis.set_title(
        f"Biểu đồ phân bố {chart_name}",
        fontsize=14,
    )

    axis.set_xlabel(x_label, fontsize=10)
    axis.set_ylabel(y_label, fontsize=10)
    axis.grid(axis="x", linestyle="--", alpha=0.35)
    axis.set_axisbelow(True)

    axis.xaxis.set_major_formatter(
        FuncFormatter(
            lambda value, position: f"{value:,.0f}"
        )
    )

    axis.margins(y=0.01)
    figure.tight_layout(pad=0)
    plt.show()

    return summary, detail
