def encode_labels(df, classes):

    df = df.copy()

    parsed_labels = (
        df[LABEL_COLUMN]
        .astype(str)
        .str.split(LABEL_SEPARATOR)
    )

    for label in classes:

        df[label] = (
            parsed_labels
            .apply(
                lambda labels:
                int(label in labels)
            )
            .astype(np.uint8)
        )

    # Số bệnh có trong mỗi ảnh
    df["num_positive_labels"] = (
        df[classes]
        .sum(axis=1)
        .astype(np.uint8)
    )

    # No Finding chỉ dùng để đánh dấu,
    # không phải output thứ 15
    df["is_no_finding"] = (
        df[LABEL_COLUMN]
        .eq(NO_FINDING_LABEL)
        .astype(np.uint8)
    )

    return df
