all_df = pd.concat(
    [
        train_df,
        validation_df,
        test_df,
    ],
    ignore_index=True
)

unique_images = (
    all_df[
        [ID_COLUMN, "original_path"]
    ]
    .drop_duplicates(
        subset=[ID_COLUMN]
    )
    .reset_index(drop=True)
)

resized_paths = {}

for _, row in tqdm(
    unique_images.iterrows(),
    total=len(unique_images),
    desc="Resize"
):

    image_name = row[ID_COLUMN]

    source_path = Path(
        row["original_path"]
    )

    target_path = (
        RESIZED_DIRECTORY
        / image_name
    )

    # Không xử lý lại nếu đã có
    if not target_path.exists():

        with Image.open(source_path) as image:

            image = image.convert("L")

            image = image.resize(
                (
                    IMAGE_SIZE,
                    IMAGE_SIZE
                ),
                Image.Resampling.LANCZOS
            )

            image.save(
                target_path,
                format="PNG"
            )

    resized_paths[
        image_name
    ] = str(
        target_path.resolve()
    )
