image_map = {
    path.name: path
    for path in IMAGE_DIRECTORY.rglob("*")
    if (
        path.is_file()
        and path.suffix.lower() in image_extensions
    )
}

def attach_image_path(df):

    df = df.copy()
    df["original_path"] = (
        df[ID_COLUMN]
        .map(
            lambda name:
            str(image_map[name])
            if name in image_map
            else None
        )
    )

    return df
