# ---------------------------------------------------------
fold_summary = []

for fold in range(1, NUMBER_OF_FOLDS + 1):
    fold_train = train_val_df[train_val_df["Fold"] != fold]
    fold_val = train_val_df[train_val_df["Fold"] == fold]

    train_patients = set(fold_train[PATIENT_ID_COLUMN])
    val_patients = set(fold_val[PATIENT_ID_COLUMN])
    patient_overlap = train_patients & val_patients

    assert len(patient_overlap) == 0, f"Fold {fold} bị patient leakage."

    fold_summary.append({
        "fold": fold,
        "train_images": len(fold_train),
        "validation_images": len(fold_val),
        "train_patients": len(train_patients),
        "validation_patients": len(val_patients),
        "patient_overlap": len(patient_overlap),
    })

fold_summary_df = pd.DataFrame(fold_summary)
