for fold in range(1, N_SPLITS + 1):
    fold_val = train_val_df[train_val_df[FOLD_COLUMN] == fold]

    for label in CLASSES:
        positive = int(fold_val[label].sum())
        fold_distribution_rows.append({
            "fold": fold,
            "class": label,
            "positive_images": positive,
            "total_images": len(fold_val),
            "positive_rate": positive / len(fold_val) if len(fold_val) else 0.0,
        })

fold_distribution_df = pd.DataFrame(fold_distribution_rows)
fold_distribution_pivot = fold_distribution_df.pivot(
    index="class",
    columns="fold",
    values="positive_rate",
)

display(fold_distribution_pivot)
