# =========================================================
# THỐNG KÊ PHÂN BỐ NHÃN TRAIN + NO FINDING
# VÀ VẼ HEATMAP VỚI COLORMAP "Blues"
# =========================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.ticker import PercentFormatter


# =========================================================
# 1. THỐNG KÊ PHÂN BỐ NHÃN
# =========================================================

train_distribution_rows = []
validation_distribution_rows = []

for fold in range(1, NUMBER_OF_FOLDS + 1):

    fold_train = train_df[train_df["Fold"] != fold]
    fold_val   = train_df[train_df["Fold"] == fold]

    # -----------------------------------------------------
    # 14 NHÃN BỆNH
    # -----------------------------------------------------
    for label in CLASSES:

        # Train
        train_positive = int(fold_train[label].sum())
        train_total = len(fold_train)

        train_distribution_rows.append({
            "Lớp": label,
            "Fold": fold,
            "Số ảnh dương tính": train_positive,
            "Tổng số ảnh": train_total,
            "Tỷ lệ": (
                train_positive / train_total
                if train_total > 0 else 0.0
            ),
        })

        # Validation
        val_positive = int(fold_val[label].sum())
        val_total = len(fold_val)

        validation_distribution_rows.append({
            "Lớp": label,
            "Fold": fold,
            "Số ảnh dương tính": val_positive,
            "Tổng số ảnh": val_total,
            "Tỷ lệ": (
                val_positive / val_total
                if val_total > 0 else 0.0
            ),
        })

    # -----------------------------------------------------
    # NO FINDING
    # Toàn bộ 14 nhãn đều bằng 0
    # -----------------------------------------------------
    train_no_finding = int(
        (fold_train[CLASSES].sum(axis=1) == 0).sum()
    )

    val_no_finding = int(
        (fold_val[CLASSES].sum(axis=1) == 0).sum()
    )

    train_distribution_rows.append({
        "Lớp": "No Finding",
        "Fold": fold,
        "Số ảnh dương tính": train_no_finding,
        "Tổng số ảnh": len(fold_train),
        "Tỷ lệ": (
            train_no_finding / len(fold_train)
            if len(fold_train) > 0 else 0.0
        ),
    })

    validation_distribution_rows.append({
        "Lớp": "No Finding",
        "Fold": fold,
        "Số ảnh dương tính": val_no_finding,
        "Tổng số ảnh": len(fold_val),
        "Tỷ lệ": (
            val_no_finding / len(fold_val)
            if len(fold_val) > 0 else 0.0
        ),
    })


# =========================================================
# 2. TẠO DATAFRAME
# =========================================================

train_distribution_df = pd.DataFrame(train_distribution_rows)

validation_distribution_df = pd.DataFrame(
    validation_distribution_rows
)


# =========================================================
# 3. SẮP XẾP NHÃN
#    NO FINDING ĐẦU TIÊN
#    CÁC BỆNH CÒN LẠI THEO ALPHABET
# =========================================================

label_order = ["No Finding"] + sorted(CLASSES)

train_distribution_df["Lớp"] = pd.Categorical(
    train_distribution_df["Lớp"],
    categories=label_order,
    ordered=True
)

validation_distribution_df["Lớp"] = pd.Categorical(
    validation_distribution_df["Lớp"],
    categories=label_order,
    ordered=True
)

train_distribution_df = (
    train_distribution_df
    .sort_values(["Lớp", "Fold"])
    .reset_index(drop=True)
)

validation_distribution_df = (
    validation_distribution_df
    .sort_values(["Lớp", "Fold"])
    .reset_index(drop=True)
)


# =========================================================
# 4. PIVOT BẢNG TRAIN
# =========================================================

train_distribution_pivot = train_distribution_df.pivot(
    index="Lớp",
    columns="Fold",
    values="Tỷ lệ",
)

train_distribution_pivot = (
    train_distribution_pivot
    .reindex(label_order)
)

train_distribution_pivot.columns = [
    f"Fold {fold}"
    for fold in train_distribution_pivot.columns
]


# =========================================================
# 5. HIỂN THỊ BẢNG TRAIN
# =========================================================

train_distribution_table = (
    train_distribution_pivot
    .reset_index()
)

display(
    train_distribution_table
    .style
    .hide(axis="index")
    .format({
        f"Fold {fold}": "{:.2%}"
        for fold in range(1, NUMBER_OF_FOLDS + 1)
    })
    .set_caption(
        "Phân bố tỷ lệ các nhãn trong tập huấn luyện"
    )
    .set_properties(**{
        "text-align": "center",
        "padding": "7px 12px",
    })
    .set_table_styles([
        {
            "selector": "caption",
            "props": [
                ("font-size", "16px"),
                ("font-weight", "bold"),
                ("text-align", "center"),
                ("margin-bottom", "10px"),
            ],
        },
        {
            "selector": "th",
            "props": [
                ("text-align", "center"),
                ("font-weight", "bold"),
                ("padding", "7px 12px"),
            ],
        },
        {
            "selector": "td",
            "props": [
                ("text-align", "center"),
            ],
        },
    ])
)


# =========================================================
# 6. VẼ HEATMAP TRAIN - BLUES
# =========================================================

data = train_distribution_pivot.to_numpy(dtype=float)

fig, ax = plt.subplots(
    figsize=(10, 8)
)

im = ax.imshow(
    data,
    aspect="auto",
    cmap="Blues",
    vmin=0,
    vmax=data.max()
)


